INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a482d76d-7f96-4d93-a50e-e174bb85a956', '竹山連句題潘氏書堂', '竹山連句題潘氏书堂', '3cab5d3d-c0ea-4d83-817a-9e68e82d298b', '唐', '["（顏真卿、陸羽、李蕚、裴修、康造、湯清河、清晝、陸士修、房夔、顏粲、顏顓、顏須、韋介、李觀、房益、柳淡、顏峴、潘述）竹山招隱處，潘子讀書堂。","（真卿）萬卷皆成袠，千竿不作行。","（陸羽）練容飡沆瀣，濯足咏「滄浪」。","（李萼）守道心自樂，下帷名益彰。","（裴修）風來似秋興，花發勝河陽。","（康造）支策曉雲近，援琴春日長。","（湯清河）水田聊學稼，野圃試條桑。","（清晝）巾折定因雨，履穿寧爲霜。","（陸士修）解衣垂蕙帶，拂席坐藜牀。","（房夔）檐宇馴輕翼，簪裾染衆芳。","（顏粲）草生遽近砌，藤長稍依牆。","（顏顓）魚樂憐清淺，禽閑熹頡行。","（顏須。","行當作「頏」）空園種桃李，遠墅於此牛羊。","（韋介）讀《易》三時罷，圍碁百事忘。","（李觀）境幽神自王，道在器猶藏（房益）晝歠山僧苟，宵傳野客觴。","（柳淡）遙峯對枕席，麗藻映縑緗。","（顏峴）偶得幽棲地，無心學鄭鄉。","（潘述）（見《三長物齋叢書》本《顏魯公文集》卷十二，寧鄉黃本驥編訂。","）（〖1〗連句詩後有黃本驥案語，曰：「連句，即聯句也。","裴修，前梁縣尉。","康造，會稽人，推官。","湯清河，大理評事。","房夔，河南人。","顏粲，魯公族人。","李觀，字元賓，趙郡贊皇人，洛陽丞，遷太子校書郎。","房益，河南人，詹事司直，《湖州志》作武康人，官監察御史。","此詩《全唐詩》未載，據石刻本補錄。","」〖2〗望按：陸羽字鴻漸，曾撰《茶經》三卷。","李萼字伯高，趙人，擢制科，歷官廬州刺史。","清晝，即釋皎然，吳興人，本姓謝氏。","陸士修，嘉興縣尉。","顏顓、顏須，並真卿族姪。","顏峴，真卿兄子。","餘待考。","）。"]', '["（顏真卿、陸羽、李蕚、裴修、康造、湯清河、清晝、陸士修、房夔、顏粲、顏顓、顏須、韋介、李观、房益、柳淡、顏峴、潘述）竹山招隐处，潘子读书堂。","（真卿）万卷皆成袠，千竿不作行。","（陸羽）練容飡沆瀣，濯足咏「滄浪」。","（李萼）守道心自乐，下帷名益彰。","（裴修）风来似秋兴，花發勝河陽。","（康造）支策晓云近，援琴春日长。","（湯清河）水田聊学稼，野圃試條桑。","（清晝）巾折定因雨，履穿寧爲霜。","（陸士修）解衣垂蕙带，拂席坐藜牀。","（房夔）檐宇馴轻翼，簪裾染衆芳。","（顏粲）草生遽近砌，藤长稍依牆。","（顏顓）鱼乐怜清淺，禽闲熹頡行。","（顏須。","行當作「頏」）空园種桃李，远墅於此牛羊。","（韋介）读《易》三时罷，圍碁百事忘。","（李观）境幽神自王，道在器猶藏（房益）晝歠山僧苟，宵傳野客觴。","（柳淡）遙峯对枕席，丽藻映縑緗。","（顏峴）偶得幽棲地，無心学鄭乡。","（潘述）（见《三长物斋叢书》本《顏魯公文集》卷十二，寧乡黄本驥編訂。","）（〖1〗連句诗後有黄本驥案語，曰：「連句，即聯句也。","裴修，前梁縣尉。","康造，會稽人，推官。","湯清河，大理評事。","房夔，河南人。","顏粲，魯公族人。","李观，字元賓，趙郡贊皇人，洛陽丞，遷太子校书郎。","房益，河南人，詹事司直，《湖州志》作武康人，官監察御史。","此诗《全唐诗》未載，據石刻本補錄。","」〖2〗望按：陸羽字鴻漸，曾撰《茶經》三卷。","李萼字伯高，趙人，擢制科，歷官廬州刺史。","清晝，即釋皎然，吳兴人，本姓謝氏。","陸士修，嘉兴縣尉。","顏顓、顏須，並真卿族姪。","顏峴，真卿兄子。","餘待考。","）。"]', '诗', 'shi', '', NULL, '竹山連句題潘氏書堂 顏真卿等 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b7c86ac-39b5-454b-8287-896dee36029e', '水名', '水名', '4429bf3f-17b1-4c56-80ec-7181420ae760', '唐', '["江湖思舊好，河洛賞遺風。","共託金門暇，來遊白□□。","竹霞開樽綠，桃花落□紅。","故鄉渺天涯。","應在□地□。","（見影印本《新編纂圖增類羣書類要事林廣記》卷之七。","）。"]', '["江湖思旧好，河洛賞遺风。","共託金门暇，来游白□□。","竹霞开樽綠，桃花落□紅。","故乡渺天涯。","應在□地□。","（见影印本《新編纂圖增類羣书類要事林廣記》卷之七。","）。"]', '诗', 'shi', '', NULL, '水名 宇文正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d081a00f-aa81-4fd7-af7e-6e4f6dd3609e', '', '', 'b10341f6-7acb-466b-bf44-a68a7ec92a20', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 程傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('178f0352-27d2-4711-8c73-91f03c96d7ff', '芙蓉峯', '芙蓉峯', 'b10341f6-7acb-466b-bf44-a68a7ec92a20', '唐', '["誰把芙蓉雲外栽，亭亭秀麗四時開。","清宵皓月峯頭掛，宛似佳人對鏡臺。","（見康熙十八年閔麟嗣撰《黃山志定本》卷六。","）。"]', '["誰把芙蓉云外栽，亭亭秀丽四时开。","清宵皓月峯头掛，宛似佳人对镜台。","（见康熙十八年閔麟嗣撰《黄山志定本》卷六。","）。"]', '诗', 'shi', '', NULL, '芙蓉峯 程傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cb5796e-e914-4cea-b4cb-24a8a5428e38', '頌裴長史歌（題擬）', '頌裴长史歌（題擬）', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["賓朋何喧喧？日夜裴公門。","願得裴公之一言，不須驅馬埒華軒。","（按李白《上安沒裴長史書》有云：「故時人歌曰〖歌不重錄〗。","白不知君侯何以得此聲于天壤之間。","」）。"]', '["賓朋何喧喧？日夜裴公门。","願得裴公之一言，不須驱马埒华軒。","（按李白《上安沒裴长史书》有云：「故时人歌曰〖歌不重錄〗。","白不知君侯何以得此声于天壤之间。","」）。"]', '诗', 'shi', '', NULL, '頌裴長史歌（題擬） 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d9ddc9-4b20-4eef-bfcd-daa01ce578b0', '青鸞鏡詩', '青鸾镜诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["月樣團圓水漾（《金石萃編》作「樣」。","）清，好將香閤（《萃編》作「閣」）伴閑身。","青鸞不用羞孤影，開匣當如見故人。","（〖1〗畢沅、阮元撰《山左金石志》卷五曰：「右鏡徑二寸八分，鼻鈕正書七言絕句一首曰〖詩不重錄〗。","外折枝花四枝。","按段若膺《四聲音韻表》，清在第十一部，身在第十二部。","然《易·彖象傳》天命淵賢信民人賓，與形成貞寧生正平精清等字幷用，是二部古有相合。","唐人首句押韻雖不必拘拘，然未有無故牽入者。","此清字可込其未備。","」〖2〗按此詩亦載王昶《金石萃編》卷一百十八，錄其按語如下：「按《山左金石志》跋此銘，謂首句清字與身人同韻，補段若膺《四聲音韻表》所未備。","然七言律絕起句，晚唐五代多有借韻者。","且真文庚青自古間有通用，顧氏寧人、毛氏大可於《唐韻正》及《古今通韻史》已詳載之，不足異也。","」）。"]', '["月樣團圓水漾（《金石萃編》作「樣」。","）清，好將香閤（《萃編》作「閣」）伴闲身。","青鸾不用羞孤影，开匣當如见故人。","（〖1〗畢沅、阮元撰《山左金石志》卷五曰：「右镜徑二寸八分，鼻鈕正书七言絕句一首曰〖诗不重錄〗。","外折枝花四枝。","按段若膺《四声音韻表》，清在第十一部，身在第十二部。","然《易·彖象傳》天命淵賢信民人賓，與形成貞寧生正平精清等字幷用，是二部古有相合。","唐人首句押韻雖不必拘拘，然未有無故牽入者。","此清字可込其未備。","」〖2〗按此诗亦載王昶《金石萃編》卷一百十八，錄其按語如下：「按《山左金石志》跋此銘，謂首句清字與身人同韻，補段若膺《四声音韻表》所未備。","然七言律絕起句，晚唐五代多有借韻者。","且真文庚青自古间有通用，顧氏寧人、毛氏大可於《唐韻正》及《古今通韻史》已詳載之，不足異也。","」）。"]', '诗', 'shi', '', NULL, '青鸞鏡詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f57af99d-18fc-42d6-bbeb-7ec708c7ac6b', '挽歌五首', '挽歌五首', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '挽歌五首 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f3fa78-12d7-44f0-b425-7f429b8e2d12', '挽歌五首 其一', '挽歌五首 其一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["高坐星文掩，人寰巷市忙。","三台投劍佩，四海哭煙霜。","夕殿震號永，秋風曉更長。","龍顏不可見，燒畫月更香。"]', '["高坐星文掩，人寰巷市忙。","三台投劍佩，四海哭煙霜。","夕殿震號永，秋风晓更长。","龙顏不可见，燒畫月更香。"]', '诗', 'shi', '', NULL, '挽歌五首 其一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee7c794-1f47-46d0-bddc-d8e7ebffd2c8', '挽歌五首 其二', '挽歌五首 其二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["憶別西凉日，來朝北闕時。","舌官捧□殿，獨召上龍墀。","寵極[孤]（狐）臣懼，恩深四表知。","此由殉靈駕，血淚自雙垂。"]', '["憶別西凉日，来朝北闕时。","舌官捧□殿，独召上龙墀。","寵極[孤]（狐）臣懼，恩深四表知。","此由殉靈駕，血泪自雙垂。"]', '诗', 'shi', '', NULL, '挽歌五首 其二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7f14e6-88bb-467f-b47d-afe17963af7c', '挽歌五首 其三', '挽歌五首 其三', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["香[嚲]（𨭐）鬱金袍，求衣不重勞。","方張洞庭樂，休種閬山桃。","鶴駕丹陵遠，龍驤碧落高。","胡髯攀斷處，□搶高弓號。"]', '["香[嚲]（𨭐）鬱金袍，求衣不重勞。","方張洞庭乐，休種閬山桃。","鹤駕丹陵远，龙驤碧落高。","胡髯攀斷处，□搶高弓號。"]', '诗', 'shi', '', NULL, '挽歌五首 其三 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3240bf79-3118-4887-8f4f-623c58b93857', '挽歌五首 其四', '挽歌五首 其四', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["巢閣方瞻[鳯]（風），鳴郊忽酬麟。","六宮悲晏駕，四嶽罷來巡。","璽綬傳當璧，河山委大臣。","自傷蒲柳質，不得扈龍輴。"]', '["巢閣方瞻[鳯]（风），鳴郊忽酬麟。","六宮悲晏駕，四嶽罷来巡。","璽綬傳當璧，河山委大臣。","自傷蒲柳質，不得扈龙輴。"]', '诗', 'shi', '', NULL, '挽歌五首 其四 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c9ecd7-fe07-470f-bcfc-7f5ba6f7e94e', '挽歌五首 其五', '挽歌五首 其五', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["七載朝金殿，千秋遇聖君。","九夷瞻北極，萬國靡南熏。","盛烈排軒后，崇淩壓□文。","靈知河瀧士，興斷高鄉雲。","（以上五詩從許國霖輯《敦煌雜錄》錄出。","許氏擬頁原作《進上挽歌》，此省作《挽歌》。","）（三處改動皆從趙遂之說。","）。"]', '["七載朝金殿，千秋遇聖君。","九夷瞻北極，万国靡南熏。","盛烈排軒后，崇淩壓□文。","靈知河瀧士，兴斷高乡云。","（以上五诗從許国霖輯《敦煌杂錄》錄出。","許氏擬頁原作《進上挽歌》，此省作《挽歌》。","）（三处改动皆從趙遂之说。","）。"]', '诗', 'shi', '', NULL, '挽歌五首 其五 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('575dd05d-0c1e-4f1b-8814-a0a1834ba640', '王昭君怨諸詞人連句', '王昭君怨諸词人連句', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["掖庭嬌幸在娥眉，爭用黃金寫艷姿。","始言恩寵由君意，誰謂容顏信畫師。","微軀一身入深宮，春華幾度落秋風。","君恩不惜便衣處，妾貌應殊畫辟中。","間道和親將我敞，選貌披圖遍宮掖。","圖中容貌既不如，選後君王空海（望疑「悔」字之誤）惜。","始知王意本相親，自恨舟（望疑「丹」字之誤）青每誤身。","昔是宮中薄命妾，今成塞外斷腸人。","九重恩愛應長謝，萬里關山愁遠嫁。","飛來北地不勝春，月照南庭空度夜。","夜中含涕獨嬋娟，遙念君邊與朔邊。","毳幕不同羅帳日，氈裘非復錦衾年。","長安高闕三千里，一望能令一心死。","秋來懷抱既不堪，況復南飛雁聲起。","（此詩見劉復《燉煌掇瑣》三四。","題雖標連句，然不著諸詞人姓名，故仍以常詩視之。","此詩又見於王重民《〈補全唐詩〉拾遺》。","王輯本刊出於本書成書之後，故兩存之。","）。"]', '["掖庭嬌幸在娥眉，爭用黄金寫艷姿。","始言恩寵由君意，誰謂容顏信畫師。","微軀一身入深宮，春华幾度落秋风。","君恩不惜便衣处，妾貌應殊畫辟中。","间道和親將我敞，選貌披圖遍宮掖。","圖中容貌既不如，選後君王空海（望疑「悔」字之誤）惜。","始知王意本相親，自恨舟（望疑「丹」字之誤）青每誤身。","昔是宮中薄命妾，今成塞外斷腸人。","九重恩愛應长謝，万里关山愁远嫁。","飞来北地不勝春，月照南庭空度夜。","夜中含涕独嬋娟，遙念君邊與朔邊。","毳幕不同羅帳日，氈裘非复錦衾年。","长安高闕三千里，一望能令一心死。","秋来懷抱既不堪，況复南飞雁声起。","（此诗见劉复《燉煌掇瑣》三四。","題雖標連句，然不著諸词人姓名，故仍以常诗視之。","此诗又见於王重民《〈補全唐诗〉拾遺》。","王輯本刊出於本书成书之後，故兩存之。","）。"]', '诗', 'shi', '', NULL, '王昭君怨諸詞人連句 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b978ce7d-573d-483f-9a3e-da179dfd3b73', '失題', '失題', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["東上波流西上船，桃源未必有真仙。","干戈滿目家何在，寂寞空山聞杜鵑。","（見《江南餘載》卷下。","南唐開寶末詩也。","）（〖1〗《江南餘載》：「開寶末，長老法倫夢金陵兵火四起，有書生朗吟曰〖詩不重錄〗」云云。","）。"]', '["东上波流西上船，桃源未必有真仙。","干戈满目家何在，寂寞空山闻杜鵑。","（见《江南餘載》卷下。","南唐开寶末诗也。","）（〖1〗《江南餘載》：「开寶末，长老法倫梦金陵兵火四起，有书生朗吟曰〖诗不重錄〗」云云。","）。"]', '诗', 'shi', '', NULL, '失題 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b7daff-fce8-4883-8715-910ac3bcbc0b', '看南山', '看南山', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["抗蜀復臨秦，凝嵐萬古新。","峭連河漢地，氣爽市朝人。","影裏天家桂，光中陸海珍。","愛山兼戀此，偏柰與誰隣？","（見《分門纂類唐歌詩》殘本第二冊《天地山川類》卷二十二。","）。"]', '["抗蜀复臨秦，凝嵐万古新。","峭連河漢地，氣爽市朝人。","影裏天家桂，光中陸海珍。","愛山兼戀此，偏柰與誰隣？","（见《分门纂類唐歌诗》殘本第二冊《天地山川類》卷二十二。","）。"]', '诗', 'shi', '', NULL, '看南山 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9cef0e-1879-42af-a31e-8b2ac163f449', '七日禁中陪宴', '七日禁中陪宴', '59725467-78f6-47b5-92b6-7beeef38270a', '唐', '["入朝貴國慙下客，七日承恩作上賓。","更見鳯（一作「凰」）聲無妓態，風流變動一園（一作「國」）春。","（此詩爲仁貞在日本國作。","見金毓黻撰《渤海國志長編》卷十八引《文華秀麗集》上。","）。"]', '["入朝貴国慙下客，七日承恩作上賓。","更见鳯（一作「凰」）声無妓態，风流变动一园（一作「国」）春。","（此诗爲仁貞在日本国作。","见金毓黻撰《渤海国志长編》卷十八引《文华秀丽集》上。","）。"]', '诗', 'shi', '', NULL, '七日禁中陪宴 仁貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70bc793-6cea-4dea-82fb-4a9159d534a6', '哭日本國內供奉大德靈仙和尚詩（幷序）', '哭日本国內供奉大德靈仙和尚诗（幷序）', '697b09f8-ede5-4b35-99d0-c45c36117b2a', '唐', '["不體（《類從》本作「航」。","〖又日本佛教全書〗本作「{舟巳}」。","考云：「{舟巳}即那字。","慧超《傳》多用此字。","」）心淚（《類從》本作「渡」。","）自涓，（望按：「此句原脫一字。","」）情因法眼奄幽泉。","明朝儻問滄波客，的說遺鞋白足還。","（見《渤海國志長編》卷十八引《入唐求法巡禮行記》三。","）（〖1〗按詩前有小注，曰「詩一首。","在唐作」。","蓋從當時渤海藩國言，故曰「在唐」也。","又詩末題「大和二年四月十四日書」十字。","〖2〗上海古籍出版社一九八六年出版顧承甫等點校本《入唐求來巡禮行記》，參據多種版本校勘，較精審。","今錄異文如次：「公作而習之」，「作」作「僕」；「余之身期降物」，作「余亦身期絳物」；「入宗五臺」，「宗」作「室」；「青癡」，作「青瘀」；「仙大師己來日久」，「己」作「亡」；「位我之血」，「位」作「泣」；「不體心淚」，「體」作「航」。","）。"]', '["不體（《類從》本作「航」。","〖又日本佛教全书〗本作「{舟巳}」。","考云：「{舟巳}即那字。","慧超《傳》多用此字。","」）心泪（《類從》本作「渡」。","）自涓，（望按：「此句原脫一字。","」）情因法眼奄幽泉。","明朝儻问滄波客，的说遺鞋白足還。","（见《渤海国志长編》卷十八引《入唐求法巡禮行記》三。","）（〖1〗按诗前有小注，曰「诗一首。","在唐作」。","蓋從當时渤海藩国言，故曰「在唐」也。","又诗末題「大和二年四月十四日书」十字。","〖2〗上海古籍出版社一九八六年出版顧承甫等点校本《入唐求来巡禮行記》，參據多種版本校勘，較精審。","今錄異文如次：「公作而習之」，「作」作「僕」；「余之身期降物」，作「余亦身期絳物」；「入宗五台」，「宗」作「室」；「青癡」，作「青瘀」；「仙大師己来日久」，「己」作「亡」；「位我之血」，「位」作「泣」；「不體心泪」，「體」作「航」。","）。"]', '诗', 'shi', '', NULL, '哭日本國內供奉大德靈仙和尚詩（幷序） 貞素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b078a6d-7982-4aad-b729-fdc1f716f04f', '元孚五十年前遊天台宿建公院登華頂攀琪樹觀石橋之險絕緬懷昔遊因爲絕句寄知建長老兼呈台州王司馬', '元孚五十年前游天台宿建公院登华頂攀琪樹观石橋之險絕緬懷昔游因爲絕句寄知建长老兼呈台州王司马', 'd820ca19-4c6e-4ad4-9ee6-bb87d9a74ce6', '唐', '["天生石月架空虛，樹綴龍髯子貫珠。","三十年前已攀折，建公曾到上方無。","（見明陶宗儀《古刻叢鈔》。","）（詩下原署曰「上都左街保壽寺文章應制內供奉大德元孚」。","又《寶刻叢編》卷十五有《唐房田寺經藏院記》，云唐崔龜從撰，僧元孚書，會昌二年立。","則元孚者，武宗提人也。","）。"]', '["天生石月架空虛，樹綴龙髯子貫珠。","三十年前已攀折，建公曾到上方無。","（见明陶宗儀《古刻叢鈔》。","）（诗下原署曰「上都左街保壽寺文章應制內供奉大德元孚」。","又《寶刻叢編》卷十五有《唐房田寺經藏院記》，云唐崔龟從撰，僧元孚书，會昌二年立。","則元孚者，武宗提人也。","）。"]', '诗', 'shi', '', NULL, '元孚五十年前遊天台宿建公院登華頂攀琪樹觀石橋之險絕緬懷昔遊因爲絕句寄知建長老兼呈台州王司馬 元孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f2f84a2-ef74-4475-9d24-116376fed23a', '', '', '49446d1b-133a-4bf0-a441-08d62fe56e85', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 思託 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1b7de91-e9b7-4ada-b55e-32b23a890da7', '五言傷大和上傳燈逝[日本]', '五言傷大和上傳灯逝[日本]', '49446d1b-133a-4bf0-a441-08d62fe56e85', '唐', '["上德乘杯渡，金人道已東。","戒香餘散馥，慧炬復流風。","月隱歸靈鷲，珠逃入梵宮。","神飛生死表，遺教法門中。","（〖1〗見同前書《唐大和上東征傳》。","詩題下原署曰「日本國傳燈沙門思託」。","〖汪向榮校注本《唐大和上東征傳》錄此詩題作《五言傷大和上傳燈逝日本》，署「傳燈沙門釋思託」。","以「日本」二字歸詩題，是，今據補。","思託爲鑒真弟子，《東征傳》中多次提及。","〗餘參閱前元開詩附注。","）。"]', '["上德乘杯渡，金人道已东。","戒香餘散馥，慧炬复流风。","月隐归靈鷲，珠逃入梵宮。","神飞生死表，遺教法门中。","（〖1〗见同前书《唐大和上东征傳》。","诗題下原署曰「日本国傳灯沙门思託」。","〖汪向榮校注本《唐大和上东征傳》錄此诗題作《五言傷大和上傳灯逝日本》，署「傳灯沙门釋思託」。","以「日本」二字归诗題，是，今據補。","思託爲鑒真弟子，《东征傳》中多次提及。","〗餘參閱前元开诗附注。","）。"]', '诗', 'shi', '', NULL, '五言傷大和上傳燈逝[日本] 思託 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('505ea7bb-b50e-49b9-9dc4-2cf0956e19c7', '七言傷大和上', '七言傷大和上', 'b3c71e4f-ad16-4380-ae1a-f8833561cd93', '唐', '["大師慈育契圓空，遠邁傳燈照海東。","度物草（寸）籌盈石室，散流佛戒紹遺蹤。","化畢分身歸淨國，娑婆誰復爲驗龍？","（驗龍，汪向榮校注本《唐大和上東征傳》據日本觀智院本改爲「驅龍」。","）（按詩題下原署「傳燈賢大法師大僧都沙門釋法進」十四字。","詩亦見《唐大和上東征傳》。","又按鑒真亡後，唐高鶴林亦曾作五言詩一首以悼之，詩亦載《唐大和尚東征傳》。","高爲唐肅宗、代宗朝人，官都虞候冠軍大將軍試太常卿上柱國，因出使日本國，欲順訪東渡僧鑒真，至則鑒真已先亡故，詩蓋寄懷傷之意也。","上野河世寧已收入《全唐詩逸》，兹不再錄。","）。"]', '["大師慈育契圓空，远邁傳灯照海东。","度物草（寸）籌盈石室，散流佛戒紹遺蹤。","化畢分身归淨国，娑婆誰复爲驗龙？","（驗龙，汪向榮校注本《唐大和上东征傳》據日本观智院本改爲「驱龙」。","）（按诗題下原署「傳灯賢大法師大僧都沙门釋法進」十四字。","诗亦见《唐大和上东征傳》。","又按鑒真亡後，唐高鹤林亦曾作五言诗一首以悼之，诗亦載《唐大和尚东征傳》。","高爲唐肅宗、代宗朝人，官都虞候冠軍大將軍試太常卿上柱国，因出使日本国，欲順訪东渡僧鑒真，至則鑒真已先亡故，诗蓋寄懷傷之意也。","上野河世寧已收入《全唐诗逸》，兹不再錄。","）。"]', '诗', 'shi', '', NULL, '七言傷大和上 法進 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7553b547-5aeb-4ca9-bfaf-4f1da9d04677', '咏紅芙蓉上宋使（「宋使」二字於此當脫「君」字。宋使君屢見於《禪月集》，《唐刺史考》考定爲宋震。）', '咏紅芙蓉上宋使（「宋使」二字於此當脫「君」字。宋使君屢见於《禪月集》，《唐刺史考》考定爲宋震。）', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["擘水苞金紫艷濃，乍觀疑在水仙宮。","難驅顏色文章裏，合出天人池館中。","芬馥靜生朱檻膩，動搖微映鷺鷥紅。","臨川內史詩相似，搖仰清吟滿閣風。","（見《唐歌詩》殘本六冊《草木蟲魚類》卷五。","）。"]', '["擘水苞金紫艷濃，乍观疑在水仙宮。","难驱顏色文章裏，合出天人池館中。","芬馥静生朱檻膩，动搖微映鷺鷥紅。","臨川內史诗相似，搖仰清吟满閣风。","（见《唐歌诗》殘本六冊《草木蟲鱼類》卷五。","）。"]', '诗', 'shi', '', NULL, '咏紅芙蓉上宋使（「宋使」二字於此當脫「君」字。宋使君屢見於《禪月集》，《唐刺史考》考定爲宋震。） 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2eb9620-c2a9-4a44-a26b-92a2f86ee10b', '苔蘚', '苔蘚', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["嚴子釣臺邊不少，謝公山展上無多。","（展，疑當作「屐」。","）世間若也皆廉潔，金玉生根柰爾何？","（見《唐歌詩》殘本六冊《草木蟲魚類》卷六。","）。"]', '["嚴子釣台邊不少，謝公山展上無多。","（展，疑當作「屐」。","）世间若也皆廉潔，金玉生根柰爾何？","（见《唐歌诗》殘本六冊《草木蟲鱼類》卷六。","）。"]', '诗', 'shi', '', NULL, '苔蘚 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d2d9e8-5300-470e-a811-17896dd98087', '長安柳', '长安柳', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["雨重依依舞態低，任人攀折路東西。","何如渡□成林處，留得黃鸎到夜啼。","（見《唐歌詩》殘本第七冊《草石蟲魚類》卷八。","）。"]', '["雨重依依舞態低，任人攀折路东西。","何如渡□成林处，留得黄鸎到夜啼。","（见《唐歌诗》殘本第七冊《草石蟲鱼類》卷八。","）。"]', '诗', 'shi', '', NULL, '長安柳 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e8755e8-f916-460c-acec-046b6ef9d1f6', '傷悼前蜀廢國（《鑑誡錄》卷五錄此詩題作《傷廢國》。）', '傷悼前蜀廢国（《鑑誡錄》卷五錄此诗題作《傷廢国》。）', '56b76209-5578-4bf8-8385-085c99d4398e', '唐', '["樂極悲來數有涯，歌聲才歇便興嗟。","牽羊廢主尋傾國，指鹿姦臣盡喪家。","丹禁夜涼空鏁月，後庭春老謾開花。","兩朝帝業都成夢，陵樹蒼蒼噪暮鴉。","（見前蜀何光遠《鑑誡錄》卷五。","日本漢學家豐田穰氏所撰《全唐詩糾謬》一文曾論及之，云《全唐詩》所未收。","）（《增修詩話總龜》卷三十錄此詩，作「蜀僧遠國《傷蜀詩》」。","詩中「指鹿」作「逐鹿」，「陵樹」作「林木」，均當以《鑑誡錄》爲長。","）。"]', '["乐極悲来數有涯，歌声才歇便兴嗟。","牽羊廢主尋傾国，指鹿姦臣尽喪家。","丹禁夜涼空鏁月，後庭春老謾开花。","兩朝帝業都成梦，陵樹蒼蒼噪暮鴉。","（见前蜀何光远《鑑誡錄》卷五。","日本漢学家豐田穰氏所撰《全唐诗糾謬》一文曾論及之，云《全唐诗》所未收。","）（《增修诗話總龟》卷三十錄此诗，作「蜀僧远国《傷蜀诗》」。","诗中「指鹿」作「逐鹿」，「陵樹」作「林木」，均當以《鑑誡錄》爲长。","）。"]', '诗', 'shi', '', NULL, '傷悼前蜀廢國（《鑑誡錄》卷五錄此詩題作《傷廢國》。） 遠公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df319db8-2859-4426-9b73-9bfd2666d06a', '看牡丹（見《唐僧弘秀集》卷五。按《全唐詩》作僧謙光詩，題作《賞牡丹應教》。詩中「毳」字，《全唐詩》作「衲」，「趣」作「事」，）', '看牡丹（见《唐僧弘秀集》卷五。按《全唐诗》作僧謙光诗，題作《賞牡丹應教》。诗中「毳」字，《全唐诗》作「衲」，「趣」作「事」，）', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["空（「髪」作「鬢」，「是」作「似」，「曳」作「異」，「晚」作「曉」，「待」作「對」。","謙光，金陵人，有才辯。","〖《全唐詩續補遺》卷十五據《分門纂類唐歌詩》、《唐詩紀事》卷七六錄此則，今刪彼存外。","《全唐詩》作謙光，所據爲陶岳《五代史補》卷五。","另《大法眼文益禪師語錄》、《五燈會元》卷十、《苕溪漁隱叢話》卷五七、《釋氏稽古略》亦收作文益詩。","〗）。"]', '["空（「髪」作「鬢」，「是」作「似」，「曳」作「異」，「晚」作「晓」，「待」作「对」。","謙光，金陵人，有才辯。","〖《全唐诗續補遺》卷十五據《分门纂類唐歌诗》、《唐诗紀事》卷七六錄此則，今刪彼存外。","《全唐诗》作謙光，所據爲陶岳《五代史補》卷五。","另《大法眼文益禪師語錄》、《五灯會元》卷十、《苕溪漁隐叢話》卷五七、《釋氏稽古略》亦收作文益诗。","〗）。"]', '诗', 'shi', '', NULL, '看牡丹（見《唐僧弘秀集》卷五。按《全唐詩》作僧謙光詩，題作《賞牡丹應教》。詩中「毳」字，《全唐詩》作「衲」，「趣」作「事」，） 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319612a4-9849-44ca-a640-e4d3e6b84f4c', '閑居', '闲居', '4f81121a-3d1b-495e-b6a3-9b8389fe213a', '唐', '["閑居誰似我，退跡理難過。","要勢危身早，浮榮敗德多。","雨催蟲出穴，寒逼鳥移窼。","野徑無人翦，疏窗入薜蘿。","（見《宋詩紀事》卷九十一。","）（張靖龍云此詩見《讀畫齋叢書》本《南宋羣賢小集》收陳起輯《增廣聖宋高僧詩選後集》卷中。","）。"]', '["闲居誰似我，退跡理难過。","要勢危身早，浮榮敗德多。","雨催蟲出穴，寒逼鸟移窼。","野徑無人翦，疏窗入薜蘿。","（见《宋诗紀事》卷九十一。","）（張靖龙云此诗见《读畫斋叢书》本《南宋羣賢小集》收陳起輯《增廣聖宋高僧诗選後集》卷中。","）。"]', '诗', 'shi', '', NULL, '閑居 延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfaed0d-3c6b-4bd9-8485-2133edb0ea57', '', '', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b61d1b85-3ea3-47cb-9329-8aec2d9896ca', '寄題水月禪院（在洞庭山縹緲峯下，梁大同四年建，山有無礙泉。）', '寄題水月禪院（在洞庭山縹緲峯下，梁大同四年建，山有無礙泉。）', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["參差峯岫晝雲昏，入望攀蘿濁浪奔。","震澤湧山來北岸，華陽連洞到東門。","日生樹掛紅霞脚，風起波搖白石根。","聞有上方僧住處，橘花林下採蘭蓀。","（見《宋詩紀事》引《吳都志》。","）（見《吳郡志》卷三三《郭外詩》，爲同題二首之一。","《吳郡志》云：「水月禪院，在洞庭山縹緲峰下。","……天祐四年，刺史曹珪以明月名之。","皇朝祥符間，詔易今名。","」贊寧卒於咸平四年〖據《釋氏疑年錄》〗，易名水月爲其身後事，詩題似應作《寄題明月禪院》。","）。"]', '["參差峯岫晝云昏，入望攀蘿濁浪奔。","震澤湧山来北岸，华陽連洞到东门。","日生樹掛紅霞脚，风起波搖白石根。","闻有上方僧住处，橘花林下採蘭蓀。","（见《宋诗紀事》引《吳都志》。","）（见《吳郡志》卷三三《郭外诗》，爲同題二首之一。","《吳郡志》云：「水月禪院，在洞庭山縹緲峰下。","……天祐四年，刺史曹珪以明月名之。","皇朝祥符间，詔易今名。","」贊寧卒於咸平四年〖據《釋氏疑年錄》〗，易名水月爲其身後事，诗題似應作《寄題明月禪院》。","）。"]', '诗', 'shi', '', NULL, '寄題水月禪院（在洞庭山縹緲峯下，梁大同四年建，山有無礙泉。） 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420576f2-8a90-4796-8562-864fd1dc92d5', '居天柱山', '居天柱山', '7b402e8f-4ee8-4b5c-90ca-8d05a0e0bdeb', '唐', '["四野豁家庭，柴門夜不扃。","水邊成半偈，月下了殘經。","雖逐諸塵轉，終歸一念醒。","未知斯旨者，萬役盡勞形。","（《瀛奎律髓》卷四十七《釋梵類》。","）（見陳起《增廣聖宋高僧詩選後集》卷上。","）。"]', '["四野豁家庭，柴门夜不扃。","水邊成半偈，月下了殘經。","雖逐諸塵轉，終归一念醒。","未知斯旨者，万役尽勞形。","（《瀛奎律髓》卷四十七《釋梵類》。","）（见陳起《增廣聖宋高僧诗選後集》卷上。","）。"]', '诗', 'shi', '', NULL, '居天柱山 贊寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa35a09-980c-4b7d-bf07-7f66b2f1adba', '答贊寧', '答贊寧', '407cc33b-1b39-4656-a3b4-529a10e9e874', '唐', '["山中人事違，天眼中修定。","（天目，一名天眼。","）我本無根株，只將筍爲命。","（見釋贊寧所撰《筍譜》。","）。"]', '["山中人事違，天眼中修定。","（天目，一名天眼。","）我本無根株，只將筍爲命。","（见釋贊寧所撰《筍譜》。","）。"]', '诗', 'shi', '', NULL, '答贊寧 天目僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea7c1d0c-be78-45c7-a3f6-a970927913db', '禪詩 一', '禪诗 一', '422702aa-0f7e-49e3-83a6-5012094fcff7', '唐', '["座禪不亂意，觀色更無緣。","三獨羅剎得成佛，不要流心再座禪。","（原注云：「五言一首。","」）。"]', '["座禪不亂意，观色更無緣。","三独羅剎得成佛，不要流心再座禪。","（原注云：「五言一首。","」）。"]', '诗', 'shi', '', NULL, '禪詩 一 無名僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e3e899-e35e-4900-bbe6-8324e90b876f', '禪詩 二', '禪诗 二', '422702aa-0f7e-49e3-83a6-5012094fcff7', '唐', '["座得須不喜動，何要觀心了三界。","但觀性內所，不知意緣起。","（原注云：「一首。","」）。"]', '["座得須不喜动，何要观心了三界。","但观性內所，不知意緣起。","（原注云：「一首。","」）。"]', '诗', 'shi', '', NULL, '禪詩 二 無名僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b40f48e4-4639-4712-baa1-c753efb3cdd8', '禪詩 三', '禪诗 三', '422702aa-0f7e-49e3-83a6-5012094fcff7', '唐', '["心平不用持戒，行直河須座。","恩則普同婦子，義則上下漠然。","苦口則是凉藥，依●定出黃蓮。","菩薩向心如覓，天堂即在眼前。"]', '["心平不用持戒，行直河須座。","恩則普同婦子，義則上下漠然。","苦口則是凉藥，依●定出黄蓮。","菩薩向心如覓，天堂即在眼前。"]', '诗', 'shi', '', NULL, '禪詩 三 無名僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61db7025-509a-45b2-a16e-7b7c13b46982', '禪詩 四', '禪诗 四', '422702aa-0f7e-49e3-83a6-5012094fcff7', '唐', '["清蓮臺上見天唐，衆生真心禮肆芳。","降摩處上夜放光，菩薩悲願遍什芳。","（以上四首見伯二一二九卷，前三首抄於一處，第四首另抄。","第三首第二句，似應作「行直何須坐禪」。","第四句「漠然」，原卷作「嘆然」，疑應作「懽然」。","第五句「涼藥」應作「良藥」。","第四首中「肆芳」、「什芳」，通「四方」、「十方」。）"]', '["清蓮台上见天唐，衆生真心禮肆芳。","降摩处上夜放光，菩薩悲願遍什芳。","（以上四首见伯二一二九卷，前三首抄於一处，第四首另抄。","第三首第二句，似應作「行直何須坐禪」。","第四句「漠然」，原卷作「嘆然」，疑應作「懽然」。","第五句「涼藥」應作「良藥」。","第四首中「肆芳」、「什芳」，通「四方」、「十方」。）"]', '诗', 'shi', '', NULL, '禪詩 四 無名僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144300f6-599b-4732-ba04-d1875e1ced48', '禪詩 五', '禪诗 五', '422702aa-0f7e-49e3-83a6-5012094fcff7', '唐', '["即日一千僧，住在寺山林。","百鳥同科宿，相看見兄弟。","（此首原注出伯二六三三卷。","末句「兄弟」，疑應作「弟兄」。","）。"]', '["即日一千僧，住在寺山林。","百鸟同科宿，相看见兄弟。","（此首原注出伯二六三三卷。","末句「兄弟」，疑應作「弟兄」。","）。"]', '诗', 'shi', '', NULL, '禪詩 五 無名僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd2a3c59-0ac1-4458-8e27-199743994400', '', '', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a4a4fd-1081-4bff-9f4b-3a75188c68dc', '酬劉侍御過草堂', '酬劉侍御過草堂', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["疇昔隳世網，就閒棲遠林。","豈謂軒車客，來過澗壑深。","既懷康濟業，仍許隱淪心。","靈液充甘飲，松風代鳴琴。","晤言不可極，真興何愔愔。","貽我方來偈，自然生玉音。","予慙乏瓊玖，無以報兼金。","他日思良會，含情時永吟。","（見道士孟宗寶集虛編《洞霄詩集》。","）。"]', '["疇昔隳世網，就閒棲远林。","豈謂軒车客，来過澗壑深。","既懷康濟業，仍許隐淪心。","靈液充甘饮，松风代鳴琴。","晤言不可極，真兴何愔愔。","貽我方来偈，自然生玉音。","予慙乏瓊玖，無以報兼金。","他日思良會，含情时永吟。","（见道士孟宗寶集虛編《洞霄诗集》。","）。"]', '诗', 'shi', '', NULL, '酬劉侍御過草堂 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08f7c5ba-1754-4fcf-ba14-5152c831765e', '酬劉侍御過草堂', '酬劉侍御過草堂', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["弱冠涉儒黑，壯懷歸道真。","棲遲高潁閒，得與巢由鄰。","豺狼亂天紀，流蕩江海濱。","江海非吾土，所賴吾同人。","築堂依絕巘，閉關從隱淪。","一過囂紛境，臥病逾三旬。","皇靈垂矜卹，正氣澄心神。","但感適起居，何堦答蒼旻。","策羸返巖壑，情抱豁已伸。","霜候變林薄，不能改松筠。","彌見攝生理，邈然超世塵。","寫懷簡同志，終古無緇磷。","（同前。","）。"]', '["弱冠涉儒黑，壯懷归道真。","棲遲高潁閒，得與巢由鄰。","豺狼亂天紀，流蕩江海濱。","江海非吾土，所賴吾同人。","築堂依絕巘，閉关從隐淪。","一過囂紛境，臥病逾三旬。","皇靈垂矜卹，正氣澄心神。","但感適起居，何堦答蒼旻。","策羸返巖壑，情抱豁已伸。","霜候变林薄，不能改松筠。","彌见攝生理，邈然超世塵。","寫懷簡同志，終古無緇磷。","（同前。","）。"]', '诗', 'shi', '', NULL, '酬劉侍御過草堂 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b5eba9-949f-48d0-aa78-53b4c895e40a', '大滌洞', '大滌洞', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["名山閟靈府，隱士此尋真。","仙去空遺鼓，雲扃不見人。","川源世上異，日月洞中春。","欲出虛無境，應修有待身。","（見《洞霄詩集》。","）（〖1〗鄧牧《洞霄圖志》卷二《山水門·大滌山》條：「大滌山，在宮〖指洞霄宮〗北，凡四峯，於九鎖內最爲巨山。","西洞據其領，石室出其半，天壇冠其顛，皆山中勝處也。","是山以洞名之。","舊志謂大可以洗滌塵心，故名大滌。","……元同先生劍履瘞山下。","」〖2〗又《洞霄圖志》卷三《洞府門·大滌洞》條：「大滌洞在宮西北半里。","《茅君傳》云第三十四洞天，名大滌元蓋之天。","周圍四百里，……相傳元同先生入游，見龍麟異境，花木鮮繁，自華陽而歸〖望按前文有云：與華陽林屋邃道通〗。","洞門石鼓，廣可尋丈，扣之逄逄有聲。","」）。"]', '["名山閟靈府，隐士此尋真。","仙去空遺鼓，云扃不见人。","川源世上異，日月洞中春。","欲出虛無境，應修有待身。","（见《洞霄诗集》。","）（〖1〗鄧牧《洞霄圖志》卷二《山水门·大滌山》條：「大滌山，在宮〖指洞霄宮〗北，凡四峯，於九鎖內最爲巨山。","西洞據其領，石室出其半，天壇冠其顛，皆山中勝处也。","是山以洞名之。","旧志謂大可以洗滌塵心，故名大滌。","……元同先生劍履瘞山下。","」〖2〗又《洞霄圖志》卷三《洞府门·大滌洞》條：「大滌洞在宮西北半里。","《茅君傳》云第三十四洞天，名大滌元蓋之天。","周圍四百里，……相傳元同先生入游，见龙麟異境，花木鲜繁，自华陽而归〖望按前文有云：與华陽林屋邃道通〗。","洞门石鼓，廣可尋丈，扣之逄逄有声。","」）。"]', '诗', 'shi', '', NULL, '大滌洞 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4257aa95-5538-425b-88d1-62e03832bbaa', '天壇', '天壇', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["天壇高百尺，只在翠微間。","碧蘚遺蹤古，青松白日閒。","丹成人已化，雲去鶴應還。","時有吹簫客，月明來故山。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡門·昇天壇》條：「舊志云：在大滌山中峯之上，又名法象壇。","上應天而圓，下應地而方，中應《易》卦而八角。","許遠遊真君精研洞典，登其上而仙去，時天降白鹿下迎，故中峯名白鹿山。","今山頂界松內數丈之地，草木弗植，是其遺址也。","」）。"]', '["天壇高百尺，只在翠微间。","碧蘚遺蹤古，青松白日閒。","丹成人已化，云去鹤應還。","时有吹簫客，月明来故山。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡门·昇天壇》條：「旧志云：在大滌山中峯之上，又名法象壇。","上應天而圓，下應地而方，中應《易》卦而八角。","許远游真君精研洞典，登其上而仙去，时天降白鹿下迎，故中峯名白鹿山。","今山頂界松內數丈之地，草木弗植，是其遺址也。","」）。"]', '诗', 'shi', '', NULL, '天壇 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca15a98e-b398-43a2-b04f-b727ec29b56a', '馴虎巖', '馴虎巖', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["外身道不遠，異類自能馴。","尚有相親獸，應無可棄人。","溪邊同飲水，林下共棲真。","寂寂空巖畔，千秋迹已陳。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡門·伏虎巖》條：「伏虎巖，在宮山西南峻壁間，若環堵之室。","南有路，自上而下，復陟厓磴，方至其所。","藤蘿深密，怪禽晝啼，非有道之士，不可處也。","昔郭真君伏虎於此。","按《晉書》云：『葛洪何幼道偕訪之，目擊而已，各無所言，引嘯而退。","』唐吳天師愛其遺跡，每游忘返，題詩巖上，今歲久昏剝，云：『郭生在童穉，已得方外心。","絕跡遺世務，棲真入長林。","元和感異類，猛獸懷德音。","不憶固無情，斯言微且深。","』末句蓋引真君與溫嶠問答語。","」）。"]', '["外身道不远，異類自能馴。","尚有相親獸，應無可棄人。","溪邊同饮水，林下共棲真。","寂寂空巖畔，千秋迹已陳。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡门·伏虎巖》條：「伏虎巖，在宮山西南峻壁间，若环堵之室。","南有路，自上而下，复陟厓磴，方至其所。","藤蘿深密，怪禽晝啼，非有道之士，不可处也。","昔郭真君伏虎於此。","按《晉书》云：『葛洪何幼道偕訪之，目擊而已，各無所言，引嘯而退。","』唐吳天師愛其遺跡，每游忘返，題诗巖上，今歲久昏剝，云：『郭生在童穉，已得方外心。","絕跡遺世務，棲真入长林。","元和感異類，猛獸懷德音。","不憶固無情，斯言微且深。","』末句蓋引真君與溫嶠问答語。","」）。"]', '诗', 'shi', '', NULL, '馴虎巖 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9efd5da6-28a0-4b97-b12a-9a3c48bebf12', '石門', '石门', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["靈關非世力，造化創元功。","屈曲穿丹壑，崢嶸倚碧空。","煙蘿常蔽日，松竹自吟風。","除卻幽人到，塵凡路不通。","（同前。","）。"]', '["靈关非世力，造化創元功。","屈曲穿丹壑，崢嶸倚碧空。","煙蘿常蔽日，松竹自吟风。","除卻幽人到，塵凡路不通。","（同前。","）。"]', '诗', 'shi', '', NULL, '石門 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81316cf1-1878-44c7-bb7f-8f2d05a7caff', '藥圃', '藥圃', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["仙翁曾播植，瓊圃尚敷榮。","春日祥光滿，秋風瑞實成。","黃精宜益壽，萱草足忘情。","候採靈芝服，還應羽翼生。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡門·藥圃》條：「藥圃，在來賢巖宜霜亭下，夏侯天師種藥於此。","芝畦校塢，百藥之植，靡所不有。","常施藥於廛市，隨緣深淺而與之。","一日，樵者聞圃內有物大噑，隔籬窺見天師，策鞭乘一獸，似虎非虎，行疾如風，入東山而去。","今四山產藥草六十餘種，圃跡猶存。","」）。"]', '["仙翁曾播植，瓊圃尚敷榮。","春日祥光满，秋风瑞實成。","黄精宜益壽，萱草足忘情。","候採靈芝服，還應羽翼生。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡门·藥圃》條：「藥圃，在来賢巖宜霜亭下，夏侯天師種藥於此。","芝畦校塢，百藥之植，靡所不有。","常施藥於廛市，隨緣深淺而與之。","一日，樵者闻圃內有物大噑，隔籬窺见天師，策鞭乘一獸，似虎非虎，行疾如风，入东山而去。","今四山產藥草六十餘種，圃跡猶存。","」）。"]', '诗', 'shi', '', NULL, '藥圃 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d0d620-83b8-42fb-815b-f23cb95b93f6', '撫掌泉', '撫掌泉', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["直下碧千尋，蛟龍此隱身。","無心能應物，拍手湧如神。","夜鏡涵星斗，春盃薦藻蘋。","終年丹竈於此，長給武陵人。","（同前。","）。"]', '["直下碧千尋，蛟龙此隐身。","無心能應物，拍手湧如神。","夜镜涵星斗，春盃薦藻蘋。","終年丹竈於此，长給武陵人。","（同前。","）。"]', '诗', 'shi', '', NULL, '撫掌泉 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f0030c-db42-4cae-ac19-8794aaceaa1c', '講堂', '講堂', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["高蹤誰可繼，一室四無隣。","聽法空雲水，成功集鬼神。","煙霞生戶牖，泉石障埃塵。","越國今何在？空悲行路人。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡門·葉天師講堂》條：「舊志載在山門外，天師役鬼神所建，制度宏巧，絕不類常工。","開元中，天師講《道德》、《度人》諸經於此，有仙花靈鶴，自天而下。","吳越高士，輻輳聽法，咸有所焐，願居弟子列者三百餘人。","惟語以濟恤孤貧，感愧覆載，忠孝君親，重人性命，凈身心，絕奢侈，即爲道之根緒也。","薦經兵火，遺跡不存，今移宮中爲演教堂。","」）。"]', '["高蹤誰可繼，一室四無隣。","听法空云水，成功集鬼神。","煙霞生戶牖，泉石障埃塵。","越国今何在？空悲行路人。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡门·葉天師講堂》條：「旧志載在山门外，天師役鬼神所建，制度宏巧，絕不類常工。","开元中，天師講《道德》、《度人》諸經於此，有仙花靈鹤，自天而下。","吳越高士，輻輳听法，咸有所焐，願居弟子列者三百餘人。","惟語以濟恤孤貧，感愧覆載，忠孝君親，重人性命，凈身心，絕奢侈，即爲道之根緒也。","薦經兵火，遺跡不存，今移宮中爲演教堂。","」）。"]', '诗', 'shi', '', NULL, '講堂 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3179a148-a28d-457d-82e1-080251d69b10', '書樓', '书楼', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["業成人已去，陳迹自依然。","竈有殘丹火，窗遺溢寶篇。","懷賢驚異世，撫事感流年。","早述《南華》理，遽應返化仙。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡門·書樓》條：「一名垂象樓，暨天師所居。","天師少好經史，著述不輟，其中卷秩，委積左右。","……白元鑒有詩。","其址亦在今道院內，爲精思流派。","」）。"]', '["業成人已去，陳迹自依然。","竈有殘丹火，窗遺溢寶篇。","懷賢驚異世，撫事感流年。","早述《南华》理，遽應返化仙。","（同前。","）（〖1〗《洞霄圖志》卷四《古跡门·书楼》條：「一名垂象楼，暨天師所居。","天師少好經史，著述不輟，其中卷秩，委積左右。","……白元鑒有诗。","其址亦在今道院內，爲精思流派。","」）。"]', '诗', 'shi', '', NULL, '書樓 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be775ba-bc8c-4990-a816-7bc29e4057cd', '瀑布', '瀑布', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["飛瀑下幽壑，令人夢寐清。","秋山匹練淨，寒谷萬珠明。","映日添霞色，迎風作雨聲。","潺湲聽莫厭，時得滌幽情。","（同前。","）。"]', '["飞瀑下幽壑，令人梦寐清。","秋山匹練淨，寒谷万珠明。","映日添霞色，迎风作雨声。","潺湲听莫厭，时得滌幽情。","（同前。","）。"]', '诗', 'shi', '', NULL, '瀑布 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('592a6c93-a6b8-42b1-83a8-8c0922aaee99', '新池', '新池', '57b73308-199d-4dcd-83ab-5e73b5178c21', '唐', '["何人鑿碧沼，待我照衰容。","洗藥餘香在，開函古鏡空。","心閒聞細溜，波靜臥喬松。","欲問仙源路，無由見落紅。","（同前。","）（〖1〗《洞霄圖志》卷五《人物門·唐高道白威儀先生》條：「白元鑒，不詳其字，西川成都府人。","高祖君敏，武德功臣。","父洪演，高蹈不襲封，娶申屠氏，生一子，即先生也。","玄宗幸蜀時，爲威儀道士，住上皇觀。","志在絶俗，逍遙遐舉，周覽山川，訪前賢高蹈之躅，得餘杭天柱觀，止焉，四十年矣。","元和十二載八月解化，瘞於天柱山大滌洞東北。","嘗有《山中十咏》。","贊曰：有志絕俗，白公威儀。","自蜀來南，名山棲遲。","元酒味淡，大音聲希。","積四十年，無人見知。","山中遺老，傳誦十詩。","適興而已，不矜能之。","」〖《知不足叢書本》〗）。"]', '["何人鑿碧沼，待我照衰容。","洗藥餘香在，开函古镜空。","心閒闻細溜，波静臥喬松。","欲问仙源路，無由见落紅。","（同前。","）（〖1〗《洞霄圖志》卷五《人物门·唐高道白威儀先生》條：「白元鑒，不詳其字，西川成都府人。","高祖君敏，武德功臣。","父洪演，高蹈不襲封，娶申屠氏，生一子，即先生也。","玄宗幸蜀时，爲威儀道士，住上皇观。","志在絶俗，逍遙遐舉，周覽山川，訪前賢高蹈之躅，得餘杭天柱观，止焉，四十年矣。","元和十二載八月解化，瘞於天柱山大滌洞东北。","嘗有《山中十咏》。","贊曰：有志絕俗，白公威儀。","自蜀来南，名山棲遲。","元酒味淡，大音声希。","積四十年，無人见知。","山中遺老，傳誦十诗。","適兴而已，不矜能之。","」〖《知不足叢书本》〗）。"]', '诗', 'shi', '', NULL, '新池 白元鑒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c0ef25c-2c29-43a4-980c-6216191f8b24', '句', '句', '35f2c362-a32e-42b8-b753-7bc0f895d5be', '唐', '["鬱鬱家國盛，濟濟經道興。","（見廖侁撰、李沖昭述《南獄小錄》。","南京圖書館藏手鈔本。","）（〖1〗《南嶽小錄·九真觀》條：唐開元年間，有王天師仙喬。","初，天師爲行者，道性沖昭，有非常之志。","因將嶽中茶二百餘串，直入京國，每攜茶器於城門內施茶。","忽一日，遇高力士，見而異之，問其所來。","乃曰：「某是南嶽行者，今爲本住九真觀殿宇破落，特將茶來募施主耳。","」於是力士上聞，玄宗召見，嘉歎久之，問曰：「爾有願否？","」對曰：「鬱鬱家國盛，濟濟經道興。","」〖《藝海珠塵》、《四庫全書》本「南嶽小錄」，此二句前皆有「願」字。","〗上深加禮焉，俾於內殿披度，厚與金帛建置，令歸嶽中修剙觀宇，不數年而完全。","道行愈高，聲流上國，尋有詔封爲天師，乾元二年三月三十日得道。","）。"]', '["鬱鬱家国盛，濟濟經道兴。","（见廖侁撰、李沖昭述《南獄小錄》。","南京圖书館藏手鈔本。","）（〖1〗《南嶽小錄·九真观》條：唐开元年间，有王天師仙喬。","初，天師爲行者，道性沖昭，有非常之志。","因將嶽中茶二百餘串，直入京国，每携茶器於城门內施茶。","忽一日，遇高力士，见而異之，问其所来。","乃曰：「某是南嶽行者，今爲本住九真观殿宇破落，特將茶来募施主耳。","」於是力士上闻，玄宗召见，嘉歎久之，问曰：「爾有願否？","」对曰：「鬱鬱家国盛，濟濟經道兴。","」〖《藝海珠塵》、《四庫全书》本「南嶽小錄」，此二句前皆有「願」字。","〗上深加禮焉，俾於內殿披度，厚與金帛建置，令归嶽中修剙观宇，不數年而完全。","道行愈高，声流上国，尋有詔封爲天師，乾元二年三月三十日得道。","）。"]', '诗', 'shi', '', NULL, '句 王仙喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a9d500e-989f-4486-8837-f3fa35c21045', '寓言（見韋莊《又玄集》卷下。按《全唐詩》卷七百二十三作李洞詩，詩與此同。又《全唐詩》卷八百五載元淳此詩前二句，今據《又玄集》，驗作元淳詩爲是。）', '寓言（见韋莊《又玄集》卷下。按《全唐诗》卷七百二十三作李洞诗，诗與此同。又《全唐诗》卷八百五載元淳此诗前二句，今據《又玄集》，驗作元淳诗爲是。）', '25869133-b4ea-4b0d-a6f8-1cb83bdde46d', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '寓言（見韋莊《又玄集》卷下。按《全唐詩》卷七百二十三作李洞詩，詩與此同。又《全唐詩》卷八百五載元淳此詩前二句，今據《又玄集》，驗作元淳詩爲是。） 元淳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2ab870-3570-4393-9c47-e123e6ae3e83', '書與胡咏之', '书與胡咏之', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["濟世應須不世才，調羹重見用鹽梅。","種成白璧人何處，熟了黃粱夢未回。","相府舊開延士閣，武夷新築望仙臺。","青雞唱徹函關曉，好卷游幃歸去來。","（見《宋詩紀事》卷九十引《墨莊漫錄》。","）（見《墨莊漫錄》卷一，云爲元符初胡咏之在信州弋陽縣見道人所題詩，時人推測此道人「必爲呂翁」。","）。"]', '["濟世應須不世才，調羹重见用鹽梅。","種成白璧人何处，熟了黄粱梦未回。","相府旧开延士閣，武夷新築望仙台。","青雞唱徹函关晓，好卷游幃归去来。","（见《宋诗紀事》卷九十引《墨莊漫錄》。","）（见《墨莊漫錄》卷一，云爲元符初胡咏之在信州弋陽縣见道人所題诗，时人推測此道人「必爲呂翁」。","）。"]', '诗', 'shi', '', NULL, '書與胡咏之 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c84e73b-96fa-4883-85aa-21818c5cb5d9', '題冢上亭', '題冢上亭', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["冢上爲亭鬼莫嗔，冢頭人即冢中人。","凭蘭莫起存亡意，除卻虛空總是塵。","（同前引《西溪叢語》。","）（見《西溪叢語》卷上。","）（〖1〗《西溪叢語》〖宋姚寬撰〗：「襄漢隱者躬耕數畝，因古冢爲亭，往來題詩甚富。","」一日，柱間得一絕。","相傳呂翁作也。","）。"]', '["冢上爲亭鬼莫嗔，冢头人即冢中人。","凭蘭莫起存亡意，除卻虛空總是塵。","（同前引《西溪叢語》。","）（见《西溪叢語》卷上。","）（〖1〗《西溪叢語》〖宋姚寬撰〗：「襄漢隐者躬耕數畝，因古冢爲亭，往来題诗甚富。","」一日，柱间得一絕。","相傳呂翁作也。","）。"]', '诗', 'shi', '', NULL, '題冢上亭 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4916981a-a7fa-4b43-843e-88cc3e17f1cb', '題崇元觀（在吉水縣）', '題崇元观（在吉水縣）', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["褰裳嬾步尋真宿，清景一宵吟不足。","月在碧潭風在松，何必洞天三十六。","（同前引宋祝穆撰《方輿勝覽》。","見《方輿勝覽》卷二十《吉州》。","）。"]', '["褰裳嬾步尋真宿，清景一宵吟不足。","月在碧潭风在松，何必洞天三十六。","（同前引宋祝穆撰《方輿勝覽》。","见《方輿勝覽》卷二十《吉州》。","）。"]', '诗', 'shi', '', NULL, '題崇元觀（在吉水縣） 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd52be35-d17c-4bbb-a12b-f15d8e50606f', '題靈石屋山', '題靈石屋山', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["南塢數回泉石，西峯幾疊烟雲。","登攜孰以爲侶，顏寓李甲蕭耘。","（同前《宋詩紀事》。","）（〖1〗《竹坡詩話》〖宋周紫芝撰〗：「西湖諸寺，所存無幾，唯南山靈石，猶是舊屋。","寺僧言，頃有數道人來丐食，拒而不與，乃題詩屋山而去。","至今猶存，字畫頗類李北海。","好事者釋之，乃是呂洞賓與三人來耳。","」）。"]', '["南塢數回泉石，西峯幾叠烟云。","登携孰以爲侶，顏寓李甲蕭耘。","（同前《宋诗紀事》。","）（〖1〗《竹坡诗話》〖宋周紫芝撰〗：「西湖諸寺，所存無幾，唯南山靈石，猶是旧屋。","寺僧言，頃有數道人来丐食，拒而不與，乃題诗屋山而去。","至今猶存，字畫頗類李北海。","好事者釋之，乃是呂洞賓與三人来耳。","」）。"]', '诗', 'shi', '', NULL, '題靈石屋山 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30acfef2-067a-4ff3-98ad-b846c25bc9ff', '歸隱（《永樂大典》題作《偶題》）', '归隐（《永乐大典》題作《偶題》）', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["十年蹤跡走紅塵，回首青山入夢頻。","紫陌縱榮爭及睡，朱門雖富（《大典》「富」作「貴」）不如貧。","愁聞劍戟扶危主，悶聽（《大典》「聽」作「見」）笙歌聒醉人。","攜取琴（《大典》「琴」作「舊」）書歸舊隱，野花啼鳥一般春。","（見北京圖書館藏《永樂大典》卷一三四五○。","二寘）。","處士門。","《宋詩紀事》卷五收陳詩七首。","其《歸隱》一首與《大典》同。","惟《大典》題作《偶題》。","其《辭上歸進詩》，作於入宋之後，茲編不取。","餘五首，一首複出。","故但錄其四首。","（又按此詩亦見元辛文房《唐才子傳》卷十。","）（〖1〗邵伯溫《易學辨惑》云：摶隱居華陰山，自晉以後，每聞一朝革命，顰蹙數日。","人有問者，瞪目不答。","一日，乘驢過華陰市，聞太祖登極，大笑。","問其故，曰：「天下自此定矣。","」遁迹之初，作此詩云云，豈淺丈夫哉。","〖見《五朝名臣言行錄》卷十引邵伯溫《易學辨惑》。","此處錄文有刪節。","〗）。"]', '["十年蹤跡走紅塵，回首青山入梦頻。","紫陌縱榮爭及睡，朱门雖富（《大典》「富」作「貴」）不如貧。","愁闻劍戟扶危主，悶听（《大典》「听」作「见」）笙歌聒醉人。","携取琴（《大典》「琴」作「旧」）书归旧隐，野花啼鸟一般春。","（见北京圖书館藏《永乐大典》卷一三四五○。","二寘）。","处士门。","《宋诗紀事》卷五收陳诗七首。","其《归隐》一首與《大典》同。","惟《大典》題作《偶題》。","其《辞上归進诗》，作於入宋之後，茲編不取。","餘五首，一首複出。","故但錄其四首。","（又按此诗亦见元辛文房《唐才子傳》卷十。","）（〖1〗邵伯溫《易学辨惑》云：摶隐居华陰山，自晉以後，每闻一朝革命，顰蹙數日。","人有问者，瞪目不答。","一日，乘驢過华陰市，闻太祖登極，大笑。","问其故，曰：「天下自此定矣。","」遁迹之初，作此诗云云，豈淺丈夫哉。","〖见《五朝名臣言行錄》卷十引邵伯溫《易学辨惑》。","此处錄文有刪節。","〗）。"]', '诗', 'shi', '', NULL, '歸隱（《永樂大典》題作《偶題》） 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063ca9c0-cf9f-46c8-9110-3d50dcf08405', '石刻詩（幷序）', '石刻诗（幷序）', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["我謂浮榮真是幻，醉來捨轡謁高公。","因聆玄論冥冥理，轉覺塵寰一夢中。","（見《宋詩紀事》卷五引《老學庵筆記》。","）（見《老學庵筆記》卷六。","末附引文有刪節。","）（〖1〗《老學菴筆記》：卭州天慶觀石刻希夷詩云云。","末書太歲丁酉，蓋蜀孟昶時，當石晉天福中也。","文與可跋云：「高公者，此觀都威儀何昌一也，希夷從之學鎖鼻術。","」）。"]', '["我謂浮榮真是幻，醉来捨轡謁高公。","因聆玄論冥冥理，轉覺塵寰一梦中。","（见《宋诗紀事》卷五引《老学庵笔記》。","）（见《老学庵笔記》卷六。","末附引文有刪節。","）（〖1〗《老学菴笔記》：卭州天慶观石刻希夷诗云云。","末书太歲丁酉，蓋蜀孟昶时，當石晉天福中也。","文與可跋云：「高公者，此观都威儀何昌一也，希夷從之学鎖鼻術。","」）。"]', '诗', 'shi', '', NULL, '石刻詩（幷序） 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f96bc4cd-abf1-4a93-944a-e21836d1869f', '贈張乖厓', '贈張乖厓', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["自吳入蜀是尋常，歌舞筵中救火忙。","乞得金陵養閑散，也須多謝鬢邊瘡。","（見《宋詩紀事》卷五。","）（見《湘山野錄》卷上、《夢溪筆談》卷二十。","）（〖1〗《古今詩話》：「張忠定公少謁華山陳圖南，圖南贈詩一絕，始皆不喻其意。","後忠定更鎮杭益，晚年發瘡於鬢，移守金陵，遂薨，悉如其言。","」）。"]', '["自吳入蜀是尋常，歌舞筵中救火忙。","乞得金陵養闲散，也須多謝鬢邊瘡。","（见《宋诗紀事》卷五。","）（见《湘山野錄》卷上、《梦溪笔談》卷二十。","）（〖1〗《古今诗話》：「張忠定公少謁华山陳圖南，圖南贈诗一絕，始皆不喻其意。","後忠定更鎮杭益，晚年發瘡於鬢，移守金陵，遂薨，悉如其言。","」）。"]', '诗', 'shi', '', NULL, '贈張乖厓 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7df8bbd-dcdc-469e-b106-b73309596010', '訪毛女（見《宋詩紀事》引《翰府名談》。按《全唐詩》卷八百六十三作毛女正美詩。此詩第二句「又編栗葉作羅襦」，「作」，《全唐詩》作「代」。三句「有時問著秦宮事」，「著」，《全唐詩》作「卻」。四句「笑撚仙花望太虛」，「仙」，《全唐詩》作「山」。餘同。〗〖見《增修詩話總龜》卷四四引《翰府名談》。〗）', '訪毛女（见《宋诗紀事》引《翰府名談》。按《全唐诗》卷八百六十三作毛女正美诗。此诗第二句「又編栗葉作羅襦」，「作」，《全唐诗》作「代」。三句「有时问著秦宮事」，「著」，《全唐诗》作「卻」。四句「笑撚仙花望太虛」，「仙」，《全唐诗》作「山」。餘同。〗〖见《增修诗話總龟》卷四四引《翰府名談》。〗）', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '訪毛女（見《宋詩紀事》引《翰府名談》。按《全唐詩》卷八百六十三作毛女正美詩。此詩第二句「又編栗葉作羅襦」，「作」，《全唐詩》作「代」。三句「有時問著秦宮事」，「著」，《全唐詩》作「卻」。四句「笑撚仙花望太虛」，「仙」，《全唐詩》作「山」。餘同。〗〖見《增修詩話總龜》卷四四引《翰府名談》。〗） 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f606c00-4d7f-4e92-ac0c-a95fe81843c6', '西峯', '西峯', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["爲愛西峯好，吟頭盡日昂。","岩花紅作陣，溪水綠成行。","幾夜礙新月，半山無夕陽。","寄言嘉遯客，此處是仙鄉。","（見《宋詩紀事》卷五引宋魏慶之撰《詩人玉屑》。","）（見《詩人玉屑》卷二十《方外》，不注出處。","又見《增修詩話總龜》卷四六引《翰府名談》。","）。"]', '["爲愛西峯好，吟头尽日昂。","岩花紅作陣，溪水綠成行。","幾夜礙新月，半山無夕陽。","寄言嘉遯客，此处是仙乡。","（见《宋诗紀事》卷五引宋魏慶之撰《诗人玉屑》。","）（见《诗人玉屑》卷二十《方外》，不注出处。","又见《增修诗話總龟》卷四六引《翰府名談》。","）。"]', '诗', 'shi', '', NULL, '西峯 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc91ca1f-4d20-4cde-bb39-b44d00310288', '題石水澗', '題石水澗', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["銀河灑落翠光冷，一派迴環[湛]（淡）晚暉。","幾恨卻爲頑石尵，琉璃滑處玉花飛。","（見《宋詩紀事》卷五引明李蔉輯《宋藝圃集》。","）（見《宋藝圃集》卷一，又見《增修詩話總龜》卷四四引《翰府名談》。","「淡」，二書皆作「湛」，今據改。","）。"]', '["銀河灑落翠光冷，一派迴环[湛]（淡）晚暉。","幾恨卻爲頑石尵，琉璃滑处玉花飞。","（见《宋诗紀事》卷五引明李蔉輯《宋藝圃集》。","）（见《宋藝圃集》卷一，又见《增修诗話總龟》卷四四引《翰府名談》。","「淡」，二书皆作「湛」，今據改。","）。"]', '诗', 'shi', '', NULL, '題石水澗 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd780dc1-6817-419c-b9b7-3d19b15ec70f', '楊勛吟詩', '楊勛吟诗', '210a75d1-9127-4c07-83ea-124dd583d52a', '唐', '["聖主何曾識仲都，可憐社禝在須臾。","市西便是神仙窟，何必乘楂汎五湖。","（《全唐詩》卷八六三收此詩，作者作楊損，題作《臨刑賦》，殆據《萬首唐人絕句》卷六八收入。","）（按宋人撰《新編分門古今類事》卷二載此詩，云：「楊勛者，前蜀後主乾德中，世號楊僕射，不知何處人，變化無常。","爲後主召羣仙於薫風殿，刑部侍郎潘嬌奏其妖怪，帝命武士於相市戮之。","隨刃化爲草，人未至所法處。","僕射吟詩曰云云。","其年冬，後主失國，果如其言，此亦可以知興廢之有前定也。","」注云「出《洞微志》」。","事雖不經，準《全唐詩》例，姑錄之以入神仙鬼怪卷。","）。"]', '["聖主何曾識仲都，可怜社禝在須臾。","市西便是神仙窟，何必乘楂汎五湖。","（《全唐诗》卷八六三收此诗，作者作楊損，題作《臨刑賦》，殆據《万首唐人絕句》卷六八收入。","）（按宋人撰《新編分门古今類事》卷二載此诗，云：「楊勛者，前蜀後主乾德中，世號楊僕射，不知何处人，变化無常。","爲後主召羣仙於薫风殿，刑部侍郎潘嬌奏其妖怪，帝命武士於相市戮之。","隨刃化爲草，人未至所法处。","僕射吟诗曰云云。","其年冬，後主失国，果如其言，此亦可以知兴廢之有前定也。","」注云「出《洞微志》」。","事雖不經，準《全唐诗》例，姑錄之以入神仙鬼怪卷。","）。"]', '诗', 'shi', '', NULL, '楊勛吟詩 楊勛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('303adfbd-6f46-4527-b498-17380382ba8d', '', '', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["（案《全唐詩》無崔致遠詩。","日本河世寧《全唐詩逸》卷中收致遠詩一首又句七聯。","此六十首詩載致遠所著《桂苑筆耕集》〖有《四部叢刊》本〗。","今即自《叢刊》本錄出，而以南京圖書館所藏高麗聚珍活字本校之。","）。"]', '["（案《全唐诗》無崔致远诗。","日本河世寧《全唐诗逸》卷中收致远诗一首又句七聯。","此六十首诗載致远所著《桂苑笔耕集》〖有《四部叢刊》本〗。","今即自《叢刊》本錄出，而以南京圖书館所藏高丽聚珍活字本校之。","）。"]', '诗', 'shi', '', NULL, ' 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea1e87e9-4157-4f02-a2e9-eda3b2cdd13c', '七言記德詩三十首謹獻司徒相公 兵機', '七言記德诗三十首謹獻司徒相公 兵機', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["惟將志業練《春秋》，早蓄雄心剗國讐。","二十年來天下事，漢皇高枕倚留侯。"]', '["惟將志業練《春秋》，早蓄雄心剗国讐。","二十年来天下事，漢皇高枕倚留侯。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 兵機 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a0cea7-b0fa-4f9d-a789-4a5fdf0efb5d', '七言記德詩三十首謹獻司徒相公 筆法', '七言記德诗三十首謹獻司徒相公 笔法', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["見說書窗暫臥龍，神傳妙訣助奇鋒。","也知外國人爭學，惟恨無因乞手蹤。","（原注：南朝蕭子雲〖高麗本作蘇子雲〗善書，百濟使人求手蹤，以爲國寶。","）。"]', '["见说书窗暫臥龙，神傳妙訣助奇鋒。","也知外国人爭学，惟恨無因乞手蹤。","（原注：南朝蕭子云〖高丽本作蘇子云〗善书，百濟使人求手蹤，以爲国寶。","）。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 筆法 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c45e6575-88db-4fe6-afdd-14d0da7abe98', '七言記德詩三十首謹獻司徒相公 性箴', '七言記德诗三十首謹獻司徒相公 性箴', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["波澄性海見深源，理究希夷闢道門。","詞翰好傳雙美跡，何須更寫五千言。"]', '["波澄性海见深源，理究希夷闢道门。","词翰好傳雙美跡，何須更寫五千言。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 性箴 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7309f6b-0c15-48b7-8471-39f17c8a5a1c', '七言記德詩三十首謹獻司徒相公 雪咏', '七言記德诗三十首謹獻司徒相公 雪咏', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["五色毫編六出花，三冬吟徹四方誇。","始知絕句勝聯句，從外芳名掩謝家。"]', '["五色毫編六出花，三冬吟徹四方誇。","始知絕句勝聯句，從外芳名掩謝家。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 雪咏 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a56ce954-6356-48b3-83fc-34044dddad61', '七言記德詩三十首謹獻司徒相公 射鵰', '七言記德诗三十首謹獻司徒相公 射鵰', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["能將一箭落雙鵰，萬里胡塵當日銷。","永使威名振沙漠，犬戎無復吠唐堯。"]', '["能將一箭落雙鵰，万里胡塵當日銷。","永使威名振沙漠，犬戎無复吠唐堯。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 射鵰 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09de181e-e3f6-4e0c-b50a-9b931784cbcf', '七言記德詩三十首謹獻司徒相公 安化', '七言記德诗三十首謹獻司徒相公 安化', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["班筆由起來不暗投，旋驅熊隼待封侯。","郡名安化能宣化，更指河湟地欲收。"]', '["班笔由起来不暗投，旋驱熊隼待封侯。","郡名安化能宣化，更指河湟地欲收。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 安化 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b93e21c8-c606-4c7c-848c-b4ec4a7a1b37', '七言記德詩三十首謹獻司徒相公 練兵', '七言記德诗三十首謹獻司徒相公 練兵', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["隴水聲秋塞草閑，霍將軍暫入長安。","太平天子憐才略，曾請陳兵盡日看。"]', '["隴水声秋塞草闲，霍將軍暫入长安。","太平天子怜才略，曾請陳兵尽日看。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 練兵 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2faa0b-3d80-4bf3-9a25-694e452f68e1', '七言記德詩三十首謹獻司徒相公 磻溪', '七言記德诗三十首謹獻司徒相公 磻溪', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["刻石書蹤妙入神，一廻窺覽一廻新。","況能早逐王師業，桃李終成萬代春。","（原注：伏覩相公《磻溪詩》云：「及到王師身已老，不知辛苦爲何人。","」又《經虢縣詩》云：「手栽桃李十餘春，今日經過重建勳。","」）。"]', '["刻石书蹤妙入神，一廻窺覽一廻新。","況能早逐王師業，桃李終成万代春。","（原注：伏覩相公《磻溪诗》云：「及到王師身已老，不知辛苦爲何人。","」又《經虢縣诗》云：「手栽桃李十餘春，今日經過重建勳。","」）。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 磻溪 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('676e724a-586e-41fc-a445-1c9bad306b9e', '七言記德詩三十首謹獻司徒相公 射虎', '七言記德诗三十首謹獻司徒相公 射虎', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["鉅牙鉤爪礙王程，一箭摧班（高麗本班作斑。","）四海驚。","白額前驅姜膽碎，方知破石是虛聲。"]', '["鉅牙鉤爪礙王程，一箭摧班（高丽本班作斑。","）四海驚。","白額前驱姜膽碎，方知破石是虛声。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 射虎 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4801868-06ba-4d54-bb1d-0a42ec6833ce', '七言記德詩三十首謹獻司徒相公 秦城', '七言記德诗三十首謹獻司徒相公 秦城', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["遠提龍劍鎮龍庭，外戶從茲永罷扃。","掃盡邊塵更無事，暮天寒角醉吟聽。"]', '["远提龙劍鎮龙庭，外戶從茲永罷扃。","掃尽邊塵更無事，暮天寒角醉吟听。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 秦城 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea301b78-3764-45b4-b620-a51e4e2daf9f', '七言記德詩三十首謹獻司徒相公 生祠', '七言記德诗三十首謹獻司徒相公 生祠', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["古來難化是蠻夷，交趾何人得去思。","萬代聖朝青史上，獨傳溪洞立生祠。"]', '["古来难化是蠻夷，交趾何人得去思。","万代聖朝青史上，独傳溪洞立生祠。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 生祠 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c500b99-0b91-4d3d-b12a-6bf03a98c713', '七言記德詩三十首謹獻司徒相公 射鞭', '七言記德诗三十首謹獻司徒相公 射鞭', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["休說戟枝非易中，莫言楊葉是難穿。","須看立節吵場上，永得安邊爲射鞭。"]', '["休说戟枝非易中，莫言楊葉是难穿。","須看立節吵場上，永得安邊爲射鞭。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 射鞭 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0a913a-04fe-4c12-820f-4684616eb298', '七言記德詩三十首謹獻司徒相公 安南', '七言記德诗三十首謹獻司徒相公 安南', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["西戎始定南蠻起，都護能摧驃信威。","萬里封疆萬戶口，一麾風雨盡收歸。"]', '["西戎始定南蠻起，都護能摧驃信威。","万里封疆万戶口，一麾风雨尽收归。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 安南 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec92f8b-c404-4b93-ab89-876f6d9bae71', '七言記德詩三十首謹獻司徒相公 天威徑', '七言記德诗三十首謹獻司徒相公 天威徑', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["鑿斷龍門猶勞身，擘分華嶽徒稱神。","如何劈開海山道，坐令八國爭來賓。"]', '["鑿斷龙门猶勞身，擘分华嶽徒稱神。","如何劈开海山道，坐令八国爭来賓。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 天威徑 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef63d15f-85ff-4aca-b70c-7c564f34b7ec', '七言記德詩三十首謹獻司徒相公 岝口徑', '七言記德诗三十首謹獻司徒相公 岝口徑', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["濟物能廻造化心，驅山偃海立功深。","安南真得安南界，從此蠻兵不敢侵。"]', '["濟物能廻造化心，驱山偃海立功深。","安南真得安南界，從此蠻兵不敢侵。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 岝口徑 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf73256-ac19-4a7a-bef8-6960f83feb44', '七言記德詩三十首謹獻司徒相公 收城碑', '七言記德诗三十首謹獻司徒相公 收城碑', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["功業已標征北賦，威名初建鎮南碑。","終知不朽齊銅柱，況是儒宗綴色絲。","（原注：碑，今度支裴僕射撰詞。","）。"]', '["功業已標征北賦，威名初建鎮南碑。","終知不朽齊銅柱，況是儒宗綴色絲。","（原注：碑，今度支裴僕射撰词。","）。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 收城碑 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68891b4c-8172-4b77-8e17-b899667f1827', '七言記德詩三十首謹獻司徒相公 執金吾', '七言記德诗三十首謹獻司徒相公 執金吾', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["一陣風雷定八蠻，來趨雲陛悅天顏。","王孫仕宦多榮貴，心爲匡君不蹔閑。","。"]', '["一陣风雷定八蠻，来趨云陛悅天顏。","王孫仕宦多榮貴，心爲匡君不蹔闲。","。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 執金吾 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c765f6ee-adfc-4fab-ba81-463d10f9a588', '七言記德詩三十首謹獻司徒相公 天平', '七言記德诗三十首謹獻司徒相公 天平', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["海岱烟塵匝鄆城，遙揮一劍落攙搶。","征旗不動降旗盡，永使天平地亦平。"]', '["海岱烟塵匝鄆城，遙揮一劍落攙搶。","征旗不动降旗尽，永使天平地亦平。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 天平 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7a81c4-b034-4004-9cc4-f79777c77286', '七言記德詩三十首謹獻司徒相公 釣魚亭', '七言記德诗三十首謹獻司徒相公 釣鱼亭', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["錦筵花下飛鸎鵡，羅袖風前唱《鷓鴣》。","占得仙家詩酒興，閑吟烟月憶蓬壺。","（原注：伏覩相公《在鄆州詩》：云：「酒滿金舡花滿枝，雙娥齊唱《鷓鴣詞》。","」又《釣魚亭詩》云：「水急魚對釣，風吹柳易低。","」）。"]', '["錦筵花下飞鸎鵡，羅袖风前唱《鷓鴣》。","占得仙家诗酒兴，闲吟烟月憶蓬壺。","（原注：伏覩相公《在鄆州诗》：云：「酒满金舡花满枝，雙娥齊唱《鷓鴣词》。","」又《釣鱼亭诗》云：「水急鱼对釣，风吹柳易低。","」）。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 釣魚亭 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55de5fb-35e2-4bf8-bedb-751af81b7cd2', '七言記德詩三十首謹獻司徒相公 相印', '七言記德诗三十首謹獻司徒相公 相印', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["早說休徵應佩刀，台星光接將星高。","欲迎霖雨歸龍闕，看滅妖氛展豹韜。"]', '["早说休徵應佩刀，台星光接將星高。","欲迎霖雨归龙闕，看滅妖氛展豹韜。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 相印 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e114bfdc-ab11-4ce3-a6e2-5459f41069a1', '七言記德詩三十首謹獻司徒相公 西川', '七言記德诗三十首謹獻司徒相公 西川', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["遠持龍斾活龜城，威懾蒙王永罷兵。","應笑欒巴噀盃酒，雨師風伯自歸行。"]', '["远持龙斾活龟城，威懾蒙王永罷兵。","應笑欒巴噀盃酒，雨師风伯自归行。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 西川 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bde778f-e3b8-4e7c-a0d4-4172395bcf3a', '七言記德詩三十首謹獻司徒相公 平蠻', '七言記德诗三十首謹獻司徒相公 平蠻', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["卭峽關東蠻塵絕，平夷鎮扼蠻地裂。","又築羅城變錦城，蠻兵永滅功不滅。"]', '["卭峽关东蠻塵絕，平夷鎮扼蠻地裂。","又築羅城变錦城，蠻兵永滅功不滅。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 平蠻 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('676adf7f-226f-4dc2-b9a6-65eb2ec9177e', '七言記德詩三十首謹獻司徒相公 築城', '七言記德诗三十首謹獻司徒相公 築城', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["一心能感衆心齊，鐵甕高吞劍閣低。","多上散花樓上望，江山供盡好詩題。"]', '["一心能感衆心齊，鐵甕高吞劍閣低。","多上散花楼上望，江山供尽好诗題。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 築城 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('011cf781-3fd0-4db4-9590-10220f2f2009', '七言記德詩三十首謹獻司徒相公 荆南', '七言記德诗三十首謹獻司徒相公 荆南', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["虎吼龍驤出峽來，福星才照陣雲開。","遙思屈宋忠魂在，應向風前奠前一杯。"]', '["虎吼龙驤出峽来，福星才照陣云开。","遙思屈宋忠魂在，應向风前奠前一杯。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 荆南 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f705e773-404b-4151-926d-f0ba70d00c45', '七言記德詩三十首謹獻司徒相公 漕運', '七言記德诗三十首謹獻司徒相公 漕運', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["濟川已展爲舟業，煮海終成富國功。","能與吾君緩宵旰，爲資心計四方通。"]', '["濟川已展爲舟業，煮海終成富国功。","能與吾君緩宵旰，爲資心計四方通。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 漕運 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b581bca-fa71-4c9b-b8b7-a8461a8b4bd3', '七言記德詩三十首謹獻司徒相公 浙西', '七言記德诗三十首謹獻司徒相公 浙西', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["九江賊膽望風摧，萬戶愁眉向日開。","楚舞吳歌一何樂，相逢相賀相公來。"]', '["九江賊膽望风摧，万戶愁眉向日开。","楚舞吳歌一何乐，相逢相賀相公来。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 浙西 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd8e30f-a818-45aa-b46a-3b60855d53de', '七言記德詩三十首謹獻司徒相公 降寇', '七言記德诗三十首謹獻司徒相公 降寇', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["唯將德化欲銷兵，長笑成長平恣意坑。","更想太丘行小惠，何如言下濟羣生。"]', '["唯將德化欲銷兵，长笑成长平恣意坑。","更想太丘行小惠，何如言下濟羣生。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 降寇 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a46e7b4-09a1-4921-afd1-bacafaf7ddc7', '七言記德詩三十首謹獻司徒相公 淮南', '七言記德诗三十首謹獻司徒相公 淮南', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["八郡榮超陶太尉，三邊靜掩霍嫖姚。","玉皇終日留金鼎，應待淮王手自調。","（原注：劍南、荆南、淮南，乃天下名鎮，相公累移節制。","西戎、南蠻、東鄙賊起，相公皆自討除。","）。"]', '["八郡榮超陶太尉，三邊静掩霍嫖姚。","玉皇終日留金鼎，應待淮王手自調。","（原注：劍南、荆南、淮南，乃天下名鎮，相公累移節制。","西戎、南蠻、东鄙賊起，相公皆自討除。","）。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 淮南 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308b1b55-656b-4546-b865-823cbb69235a', '七言記德詩三十首謹獻司徒相公 朝上清', '七言記德诗三十首謹獻司徒相公 朝上清', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["齊心不倦自朝真，豈爲修仙欲濟人。","天上香風吹楚澤，江南江北鎮成春。"]', '["齊心不倦自朝真，豈爲修仙欲濟人。","天上香风吹楚澤，江南江北鎮成春。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 朝上清 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1464483d-3c24-486a-b54b-f6a63ffd03b6', '七言記德詩三十首謹獻司徒相公 陳情', '七言記德诗三十首謹獻司徒相公 陳情', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["俗眼難窺冰雪姿，終朝共詠小山詞。","此身依托同鷄犬，他日昇天莫棄遺。","（按以上三十首詩見《桂苑筆耕集》第十七卷，前有《獻詩啓》，畧謂：「如某者，跡自外方，藝唯下品。","雖儒宮慕善，每嘗窺顏冉之牆，而筆陣爭雄，未得摩曹劉之壘。","但以幸遊樂國，獲覩仁風，久貯懇誠，冀伸歌詠，輒獻紀德絕句詩三十首，謹封如別。","」）。"]', '["俗眼难窺冰雪姿，終朝共詠小山词。","此身依托同鷄犬，他日昇天莫棄遺。","（按以上三十首诗见《桂苑笔耕集》第十七卷，前有《獻诗啓》，畧謂：「如某者，跡自外方，藝唯下品。","雖儒宮慕善，每嘗窺顏冉之牆，而笔陣爭雄，未得摩曹劉之壘。","但以幸游乐国，獲覩仁风，久貯懇誠，冀伸歌詠，輒獻紀德絕句诗三十首，謹封如別。","」）。"]', '诗', 'shi', '', NULL, '七言記德詩三十首謹獻司徒相公 陳情 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e2d4fc-8ad2-418c-a389-80150482e184', '陳情上太尉', '陳情上太尉', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["海內誰憐海外人，問津何處是通津。","本求食祿非求利，只爲榮親不爲身。","客路離愁江上雨，故園歸夢日邊春。","濟川幸遇恩波廣，願濯凡纓十載塵。"]', '["海內誰怜海外人，问津何处是通津。","本求食祿非求利，只爲榮親不爲身。","客路離愁江上雨，故园归梦日邊春。","濟川幸遇恩波廣，願濯凡纓十載塵。"]', '诗', 'shi', '', NULL, '陳情上太尉 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('862f380a-486f-461d-8238-ab087b2f70e7', '奉和座主尚書避難過維陽寵示絕句三首（「陽」，疑當作「揚」。） 一', '奉和座主尚书避难過維陽寵示絕句三首（「陽」，疑當作「揚」。） 一', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["年年荆棘侵儒苑，處處烟塵滿戰場。","豈料今朝覲宣父，豁開凡眼睹文章。"]', '["年年荆棘侵儒苑，处处烟塵满戰場。","豈料今朝覲宣父，豁开凡眼睹文章。"]', '诗', 'shi', '', NULL, '奉和座主尚書避難過維陽寵示絕句三首（「陽」，疑當作「揚」。） 一 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b93029df-0223-4f79-a052-bf564c253eec', '奉和座主尚書避難過維陽寵示絕句三首（「陽」，疑當作「揚」。） 二', '奉和座主尚书避难過維陽寵示絕句三首（「陽」，疑當作「揚」。） 二', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["亂時無事不悲傷，鸞鳯驚飛出帝鄉。","應念浴沂諸弟子，每逢春色耿離腸。"]', '["亂时無事不悲傷，鸾鳯驚飞出帝乡。","應念浴沂諸弟子，每逢春色耿離腸。"]', '诗', 'shi', '', NULL, '奉和座主尚書避難過維陽寵示絕句三首（「陽」，疑當作「揚」。） 二 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b66b5e-4b22-4f7e-a35e-18ea6a5ffae1', '奉和座主尚書避難過維陽寵示絕句三首（「陽」，疑當作「揚」。） 三', '奉和座主尚书避难過維陽寵示絕句三首（「陽」，疑當作「揚」。） 三', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["濟川終望拯湮沉，喜捧清詞渲俗襟。","唯根吟歸滄海去，泣珠何計報恩深。"]', '["濟川終望拯湮沉，喜捧清词渲俗襟。","唯根吟归滄海去，泣珠何計報恩深。"]', '诗', 'shi', '', NULL, '奉和座主尚書避難過維陽寵示絕句三首（「陽」，疑當作「揚」。） 三 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d189f2-cbb1-41ce-9d14-c302e0876f20', '歸燕吟獻太尉', '归燕吟獻太尉', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["秋去春來能守信，暖風凉雨飽相諳。","再依大厦雖知許，久污雕梁却自慙。","深避鷹鸇投海島，羨他鴛鷺戲江潭。","只將名品齊黃雀，獨讓銜環意未甘。"]', '["秋去春来能守信，暖风凉雨飽相諳。","再依大厦雖知許，久污雕梁却自慙。","深避鷹鸇投海島，羨他鴛鷺戲江潭。","只將名品齊黄雀，独讓銜环意未甘。"]', '诗', 'shi', '', NULL, '歸燕吟獻太尉 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f30e886-4571-49dc-8c19-72e2a72258a9', '酬楊贍秀才送別', '酬楊贍秀才送別', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["海槎雖定隔年廻，衣錦還鄉愧不才。","暫別蕪城當葉落，遠尋蓬島趂花開。","谷鸎遙想高飛去，（原注：時楊生有隨計〖高麗本計作行〗之計。","）遼豕寧慙再獻來。","好把壯心謀後會，廣陵風月待銜杯。"]', '["海槎雖定隔年廻，衣錦還乡愧不才。","暫別蕪城當葉落，远尋蓬島趂花开。","谷鸎遙想高飞去，（原注：时楊生有隨計〖高丽本計作行〗之計。","）遼豕寧慙再獻来。","好把壯心謀後會，廣陵风月待銜杯。"]', '诗', 'shi', '', NULL, '酬楊贍秀才送別 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc1a23d-aa5a-4528-97a5-0b8b99fb8e00', '行次山陽續家太尉寄賜衣段令充歸覲續壽信物謹以詩謝', '行次山陽續家太尉寄賜衣段令充归覲續壽信物謹以诗謝', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["自古雖誇晝錦行，長卿翁子占虛名。","既傳國信兼家信，不獨家榮國亦榮。","萬里始成歸去計，一心先算却來程。","望中遙想深恩處，三朵仙山目畔橫。","。"]', '["自古雖誇晝錦行，长卿翁子占虛名。","既傳国信兼家信，不独家榮国亦榮。","万里始成归去計，一心先算却来程。","望中遙想深恩处，三朵仙山目畔橫。","。"]', '诗', 'shi', '', NULL, '行次山陽續家太尉寄賜衣段令充歸覲續壽信物謹以詩謝 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21071cc9-d7f0-4ad2-81b9-3f9cdbf7ee09', '留別女道士', '留別女道士', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["每恨塵中厄宦塗，數年深喜識麻姑。"]', '["每恨塵中厄宦塗，數年深喜識麻姑。"]', '诗', 'shi', '', NULL, '留別女道士 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae8b6960-0bb3-497b-8490-7f9d1eaec273', '酬進士楊贍送別', '酬進士楊贍送別', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["海山遙望曉烟濃，百幅帆張萬里風。","悲莫悲兮兒女事，不須怊悵別離中。"]', '["海山遙望晓烟濃，百幅帆張万里风。","悲莫悲兮兒女事，不須怊悵別離中。"]', '诗', 'shi', '', NULL, '酬進士楊贍送別 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('234ea344-0575-4702-9749-61f74961de20', '楚州張尚書水郭相迎因以詩謝', '楚州張尚书水郭相迎因以诗謝', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["楚天蕭瑟碧雲秋，旟隼高飛訪葉舟。","萬里乘槎從此去，預愁魂斷謝公樓。"]', '["楚天蕭瑟碧云秋，旟隼高飞訪葉舟。","万里乘槎從此去，預愁魂斷謝公楼。"]', '诗', 'shi', '', NULL, '楚州張尚書水郭相迎因以詩謝 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63beb744-b4e6-40e1-ba99-bf661b009483', '酬吳巒秀才惜別二絕句 一', '酬吳巒秀才惜別二絕句 一', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["榮祿危時未及親，莫嗟歧路蹔勞身。","今朝遠別無他語，一片心須不愧人。"]', '["榮祿危时未及親，莫嗟歧路蹔勞身。","今朝远別無他語，一片心須不愧人。"]', '诗', 'shi', '', NULL, '酬吳巒秀才惜別二絕句 一 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733b1199-7bd3-4f96-b0f1-46167069a460', '酬吳巒秀才惜別二絕句 二', '酬吳巒秀才惜別二絕句 二', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["殘日塞鴻高的的，暮烟汀樹遠依依。","此時回首情何限，天際孤帆窣浪飛。"]', '["殘日塞鴻高的的，暮烟汀樹远依依。","此时回首情何限，天際孤帆窣浪飞。"]', '诗', 'shi', '', NULL, '酬吳巒秀才惜別二絕句 二 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc991d6-7501-4970-8ff3-01b358d8d529', '石峰（原注：中和甲辰年冬十月，奉使東泛，泊舟於大珠山下。凡所入目，命爲篇名，嘯月吟風，貯成十首寄高員外。）', '石峰（原注：中和甲辰年冬十月，奉使东泛，泊舟於大珠山下。凡所入目，命爲篇名，嘯月吟风，貯成十首寄高員外。）', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["巉嵒絕頂欲摩天，海日初開一朶蓮。","勢削不容凡樹木，格高唯惹好雲烟。","點蘇寒影粧新雪，戞玉清音噴細泉。","靜想蓬萊只如此，應當月夜會羣仙。"]', '["巉嵒絕頂欲摩天，海日初开一朶蓮。","勢削不容凡樹木，格高唯惹好云烟。","点蘇寒影粧新雪，戞玉清音噴細泉。","静想蓬萊只如此，應當月夜會羣仙。"]', '诗', 'shi', '', NULL, '石峰（原注：中和甲辰年冬十月，奉使東泛，泊舟於大珠山下。凡所入目，命爲篇名，嘯月吟風，貯成十首寄高員外。） 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40c0e94d-32ab-457d-81db-0db75bdbbb60', '潮浪', '潮浪', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["驟雪翻霜千萬重，往來弦望躡前蹤。","見君終更能懷信，慚我趨時盡放慵。","石壁戰聲飛霹靂，雲峰倒影撼芙蓉。","因思宗慤長風語，壯氣橫生憶臥龍。","。"]', '["驟雪翻霜千万重，往来弦望躡前蹤。","见君終更能懷信，慚我趨时尽放慵。","石壁戰声飞霹靂，云峰倒影撼芙蓉。","因思宗慤长风語，壯氣橫生憶臥龙。","。"]', '诗', 'shi', '', NULL, '潮浪 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb22265-1d7f-4cd9-88fd-7c631866d5f7', '沙汀', '沙汀', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["遠看還似雪花飛，弱質由來不自持。","聚散只憑潮浪簸，高低況被海風吹。","煙籠靜練入行絕，日射凝霜鶴步遲。","別恨滿懷吟到夜，那堪又值月圓時。"]', '["远看還似雪花飞，弱質由来不自持。","聚散只憑潮浪簸，高低況被海风吹。","煙籠静練入行絕，日射凝霜鹤步遲。","別恨满懷吟到夜，那堪又值月圓时。"]', '诗', 'shi', '', NULL, '沙汀 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d51d31-9ac0-4287-a0cc-f77f8f23679d', '野燒', '野燒', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["望中旌斾忽繽紛，疑是橫行出塞軍。","猛焰燎空欺落日，狂煙遮野截歸雲。","莫嫌牛馬皆妨牧，須喜狐狸盡喪羣。","只恐風驅上山去，虛教玉石一時焚。"]', '["望中旌斾忽繽紛，疑是橫行出塞軍。","猛焰燎空欺落日，狂煙遮野截归云。","莫嫌牛马皆妨牧，須喜狐狸尽喪羣。","只恐风驱上山去，虛教玉石一时焚。"]', '诗', 'shi', '', NULL, '野燒 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30eca23c-a661-4186-8dc3-4949472201bc', '杜鵑', '杜鵑', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["石罅根危葉易乾，風霜偏覺見摧殘。","已饒野菊誇秋艷，應羨巖松保歲寒。","可惜含芳臨碧海，誰能移植到朱欄。","與凡草木還殊品，只恐樵夫一例看。"]', '["石罅根危葉易乾，风霜偏覺见摧殘。","已饒野菊誇秋艷，應羨巖松保歲寒。","可惜含芳臨碧海，誰能移植到朱欄。","與凡草木還殊品，只恐樵夫一例看。"]', '诗', 'shi', '', NULL, '杜鵑 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974fe869-9efb-4358-91b3-61a2953e1653', '海鷗', '海鷗', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["慢隨花浪飄飄然，輕擺毛衣真水仙。","出沒自由塵外境，往來□□洞中天。","稻粱滋味好不識，風月性靈深可憐。","想得漆園蝴蝶夢，只應如我對君眠。"]', '["慢隨花浪飄飄然，轻擺毛衣真水仙。","出沒自由塵外境，往来□□洞中天。","稻粱滋味好不識，风月性靈深可怜。","想得漆园蝴蝶梦，只應如我对君眠。"]', '诗', 'shi', '', NULL, '海鷗 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc8a10b-edc0-4698-baf9-4470dc601150', '山頂危石', '山頂危石', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["萬古天成勝琢磨，高高頂上立青螺。","永無飛溜侵凌得，唯有閑雲撥觸多。","峻影每先迎海日，危形長恐墜潮波。","縱饒蘊玉誰回顧，舉世謀身笑卞和。"]', '["万古天成勝琢磨，高高頂上立青螺。","永無飞溜侵凌得，唯有闲云撥觸多。","峻影每先迎海日，危形长恐墜潮波。","縱饒蘊玉誰回顧，舉世謀身笑卞和。"]', '诗', 'shi', '', NULL, '山頂危石 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476cd420-cfd7-4e75-a958-1530eaa29134', '石上矮松', '石上矮松', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["不材終得老煙霞，澗底何如在海涯。","日引暮陰齊島樹，風敲夜子落潮沙。","自能盤石根長固，豈恨凌雲路尚賒。","莫訝低顏無所愧，棟樑堪入晏嬰家。"]', '["不材終得老煙霞，澗底何如在海涯。","日引暮陰齊島樹，风敲夜子落潮沙。","自能盤石根长固，豈恨凌云路尚賒。","莫訝低顏無所愧，棟樑堪入晏嬰家。"]', '诗', 'shi', '', NULL, '石上矮松 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdbbc4d-109f-47bb-8e9a-69de07dbfdb8', '紅葉樹', '紅葉樹', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["白雲巖畔立仙姝，一簇烟蘿倚畫圖。","麗色也知於世有，閑情長得似君無。","宿粧含露疑垂泣，醉態迎風欲待扶。","吟對寒林却惆悵，山中猶自辨榮枯。"]', '["白云巖畔立仙姝，一簇烟蘿倚畫圖。","丽色也知於世有，闲情长得似君無。","宿粧含露疑垂泣，醉態迎风欲待扶。","吟对寒林却惆悵，山中猶自辨榮枯。"]', '诗', 'shi', '', NULL, '紅葉樹 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da536361-3d30-4161-b030-03ade0551043', '石上流泉', '石上流泉', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["琴曲雖誇妙手彈，遠輪雲底響珊珊。","靜無纖垢侵金鏡，時有輕飔觸玉盤。","嗚咽張良言未用，潺湲孫楚枕應寒。","尋思堪惜清冷色，流入滄溟便一般。"]', '["琴曲雖誇妙手彈，远輪云底响珊珊。","静無纖垢侵金镜，时有轻飔觸玉盤。","嗚咽張良言未用，潺湲孫楚枕應寒。","尋思堪惜清冷色，流入滄溟便一般。"]', '诗', 'shi', '', NULL, '石上流泉 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec63aa14-f009-4f52-95b2-5bbce6f7c129', '和友人除夜見寄', '和友人除夜见寄', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["與君相見且歌吟，莫恨流年挫壯心。","幸得東風已迎路，好花時節到鷄林。"]', '["與君相见且歌吟，莫恨流年挫壯心。","幸得东风已迎路，好花时節到鷄林。"]', '诗', 'shi', '', NULL, '和友人除夜見寄 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4717b79-d925-44ed-a7bc-9d5932154636', '東風', '东风', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["知爾新從海外來，曉窗吟坐思難裁。","堪憐時復撼書幌，似報故園花欲開。"]', '["知爾新從海外来，晓窗吟坐思难裁。","堪怜时复撼书幌，似報故园花欲开。"]', '诗', 'shi', '', NULL, '東風 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edcdce30-f778-48fa-8482-2862ab54dedc', '海邊春望', '海邊春望', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["鷗鷺分飛高復低，遠汀幽草欲萋萋。","此時千里萬里意，目極暮雲翻自迷。"]', '["鷗鷺分飞高复低，远汀幽草欲萋萋。","此时千里万里意，目極暮云翻自迷。"]', '诗', 'shi', '', NULL, '海邊春望 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee221c8-60bd-4655-972b-27cd6b346be1', '春曉閑望', '春晓闲望', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["山面嬾雲風惱散，岸頭頑雪日欺銷。","獨吟光景情何限，猶賴沙鷗伴寂寥。","。"]', '["山面嬾云风惱散，岸头頑雪日欺銷。","独吟光景情何限，猶賴沙鷗伴寂寥。","。"]', '诗', 'shi', '', NULL, '春曉閑望 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63135aa0-9eb7-48d8-bfe5-9af7b767576d', '海邊閑步', '海邊闲步', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["潮波靜退步登沙，落日山頭簇暮霞。","春色不應長惱我，看看即醉故園花。"]', '["潮波静退步登沙，落日山头簇暮霞。","春色不應长惱我，看看即醉故园花。"]', '诗', 'shi', '', NULL, '海邊閑步 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e866e2-6a15-43a9-8158-1bed1fefd377', '將歸海東巉山春望', '將归海东巉山春望', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["目極煙波浩渺間，曉烏飛處認鄉關。","旅愁從此休凋鬢，行色偏能助破顏。","浪蹙沙頭花撲岸，雲粧石頂葉籠山。","寄言來往鴟夷子，誰把千金解買閑。"]', '["目極煙波浩渺间，晓烏飞处認乡关。","旅愁從此休凋鬢，行色偏能助破顏。","浪蹙沙头花撲岸，云粧石頂葉籠山。","寄言来往鴟夷子，誰把千金解買闲。"]', '诗', 'shi', '', NULL, '將歸海東巉山春望 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b9ff08-bbe9-497b-bef0-0abf929ef080', '和金員外贈巉山清上人', '和金員外贈巉山清上人', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["海畔雲菴倚碧螺，遠離塵日稱僧家。","勸君休問芭蕉喻，看取春風撼浪花。"]', '["海畔云菴倚碧螺，远離塵日稱僧家。","勸君休问芭蕉喻，看取春风撼浪花。"]', '诗', 'shi', '', NULL, '和金員外贈巉山清上人 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('227b0278-f5e6-4dd1-90fb-0b8b18024b6f', '題海門蘭若柳', '題海门蘭若柳', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["廣陵城畔別蛾眉，豈料相逢在海涯。","只恐觀音菩薩惜，臨行不敢折纖枝。","（〖1〗以上三十首詩見《桂苑筆耕集》第二十卷。","〖2〗按南京圖書館藏有高麗活字印本《桂苑筆耕集》二十卷，前有高麗人洪奭周、徐有榘二序。","特節錄徐有榘序中有涉崔致遠行事者如次，其文曰：「《桂苑筆耕集》二十卷，新羅孤雲崔公在唐淮南幙府時公私應酬之作，而東還之後，手編表進於朝者也。","公名致遠，字海夫，孤雲其號也。","湖南之沃溝〖新羅地名〗人。","幼穎慧絶倫，年十二，從商舶入中原。","十八舉進士第。","久之，調溧水縣尉，任滿而罷。","時值黃巢之亂，諸道得營都統高駢開府淮南，辟公爲都統巡官，凡表狀文告，皆出公手。","其《討黃巢檄》，天下傳誦。","奏除殿中侍御史，賜緋魚袋。","後四年，充國信使東歸，事憲康王、定康王爲翰林學士、兵部侍郎，出爲武城太守。","真聖時，契家入江陽郡伽倻山以終焉。","葬在湖西之鴻山。","……」）。"]', '["廣陵城畔別蛾眉，豈料相逢在海涯。","只恐观音菩薩惜，臨行不敢折纖枝。","（〖1〗以上三十首诗见《桂苑笔耕集》第二十卷。","〖2〗按南京圖书館藏有高丽活字印本《桂苑笔耕集》二十卷，前有高丽人洪奭周、徐有榘二序。","特節錄徐有榘序中有涉崔致远行事者如次，其文曰：「《桂苑笔耕集》二十卷，新羅孤云崔公在唐淮南幙府时公私應酬之作，而东還之後，手編表進於朝者也。","公名致远，字海夫，孤云其號也。","湖南之沃溝〖新羅地名〗人。","幼穎慧絶倫，年十二，從商舶入中原。","十八舉進士第。","久之，調溧水縣尉，任满而罷。","时值黄巢之亂，諸道得營都統高駢开府淮南，辟公爲都統巡官，凡表狀文告，皆出公手。","其《討黄巢檄》，天下傳誦。","奏除殿中侍御史，賜緋鱼袋。","後四年，充国信使东归，事憲康王、定康王爲翰林学士、兵部侍郎，出爲武城太守。","真聖时，契家入江陽郡伽倻山以終焉。","葬在湖西之鴻山。","……」）。"]', '诗', 'shi', '', NULL, '題海門蘭若柳 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adbcc6cf-2a4e-4dae-8442-a94f85d93c90', '逢漢使入蕃略題四韻', '逢漢使入蕃略題四韻', '4e0b30ca-e528-46f0-b131-b9049ba8db31', '唐', '["君恨西蕃遠，余嗟東路長。","道荒宏雪嶺，險澗賊途倡。","鳥飛驚峭嶷，人去□偏樑。","平生不捫淚，今日灑千行。"]', '["君恨西蕃远，余嗟东路长。","道荒宏雪嶺，險澗賊途倡。","鸟飞驚峭嶷，人去□偏樑。","平生不捫泪，今日灑千行。"]', '诗', 'shi', '', NULL, '逢漢使入蕃略題四韻 慧超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b83bcf-3675-42ba-a651-17d24a1adfc4', '冬日在吐火羅逢雪述懷', '冬日在吐火羅逢雪述懷', '4e0b30ca-e528-46f0-b131-b9049ba8db31', '唐', '["冷雪牽冰合，寒風擘地烈。","巨海凍漫壇，江河凌崖囓。","龍門絕瀑布。","井口盤蛇結。","伴火上𮌑（垓）歌，焉能度播蜜。","（上詩見《大藏經》二○八九號《遊方記抄》中所載新羅僧慧超作《往五天竺國傳》，畧謂：「又從吐火羅國東行七日，至胡蜜王住城，當來於吐火羅國。","逢漢使入蕃，略題四韻，取辭五言〖詩不重錄〗。","冬日在吐火羅逢雪述懷，五言〖詩不重錄〗。","此胡蜜王兵馬少弱，不能自護，見屬大𥦽所管。","」云云。","又曰：「過播蜜川，即至葱嶺鎮。","」「開元十五年十一月上旬至安西。","於時節度大使趙君……」云云。","讀此則兩詩之作年可知矣。","）。"]', '["冷雪牽冰合，寒风擘地烈。","巨海凍漫壇，江河凌崖囓。","龙门絕瀑布。","井口盤蛇結。","伴火上𮌑（垓）歌，焉能度播蜜。","（上诗见《大藏經》二○八九號《游方記抄》中所載新羅僧慧超作《往五天竺国傳》，畧謂：「又從吐火羅国东行七日，至胡蜜王住城，當来於吐火羅国。","逢漢使入蕃，略題四韻，取辞五言〖诗不重錄〗。","冬日在吐火羅逢雪述懷，五言〖诗不重錄〗。","此胡蜜王兵马少弱，不能自護，见屬大𥦽所管。","」云云。","又曰：「過播蜜川，即至葱嶺鎮。","」「开元十五年十一月上旬至安西。","於时節度大使趙君……」云云。","读此則兩诗之作年可知矣。","）。"]', '诗', 'shi', '', NULL, '冬日在吐火羅逢雪述懷 慧超 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7405ece2-d677-4e8d-926e-3a3161f0e6cc', '後記', '後記', 'a554789a-604f-42fc-bec5-2f74a6899fbd', '唐', '["右《全唐詩補逸》二十卷。","是稿初印於丙子歲（一九三六年），當時收詩止二百七十有奇，暫分七卷，名曰《全唐詩補逸初稿》。","稱《初稿》者，蓋欲賡揚裒集，期畢功釐定於他日也。","其明年而蘆溝變起，舉家流徙，奔走萬里，藏書既失，舊業盡廢，甯居之不遑，奚論撰輯。","荏苒八載，抗戰勝利，始得復返金陵。","顧政敝民窮，生事維艱，丁彼衰世，徒知騰議於私室，已無心於學問矣。","及己丑歲（一九四九年）而雄旆南指，落葉東飄，日出曜景，積瘴煙銷，慶堯宇之得蘇，見山河之重締，薄海同歡，余寧獨異？","自來南師，將三十年矣，生計豐足，心神怡暢，得黨政之關懷，承師友之相勉，於教學之餘，復得游心翰府，繼事蒐聚，雖四凶逞虐之日，猶未嘗或輟。","積之既久，漸成卷帙，略加編次，合之舊稿，得詩近八百篇，離爲二十卷，仍其名曰《全唐詩補逸》。","自維頭白齒脫，精力有竭，而唐詩散佚，遠不止外，倘假我以年，其增輯續補，願待來日，則茲編雖稱《全唐詩補逸》，仍以初稿目之可耳。","惟昔丙子舊稿，收韋莊《秦婦吟》一首，又曾錄《雲謠集雜曲子》三十首及無名氏詞等爲一卷，今王重民氏《敦惶曲子詞集》及《補全唐詩》既悉數絬刊矣，故從刪。","又《全唐詩》以日人朝衡及新羅公主金真德等雜於唐詩人之列，茲編則集日人及新羅人之與唐土人士有交往酬唱者，各自成卷，標以「友邦」之目，附於編末，意欲存當時文化交流之跡云爾。","此則有異於《全唐詩》體制者。","值茲付印之際，畧記前後過程如此。","戊午歲（一九七八年）秋，孫望記於南京師範學院。"]', '["右《全唐诗補逸》二十卷。","是稿初印於丙子歲（一九三六年），當时收诗止二百七十有奇，暫分七卷，名曰《全唐诗補逸初稿》。","稱《初稿》者，蓋欲賡揚裒集，期畢功釐定於他日也。","其明年而蘆溝变起，舉家流徙，奔走万里，藏书既失，旧業尽廢，甯居之不遑，奚論撰輯。","荏苒八載，抗戰勝利，始得复返金陵。","顧政敝民窮，生事維艱，丁彼衰世，徒知腾議於私室，已無心於学问矣。","及己丑歲（一九四九年）而雄旆南指，落葉东飄，日出曜景，積瘴煙銷，慶堯宇之得蘇，见山河之重締，薄海同歡，余寧独異？","自来南師，將三十年矣，生計豐足，心神怡暢，得黨政之关懷，承師友之相勉，於教学之餘，复得游心翰府，繼事蒐聚，雖四凶逞虐之日，猶未嘗或輟。","積之既久，漸成卷帙，略加編次，合之旧稿，得诗近八百篇，離爲二十卷，仍其名曰《全唐诗補逸》。","自維头白齒脫，精力有竭，而唐诗散佚，远不止外，倘假我以年，其增輯續補，願待来日，則茲編雖稱《全唐诗補逸》，仍以初稿目之可耳。","惟昔丙子旧稿，收韋莊《秦婦吟》一首，又曾錄《云謠集杂曲子》三十首及無名氏词等爲一卷，今王重民氏《敦惶曲子词集》及《補全唐诗》既悉數絬刊矣，故從刪。","又《全唐诗》以日人朝衡及新羅公主金真德等杂於唐诗人之列，茲編則集日人及新羅人之與唐土人士有交往酬唱者，各自成卷，標以「友邦」之目，附於編末，意欲存當时文化交流之跡云爾。","此則有異於《全唐诗》體制者。","值茲付印之際，畧記前後過程如此。","戊午歲（一九七八年）秋，孫望記於南京師範学院。"]', '诗', 'shi', '', NULL, '後記 孫望 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af62b5c-84bb-443c-8135-573e244cb6a2', '前言', '前言', '3da663e8-0291-43b0-b69b-ef71acaf976f', '唐', '["唐詩體制繁複。","前承樂府、古風，後啟律詩、雜言，抒情、說理、敍事、寫景，蔚爲大觀。","上自達官，下至隱逸，文士筆述，民間口傳，遍地開花，豐富多彩。","它在中國詩壇上，也在世界詩歌史上，都占有並將永久占有極其重要的地位。","唐、宋、元至明中葉以前，唐詩選本多，而全集少。","明中期以後，漸有人重視唐詩全集的編刻，便斷代分期出書，流傳極少。","如隆慶時吳琯等《唐詩紀》，只成初唐、盛唐。","至清康熙四十五、六年間，纔開始根據胡震亨《唐音統籤》及錢謙益、季振宜連接編輯的《全唐詩集》（只有稿本。","初稿爲不同版本的詩集拼成，有抄有刻，我曾寫出目錄，留備參考。","該稿現在台灣。","清內府舊藏是重抄稿本。","）綜合改編成爲現時仍在通行的《全唐詩》。","《全唐詩》共九百卷，收詩五萬餘首。","因時時急於求成，存在不少缺點錯誤。","近代有不昳，如劉師培、李嘉言等提出勘誤和改編的意見，偶然也提到尚有可補之詩。","日本河世寧能早在我國韓隆時期進行《全唐詩》的輯逸工作，雖然所輯有限，又多屬摘句，最後附李嶠幾首詩的校異，也還是值得歡迎的。","近半個世紀中，有羅振玉、王重民，包括最近舒學等，單從敦惶遺書中先後輯出唐人遺詩共約一百八十首。","只限於文士的雅言詩，而未收民間的口語詩，終令人對唐詩有不全之感。","我在較長時期，對全漢至隋詩、全唐詩，都留心輯補，隨見隨鈔，各有積稿。","現中華書局以《全唐詩》先行再版，廣徵補遺。","最近一年多，我根據原輯加工，僅就手邊可利用的書，加以鈔補，五百五十餘人，詩一千餘首，摘句（一聯一韻作爲一句）二百三十以上，詞三十一首，編爲二十一卷。","現時的工作以補爲主，但也以補帶校。","如不事先反複細校，則又不知缺在何處。","多卷集的大家、名家，比較難補，而零句比全詩更難補。","古今學者中，雖對某一家某一集，進行過專門的研究，而竟不知何者可補，或雖補而反誤。","明、清刻本中，誤補者更多一些。","如《四部叢刊》影印明刊本《張籍集》，極爲錯亂，有《臺城》及其他十題，共十七首，實爲劉禹錫詩，《楊柳送客》等四首，爲李益詩，竟大量收入。","席刻《唐詩百名家集》中，《馬戴集》比《全唐詩》多出《早秋宿崔業居處》以下九首，皆爲秦系詩，又席刻百家有《于鄴集》，江標五十家小集有《于武陵集》。","《唐詩紀事》及《全唐詩》都分作二家，據《唐才子傳》，武陵爲鄴之字，實爲一人。","也有些詩。","見於兩家以上，不能肯定爲某一人詩者，保留詩題，文字出入較大者並存。","有此詩雖有疑問，如王維樂府詩等，也作爲附錄保存，留待後來學者參攷。","以上這些情況，都在詩前、詩後或詩人小傳中，加以說明。","體例問題：現在略依原書凡例，如已有傳的，就不再錄，沒有傳而可以查到的，就畧補小傳。","如暫時查不出，就參照原書前後人次，訂其時代。","否則統依姓名筆劃，集中放在「無世次」一卷之中。","本輯稿每詩後面，都注明出處。","所附小傳及詩解等，大都引用原文，形式近於《宋詩紀事》。","原書補遺、歌謠、神仙等詩，也是如此。","不過有詳、有略、也有遺漏，又多數不注出處。","這對以後校勘或改編《全唐詩》，有一定困難。","本輯稿破除以往慣例，不論帝王將相、朝野人士、婦女、僧道，都按時代先後排刊。","缺姓名而有時代，或有關人物可尋，也依照上例列入。","本輯稿略依《唐詩品彙》及《詩藪》、《唐音癸籤》所論，暫分爲初、盛、中、晚。","五代十國補詩較多，（李調元《全五代詩》晚全唐詩於，缺漏還很多。","）題作《全唐五代詩續補遺》，也是可以的。","胡震亨對胡應麟的論述，比較佩服。","但初、盛、中、晚，具體細分，又不盡相同。","如應麟以李適、孫逖爲盛唐，震亨改爲初唐；應麟以包融爲初唐，劉方平爲中唐，震亨都改爲盛唐；應麟以元載、蘇渙爲盛唐，震亨改爲中唐；應麟以魏謩、孫元宴爲中唐，震亨又改爲晚唐；應麟以杜荀鶴、沈彬、陳陶、黃滔特爲晚唐，震亨改爲閏唐（即五代十國）。","而初、盛、中、晚之中，又各有先後，至于五代十國詩在《全唐詩》中混而不分，現也略依《全五代詩》並參照《五代史》、《十國春秋》加以區分。","本稿是繼《全唐詩》原有補遺輯補的，故稱《續補遺》。","筆者限於時間和水平，目前只能勉成此初稿，難免有誤有漏，至於修改補充，更準確地加以排比，則有待今後進一步的努力。","童養年於安徽大學一九八○年四月。"]', '["唐诗體制繁複。","前承乐府、古风，後啟律诗、杂言，抒情、说理、敍事、寫景，蔚爲大观。","上自達官，下至隐逸，文士笔述，民间口傳，遍地开花，豐富多彩。","它在中国诗壇上，也在世界诗歌史上，都占有並將永久占有極其重要的地位。","唐、宋、元至明中葉以前，唐诗選本多，而全集少。","明中期以後，漸有人重視唐诗全集的編刻，便斷代分期出书，流傳極少。","如隆慶时吳琯等《唐诗紀》，只成初唐、盛唐。","至清康熙四十五、六年间，纔开始根據胡震亨《唐音統籤》及錢謙益、季振宜連接編輯的《全唐诗集》（只有稿本。","初稿爲不同版本的诗集拼成，有抄有刻，我曾寫出目錄，留備參考。","該稿現在台灣。","清內府旧藏是重抄稿本。","）綜合改編成爲現时仍在通行的《全唐诗》。","《全唐诗》共九百卷，收诗五万餘首。","因时时急於求成，存在不少缺点錯誤。","近代有不昳，如劉師培、李嘉言等提出勘誤和改編的意见，偶然也提到尚有可補之诗。","日本河世寧能早在我国韓隆时期進行《全唐诗》的輯逸工作，雖然所輯有限，又多屬摘句，最後附李嶠幾首诗的校異，也還是值得歡迎的。","近半個世紀中，有羅振玉、王重民，包括最近舒学等，單從敦惶遺书中先後輯出唐人遺诗共約一百八十首。","只限於文士的雅言诗，而未收民间的口語诗，終令人对唐诗有不全之感。","我在較长时期，对全漢至隋诗、全唐诗，都留心輯補，隨见隨鈔，各有積稿。","現中华书局以《全唐诗》先行再版，廣徵補遺。","最近一年多，我根據原輯加工，僅就手邊可利用的书，加以鈔補，五百五十餘人，诗一千餘首，摘句（一聯一韻作爲一句）二百三十以上，词三十一首，編爲二十一卷。","現时的工作以補爲主，但也以補带校。","如不事先反複細校，則又不知缺在何处。","多卷集的大家、名家，比較难補，而零句比全诗更难補。","古今学者中，雖对某一家某一集，進行過專门的研究，而竟不知何者可補，或雖補而反誤。","明、清刻本中，誤補者更多一些。","如《四部叢刊》影印明刊本《張籍集》，極爲錯亂，有《台城》及其他十題，共十七首，實爲劉禹錫诗，《楊柳送客》等四首，爲李益诗，竟大量收入。","席刻《唐诗百名家集》中，《马戴集》比《全唐诗》多出《早秋宿崔業居处》以下九首，皆爲秦系诗，又席刻百家有《于鄴集》，江標五十家小集有《于武陵集》。","《唐诗紀事》及《全唐诗》都分作二家，據《唐才子傳》，武陵爲鄴之字，實爲一人。","也有些诗。","见於兩家以上，不能肯定爲某一人诗者，保留诗題，文字出入較大者並存。","有此诗雖有疑问，如王維乐府诗等，也作爲附錄保存，留待後来学者參攷。","以上這些情況，都在诗前、诗後或诗人小傳中，加以说明。","體例问題：現在略依原书凡例，如已有傳的，就不再錄，沒有傳而可以查到的，就畧補小傳。","如暫时查不出，就參照原书前後人次，訂其时代。","否則統依姓名笔劃，集中放在「無世次」一卷之中。","本輯稿每诗後面，都注明出处。","所附小傳及诗解等，大都引用原文，形式近於《宋诗紀事》。","原书補遺、歌謠、神仙等诗，也是如此。","不過有詳、有略、也有遺漏，又多數不注出处。","這对以後校勘或改編《全唐诗》，有一定困难。","本輯稿破除以往慣例，不論帝王將相、朝野人士、婦女、僧道，都按时代先後排刊。","缺姓名而有时代，或有关人物可尋，也依照上例列入。","本輯稿略依《唐诗品彙》及《诗藪》、《唐音癸籤》所論，暫分爲初、盛、中、晚。","五代十国補诗較多，（李調元《全五代诗》晚全唐诗於，缺漏還很多。","）題作《全唐五代诗續補遺》，也是可以的。","胡震亨对胡應麟的論述，比較佩服。","但初、盛、中、晚，具體細分，又不尽相同。","如應麟以李適、孫逖爲盛唐，震亨改爲初唐；應麟以包融爲初唐，劉方平爲中唐，震亨都改爲盛唐；應麟以元載、蘇渙爲盛唐，震亨改爲中唐；應麟以魏謩、孫元宴爲中唐，震亨又改爲晚唐；應麟以杜荀鹤、沈彬、陳陶、黄滔特爲晚唐，震亨改爲閏唐（即五代十国）。","而初、盛、中、晚之中，又各有先後，至于五代十国诗在《全唐诗》中混而不分，現也略依《全五代诗》並參照《五代史》、《十国春秋》加以區分。","本稿是繼《全唐诗》原有補遺輯補的，故稱《續補遺》。","笔者限於时间和水平，目前只能勉成此初稿，难免有誤有漏，至於修改補充，更準確地加以排比，則有待今後進一步的努力。","童養年於安徽大学一九八○年四月。"]', '诗', 'shi', '', NULL, '前言 童養年 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46ee976-110f-46cb-8f89-29d301cf0d42', '爲秦王制詩', '爲秦王制诗', '447a5d9b-1a70-420a-814a-3f559d4fd3f3', '唐', '["（初太宗爲秦王，高祖制詩云云。","帝於宮西造宅初成，高祖送玉璽以至帝所，縉紳先生相謂曰：「詩及玉璽。","蓋奉國之祥瑞者歟。","」○今按：《全唐詩凡例》引胡震亨謂唐初無五星聯聚之事，疑其僞託。","曾見陜西鄠縣有大業三年鄭州刺史李淵爲子世民祈疾疏石刻拓本，孫星衍《訪碑錄》亦收載。","）聖德合天地，五宿連珠見。","和風拂世民，上下同歡宴。","（《冊府元龜》二一《帝王部·徵應》）。"]', '["（初太宗爲秦王，高祖制诗云云。","帝於宮西造宅初成，高祖送玉璽以至帝所，縉紳先生相謂曰：「诗及玉璽。","蓋奉国之祥瑞者歟。","」○今按：《全唐诗凡例》引胡震亨謂唐初無五星聯聚之事，疑其僞託。","曾见陜西鄠縣有大業三年鄭州刺史李淵爲子世民祈疾疏石刻拓本，孫星衍《訪碑錄》亦收載。","）聖德合天地，五宿連珠见。","和风拂世民，上下同歡宴。","（《冊府元龟》二一《帝王部·徵應》）。"]', '诗', 'shi', '', NULL, '爲秦王制詩 李淵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ffc844e-1191-4278-a4ee-6dbe5d1d3fe6', '題龜峯山（在麻城縣）', '題龟峯山（在麻城縣）', 'd7b56446-8b61-4c37-b138-941773c577a8', '唐', '["乾坤造化有神功，勝地安然氣象雄。","馬蹟印開蒼石上，龜頭橫插白雲中。","山高每有神仙過，寺號能仁天子封。","試劍石邊風拂拂，虎跑泉內水溶溶。","龍吟南嶺崎山雨，虎嘯東林什子風。","舍利塔中遺釋子，觀音崖上禮慈容。","天開雲現瑠璃碧，日落霞明瑪瑙紅。","巖畔芊芊羅漢草，領頭鬱鬱大夫松。","望龜亭內迎仙客，噴雪崖前活水通。","萬里黎民皆潤澤，一堂賢聖總虛空。","遊山宰相書名字，採藥仙人留跡踪。","任是丹青描不就，恍疑身世九霄宮。","（《弘治黃州府志》七《藝文》）。"]', '["乾坤造化有神功，勝地安然氣象雄。","马蹟印开蒼石上，龟头橫插白云中。","山高每有神仙過，寺號能仁天子封。","試劍石邊风拂拂，虎跑泉內水溶溶。","龙吟南嶺崎山雨，虎嘯东林什子风。","舍利塔中遺釋子，观音崖上禮慈容。","天开云現瑠璃碧，日落霞明瑪瑙紅。","巖畔芊芊羅漢草，領头鬱鬱大夫松。","望龟亭內迎仙客，噴雪崖前活水通。","万里黎民皆潤澤，一堂賢聖總虛空。","游山宰相书名字，採藥仙人留跡踪。","任是丹青描不就，恍疑身世九霄宮。","（《弘治黄州府志》七《藝文》）。"]', '诗', 'shi', '', NULL, '題龜峯山（在麻城縣） 李世民 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c124ac-a9c9-46e1-8a40-557d4089d026', '遊石淙詩（幷序）', '游石淙诗（幷序）', '9f31b16c-1249-4079-9df0-2bcd08faa44c', '唐', '["若夫圓嶠方壺，涉滄波而靡際；金臺玉闕，陟玄圃而無階。","惟聞《山海》之經，空覽《神仙》之記。","爰有石淙者，即平樂澗也。","爾其近接嵩領，俯屆箕峯，瞻少室兮若蓮，睇潁川兮如帶。","既而躡崎嶇之山徑，蔭蒙密之藤蘿，洶湧洪湍，落虛潭而送響；高低翠壁，列幽澗而開筵。","密葉舒帷，屏氛而蕩燠；疏松引吹，清麥候以含涼。","就林藪而王心神，對煙霞具而滌塵累。","森沈丘壑，即是桃源；淼漫平流，還浮竹箭。","[紉]（網）薜荔而成帳，聳蓮石而如樓。","洞口全開，溜千年之芳髓，山腰半坼，吐十里之香粳。","無煩崑閬之遊，自然形勢之所。","當使人題綵翰，各寫瓊篇，庶無滯於幽棲，冀不孤於泉石。","各題四韻，咸賦七言。","（《古今圖書集成·山川典》六○《嵩山部》○今按：此詩在《全唐詩》一般有詩序者，大都全錄，此係遺漏。","現特補序，詩不重錄。","又《圖書集成》推崇卷，作嵩山石淙侍宴應制者，有宋之問、沈佺期、蘇味道、李嶠諸人。","）（據《金石萃編》卷六十三校改。","）。"]', '["若夫圓嶠方壺，涉滄波而靡際；金台玉闕，陟玄圃而無階。","惟闻《山海》之經，空覽《神仙》之記。","爰有石淙者，即平乐澗也。","爾其近接嵩領，俯屆箕峯，瞻少室兮若蓮，睇潁川兮如带。","既而躡崎嶇之山徑，蔭蒙密之藤蘿，洶湧洪湍，落虛潭而送响；高低翠壁，列幽澗而开筵。","密葉舒帷，屏氛而蕩燠；疏松引吹，清麦候以含涼。","就林藪而王心神，对煙霞具而滌塵累。","森沈丘壑，即是桃源；淼漫平流，還浮竹箭。","[紉]（網）薜荔而成帳，聳蓮石而如楼。","洞口全开，溜千年之芳髓，山腰半坼，吐十里之香粳。","無煩崑閬之游，自然形勢之所。","當使人題綵翰，各寫瓊篇，庶無滯於幽棲，冀不孤於泉石。","各題四韻，咸賦七言。","（《古今圖书集成·山川典》六○《嵩山部》○今按：此诗在《全唐诗》一般有诗序者，大都全錄，此係遺漏。","現特補序，诗不重錄。","又《圖书集成》推崇卷，作嵩山石淙侍宴應制者，有宋之问、沈佺期、蘇味道、李嶠諸人。","）（據《金石萃編》卷六十三校改。","）。"]', '诗', 'shi', '', NULL, '遊石淙詩（幷序） 武曌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f287f4d8-55d4-4555-a306-a6840d0242b6', '', '', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bab2f7e-6a2f-441b-b136-2cfc6e30a0ac', '遼左雪中登樓', '遼左雪中登楼', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["歲杪崇朝雪，天涯絕塞城。","凍雲連海色，枯木助風聲。","懷古情無已，登樓賦未成。","梅花南國思，笛裏暮愁生。","（《古今圖書集成·職方典》一七四《奉天府部》）。"]', '["歲杪崇朝雪，天涯絕塞城。","凍云連海色，枯木助风声。","懷古情無已，登楼賦未成。","梅花南国思，笛裏暮愁生。","（《古今圖书集成·職方典》一七四《奉天府部》）。"]', '诗', 'shi', '', NULL, '遼左雪中登樓 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601c69f3-9ada-4447-991f-f05c1e53cea3', '白龜城', '白龟城', '3fed5b11-cb4b-438f-8694-a9390a8f26c1', '唐', '["城堞千尋險，池隍十里餘。","樓臺侵漢宇，鼓角動郊墟。","羆虎三軍擁，壺漿萬戶舒。","急須修表進，天意欲何如？","（《嘉慶涇縣志》三十二《詞賦》）。"]', '["城堞千尋險，池隍十里餘。","楼台侵漢宇，鼓角动郊墟。","羆虎三軍擁，壺漿万戶舒。","急須修表進，天意欲何如？","（《嘉慶涇縣志》三十二《词賦》）。"]', '诗', 'shi', '', NULL, '白龜城 左匡政 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87932516-f43e-4f80-91e7-57b6293da2c7', '留題雲門（一作「秦望山」）', '留題云门（一作「秦望山」）', '51f3758c-8031-4cec-9eb5-430cc4fb59a6', '唐', '["絕頂高峯（一作「山」）路不分。","嵐烟（一作「烟嵐」）長鎖綠苔紋。","彌猴推落臨（一作「懸」）崖石。","打破（一作「落」）下方遮日雲。","（《萬首唐人絕句》十一、《古今圖書集成·山川典》一○五《秦望山部》）（北宋孔延之編《會稽掇獻總集》卷六已收此詩。","）。"]', '["絕頂高峯（一作「山」）路不分。","嵐烟（一作「烟嵐」）长鎖綠苔紋。","彌猴推落臨（一作「懸」）崖石。","打破（一作「落」）下方遮日云。","（《万首唐人絕句》十一、《古今圖书集成·山川典》一○五《秦望山部》）（北宋孔延之編《會稽掇獻總集》卷六已收此诗。","）。"]', '诗', 'shi', '', NULL, '留題雲門（一作「秦望山」） 蕭翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02feaa51-8b36-43a0-b556-84fdcf675414', '題雷威琴', '題雷威琴', '34606369-a7ad-400f-aefc-c6b12375ac82', '唐', '["合雅大樂，成文正音。","徽絃一泛，山水俱深。","（《西溪叢語》上）（《西溪叢語》云：「長兄伯聲云：昔至澠邑，獲一古琴，中題云〖略〗。","雷威斷，歐陽詢書，陜郊處士魏野家藏。","」同書復錄雷威大曆三年題字，知歐、雷並非同時之人。","此詩如爲歐作，則詩題誤。","頗疑「歐陽詢書」云云，僅指其字體爲歐書，而非必歐本人之作。","）。"]', '["合雅大乐，成文正音。","徽絃一泛，山水俱深。","（《西溪叢語》上）（《西溪叢語》云：「长兄伯声云：昔至澠邑，獲一古琴，中題云〖略〗。","雷威斷，歐陽詢书，陜郊处士魏野家藏。","」同书复錄雷威大曆三年題字，知歐、雷並非同时之人。","此诗如爲歐作，則诗題誤。","頗疑「歐陽詢书」云云，僅指其字體爲歐书，而非必歐本人之作。","）。"]', '诗', 'shi', '', NULL, '題雷威琴 歐陽詢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e0ad678-f0d1-4dae-8bb9-0b78d7bcef4d', '過楊玄感墓', '過楊玄感墓', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["（《唐書》曰：天后西幸京師，路經楊玄感墓，上誦李百藥《過玄感墓詩》云云，歎曰：「百藥唯解綴文，不識大義。","」○今按：兩《唐書·則天紀》、《百藥傳》均不載。","）劍有萬人敵，文爲一代英。","除昏志不遂，僭亂道難平。","（《太平御覽》五五八《禮儀部》。","）。"]', '["（《唐书》曰：天后西幸京師，路經楊玄感墓，上誦李百藥《過玄感墓诗》云云，歎曰：「百藥唯解綴文，不識大義。","」○今按：兩《唐书·則天紀》、《百藥傳》均不載。","）劍有万人敵，文爲一代英。","除昏志不遂，僭亂道难平。","（《太平御覽》五五八《禮儀部》。","）。"]', '诗', 'shi', '', NULL, '過楊玄感墓 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0fa57a2-9e65-477c-a972-85095a77a584', '落成會詠二首（前一首《全唐詩》已收）', '落成會詠二首（前一首《全唐诗》已收）', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["雲霄開岳鎮，日月列衙瞻。","勝日當佳慶，清風去積炎。","山畚遙獵虎，海舶近通鹽。","龍澤覃江浦，螭坳耀斗蟾。","文床堆玉笏，武座肅金簽。","奇計繩陳美，明誠學孔兼。","忠勤非一日，箴訓要三拈。","千古清泉水，居官顯孝廉。"]', '["云霄开岳鎮，日月列衙瞻。","勝日當佳慶，清风去積炎。","山畚遙獵虎，海舶近通鹽。","龙澤覃江浦，螭坳耀斗蟾。","文床堆玉笏，武座肅金簽。","奇計繩陳美，明誠学孔兼。","忠勤非一日，箴訓要三拈。","千古清泉水，居官显孝廉。"]', '诗', 'shi', '', NULL, '落成會詠二首（前一首《全唐詩》已收） 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca8db3e-61dd-4a49-8d41-cbee5e5f7785', '半徑尋真', '半徑尋真', '472d30b6-81ca-434c-bbe5-9ccfc5102bd1', '唐', '["半徑尋仙蹟，危峯望帝州。","千山紅日媚，萬壑白雲浮。","坐石花容笑，穿林鳥語愁。","招呼玄鶴下，撚捋紫芝柔。","鑄鼎龍歸洞，驚旗虎負丘。","高棲謀未遂，勝景至須留。","巖谷連聲應，漳湖合派流。","飄然歌一曲，縹緲在瀛州。","（以上《康熙漳浦縣志》十八《藝文》下）。"]', '["半徑尋仙蹟，危峯望帝州。","千山紅日媚，万壑白云浮。","坐石花容笑，穿林鸟語愁。","招呼玄鹤下，撚捋紫芝柔。","鑄鼎龙归洞，驚旗虎負丘。","高棲謀未遂，勝景至須留。","巖谷連声應，漳湖合派流。","飄然歌一曲，縹緲在瀛州。","（以上《康熙漳浦縣志》十八《藝文》下）。"]', '诗', 'shi', '', NULL, '半徑尋真 陳元光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78366817-ccaa-41a0-bee4-0f4fa30b8cd0', '照鏡見白髪（聯句）', '照镜见白髪（聯句）', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["宿昔青雲志，蹉跎白髪年。","誰知明鏡裏，形影自相憐。","（《萬首唐人絕句》補本一。","又見《四部叢刊》影明本《張九齡集》）。"]', '["宿昔青云志，蹉跎白髪年。","誰知明镜裏，形影自相怜。","（《万首唐人絕句》補本一。","又见《四部叢刊》影明本《張九齡集》）。"]', '诗', 'shi', '', NULL, '照鏡見白髪（聯句） 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30819655-6c47-408e-9254-2030d4fdfc7e', '謝公樓', '謝公楼', '61ac39ce-7be0-4731-bb9f-3c34fdb7d73f', '唐', '["謝公樓上好醇酒，三百青蚨買一斗。","紅泥乍擘綠蟻浮，玉盌纔傾黃蜜剖。","（《永樂大典》七八九一「樓」字韻）。"]', '["謝公楼上好醇酒，三百青蚨買一斗。","紅泥乍擘綠蟻浮，玉盌纔傾黄蜜剖。","（《永乐大典》七八九一「楼」字韻）。"]', '诗', 'shi', '', NULL, '謝公樓 張九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('594adf6e-4e2d-4337-ad31-04779d22200c', '幸未央宮應制（補後四句）', '幸未央宮應制（補後四句）', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["登高省時物，懷古發宸聰。","鐘連長樂處，臺識未央中。","（《文苑英華辨證》六《脫文》）（《文苑英華辨證》據宋之問集補此四句，原詩指《全唐詩》卷五三已收之《奉和幸長安故城未央宮應制》。","詩云：「漢王未息戰，蕭相乃營宮。","壯麗一朝盡，威靈千載空。","皇明悵前跡，置酒宴羣公。","寒輕綵仗外，春發幔城中。","樂思回斜日，歌詞繼《大風》。","今朝天子貴，不假叔孫通。","」《文苑英華辨證》謂「春發幔城中」，集作「春發幔城東」，「《文苑》以『東』作『中』，遂脫四句。","」四句應於「樂思」二句之前。","）。"]', '["登高省时物，懷古發宸聰。","鐘連长乐处，台識未央中。","（《文苑英华辨證》六《脫文》）（《文苑英华辨證》據宋之问集補此四句，原诗指《全唐诗》卷五三已收之《奉和幸长安故城未央宮應制》。","诗云：「漢王未息戰，蕭相乃營宮。","壯丽一朝尽，威靈千載空。","皇明悵前跡，置酒宴羣公。","寒轻綵仗外，春發幔城中。","乐思回斜日，歌词繼《大风》。","今朝天子貴，不假叔孫通。","」《文苑英华辨證》謂「春發幔城中」，集作「春發幔城东」，「《文苑》以『东』作『中』，遂脫四句。","」四句應於「乐思」二句之前。","）。"]', '诗', 'shi', '', NULL, '幸未央宮應制（補後四句） 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ac69c0-1a82-4b9d-8af6-7b85326af8c9', '題雷琴（二首） 一', '題雷琴（二首） 一', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["山虛水深，萬籟蕭蕭。","古無人蹤，惟石嶕峣。"]', '["山虛水深，万籟蕭蕭。","古無人蹤，惟石嶕峣。"]', '诗', 'shi', '', NULL, '題雷琴（二首） 一 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aa5a708-b778-488a-8546-7494b7ca6e45', '題雷琴（二首） 二', '題雷琴（二首） 二', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["洛水多清泚，崧高有白雲。","聖朝容隱逸，時得詠南薫。","（《古今圖書集成》）（宋姚寬《西溪叢語》卷上云：「長兄伯聲云：洛中董氏蓄雷琴一張，中題云〖引前四言詩，略〗。","狀其聲也。","其外漆下隱有朱書云〖引後五言詩，略〗。","此詩見《宋之問集》。","」據此，應僅後首爲宋之問作。","又此爲後人取宋詩題雷琴此擬題爲《題雷琴》，誤。","雷琴因雷威所製而得名，雷威爲大曆間人，宋之问不及見。","）。"]', '["洛水多清泚，崧高有白云。","聖朝容隐逸，时得詠南薫。","（《古今圖书集成》）（宋姚寬《西溪叢語》卷上云：「长兄伯声云：洛中董氏蓄雷琴一張，中題云〖引前四言诗，略〗。","狀其声也。","其外漆下隐有朱书云〖引後五言诗，略〗。","此诗见《宋之问集》。","」據此，應僅後首爲宋之问作。","又此爲後人取宋诗題雷琴此擬題爲《題雷琴》，誤。","雷琴因雷威所製而得名，雷威爲大曆间人，宋之问不及见。","）。"]', '诗', 'shi', '', NULL, '題雷琴（二首） 二 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0677f7-e286-473b-bf22-7ab40e030049', '錢', '錢', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["九府五銖世上珍，魯襃曾詠道通神。","勸君覔得須知足，雖解榮人也辱人。","（《古今圖書集成·食貨典》三五八《錢鈔部》）。"]', '["九府五銖世上珍，魯襃曾詠道通神。","勸君覔得須知足，雖解榮人也辱人。","（《古今圖书集成·食貨典》三五八《錢鈔部》）。"]', '诗', 'shi', '', NULL, '錢 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1732b039-d9d1-4e72-9bed-c4fb2e83fdc8', '玄武山聖水宴（幷序）', '玄武山聖水宴（幷序）', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["玄武山有聖泉焉，浸淫歷數百千年，（「歷」字據陽熙晉《駱臨海集箋注》卷九補。","陳熙晉云：「此序各本皆不載，今從《全唐文》錄出。","」「子安在梓州所作詩文尚多，恐非駱文。","」）垂巖沁湧，接磴分流，下瞰長江，沙堤石岸，咸古人遺迹也。","茲乃青蘋綠芰，紫苔蒼蘚，遂使江湖思遠，寤寐寄託。","既而崇巒左峙，石壑（一作「壁」）前縈，丹崿萬尋，碧潭千頃，松風唱響，竹露薫空。","瀟瀟乎人間之難遇也，方欲以林壑爲天屬，琴罇爲日用。","嗟乎！古今同逝（一作「代謝」。","）方深川上之悲；少長偕遊，且盡山陰之樂。","盍題芳什，共寫高情。","詩得泉字。","詩曰。","（《古今圖書集成·坤輿典》三六《泉部》）（今按：《全唐詩》五六題作《聖泉宴》，有詩無序，故補序，詩不重錄。","）。"]', '["玄武山有聖泉焉，浸淫歷數百千年，（「歷」字據陽熙晉《駱臨海集箋注》卷九補。","陳熙晉云：「此序各本皆不載，今從《全唐文》錄出。","」「子安在梓州所作诗文尚多，恐非駱文。","」）垂巖沁湧，接磴分流，下瞰长江，沙堤石岸，咸古人遺迹也。","茲乃青蘋綠芰，紫苔蒼蘚，遂使江湖思远，寤寐寄託。","既而崇巒左峙，石壑（一作「壁」）前縈，丹崿万尋，碧潭千頃，松风唱响，竹露薫空。","瀟瀟乎人间之难遇也，方欲以林壑爲天屬，琴罇爲日用。","嗟乎！古今同逝（一作「代謝」。","）方深川上之悲；少长偕游，且尽山陰之乐。","盍題芳什，共寫高情。","诗得泉字。","诗曰。","（《古今圖书集成·坤輿典》三六《泉部》）（今按：《全唐诗》五六題作《聖泉宴》，有诗無序，故補序，诗不重錄。","）。"]', '诗', 'shi', '', NULL, '玄武山聖水宴（幷序） 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80abd93f-0cb6-44d5-86e6-dd11b36aea92', '隴西行（十首） 一', '隴西行（十首） 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["隴西多名家，子弟復豪華。","千金買駿馬，蹀躞長安斜。"]', '["隴西多名家，子弟复豪华。","千金買駿马，蹀躞长安斜。"]', '诗', 'shi', '', NULL, '隴西行（十首） 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2db8a8d7-198b-41e8-b65a-17ba7a3e1ec9', '隴西行（十首） 二', '隴西行（十首） 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["彫弓侍羽林，寶劍照期門。","南來射猛虎，西去獵平原。"]', '["彫弓侍羽林，寶劍照期门。","南来射猛虎，西去獵平原。"]', '诗', 'shi', '', NULL, '隴西行（十首） 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d121cd-5dff-4222-8f7a-8bffa0af6437', '隴西行（十首） 三', '隴西行（十首） 三', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["既夕罷朝參，薄暮入終南。","田間遭罵詈，低語示乘驂。"]', '["既夕罷朝參，薄暮入終南。","田间遭罵詈，低語示乘驂。"]', '诗', 'shi', '', NULL, '隴西行（十首） 三 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00d5a757-abbd-41ca-8f22-65b26a33d262', '隴西行（十首） 四', '隴西行（十首） 四', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["入被鑾輿寵，出視轅門勇。","無勞豪吏猜，常侍當無恐。"]', '["入被鑾輿寵，出視轅门勇。","無勞豪吏猜，常侍當無恐。"]', '诗', 'shi', '', NULL, '隴西行（十首） 四 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e49c6eec-9824-45ba-b8f0-69c8b8e4f0cd', '隴西行（十首） 五', '隴西行（十首） 五', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["充國出上邽，李廣出天水。","門第倚崆峒，家世垂金紫。"]', '["充国出上邽，李廣出天水。","门第倚崆峒，家世垂金紫。"]', '诗', 'shi', '', NULL, '隴西行（十首） 五 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78122776-2f38-477c-8213-a52e45a3a079', '隴西行（十首） 六', '隴西行（十首） 六', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["麟閣圖良將，六郡名居上。","天子重開邊，龍雲壘相向。"]', '["麟閣圖良將，六郡名居上。","天子重开邊，龙云壘相向。"]', '诗', 'shi', '', NULL, '隴西行（十首） 六 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50273723-cb2d-459d-8b59-69c537c56948', '隴西行（十首） 七', '隴西行（十首） 七', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["烽火照臨洮，榆塞馬蕭蕭。","先鋒秦子弟，大將霍嫖姚。"]', '["烽火照臨洮，榆塞马蕭蕭。","先鋒秦子弟，大將霍嫖姚。"]', '诗', 'shi', '', NULL, '隴西行（十首） 七 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6b16be-bac3-42e7-9ef0-8571619faa8a', '隴西行（十首） 八', '隴西行（十首） 八', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["開壁左賢敗，夾戰樓蘭潰。","獻捷上明光，揚鞭歌《入塞》。"]', '["开壁左賢敗，夾戰楼蘭潰。","獻捷上明光，揚鞭歌《入塞》。"]', '诗', 'shi', '', NULL, '隴西行（十首） 八 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b726b08-ef6e-4e4f-94ab-8671c4b3d005', '隴西行（十首） 九', '隴西行（十首） 九', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["更欲奏屯田，不必勒燕然。","古人薄軍旅，千載謹邊關。"]', '["更欲奏屯田，不必勒燕然。","古人薄軍旅，千載謹邊关。"]', '诗', 'shi', '', NULL, '隴西行（十首） 九 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502e7760-3ca9-4a0b-af20-0d1acb3b773d', '隴西行（十首） 十', '隴西行（十首） 十', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["少婦經年別，開簾知禮客。","門戶爾能持，歸來笑投策。","（以上同上五六五《鞏昌府部》，又乾隆《直隸秦州新志》十一《藝文》於此《詩》）（乾隆《秦州新志》及乾隆《狄道州志》十三收外詩，連作一首。","前書每二十字爲一行，或因此而析爲十首。）"]', '["少婦經年別，开簾知禮客。","门戶爾能持，归来笑投策。","（以上同上五六五《鞏昌府部》，又乾隆《直隸秦州新志》十一《藝文》於此《诗》）（乾隆《秦州新志》及乾隆《狄道州志》十三收外诗，連作一首。","前书每二十字爲一行，或因此而析爲十首。）"]', '诗', 'shi', '', NULL, '隴西行（十首） 十 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be256466-df94-4f60-a539-638112262786', '自鄉[還]（遠）虢', '自乡[還]（远）虢', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["（王福畤之子，勔、勮、勃皆有才名，故杜易簡稱爲三珠樹。","其後助、劼、勸，又皆以文顯。","勃於兄弟之間極友愛，《自鄉[還]〖還〗虢》詩云云。","觀此語意，豈兄弟有不相能者耶？","及觀《誡功勁云》：「欲不可縱，爭不可常，勿輕小忿，將成大殃。","」此二人者，似非處於禮義之域者。","「《棠棣》廢」之語，疑爲此二人設也。","）人生忽如客，骨肉知何常。","願及百年內，花萼常相將。","無使《棠棣》廢，取譬人無良。","（《韻語陽秋》十）（據影宋本《韻語陽秋》校改。","）。"]', '["（王福畤之子，勔、勮、勃皆有才名，故杜易簡稱爲三珠樹。","其後助、劼、勸，又皆以文显。","勃於兄弟之间極友愛，《自乡[還]〖還〗虢》诗云云。","观此語意，豈兄弟有不相能者耶？","及观《誡功勁云》：「欲不可縱，爭不可常，勿轻小忿，將成大殃。","」此二人者，似非处於禮義之域者。","「《棠棣》廢」之語，疑爲此二人設也。","）人生忽如客，骨肉知何常。","願及百年內，花萼常相將。","無使《棠棣》廢，取譬人無良。","（《韻語陽秋》十）（據影宋本《韻語陽秋》校改。","）。"]', '诗', 'shi', '', NULL, '自鄉[還]（遠）虢 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7df153f-ef42-4906-b578-2d3052408080', '述懷擬古詩', '述懷擬古诗', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["僕生二十祀，有志十數年。","下策圖富貴，上策懷神仙。","（《韻語陽秋》十二）。"]', '["僕生二十祀，有志十數年。","下策圖富貴，上策懷神仙。","（《韻語陽秋》十二）。"]', '诗', 'shi', '', NULL, '述懷擬古詩 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b7786e5-190f-4949-b67d-9a9f0783efe4', '示知己（句）', '示知己（句）', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["客書同十奏，臣劍已三奔。","（同上。","）。"]', '["客书同十奏，臣劍已三奔。","（同上。","）。"]', '诗', 'shi', '', NULL, '示知己（句） 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2dc4d78-c398-4c08-b2c3-3757b7caa255', '春日代情人', '春日代情人', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["昔日管絃調，將人舞細腰。","懸知今日恨，誰分昔時嬌。","棄妾頻登隴，從軍幾度遼？","可憐香草夜，空見落花朝。","淚滴珠難盡，容殘玉易銷。","償隨明月去，（「償」，趙遂之云當作「儻」。","）莫道夢魂遙。","（《永樂大典》三○○五人字韻引《玉臺後詠》）。"]', '["昔日管絃調，將人舞細腰。","懸知今日恨，誰分昔时嬌。","棄妾頻登隴，從軍幾度遼？","可怜香草夜，空见落花朝。","泪滴珠难尽，容殘玉易銷。","償隨明月去，（「償」，趙遂之云當作「儻」。","）莫道梦魂遙。","（《永乐大典》三○○五人字韻引《玉台後詠》）。"]', '诗', 'shi', '', NULL, '春日代情人 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435a676c-ae39-4638-8782-501c074ca3fc', '座右銘（《陳伯玉集》未收）', '座右銘（《陳伯玉集》未收）', 'cb7dbcc9-63f9-4ef0-aee2-d4b99fd366ee', '唐', '["事父盡孝敬，事君端忠貞。","兄弟敦和睦，朋友篤信誠。","從官重公慎，立身貴廉明。","待士慕謙讓，蒞民尚寬平。","理訟惟正直，察獄必審情。","謗議不足怨，寵辱詎須驚？","處[滿]（蒲）常憚溢，居高本慮傾。","詩、禮固可學，鄭、衛不足聽。","幸能修實操，何俟鈞虛聲？","白珪玷可滅，黃金諾不輕。","秦穆飲盗馬，楚客報絕纓。","言行既無擇，存歿自揚名。","（《文苑英華》七九○《銘》）。"]', '["事父尽孝敬，事君端忠貞。","兄弟敦和睦，朋友篤信誠。","從官重公慎，立身貴廉明。","待士慕謙讓，蒞民尚寬平。","理訟惟正直，察獄必審情。","謗議不足怨，寵辱詎須驚？","处[满]（蒲）常憚溢，居高本慮傾。","诗、禮固可学，鄭、衛不足听。","幸能修實操，何俟鈞虛声？","白珪玷可滅，黄金諾不轻。","秦穆饮盗马，楚客報絕纓。","言行既無擇，存歿自揚名。","（《文苑英华》七九○《銘》）。"]', '诗', 'shi', '', NULL, '座右銘（《陳伯玉集》未收） 陳子昂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be727e6-12f4-42f5-89d5-d53ac16e98be', '送敬丞', '送敬丞', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["嘉會良難永，芳罇此夜閑。","別離三春暮，親愛相鄉間。","落花已覆水，巖雲欲起山。","庭蘭行可佩，采采贈河關。"]', '["嘉會良难永，芳罇此夜闲。","別離三春暮，親愛相乡间。","落花已覆水，巖云欲起山。","庭蘭行可佩，采采贈河关。"]', '诗', 'shi', '', NULL, '送敬丞 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7989baaf-1343-40df-97fe-8395dd837484', '見諸人送杜承詩因以成作（荆州作）', '见諸人送杜承诗因以成作（荆州作）', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["吳楚分江鎮，華容改舊城。","訝君來遠謁，知有去思情。","風度沅湘險，煙還雲夢平。"]', '["吳楚分江鎮，华容改旧城。","訝君来远謁，知有去思情。","风度沅湘險，煙還云梦平。"]', '诗', 'shi', '', NULL, '見諸人送杜承詩因以成作（荆州作） 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38f9c7f-6b0d-43a7-b337-71223b3034be', '幽州送隨軍入秦', '幽州送隨軍入秦', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["楊子來戎幕，老夫欣主諾。","歸路有光華，邊庭少咨度。","雁知窮朔苦，人羨長安樂。","獨將馬革心，同聲謝臺閣。"]', '["楊子来戎幕，老夫欣主諾。","归路有光华，邊庭少咨度。","雁知窮朔苦，人羨长安乐。","独將马革心，同声謝台閣。"]', '诗', 'shi', '', NULL, '幽州送隨軍入秦 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c09fb65-f4fb-4252-9c9d-eda5fce8172b', '金庭觀（在嵊縣東南七十二里）', '金庭观（在嵊縣东南七十二里）', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["元珠道在豈難求，海變須教鬢不秋。","他日洞天三十六，碧桃花發共師遊。","（《嘉慶浙江通志》二三一《寺觀》）（見《剡錄》卷八，幷云：「先天間，遣女道士投簡金庭觀，見許承瓢，遂持以進。","」《寶慶待物續志》卷四引後二句。","）。"]', '["元珠道在豈难求，海变須教鬢不秋。","他日洞天三十六，碧桃花發共師游。","（《嘉慶浙江通志》二三一《寺观》）（见《剡錄》卷八，幷云：「先天间，遣女道士投簡金庭观，见許承瓢，遂持以進。","」《寶慶待物續志》卷四引後二句。","）。"]', '诗', 'shi', '', NULL, '金庭觀（在嵊縣東南七十二里） 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25da873e-0a7c-4abf-9c0b-3012313416f4', '黃金臺', '黄金台', 'a49de5fb-84ad-4b6a-bd39-e1a22ce8811c', '唐', '["雕牆峻字無不亡，薊城築宮國乃昌。","屈身延士禮優異，四方英俊如雲翔。","郭生馬喻真良策，亟卿拜樂卿爲上客。","兵行旬日入臨淄，秦楚諸君咸辟易。","夙心已雪先王耻，七十齊城祇餘二。","君王先去主帥逃，嘆息後人非繼志。","巍臺悲慘朔風號，不知騎劫何時招。","（《古今圖書集成·職方典》二九《順天府部》）。"]', '["雕牆峻字無不亡，薊城築宮国乃昌。","屈身延士禮優異，四方英俊如云翔。","郭生马喻真良策，亟卿拜乐卿爲上客。","兵行旬日入臨淄，秦楚諸君咸辟易。","夙心已雪先王耻，七十齊城祇餘二。","君王先去主帥逃，嘆息後人非繼志。","巍台悲慘朔风號，不知騎劫何时招。","（《古今圖书集成·職方典》二九《順天府部》）。"]', '诗', 'shi', '', NULL, '黃金臺 岑義 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a00093a-06dc-472e-864c-f8a048e02fd1', '從軍行', '從軍行', 'd46e096a-2502-4e0d-b053-67b4df6a30f6', '唐', '["空（〖1〗原列入「無世次」卷。","檢《新唐書·宰相世系表》瑯琊王氏有王寵，其宜綝，相武后，曾孫璵，相肅宗。","武后至肅宗間僅六、七十年，不至隔五世，其間必有誤。","然王寵約爲開元前後人，殆無問題。","故移入本卷。","〖2〗〖《全唐詩》三八作王宏時，第九句「王」《文苑英華》作「皇」，「千」作「十」○《文苑英華》一九九《樂府》〗〖《全唐詩》卷三八錄王宏詩，係源自《初唐詩紀》卷五，《初唐詩紀》則引僞書《龍城錄》作宏傳，幷不足據。","當從《文苑英華》歸王寵。","〗）。"]', '["空（〖1〗原列入「無世次」卷。","檢《新唐书·宰相世系表》瑯琊王氏有王寵，其宜綝，相武后，曾孫璵，相肅宗。","武后至肅宗间僅六、七十年，不至隔五世，其间必有誤。","然王寵約爲开元前後人，殆無问題。","故移入本卷。","〖2〗〖《全唐诗》三八作王宏时，第九句「王」《文苑英华》作「皇」，「千」作「十」○《文苑英华》一九九《乐府》〗〖《全唐诗》卷三八錄王宏诗，係源自《初唐诗紀》卷五，《初唐诗紀》則引僞书《龙城錄》作宏傳，幷不足據。","當從《文苑英华》归王寵。","〗）。"]', '诗', 'shi', '', NULL, '從軍行 王寵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867c66b6-1407-4310-ac30-5ff40b74194a', '夏彈琴（《文苑英華》二一二《音樂》、《初學記》一六「樂」部）', '夏彈琴（《文苑英华》二一二《音乐》、《初学記》一六「乐」部）', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["空（〖1〗《唐文粹》、《唐詩紀事》作劉希戩《彈琴》。","〖2〗今按：《全唐詩》七六九作劉戩，第二句「素琴」《英華》作「素絲」，第六句「泉魚」《英華》作「淵魚」，第十二句「荒岳」《英華》作「山丘」。","）。"]', '["空（〖1〗《唐文粹》、《唐诗紀事》作劉希戩《彈琴》。","〖2〗今按：《全唐诗》七六九作劉戩，第二句「素琴」《英华》作「素絲」，第六句「泉鱼」《英华》作「淵鱼」，第十二句「荒岳」《英华》作「山丘」。","）。"]', '诗', 'shi', '', NULL, '夏彈琴（《文苑英華》二一二《音樂》、《初學記》一六「樂」部） 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad99220-9010-44c4-9157-b6d32e30df1a', '登樓', '登楼', '3851c360-9e76-40b3-a89b-a1bcf247633a', '唐', '["空（〖1〗《唐詩紀事》、《全唐詩》二五三作王之渙，《全唐詩》二○三又作處士朱斌。","〖2〗武后嘗吟詩云云，問是誰作，李嶠對曰：「御史朱佐日詩也。","」賜綵百疋，轉侍御史。","○《輿地紀勝》五《平江府·人物》、《中國人名大辭典》）（〖此詩作者凡有三說。","其一爲王之渙作，題作《登鸛鵲樓》，以《文苑英華》卷三一二所收爲最早，宋執行所著《溫公續詩話》、《夢溪筆談》卷十五、《唐詩紀事》卷二六皆沿之，今人亦多從此說。","其二爲朱斌作，以收詩迄止年代距王之渙去世僅隔二年〖天寶三載〗的芮挺章《國秀集》卷下爲最早，同書亦收有王之渙詩。","其三即朱佐日作，除《輿地紀勝》外，又見於《記纂淵海》卷二十四及《吳郡志》卷二十二，《吳郡志》幷注明此條出自《翰林盛事》。","《翰林盛事》爲唐人張著撰，約撰成於大曆、貞元間，今已佚，《郡齋讀書志》卷二、《直齋書錄解題》卷五均著錄。","以三說出現的次第言，朱斌最早，朱佐日次之，王之渙爲最遲。","《千唐誌齋藏誌》九○○頁有朱佐日墓誌，官武强縣尉，待物人，天寶十三載卒，年四十九，似爲另一人。","〗）。"]', '["空（〖1〗《唐诗紀事》、《全唐诗》二五三作王之渙，《全唐诗》二○三又作处士朱斌。","〖2〗武后嘗吟诗云云，问是誰作，李嶠对曰：「御史朱佐日诗也。","」賜綵百疋，轉侍御史。","○《輿地紀勝》五《平江府·人物》、《中国人名大辞典》）（〖此诗作者凡有三说。","其一爲王之渙作，題作《登鸛鵲楼》，以《文苑英华》卷三一二所收爲最早，宋執行所著《溫公續诗話》、《梦溪笔談》卷十五、《唐诗紀事》卷二六皆沿之，今人亦多從此说。","其二爲朱斌作，以收诗迄止年代距王之渙去世僅隔二年〖天寶三載〗的芮挺章《国秀集》卷下爲最早，同书亦收有王之渙诗。","其三即朱佐日作，除《輿地紀勝》外，又见於《記纂淵海》卷二十四及《吳郡志》卷二十二，《吳郡志》幷注明此條出自《翰林盛事》。","《翰林盛事》爲唐人張著撰，約撰成於大曆、貞元间，今已佚，《郡斋读书志》卷二、《直斋书錄解題》卷五均著錄。","以三说出現的次第言，朱斌最早，朱佐日次之，王之渙爲最遲。","《千唐誌斋藏誌》九○○頁有朱佐日墓誌，官武强縣尉，待物人，天寶十三載卒，年四十九，似爲另一人。","〗）。"]', '诗', 'shi', '', NULL, '登樓 朱佐日 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a51cad1-dec0-4c37-963b-4ecd77ca4d4c', '七言', '七言', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["生時不共作榮華，死後隨車强叫喚。","齊頭送到墓門迴，分你錢財各頭散。"]', '["生时不共作榮华，死後隨车强叫喚。","齊头送到墓门迴，分你錢財各头散。"]', '诗', 'shi', '', NULL, '七言 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('032abfdd-8c51-4bf4-b6dd-63b308ec6717', '五言（八首） 一', '五言（八首） 一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我肉衆生肉，形殊姓不殊。","元同一性命，只是別形軀。","苦痛教他死，將來作己須。"]', '["我肉衆生肉，形殊姓不殊。","元同一性命，只是別形軀。","苦痛教他死，將来作己須。"]', '诗', 'shi', '', NULL, '五言（八首） 一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('effdeedc-98d7-4832-86c7-7e2692660a88', '五言（八首） 二', '五言（八首） 二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["粗行出家兒，心中未平實。","貧齋行則遲，富齋行則疾。","貪他油煮䭔，我有波羅蜜。","飽食不知慙，受罪無休日。"]', '["粗行出家兒，心中未平實。","貧斋行則遲，富斋行則疾。","貪他油煮䭔，我有波羅蜜。","飽食不知慙，受罪無休日。"]', '诗', 'shi', '', NULL, '五言（八首） 二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f7dcc5-def6-4390-b5a0-257b31454999', '五言（八首） 三', '五言（八首） 三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["不願大大富，不願大大貧。","昨日了今日，今日了明晨。","此之大大因，[彼之大大身]。","（此句據《說郛》卷一引《雲溪友議》補。","）所願只如此，真成上上人。","（今按：疑缺第五句。","）。"]', '["不願大大富，不願大大貧。","昨日了今日，今日了明晨。","此之大大因，[彼之大大身]。","（此句據《说郛》卷一引《云溪友議》補。","）所願只如此，真成上上人。","（今按：疑缺第五句。","）。"]', '诗', 'shi', '', NULL, '五言（八首） 三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353c9d7d-7056-4780-800e-02c0c69b4144', '五言（八首） 四', '五言（八首） 四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["良田收百頃，兄弟猶工商。","却是成憂惱，珠金虛滿堂。","滿堂何所用？妻兒日夜忙。","行坐聞人死，不解暫思量。","貧兒二畝地，（自「貧兒二畝地」以下，張錫厚另作一首。","此句《說郛》作「買得貧家地。","」）乾枯十樹桑。","桑下種粟麥，四時供父娘。","圖謀未入手，祇是願饑荒。","結得百家怨，此身終受殃。"]', '["良田收百頃，兄弟猶工商。","却是成憂惱，珠金虛满堂。","满堂何所用？妻兒日夜忙。","行坐闻人死，不解暫思量。","貧兒二畝地，（自「貧兒二畝地」以下，張錫厚另作一首。","此句《说郛》作「買得貧家地。","」）乾枯十樹桑。","桑下種粟麦，四时供父娘。","圖謀未入手，祇是願饑荒。","結得百家怨，此身終受殃。"]', '诗', 'shi', '', NULL, '五言（八首） 四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f2b9b8-6a0d-4b1f-8d76-e4ed303b5d93', '五言（八首） 五', '五言（八首） 五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["本是尿屎袋，强將脂粉塗。","（原注：「音茶。","」）凡人無所識，喚作一團花。","相牽入地獄，此最是寃家。"]', '["本是尿屎袋，强將脂粉塗。","（原注：「音茶。","」）凡人無所識，喚作一團花。","相牽入地獄，此最是寃家。"]', '诗', 'shi', '', NULL, '五言（八首） 五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70da9dfa-c9d0-4833-bc17-cd02b352fbce', '五言（八首） 六', '五言（八首） 六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["照面不用鏡，布施不須財。","端坐念真相，此便是如來。"]', '["照面不用镜，布施不須財。","端坐念真相，此便是如来。"]', '诗', 'shi', '', NULL, '五言（八首） 六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74350f0b-aa7d-4912-8a7e-87a0e2d44ffa', '五言（八首） 七', '五言（八首） 七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["大皮裏大樹，小皮裏小木。","生兒不用多，了事一箇足。","省得分田宅，無人橫煎蹙。","但行平等心，天亦念孤獨。","我身雖孤獨，（自「我身雖孤獨」以下，張錫厚作另一首。","）未死先懷慮。","家有五男兒，哭我無所據。","哭我我不聞，不哭我亦去。"]', '["大皮裏大樹，小皮裏小木。","生兒不用多，了事一箇足。","省得分田宅，無人橫煎蹙。","但行平等心，天亦念孤独。","我身雖孤独，（自「我身雖孤独」以下，張錫厚作另一首。","）未死先懷慮。","家有五男兒，哭我無所據。","哭我我不闻，不哭我亦去。"]', '诗', 'shi', '', NULL, '五言（八首） 七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052ae95a-1879-46ba-a16b-a2d81c997eca', '五言（八首） 八', '五言（八首） 八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世間何物貴？無價是詩書。","了了說仁義，愚夫都不知。","深房禁婢妾，對客誇妻兒。","青石甃行路，未知身死時。","（以上五七言共九首，空虛錄自《雲谿友議》下）。"]', '["世间何物貴？無價是诗书。","了了说仁義，愚夫都不知。","深房禁婢妾，对客誇妻兒。","青石甃行路，未知身死时。","（以上五七言共九首，空虛錄自《云谿友議》下）。"]', '诗', 'shi', '', NULL, '五言（八首） 八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb1f2b57-0f1e-46eb-a846-779c320b7a53', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 一', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兀然無事改換，無事何須論一段。","直心無散亂，他事不須斷。","過去已過去，未來何用算。"]', '["兀然無事改換，無事何須論一段。","直心無散亂，他事不須斷。","過去已過去，未来何用算。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70f228a7-12ec-4807-94a0-bad185450534', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 二', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 二', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["兀然無一事，何曾有人喚。","向外覓功夫，總是癡頑漢。","糧不畜一粒，逢飯便知{嗎灬=廾}。","世間多事人，相趁渾不反。"]', '["兀然無一事，何曾有人喚。","向外覓功夫，總是癡頑漢。","糧不畜一粒，逢飯便知{嗎灬=廾}。","世间多事人，相趁渾不反。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 二 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f9e81b8-a4ef-4e15-b2ae-fd35b7f36628', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 三', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 三', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["我不樂生天，亦不愛福田。","饑來一鉢飯，困來展脚眠。","愚人以爲笑，智者謂之然。","非愚亦非智，不是玄中玄。"]', '["我不乐生天，亦不愛福田。","饑来一鉢飯，困来展脚眠。","愚人以爲笑，智者謂之然。","非愚亦非智，不是玄中玄。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 三 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d470325-2d3e-4a16-b6ec-935f921cb873', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 四', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 四', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["要去如是去，要住如住。","身披一破衲，脚著娘生袴。","多言復多語，由來反相誤。","若欲度衆生，無過且自度。"]', '["要去如是去，要住如住。","身披一破衲，脚著娘生袴。","多言复多語，由来反相誤。","若欲度衆生，無過且自度。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 四 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130fa7c2-a043-4ced-b693-a4085944634e', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 五', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 五', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["莫漫求真佛，真佛不可見。","妙性及靈臺，何曾受薰鍊。","心是無事心，面是娘生面。","劫石可動搖，箇中無改變。"]', '["莫漫求真佛，真佛不可见。","妙性及靈台，何曾受薰鍊。","心是無事心，面是娘生面。","劫石可动搖，箇中無改变。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 五 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4048b4a4-38de-4f82-8da3-10997d4a0b90', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 六', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 六', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["無事何須讀文字，削除人我本，冥合箇中意。","種種勞筋骨，不如林中睡兀兀。","舉頭見日出，乞飯從頭𢫫。"]', '["無事何須读文字，削除人我本，冥合箇中意。","種種勞筋骨，不如林中睡兀兀。","舉头见日出，乞飯從头𢫫。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 六 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b255b4c-60ba-493f-a7d9-be760443d9c4', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 七', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 七', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["將功用功，展轉冥蒙。","取即不得，不取自通。"]', '["將功用功，展轉冥蒙。","取即不得，不取自通。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 七 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9236205c-5729-49f4-aa1a-be2fe7a65df2', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 八', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 八', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["吾有一言，絕慮忘緣。","巧說不得，只用心傳。"]', '["吾有一言，絕慮忘緣。","巧说不得，只用心傳。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 八 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2daed6b5-8f5b-4d2a-93b4-136f8f4cbc43', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 九', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 九', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["更有一語，無過直與。","細極毫末，大無方所。","本自圓成，不勞機杼。"]', '["更有一語，無過直與。","細極毫末，大無方所。","本自圓成，不勞機杼。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 九 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13f89643-732b-4f43-8e77-d840a269c934', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 十', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 十', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["世事悠悠，不如山丘。","青松蔽日，碧澗常秋。","山雲當幕，夜月爲鉤。","臥藤蘿下，塊石枕頭。","不朝天子，豈羨王侯？","生死無慮，更復何憂。"]', '["世事悠悠，不如山丘。","青松蔽日，碧澗常秋。","山云當幕，夜月爲鉤。","臥藤蘿下，塊石枕头。","不朝天子，豈羨王侯？","生死無慮，更复何憂。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 十 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01f2cd7-8482-4630-a8ae-b5d336b95146', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 十一', '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 十一', '19db254f-5960-4bc1-bd56-30131177dae9', '唐', '["水月無形，我常只寧。","萬法皆爾，本自無生。","兀然無事坐，春來草自青。","（高士奇《江邨銷夏錄》卷二黃庭堅書梵志詩卷○董其昌題云：「黃文節公書，世多摹本，又多贋本。","生平所見，以此卷爲灼然無疑。","梵志詩較寒山更自奇崛，書亦近之。","」）（此組詩，黃庭堅自跋不云爲王梵志作，至董其昌作跋時始斷爲王梵志作，實誤。","此詩爲唐大曆間衡嶽僧明瓚〖即懶殘〗作，見《祖堂集》卷三、《景德傳燈錄》卷三十、《南嶽總勝集》卷下、《林間錄》等書。","諸書異文較多，另參《全唐詩續拾》卷十五。","另項楚對此有考證，文刊《中華文史論叢》。","又原詩爲長詩一首，此處析爲十一首，亦未允。","）。"]', '["水月無形，我常只寧。","万法皆爾，本自無生。","兀然無事坐，春来草自青。","（高士奇《江邨銷夏錄》卷二黄庭堅书梵志诗卷○董其昌題云：「黄文節公书，世多摹本，又多贋本。","生平所见，以此卷爲灼然無疑。","梵志诗較寒山更自奇崛，书亦近之。","」）（此組诗，黄庭堅自跋不云爲王梵志作，至董其昌作跋时始斷爲王梵志作，實誤。","此诗爲唐大曆间衡嶽僧明瓚〖即懶殘〗作，见《祖堂集》卷三、《景德傳灯錄》卷三十、《南嶽總勝集》卷下、《林间錄》等书。","諸书異文較多，另參《全唐诗續拾》卷十五。","另項楚对此有考證，文刊《中华文史論叢》。","又原诗爲长诗一首，此处析爲十一首，亦未允。","）。"]', '诗', 'shi', '', NULL, '兀然無事（原卷缺題，不分篇段，現將分爲十一首） 十一 王梵志 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de212439-fa06-445d-a7b1-29158d24fd05', '五言白話詩', '五言白話诗', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["（原缺卷首。","劉復云：「抄出者共四十六首。","」現選錄二十六首張錫厚《王梵志詩校輯》云與劉復所見伯三二一一卷同一系統的敦煌遺書尚有斯五四四一、斯五六四一兩卷。","其中斯五四四一卷題作「王梵志立詩集卷中」，因知伯三二一一卷諸詩亦應爲王梵志作。","）。"]', '["（原缺卷首。","劉复云：「抄出者共四十六首。","」現選錄二十六首張錫厚《王梵志诗校輯》云與劉复所见伯三二一一卷同一系統的敦煌遺书尚有斯五四四一、斯五六四一兩卷。","其中斯五四四一卷題作「王梵志立诗集卷中」，因知伯三二一一卷諸诗亦應爲王梵志作。","）。"]', '诗', 'shi', '', NULL, '五言白話詩 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde9c1db-2496-4d2a-b21b-7d47c48035dd', '五言白話詩 一', '五言白話诗 一', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["村頭語戶主，鄉頭無處得。","在縣用紙多，從吾相便貸。","我命自貧窮，獨辨不可得。","（「辨」，張錫厚改作「辧」。","）合村看我面，此度必須得。","後衙空手去，定是搦你勒。","（「搦」，斯五四四一卷作「獨」，據張錫厚改。","）。"]', '["村头語戶主，乡头無处得。","在縣用紙多，從吾相便貸。","我命自貧窮，独辨不可得。","（「辨」，張錫厚改作「辧」。","）合村看我面，此度必須得。","後衙空手去，定是搦你勒。","（「搦」，斯五四四一卷作「独」，據張錫厚改。","）。"]', '诗', 'shi', '', NULL, '五言白話詩 一 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('259b0b8c-1242-4dff-90c2-cfb9878813b5', '五言白話詩 二', '五言白話诗 二', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["人生一代間，貧富不覺老。","王役逼駈駈，走多換行少。","（「換行少」，斯五四四一卷作「緣行步」。","）他家馬上坐，我身步擎草。","種得果報緣，不須自煩惱。","受報人中生，（自「受報人中生」以下，張錫厚另作一首。","）本爲前身罪。","今身不修福，癡愚膿血袋。","病困臥着牀，慳心由不改。","（「由」，斯五四四一卷作「猶」。","）臨死命欲終，𢗞財不懺悔。","身死妻後嫁，總將陪新壻。"]', '["人生一代间，貧富不覺老。","王役逼駈駈，走多換行少。","（「換行少」，斯五四四一卷作「緣行步」。","）他家马上坐，我身步擎草。","種得果報緣，不須自煩惱。","受報人中生，（自「受報人中生」以下，張錫厚另作一首。","）本爲前身罪。","今身不修福，癡愚膿血袋。","病困臥着牀，慳心由不改。","（「由」，斯五四四一卷作「猶」。","）臨死命欲終，𢗞財不懺悔。","身死妻後嫁，總將陪新壻。"]', '诗', 'shi', '', NULL, '五言白話詩 二 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d26aad1-0761-4492-904c-4ee637e64618', '五言白話詩 三', '五言白話诗 三', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["世間何物貴？只有我身是。","不見好出生，衣食穀米費。","廣貪長命財，纏繩短命鬼。","放頑鄰里行，元來不怕死。"]', '["世间何物貴？只有我身是。","不见好出生，衣食穀米費。","廣貪长命財，纏繩短命鬼。","放頑鄰里行，元来不怕死。"]', '诗', 'shi', '', NULL, '五言白話詩 三 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a25b2f1d-9fb6-474b-8d7a-ec7f61fdb5da', '五言白話詩 四', '五言白話诗 四', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["世間慵懶人，五分向有二。","例着一草衫，兩膊成山字。","出語觜頭高，（「觜」，斯五四四一卷作「嘴」。","）詐作達官子。","草舍元無床，無氊復無被。","他家人定臥，日西展脚睡。","諸人五更走，日高未肯起。","朝庭數千人，（自「朝庭數千人」以下，張錫厚另作一首。","項楚謂另作一首不當。","）平章共傳戲。","菜粥喫一𪲄，（「𪲄」，斯五四四一卷作「盔」。","）街頭闊立地。","（「濶」，項楚校作「閑」。","）逢人若共語，荒說天下事。","喚女作家生，將兒作奴使。","妻即赤體行，尋常飢欲死。","一羣病賴賊，（「賴」，張錫厚改「懶」，項楚校作「癩」。","）却搦父母耻。","日月甚寬恩，不照五逆鬼。"]', '["世间慵懶人，五分向有二。","例着一草衫，兩膊成山字。","出語觜头高，（「觜」，斯五四四一卷作「嘴」。","）詐作達官子。","草舍元無床，無氊复無被。","他家人定臥，日西展脚睡。","諸人五更走，日高未肯起。","朝庭數千人，（自「朝庭數千人」以下，張錫厚另作一首。","項楚謂另作一首不當。","）平章共傳戲。","菜粥喫一𪲄，（「𪲄」，斯五四四一卷作「盔」。","）街头闊立地。","（「濶」，項楚校作「闲」。","）逢人若共語，荒说天下事。","喚女作家生，將兒作奴使。","妻即赤體行，尋常飢欲死。","一羣病賴賊，（「賴」，張錫厚改「懶」，項楚校作「癩」。","）却搦父母耻。","日月甚寬恩，不照五逆鬼。"]', '诗', 'shi', '', NULL, '五言白話詩 四 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0643ea93-5847-44d9-adca-3c4d121b04c5', '五言白話詩 五', '五言白話诗 五', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["家中漸漸貧，良由慵懶婦。","長頭愛床坐，飽喫沒娑肚。","頻年懃生兒，不肯收家具。","飲酒五夫敵，不解縫衫袴。","（「不解」，斯五六四一卷作「不能」。","）事當好衣裳，得便走出去。","不要男爲伴，心裏恒攀慕。","東家能湼舌，西家好合[鬭]。","兩家既不和，角眼相蛆姡。","別覓好時對，趁却莫交住。","。"]', '["家中漸漸貧，良由慵懶婦。","长头愛床坐，飽喫沒娑肚。","頻年懃生兒，不肯收家具。","饮酒五夫敵，不解縫衫袴。","（「不解」，斯五六四一卷作「不能」。","）事當好衣裳，得便走出去。","不要男爲伴，心裏恒攀慕。","东家能湼舌，西家好合[鬭]。","兩家既不和，角眼相蛆姡。","別覓好时对，趁却莫交住。","。"]', '诗', 'shi', '', NULL, '五言白話詩 五 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bed3a0a-046c-48eb-9bd1-837f0dd6966e', '五言白話詩 六', '五言白話诗 六', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["用錢索新婦，當家有新故。","兒替阿耶來，新婦替家母。","替人既倒來，（「倒」，斯五六四一卷作「到」。","）條錄相分付。","新婦知家事，兒郎永門戶。","（「永」，斯五六四一卷作「丞」，張錫厚改作「承」）好衣我須着，好食入我肚。","我老妻亦老，替代不得住。","語你夫妻道，我死還到汝。"]', '["用錢索新婦，當家有新故。","兒替阿耶来，新婦替家母。","替人既倒来，（「倒」，斯五六四一卷作「到」。","）條錄相分付。","新婦知家事，兒郎永门戶。","（「永」，斯五六四一卷作「丞」，張錫厚改作「承」）好衣我須着，好食入我肚。","我老妻亦老，替代不得住。","語你夫妻道，我死還到汝。"]', '诗', 'shi', '', NULL, '五言白話詩 六 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d934c0ad-1d67-42ac-8da6-d98026dfad2c', '五言白話詩 七', '五言白話诗 七', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["孝是前身緣，不由相放習。","兒行不憶母，母恒行坐泣。","兒行母亦征，項膇連腦急。","聞道賊出來，母愁空有骨。","兒迴見母面，顏色肥沒忽。"]', '["孝是前身緣，不由相放習。","兒行不憶母，母恒行坐泣。","兒行母亦征，項膇連腦急。","闻道賊出来，母愁空有骨。","兒迴见母面，顏色肥沒忽。"]', '诗', 'shi', '', NULL, '五言白話詩 七 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133dff39-4b6b-4aaa-803a-601f145d7f54', '五言白話詩 八', '五言白話诗 八', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["聞道須鬼兵，逢頭即須搦。","欲似園中果，未熟亦須摘。","老少總皆去，共同衆死厄。","長命得八十，恰同寄住客。","蹔在主人家，不久自分擘。","喻若行路人，前後踏光陌。","（「光」，戴密微校作「巷」。","）。"]', '["闻道須鬼兵，逢头即須搦。","欲似园中果，未熟亦須摘。","老少總皆去，共同衆死厄。","长命得八十，恰同寄住客。","蹔在主人家，不久自分擘。","喻若行路人，前後踏光陌。","（「光」，戴密微校作「巷」。","）。"]', '诗', 'shi', '', NULL, '五言白話詩 八 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81a61b64-d797-43d3-b909-bc6ceb6cdb9d', '五言白話詩 九', '五言白話诗 九', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["自生還自死，煞活非關我。","續續生出來，世間無處坐。","若不急抽却，眼看塞天破。"]', '["自生還自死，煞活非关我。","續續生出来，世间無处坐。","若不急抽却，眼看塞天破。"]', '诗', 'shi', '', NULL, '五言白話詩 九 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b233c9b7-a231-4267-94c8-1654ae171327', '五言白話詩 十', '五言白話诗 十', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["天下惡官職，不過是府兵。","四面有賊動，當日即須行。","有緣重相見，業薄即隔生。","逢賊被打煞，五品無人諍。","生住無常界，（項楚云此句以下應移入下一首。","）攘攘滿街行。","只擬人間死，不肯佛邊生。"]', '["天下惡官職，不過是府兵。","四面有賊动，當日即須行。","有緣重相见，業薄即隔生。","逢賊被打煞，五品無人諍。","生住無常界，（項楚云此句以下應移入下一首。","）攘攘满街行。","只擬人间死，不肯佛邊生。"]', '诗', 'shi', '', NULL, '五言白話詩 十 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9de8f42-50c8-4702-859d-24ac85432ffe', '五言白話詩 十一', '五言白話诗 十一', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["從頭捉將去，「頑骨」不心擎。","（「頑骨」二字據斯五六四一卷補。","「擎」，斯五六四一卷作「驚」。","）雖然畜兩眼，終是一雙盲。","向前黑如漆，直掇入深坑。","沉淪苦海裏，何日更逢明？。"]', '["從头捉將去，「頑骨」不心擎。","（「頑骨」二字據斯五六四一卷補。","「擎」，斯五六四一卷作「驚」。","）雖然畜兩眼，終是一雙盲。","向前黑如漆，直掇入深坑。","沉淪苦海裏，何日更逢明？。"]', '诗', 'shi', '', NULL, '五言白話詩 十一 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54303255-32f4-466c-9563-19be91dd4bcf', '五言白話詩 十二', '五言白話诗 十二', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["本是達官兒，名作郎君子。","從小好讀書，更須多識字。","長大人中官，當衙判曹事。","高馬衣輕裘，伴涉諸王子。","官高漸入朝，供奉親天子。","縱得公王侯，終歸不免死。"]', '["本是達官兒，名作郎君子。","從小好读书，更須多識字。","长大人中官，當衙判曹事。","高马衣轻裘，伴涉諸王子。","官高漸入朝，供奉親天子。","縱得公王侯，終归不免死。"]', '诗', 'shi', '', NULL, '五言白話詩 十二 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a8b2f7-5ff0-4ee1-9a39-76ee43fd7b1b', '五言白話詩 十三', '五言白話诗 十三', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["秋長夜甚明，長夜照衆生。","死者歸長路，生者蹔時行。","夜眠由鬼界，天曉即營生。","兩兩相刼奪，分毫努眼淨。","賢愚不相識。","壤壤信緣行。"]', '["秋长夜甚明，长夜照衆生。","死者归长路，生者蹔时行。","夜眠由鬼界，天晓即營生。","兩兩相刼奪，分毫努眼淨。","賢愚不相識。","壤壤信緣行。"]', '诗', 'shi', '', NULL, '五言白話詩 十三 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdc2e3ff-be5e-46d9-a369-a7340db5bf3d', '五言白話詩 十四', '五言白話诗 十四', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["工匠莫學巧，巧即他人使。","身是自來奴，妻亦官人婢。","夫壻蹔時無，曳將仍被耻。","未作道與錢，作了擘眼你。"]', '["工匠莫学巧，巧即他人使。","身是自来奴，妻亦官人婢。","夫壻蹔时無，曳將仍被耻。","未作道與錢，作了擘眼你。"]', '诗', 'shi', '', NULL, '五言白話詩 十四 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20bf057c-ad78-447d-9634-7b3045da6017', '五言白話詩 十五', '五言白話诗 十五', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["奴人賜酒食，恩言出義氣。","（「奴」，項楚校作「好」。","「義」，蔣紹愚校作「美」。","）無賴不與錢，蛆心打脊使。","貧窮實可憐，饑寒肚露地。","戶役一槩差，不辧棒下死。","可出頭坐，誰肯被鞭耻。","何爲拋宅走，良由不得止。"]', '["奴人賜酒食，恩言出義氣。","（「奴」，項楚校作「好」。","「義」，蔣紹愚校作「美」。","）無賴不與錢，蛆心打脊使。","貧窮實可怜，饑寒肚露地。","戶役一槩差，不辧棒下死。","可出头坐，誰肯被鞭耻。","何爲拋宅走，良由不得止。"]', '诗', 'shi', '', NULL, '五言白話詩 十五 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4a70cb-8251-46af-9f54-32c60a7f571f', '五言白話詩 十六', '五言白話诗 十六', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["狼多羊數少，莫畜惡兒子。","年是無限年，你身甚急速。","有意造罪根，無心念諸佛。","你從何處來，膿血相和出。","身如水上泡，暫時還却沒。","魂魄游空虛，盲人入闇窟。","生死如江河，波浪𧉸啾唧。","（「𧉸」，斯五六四一卷作「沸」）。"]', '["狼多羊數少，莫畜惡兒子。","年是無限年，你身甚急速。","有意造罪根，無心念諸佛。","你從何处来，膿血相和出。","身如水上泡，暫时還却沒。","魂魄游空虛，盲人入闇窟。","生死如江河，波浪𧉸啾唧。","（「𧉸」，斯五六四一卷作「沸」）。"]', '诗', 'shi', '', NULL, '五言白話詩 十六 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d072027-53c3-450a-bd10-3c784cc7f8be', '五言白話詩 十七', '五言白話诗 十七', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["世間日月明，皎皎照衆生。","貴者乘車馬，賤者膊膽行。","富者前身種，貧者慳貪生。","貧富有殊別，業報自相迎。","聞强造功德，喫着自身榮。","智者天上去，愚者入深坑。"]', '["世间日月明，皎皎照衆生。","貴者乘车马，賤者膊膽行。","富者前身種，貧者慳貪生。","貧富有殊別，業報自相迎。","闻强造功德，喫着自身榮。","智者天上去，愚者入深坑。"]', '诗', 'shi', '', NULL, '五言白話詩 十七 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4919ffa2-00f3-4e41-bd42-0b07863fd09d', '五言白話詩 十八', '五言白話诗 十八', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["身如大店家，命如一宿客。","忽起向前去，本不是吾宅。","吾宅在丘荒，園林出松柏。","隣接千年塚，故路來長陌。","。"]', '["身如大店家，命如一宿客。","忽起向前去，本不是吾宅。","吾宅在丘荒，园林出松柏。","隣接千年塚，故路来长陌。","。"]', '诗', 'shi', '', NULL, '五言白話詩 十八 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36fe0011-a84b-4cd6-adcb-e489d11c758c', '五言白話詩 十九', '五言白話诗 十九', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["身臥空堂內，獨坐令人怕。","我今避頭去，拋却空閑舍。","（項楚謂以上四句應自爲一首。","）你道生時樂，吾道死時好。","死即長夜眠，生即緣長道。","生時愁衣食，死鬼無釜竃。","願作製撥鬼，入家偷喫飽。"]', '["身臥空堂內，独坐令人怕。","我今避头去，拋却空闲舍。","（項楚謂以上四句應自爲一首。","）你道生时乐，吾道死时好。","死即长夜眠，生即緣长道。","生时愁衣食，死鬼無釜竃。","願作製撥鬼，入家偷喫飽。"]', '诗', 'shi', '', NULL, '五言白話詩 十九 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba746ca-1646-4b73-9020-a00cad257390', '五言白話詩 二十', '五言白話诗 二十', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["身如破皮袋，盛膿兼裏骨。","將板作皮裘，埋入深坑窟。","一入恒沙劫，無由更得出。","除非寒食節，子孫塚傍泣。"]', '["身如破皮袋，盛膿兼裏骨。","將板作皮裘，埋入深坑窟。","一入恒沙劫，無由更得出。","除非寒食節，子孫塚傍泣。"]', '诗', 'shi', '', NULL, '五言白話詩 二十 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb6edaf-7132-47e8-a439-398b73079638', '五言白話詩 二十一', '五言白話诗 二十一', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["世間何物平？不過死一色。","老小終須去，信前業道力。","縱使公王侯，用錢遮不得。","各身改頭皮，相逢定不識。"]', '["世间何物平？不過死一色。","老小終須去，信前業道力。","縱使公王侯，用錢遮不得。","各身改头皮，相逢定不識。"]', '诗', 'shi', '', NULL, '五言白話詩 二十一 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('193212b1-e8d1-43f6-a416-d55a4d3705c6', '五言白話詩 二十二', '五言白話诗 二十二', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["身如內架堂，（「內」，項楚校作「肉」。","）命似堂中燭。","風急吹燭滅，即是空堂屋。","家貧無好衣，（自「家貧無好衣」以下，張錫厚作另一首。","）造得一襖子。","中心禳破氈，還將布作裏。","清貧常使樂，不用濁富貴。","白日串項行，夜眠還作被。"]', '["身如內架堂，（「內」，項楚校作「肉」。","）命似堂中燭。","风急吹燭滅，即是空堂屋。","家貧無好衣，（自「家貧無好衣」以下，張錫厚作另一首。","）造得一襖子。","中心禳破氈，還將布作裏。","清貧常使乐，不用濁富貴。","白日串項行，夜眠還作被。"]', '诗', 'shi', '', NULL, '五言白話詩 二十二 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084e1bd0-cfba-422d-9376-c06684b8f355', '五言白話詩 二十三', '五言白話诗 二十三', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["人生一代間，有錢須喫着。","四海並交游，風光亦須覓。","錢財只恨無，有時實不惜。","聞身强健時，多施還須喫。"]', '["人生一代间，有錢須喫着。","四海並交游，风光亦須覓。","錢財只恨無，有时實不惜。","闻身强健时，多施還須喫。"]', '诗', 'shi', '', NULL, '五言白話詩 二十三 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a435a209-c308-4abe-9885-d8217a1c9d86', '五言白話詩 二十四', '五言白話诗 二十四', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["生坐四合舍。","死入土角䚥。","窅窅黑闇眠，永別明燈燭。","死鬼憶四時，八節生人哭。"]', '["生坐四合舍。","死入土角䚥。","窅窅黑闇眠，永別明灯燭。","死鬼憶四时，八節生人哭。"]', '诗', 'shi', '', NULL, '五言白話詩 二十四 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa8c9936-b75a-4c5a-85b4-1b5999b23d19', '五言白話詩 二十五', '五言白話诗 二十五', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["虛霑一百年，八十最是老。","逢頭捉將去，無老亦無小。","須臾得暫時，恰同霜下草。","橫遭狂風吹，總即連根倒。","悠悠度今日，今夜誰能保。","語你愚癡人，急修未來道。"]', '["虛霑一百年，八十最是老。","逢头捉將去，無老亦無小。","須臾得暫时，恰同霜下草。","橫遭狂风吹，總即連根倒。","悠悠度今日，今夜誰能保。","語你愚癡人，急修未来道。"]', '诗', 'shi', '', NULL, '五言白話詩 二十五 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf164281-a721-4853-81ca-c93f0db0ae87', '五言白話詩 二十六', '五言白話诗 二十六', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["暫出門前觀，川原足故塚。","富者造山門，貧者如破瓮。","年年並舍多，歲歲成街巷。","前死後人塒，鬼補悲聲送。","縱得百年活，還入土孔籠。","（以上《燉煌掇瑣》三一引伯希和卷三二一一）。"]', '["暫出门前观，川原足故塚。","富者造山门，貧者如破瓮。","年年並舍多，歲歲成街巷。","前死後人塒，鬼補悲声送。","縱得百年活，還入土孔籠。","（以上《燉煌掇瑣》三一引伯希和卷三二一一）。"]', '诗', 'shi', '', NULL, '五言白話詩 二十六 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0519f6e-4652-43ac-b657-b6bf415167bf', '五言詩', '五言诗', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["（原爲長篇連續不斷。","劉復云：「卷殘，抄出者共五十二首。","」現選錄十首。","〖張錫厚《王梵志詩校輯》卷五云與伯三四一八卷爲同一系統的敦煌遺書尚有伯三七二四、斯六○三二、蘇二八五二等三卷。","今即據其所錄校補。","此組詩作者，張錫厚推測亦應爲王梵志，但尚缺明確的證據。","〗）。"]', '["（原爲长篇連續不斷。","劉复云：「卷殘，抄出者共五十二首。","」現選錄十首。","〖張錫厚《王梵志诗校輯》卷五云與伯三四一八卷爲同一系統的敦煌遺书尚有伯三七二四、斯六○三二、蘇二八五二等三卷。","今即據其所錄校補。","此組诗作者，張錫厚推測亦應爲王梵志，但尚缺明確的證據。","〗）。"]', '诗', 'shi', '', NULL, '五言詩 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('927c896f-51ad-4d6e-a8df-2daf5775562c', '五言詩 一', '五言诗 一', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["審看世上人，有賤亦有貴。","賤者由慳貪，𢗞財不布施。","貴賤既有殊，業報前生值。","（「值」，戴密微、項楚校作「植」。","項楚謂以上應爲一首。","）有錢但喫着，（「有錢」，伯三七二四卷作「有財」。","）實莫留樻□。","（「樻□」，原缺一字，伯三七二四卷作「田柜」，張錫厚改作「填櫃」。","）一日厥摩師，（自「一日厥摩師」以下，張錫厚另作另一首。","）他用不由你。","妻嫁親後夫，子心隨母意。","我物我不用，我自無意智。","未有千年身，（「千年」，伯三七二四卷作「百年」。","）從作千年事。","（「從作」，伯三七二四卷作「徒使」。","）。"]', '["審看世上人，有賤亦有貴。","賤者由慳貪，𢗞財不布施。","貴賤既有殊，業報前生值。","（「值」，戴密微、項楚校作「植」。","項楚謂以上應爲一首。","）有錢但喫着，（「有錢」，伯三七二四卷作「有財」。","）實莫留樻□。","（「樻□」，原缺一字，伯三七二四卷作「田柜」，張錫厚改作「填櫃」。","）一日厥摩師，（自「一日厥摩師」以下，張錫厚另作另一首。","）他用不由你。","妻嫁親後夫，子心隨母意。","我物我不用，我自無意智。","未有千年身，（「千年」，伯三七二四卷作「百年」。","）從作千年事。","（「從作」，伯三七二四卷作「徒使」。","）。"]', '诗', 'shi', '', NULL, '五言詩 一 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e281d1-2a52-4026-8e59-0a9a1377285e', '五言詩 二', '五言诗 二', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["吾死不須哭，徒勞枉却聲。","祇用四片板，四角八枚丁。","急手涂埋却，（「涂」，袁賓、項楚校作「深」。","）臭穢不中亭。","墓內不須食，麥酒三五瓶。","（「麥」酒，張錫厚錄作「美酒」，伯三七二四卷作「羹酒」。","）時時獨飲樂，飲盡更須傾。","（「飲」，伯三七二四卷作「沉」。","）只願長頭醉，作伴喚劉伶。","你道生勝死（自「你道生勝死」以下，張錫厚另作一首。","），我道死勝生。","生即苦戰死，死即無人征。","十六作夫役，二十充府兵。","磧裏向前走，衣鉀困須擎。","白日趁食地，每也悉知更。","（「每也」，伯三七二四卷作「□夜」。","）鐵鉢淹甘飯，同火共分諍。","長頭饑欲旺。","（「旺」，伯三七二四卷作「死」。","）[肚]似砍窮坑。","（「肚」字據伯三七二四卷補。","「砍」，伯三七二四卷作「破」。","）遺兒我受苦，（「遺」，伯三七二四卷作「遣」。","）慈母不須生。","相將歸去來，（自「相將歸去來」以下，張錫厚另作一首。","）間不浮可亭。","（「間不浮可亭」，伯三七二四卷作「閻浮不可停」。","）婦人因重役，（「因」，伯三七二四卷作「應」。","戴密微校作「困」。","）男子從征行。","帶刀擬開煞，逢陣即相刑。","將軍馬上死，兵滅地君營。","（「君」，伯三七二四卷作「居」。","「地君」，袁賓校作「敵軍」，戴密微校作「他君」。","）血流遍荒野，白骨在邊庭。","去馬游殘跡，（項楚校「游」爲「猶」。","）空留紙上名。","關山千萬里，影絕故鄉城。","生受刀光苦，意裏極皇皇。","（「皇皇」，呂朋林謂當爲「星星」，即「惺惺」。","）。"]', '["吾死不須哭，徒勞枉却声。","祇用四片板，四角八枚丁。","急手涂埋却，（「涂」，袁賓、項楚校作「深」。","）臭穢不中亭。","墓內不須食，麦酒三五瓶。","（「麦」酒，張錫厚錄作「美酒」，伯三七二四卷作「羹酒」。","）时时独饮乐，饮尽更須傾。","（「饮」，伯三七二四卷作「沉」。","）只願长头醉，作伴喚劉伶。","你道生勝死（自「你道生勝死」以下，張錫厚另作一首。","），我道死勝生。","生即苦戰死，死即無人征。","十六作夫役，二十充府兵。","磧裏向前走，衣鉀困須擎。","白日趁食地，每也悉知更。","（「每也」，伯三七二四卷作「□夜」。","）鐵鉢淹甘飯，同火共分諍。","长头饑欲旺。","（「旺」，伯三七二四卷作「死」。","）[肚]似砍窮坑。","（「肚」字據伯三七二四卷補。","「砍」，伯三七二四卷作「破」。","）遺兒我受苦，（「遺」，伯三七二四卷作「遣」。","）慈母不須生。","相將归去来，（自「相將归去来」以下，張錫厚另作一首。","）间不浮可亭。","（「间不浮可亭」，伯三七二四卷作「閻浮不可停」。","）婦人因重役，（「因」，伯三七二四卷作「應」。","戴密微校作「困」。","）男子從征行。","带刀擬开煞，逢陣即相刑。","將軍马上死，兵滅地君營。","（「君」，伯三七二四卷作「居」。","「地君」，袁賓校作「敵軍」，戴密微校作「他君」。","）血流遍荒野，白骨在邊庭。","去马游殘跡，（項楚校「游」爲「猶」。","）空留紙上名。","关山千万里，影絕故乡城。","生受刀光苦，意裏極皇皇。","（「皇皇」，呂朋林謂當爲「星星」，即「惺惺」。","）。"]', '诗', 'shi', '', NULL, '五言詩 二 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a10a14-7f63-4bf8-b1a2-ef6ebec77ce2', '五言詩 三', '五言诗 三', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["夫婦生五男，幷有一雙女。","兒大須娶妻，女大須嫁處。","（「處」，項楚校爲「去」。","）戶役差耕來，（「差耕」，伯三七二四卷作「差科」。","）棄拋我夫婦。","（「拋」，伯三七二四卷作「挽」。","）妻即無裙祓，（「裙祓」，伯三七二四卷作「褐被」。","袁賓校「裙被」。","）夫體無褌袴。","父母俱八十，兒年五十五。","當頭憂妻兒，（「憂」，伯三七二四卷作「養」。","）不勤養父母。","渾家少糧食，尋常空餓肚。","男女一處生，（「生」，伯三七二四卷作「坐」。","「處」，項楚校作「出」。","）却似餓狼虎。","粗飯衆厨飡，美味當房傳佉。","（「佉」，伯三七二四卷作「棄」，張錫厚改作「去」。","）努眼看尊親，只覓乳食處。","少年生平又，（「平又」，伯三七二四卷作「夜□」，張錫厚改作「夜樂」，項楚校爲「夜叉」。","）老頭自受苦。","。"]', '["夫婦生五男，幷有一雙女。","兒大須娶妻，女大須嫁处。","（「处」，項楚校爲「去」。","）戶役差耕来，（「差耕」，伯三七二四卷作「差科」。","）棄拋我夫婦。","（「拋」，伯三七二四卷作「挽」。","）妻即無裙祓，（「裙祓」，伯三七二四卷作「褐被」。","袁賓校「裙被」。","）夫體無褌袴。","父母俱八十，兒年五十五。","當头憂妻兒，（「憂」，伯三七二四卷作「養」。","）不勤養父母。","渾家少糧食，尋常空餓肚。","男女一处生，（「生」，伯三七二四卷作「坐」。","「处」，項楚校作「出」。","）却似餓狼虎。","粗飯衆厨飡，美味當房傳佉。","（「佉」，伯三七二四卷作「棄」，張錫厚改作「去」。","）努眼看尊親，只覓乳食处。","少年生平又，（「平又」，伯三七二四卷作「夜□」，張錫厚改作「夜乐」，項楚校爲「夜叉」。","）老头自受苦。","。"]', '诗', 'shi', '', NULL, '五言詩 三 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('794a6f9a-3e7b-4b2a-93e1-e7258ce04796', '五言詩 四', '五言诗 四', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["一歲已百年，（「已」，伯三七二四卷作「與」。","）中間不怕死。","長命得八十，漸漸無意智。","悉能造罪根，不解生慚愧。","廣貪長命財，身當短命死。","興生向前走，惟求多出利。","析心即心枉，（「析心」，伯三七二四卷作「折本」。","）惶惶煩惱起。","錢逸即獨富，（「逸」，伯三七二四卷作「𨓚」，張錫厚定作「兌」，蔣紹愚校作「遶」，逮「饒」。","）吾貧長省事。","奴富欺郎君，婢富遠娘子。","（「富遠」，伯三七二四卷作「有陵〖淩〗」。","）鳥饑緣食亡，人能爲財死。","（「能」，項楚校作「窮」。","）錢是害人物，智者常遠離。","（張錫厚錄此詩，下有「□□□□□，心恒更愿取」。","項楚謂此首當析爲三首。","）。"]', '["一歲已百年，（「已」，伯三七二四卷作「與」。","）中间不怕死。","长命得八十，漸漸無意智。","悉能造罪根，不解生慚愧。","廣貪长命財，身當短命死。","兴生向前走，惟求多出利。","析心即心枉，（「析心」，伯三七二四卷作「折本」。","）惶惶煩惱起。","錢逸即独富，（「逸」，伯三七二四卷作「𨓚」，張錫厚定作「兌」，蔣紹愚校作「遶」，逮「饒」。","）吾貧长省事。","奴富欺郎君，婢富远娘子。","（「富远」，伯三七二四卷作「有陵〖淩〗」。","）鸟饑緣食亡，人能爲財死。","（「能」，項楚校作「窮」。","）錢是害人物，智者常远離。","（張錫厚錄此诗，下有「□□□□□，心恒更愿取」。","項楚謂此首當析爲三首。","）。"]', '诗', 'shi', '', NULL, '五言詩 四 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a17c41-ed09-4ead-a5b8-441b7298d504', '五言詩 五', '五言诗 五', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["富饒田舍兒，論請實好事。","度種如生田，（「度」，伯三七二四卷作「廣」。","）宅舍青煙起。","槽上飼肥馬，仍更賣奴婢。","（「賣」，伯三七二四卷作「買」。","）牛羊共成羣，滿圈養生子。","（「養牛子」，伯三七二四卷作「豢肥子」。","項楚謂「牛」當作「㹠」。","）窖內多埋穀，尋常願米貴。","里政追役來，（「里政」，伯三七二四卷作「里正」。","下同。","）坐着南廳裏。","廣設好飲食，多須遣醉。","（「多須」，伯三七二四卷作「多酒」。","）追車即與車，須馬即與馬。","（「須馬」，伯三七二四卷作「追馬」。","「與馬」，伯三七二四卷作「與使」。","）須錢便與錢，和市亦不避。","索麵驢駝送，續後更有雉。","官人應須物，當家皆具備。","縣官與恩宅，（「恩宅」，伯三七二四卷作「恩澤」。","）曹司一家事。","縱有重差科，有錢不怕你。","貧窮田舍漢，（自「貧窮田舍漢」以下，張錫厚作另一首。","）菴子𪳜孤栖。","兩共前生種，（「兩共」，伯三七二是卷作「兩窮」。","）今世作夫妻。","婦即客舂擣，夫即客扶犂。","黃昏到家裏，無米復無柴。","男女空餓肚，狀似一食齋。","里政追庸調，村頭[共]相催。","（「共」，據三七二四卷補。","）𮂓頭巾子路，（「路」，伯三七二四卷作「露」。","）衫破肚皮開。","體上無褌袴，足下復無鞋。","醜婦來惡罵，啾唧搦頭灰。","里政被脚蹴，村頭被拳搓，駈將見朋友。","（「朋友」，伯三七二四卷作「枚」。","）打脊趁迴來。","租調無處出，還須里政倍。","（「倍」，伯三七二四卷作「陪」。","）門前見債主，入戶見貧妻。","舍漏兒啼哭，重重逢苦哉。","（「苦哉」，伯三七二四卷「苦災」。","）如此更窮漢，村村一兩𪱿。","（「𪱿」，伯三七二四卷作「枚」。","）。"]', '["富饒田舍兒，論請實好事。","度種如生田，（「度」，伯三七二四卷作「廣」。","）宅舍青煙起。","槽上飼肥马，仍更賣奴婢。","（「賣」，伯三七二四卷作「買」。","）牛羊共成羣，满圈養生子。","（「養牛子」，伯三七二四卷作「豢肥子」。","項楚謂「牛」當作「㹠」。","）窖內多埋穀，尋常願米貴。","里政追役来，（「里政」，伯三七二四卷作「里正」。","下同。","）坐着南廳裏。","廣設好饮食，多須遣醉。","（「多須」，伯三七二四卷作「多酒」。","）追车即與车，須马即與马。","（「須马」，伯三七二四卷作「追马」。","「與马」，伯三七二四卷作「與使」。","）須錢便與錢，和市亦不避。","索麵驢駝送，續後更有雉。","官人應須物，當家皆具備。","縣官與恩宅，（「恩宅」，伯三七二四卷作「恩澤」。","）曹司一家事。","縱有重差科，有錢不怕你。","貧窮田舍漢，（自「貧窮田舍漢」以下，張錫厚作另一首。","）菴子𪳜孤栖。","兩共前生種，（「兩共」，伯三七二是卷作「兩窮」。","）今世作夫妻。","婦即客舂擣，夫即客扶犂。","黄昏到家裏，無米复無柴。","男女空餓肚，狀似一食斋。","里政追庸調，村头[共]相催。","（「共」，據三七二四卷補。","）𮂓头巾子路，（「路」，伯三七二四卷作「露」。","）衫破肚皮开。","體上無褌袴，足下复無鞋。","醜婦来惡罵，啾唧搦头灰。","里政被脚蹴，村头被拳搓，駈將见朋友。","（「朋友」，伯三七二四卷作「枚」。","）打脊趁迴来。","租調無处出，還須里政倍。","（「倍」，伯三七二四卷作「陪」。","）门前见債主，入戶见貧妻。","舍漏兒啼哭，重重逢苦哉。","（「苦哉」，伯三七二四卷「苦災」。","）如此更窮漢，村村一兩𪱿。","（「𪱿」，伯三七二四卷作「枚」。","）。"]', '诗', 'shi', '', NULL, '五言詩 五 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094302bd-b660-479d-a8a9-e882f49f2293', '五言詩 六', '五言诗 六', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["當官自慵懶，不勤判文案。","尋常打酒醉，（「打酒」，伯三七二四卷作「村酒」。","）每日出逐伴。","衙日唱稽逋，佐史寸脊爛。","更兼受取錢，（「受」，伯三七二四卷作「愛」。","）差科放却半。","狂棒百姓死，（「狂」，伯三七二四卷作「枉」。","）荒忙怕麥散。","賦歛既不均，（「歛」，伯三七二四卷候「役」。","）曹司即潦亂。","啾唧被人言，御史秉正斷。","除名仍解官，告身奪入案。","宅舍不許坐，（「宅舍」，伯三七二四卷作「官宅」。","）錢財即分散。","路人見心酸，傍看罪過漢。","一則恥妻兒，二則羞同伴。","無面還本鄉，諸州且游觀。"]', '["當官自慵懶，不勤判文案。","尋常打酒醉，（「打酒」，伯三七二四卷作「村酒」。","）每日出逐伴。","衙日唱稽逋，佐史寸脊爛。","更兼受取錢，（「受」，伯三七二四卷作「愛」。","）差科放却半。","狂棒百姓死，（「狂」，伯三七二四卷作「枉」。","）荒忙怕麦散。","賦歛既不均，（「歛」，伯三七二四卷候「役」。","）曹司即潦亂。","啾唧被人言，御史秉正斷。","除名仍解官，告身奪入案。","宅舍不許坐，（「宅舍」，伯三七二四卷作「官宅」。","）錢財即分散。","路人见心酸，傍看罪過漢。","一則恥妻兒，二則羞同伴。","無面還本乡，諸州且游观。"]', '诗', 'shi', '', NULL, '五言詩 六 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924df6a3-94c0-4476-8328-6763602d8b24', '五言詩 七', '五言诗 七', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["天下浮游人，（「浮游」，斯六○三二卷作「浮逃」。","）商多買一半。","（「商多買一半」，斯六○三二卷作「不啻多一半」。","）南北擲縱橫，誰他蹔歸貫。","（「誰」，斯六○三二卷作「誑」；「縱橫」作「蹤藏」。","）游游自覓活，不愁雁戶役。","無心念二親，有意隨惡伴。","强處出頭來，不須曹主喚。","（「曹主」，斯六○三二卷作「主人」。","）聞苦即深藏，尋常擬於算。","（「於」項楚校作「相」。","）欲似鳥作羣，驚即當頭散。","（「當頭」，斯六○三二卷作「分頭」。","）心毒無忠孝，不過浮游漢。","（「浮遊」，斯六○三二卷作「浮浪」。","）此是五逆賊，打殺何須案。"]', '["天下浮游人，（「浮游」，斯六○三二卷作「浮逃」。","）商多買一半。","（「商多買一半」，斯六○三二卷作「不啻多一半」。","）南北擲縱橫，誰他蹔归貫。","（「誰」，斯六○三二卷作「誑」；「縱橫」作「蹤藏」。","）游游自覓活，不愁雁戶役。","無心念二親，有意隨惡伴。","强处出头来，不須曹主喚。","（「曹主」，斯六○三二卷作「主人」。","）闻苦即深藏，尋常擬於算。","（「於」項楚校作「相」。","）欲似鸟作羣，驚即當头散。","（「當头」，斯六○三二卷作「分头」。","）心毒無忠孝，不過浮游漢。","（「浮游」，斯六○三二卷作「浮浪」。","）此是五逆賊，打殺何須案。"]', '诗', 'shi', '', NULL, '五言詩 七 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca88e42d-f523-4612-a39c-85c241466bf8', '五言詩 八', '五言诗 八', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["男女有亦好，無時亦最精。","兒在愁他役，又恐點着征。","一則無租調，二則絕兵名。","閉門無呼喚，耳裏挃星星。","（「挃」，項楚校作「極」。","）。"]', '["男女有亦好，無时亦最精。","兒在愁他役，又恐点着征。","一則無租調，二則絕兵名。","閉门無呼喚，耳裏挃星星。","（「挃」，項楚校作「極」。","）。"]', '诗', 'shi', '', NULL, '五言詩 八 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6622f2b-6f61-47d1-a91d-edda51076fe3', '五言詩 九', '五言诗 九', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["生兒擬替公，兒大須公死。","天配作次第，合去不由你。","父子總長命，地下無人使。","閻老忽嗔遲，即棒伺命使。","火急須領兵，走來且取你。","不及別妻兒，向前任料理。"]', '["生兒擬替公，兒大須公死。","天配作次第，合去不由你。","父子總长命，地下無人使。","閻老忽嗔遲，即棒伺命使。","火急須領兵，走来且取你。","不及別妻兒，向前任料理。"]', '诗', 'shi', '', NULL, '五言詩 九 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1686b0c6-a9bd-4d36-872f-19710b92c1f2', '五言詩 十', '五言诗 十', '20973248-daf1-40cd-b0be-d9fc489e5f5d', '唐', '["蹔得一代人，風光亦須覓。","（張錫厚以止二句屬另一首。","）金玉不成寶，{戒廾=天}身實可惜。","（「{戒廾=天}」，項楚校作「宍」，即「肉」字。","）白髮隨年生，美貌別今夕。","貧富光常空，（「光」，郭在貽校作「无」，即「無」。","）恣意多着喫。","活時恠不用，塞墓慎何益？","（「慎」，戴密微校作「真」。","）（以上《燉煌掇瑣》三○引伯希和卷三四一八。","詩中別體不明之處，暫未校正（王梵志詩及此無名氏詩所錄今人校訂意見，皆錄自郭在貽《王梵志詩彙校》。","））。"]', '["蹔得一代人，风光亦須覓。","（張錫厚以止二句屬另一首。","）金玉不成寶，{戒廾=天}身實可惜。","（「{戒廾=天}」，項楚校作「宍」，即「肉」字。","）白髮隨年生，美貌別今夕。","貧富光常空，（「光」，郭在貽校作「无」，即「無」。","）恣意多着喫。","活时恠不用，塞墓慎何益？","（「慎」，戴密微校作「真」。","）（以上《燉煌掇瑣》三○引伯希和卷三四一八。","诗中別體不明之处，暫未校正（王梵志诗及此無名氏诗所錄今人校訂意见，皆錄自郭在貽《王梵志诗彙校》。","））。"]', '诗', 'shi', '', NULL, '五言詩 十 缺名 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4cd5ea-8dcf-404c-ae5e-da64c78cd7eb', '雜詩', '杂诗', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["無嗔即是戒，心淨即出家。","我性與汝合，一切法無差。","（《萬首唐人絕句補》十）（《宗鏡鏡》卷二四、《五燈會元》卷二收此詩爲拾得作。","）。"]', '["無嗔即是戒，心淨即出家。","我性與汝合，一切法無差。","（《万首唐人絕句補》十）（《宗镜镜》卷二四、《五灯會元》卷二收此诗爲拾得作。","）。"]', '诗', 'shi', '', NULL, '雜詩 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1ce326-e89b-4130-bf65-341e4c811f2f', '', '', '623aa19d-0de7-4fc1-af1e-c637fe88713b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 弘忍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9e16488-2962-4292-9191-8a48fc414236', '五祖自詠（時復生再來）（此詩爲後人僞托。）', '五祖自詠（时复生再来）（此诗爲後人僞托。）', '623aa19d-0de7-4fc1-af1e-c637fe88713b', '唐', '["垂垂白髮下青山，七歲歸來改舊顏。","人却少年松却老，是非從此落人間。","（《弘治黃州府志》五《人物·仙釋》、同上七《藝文·黃梅縣》）。"]', '["垂垂白髮下青山，七歲归来改旧顏。","人却少年松却老，是非從此落人间。","（《弘治黄州府志》五《人物·仙釋》、同上七《藝文·黄梅縣》）。"]', '诗', 'shi', '', NULL, '五祖自詠（時復生再來）（此詩爲後人僞托。） 弘忍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94cf2ada-5891-454a-b53d-e7323994e82b', '偈', '偈', '11ec8c2e-ff40-4dd3-b085-f03a77726bf7', '唐', '["（五祖弘忍一日會衆傳法弟子，神秀呈偈出於壁間。","）身是菩提樹，心如明鏡臺。","時時勤拂拭，勿使惹塵埃。","（《嘉慶廣東通志》三二八《釋老傳》引《指月錄》）（此偈最早見於《六祖法寶壇經》。","末句，敦煌本作「莫使有塵埃」。","）。"]', '["（五祖弘忍一日會衆傳法弟子，神秀呈偈出於壁间。","）身是菩提樹，心如明镜台。","时时勤拂拭，勿使惹塵埃。","（《嘉慶廣东通志》三二八《釋老傳》引《指月錄》）（此偈最早见於《六祖法寶壇經》。","末句，敦煌本作「莫使有塵埃」。","）。"]', '诗', 'shi', '', NULL, '偈 神秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8bdfbba-0c68-4428-ba52-81429f4ae206', '', '', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17f8142f-54c8-463a-8d6e-fd174cfe830a', '偈', '偈', '871d0178-fdc2-498c-ab67-64c9ad0d52b8', '唐', '["（慧能不識字，聞人誦神秀偈，乃偈請人書其側曰：）菩提本無樹，明鏡亦非臺。","本來無一物，何處惹塵埃？","（同上。","）（此偈最早見於法海本《六祖法寶壇經》。","敦煌本引作二首，文字差異較大，另詳《全唐詩續拾》卷九。","）（今按：禪宗六祖南北二家之偈，實爲明白如話的哲理詩，最有代表性，故特補錄。","）。"]', '["（慧能不識字，闻人誦神秀偈，乃偈請人书其側曰：）菩提本無樹，明镜亦非台。","本来無一物，何处惹塵埃？","（同上。","）（此偈最早见於法海本《六祖法寶壇經》。","敦煌本引作二首，文字差異較大，另詳《全唐诗續拾》卷九。","）（今按：禪宗六祖南北二家之偈，實爲明白如話的哲理诗，最有代表性，故特補錄。","）。"]', '诗', 'shi', '', NULL, '偈 慧能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee31704-50d5-4739-8ec9-1e6c866092b0', '自臯亭至吳門弔二大護法', '自臯亭至吳门弔二大護法', '20fcd008-fe45-47fa-8b42-1acd6122e6c1', '唐', '["病耳蚊過似走雷，杖行猶怯步難回。","一舠白水牽愁斷，兩束黃香拭淚開。","了悟世緣容直往，徘徊夢影或雙來。","遠公自看蓮花漏，無復宗雷過講臺。","（《古今圖書集成·神異典》二一一《居士部》）。"]', '["病耳蚊過似走雷，杖行猶怯步难回。","一舠白水牽愁斷，兩束黄香拭泪开。","了悟世緣容直往，徘徊梦影或雙来。","远公自看蓮花漏，無复宗雷過講台。","（《古今圖书集成·神異典》二一一《居士部》）。"]', '诗', 'shi', '', NULL, '自臯亭至吳門弔二大護法 慧淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c6cb39-0d50-4d60-a417-525e1aa218bf', '丹霄驛詩刻', '丹霄驛诗刻', '8ecd1809-2c73-416c-808a-db5ad6618860', '唐', '["驛前南面架危橋，久欲登臨畏路遙。","今日偶然尋得到。","直從平地上丹霄。","（《輿地紀勝》一○七《昭州》）。"]', '["驛前南面架危橋，久欲登臨畏路遙。","今日偶然尋得到。","直從平地上丹霄。","（《輿地紀勝》一○七《昭州》）。"]', '诗', 'shi', '', NULL, '丹霄驛詩刻 李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63a8657-0564-4f07-a7a8-59013ef1d56c', '幸蜀回居南內夢中見妃子於蓬山太真院作詩遺之使焚於馬嵬山下', '幸蜀回居南內梦中见妃子於蓬山太真院作诗遺之使焚於马嵬山下', '8ecd1809-2c73-416c-808a-db5ad6618860', '唐', '["風急雲驚雨不成，覺來仙夢甚分明。","當時苦根銀屏影，遮隔仙姬秪聽聲。"]', '["风急云驚雨不成，覺来仙梦甚分明。","當时苦根銀屏影，遮隔仙姬秪听声。"]', '诗', 'shi', '', NULL, '幸蜀回居南內夢中見妃子於蓬山太真院作詩遺之使焚於馬嵬山下 李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0a0cfc-5f7e-46ab-bd89-37cbeb2438aa', '又作妃子所遺羅襪銘', '又作妃子所遺羅襪銘', '8ecd1809-2c73-416c-808a-db5ad6618860', '唐', '["羅襪羅襪，香塵生不絕。","細細圓圓，地下得瓊鈎；窄窄弓弓，手中弄新月。","又如脫履露纖圓，恰似同衾見時節。","方知清夢事非虛，暗引相思幾時歇？","（以上《詩話總龜》三三《紀夢門》）（此二首疑出後人依託。","）。"]', '["羅襪羅襪，香塵生不絕。","細細圓圓，地下得瓊鈎；窄窄弓弓，手中弄新月。","又如脫履露纖圓，恰似同衾见时節。","方知清梦事非虛，暗引相思幾时歇？","（以上《诗話總龟》三三《紀梦门》）（此二首疑出後人依託。","）。"]', '诗', 'shi', '', NULL, '又作妃子所遺羅襪銘 李隆基 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a875aa41-dc74-494a-a505-b7e18a330cd1', '馬跑神泉', '马跑神泉', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["將軍稱賀魯，遺廟俯靈淵。","漦噴蛟龍穴，波跳赤鯉泉。","路迴芹澗水，村近石林烟。","野馬含暄氣，農夫出故廛。","土膏興耒耜，尸祝傍山嶺。","閱世無銘石，茲遊匪慕天。","頃來規下宇，必葺慕先賢。","悅使成能事，掄材出俸錢。","伉香推幹蠱，班匠擇精專。","黝堊何其麗，欒櫨本自然。","松青離石道，雲白介山田。","適嘆飛翬速，仍憂黃雀穿。","梨花寒食後，桂藉酒樽前。","饑麝尋香柏，流鶯助晚絃。","吳歈催玉斝，趙舞落金鈿。","上巳無過酒，春衣欲試湔。","故園思鞏洛，褉飲客汾川。","寄語西河老，鄉心朝暮懸。","（《古今圖書集成·職方典》三四一《汾州府部》）。"]', '["將軍稱賀魯，遺廟俯靈淵。","漦噴蛟龙穴，波跳赤鯉泉。","路迴芹澗水，村近石林烟。","野马含暄氣，農夫出故廛。","土膏兴耒耜，尸祝傍山嶺。","閱世無銘石，茲游匪慕天。","頃来規下宇，必葺慕先賢。","悅使成能事，掄材出俸錢。","伉香推幹蠱，班匠擇精專。","黝堊何其丽，欒櫨本自然。","松青離石道，云白介山田。","適嘆飞翬速，仍憂黄雀穿。","梨花寒食後，桂藉酒樽前。","饑麝尋香柏，流鶯助晚絃。","吳歈催玉斝，趙舞落金鈿。","上巳無過酒，春衣欲試湔。","故园思鞏洛，褉饮客汾川。","寄語西河老，乡心朝暮懸。","（《古今圖书集成·職方典》三四一《汾州府部》）。"]', '诗', 'shi', '', NULL, '馬跑神泉 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5140ff9-e856-4bfe-a04f-716d356b7505', '送李邕之秦', '送李邕之秦', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["空（《文鏡秘府論》地《十七勢》，《全唐詩》作《送李十五》。","《文鏡秘府》首句「怨別」作「別怨」，三句「杳」作「夢」，四句「影」作「映」。","）。"]', '["空（《文镜秘府論》地《十七勢》，《全唐诗》作《送李十五》。","《文镜秘府》首句「怨別」作「別怨」，三句「杳」作「梦」，四句「影」作「映」。","）。"]', '诗', 'shi', '', NULL, '送李邕之秦 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('036054ed-07a4-4739-9b3a-7fa4d4f521d7', '', '', 'de586bc4-e7e4-48b4-a28c-4f72e023b32f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 元德秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5efda1d-10b5-4296-bc26-f206ad8fba1a', '歸隱', '归隐', 'de586bc4-e7e4-48b4-a28c-4f72e023b32f', '唐', '["緩步巾車出魯山，陸渾佳處處恣安閑。","家無僕妾饑忘爨，自有琴書興不闌。","（《古今圖書集成·職方典》四八八《汝州部》）。"]', '["緩步巾车出魯山，陸渾佳处处恣安闲。","家無僕妾饑忘爨，自有琴书兴不闌。","（《古今圖书集成·職方典》四八八《汝州部》）。"]', '诗', 'shi', '', NULL, '歸隱 元德秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf63efef-217d-47d0-b2c6-35b5b2072686', '春燕', '春燕', '025022cd-ba33-4ebc-9ecf-26f53a73cf34', '唐', '["空（《文苑英華》三二九《禽獸》詩《全唐詩》七六九失題，又列爲無世次爵里可考）。"]', '["空（《文苑英华》三二九《禽獸》诗《全唐诗》七六九失題，又列爲無世次爵里可考）。"]', '诗', 'shi', '', NULL, '春燕 徐璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4039d820-f678-4992-8f8e-a578e75fc2d3', '催粧', '催粧', '025022cd-ba33-4ebc-9ecf-26f53a73cf34', '唐', '["空（《搜玉小集》《唐人選唐詩》，皆初唐人〖《全唐詩》七六九作徐安期。","〗〖《唐詩紀事》卷十三署徐安期，《萬首唐人絕句》卷五五亦署徐璧。","《全唐詩補逸》卷十七據《永樂大典》卷六五二三錄《催妝》詩，作徐壁，今刪彼存此。","〗）。"]', '["空（《搜玉小集》《唐人選唐诗》，皆初唐人〖《全唐诗》七六九作徐安期。","〗〖《唐诗紀事》卷十三署徐安期，《万首唐人絕句》卷五五亦署徐璧。","《全唐诗補逸》卷十七據《永乐大典》卷六五二三錄《催妝》诗，作徐壁，今刪彼存此。","〗）。"]', '诗', 'shi', '', NULL, '催粧 徐璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('219312a2-87f8-4deb-8b40-e5c698109198', '題季子廟', '題季子廟', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["空（《全唐詩》七七八作李季華詩，第二句「聽」《圖書集成》作「繼」，第四句「冷」作「滿」。","）（出處當爲《輿地紀勝》卷七《鎮江府》。","《全唐詩》作李季華，係出《萬首唐人絕句》卷一百，疑涉詩題而致誤。","）。"]', '["空（《全唐诗》七七八作李季华诗，第二句「听」《圖书集成》作「繼」，第四句「冷」作「满」。","）（出处當爲《輿地紀勝》卷七《鎮江府》。","《全唐诗》作李季华，係出《万首唐人絕句》卷一百，疑涉诗題而致誤。","）。"]', '诗', 'shi', '', NULL, '題季子廟 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bda159cb-4ed9-4809-9536-6cf2de08092a', '題澤州石佛閣', '題澤州石佛閣', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["覽勝詩千首，登高酒一壺。","此情誰管領，分付石浮圖。","（《古今圖書集成·職方典》三六四《澤州部》）。"]', '["覽勝诗千首，登高酒一壺。","此情誰管領，分付石浮圖。","（《古今圖书集成·職方典》三六四《澤州部》）。"]', '诗', 'shi', '', NULL, '題澤州石佛閣 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef01583-7bf0-4b8d-8990-f102ab94876e', '贈任華', '贈任华', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["丈夫結交須結貧，貧者結交交始親。","世人不解結交者，唯重黃金不重人。","黃金雖多有盡時，結交一成無竭期。","君不見管仲與鮑叔，至今留名名不移。","（《唐詩紀事》二二《任華》）。"]', '["丈夫結交須結貧，貧者結交交始親。","世人不解結交者，唯重黄金不重人。","黄金雖多有尽时，結交一成無竭期。","君不见管仲與鲍叔，至今留名名不移。","（《唐诗紀事》二二《任华》）。"]', '诗', 'shi', '', NULL, '贈任華 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473d242b-d094-4a77-b940-0b7fcd332c11', '題雷威琴', '題雷威琴', '112c4420-04c5-498a-ba29-cb5654ad7e32', '唐', '["石山孫枝，樣剪伏羲。","將扶大隱，永契神機。","（《西溪叢語》上）。"]', '["石山孫枝，樣剪伏羲。","將扶大隐，永契神機。","（《西溪叢語》上）。"]', '诗', 'shi', '', NULL, '題雷威琴 徐浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47e661e-4f5a-403c-9e9b-3c4e3e11eed1', '送東林廉上人還廬（山）', '送东林廉上人還廬（山）', '112c4420-04c5-498a-ba29-cb5654ad7e32', '唐', '["空（《古今圖書集成·神異典·僧部》。","又《山川典·廬山部》作句融詩）殷璠《河嶽共同願望盡快集》卷上收此爲（劉眘虛詩。","）（《全唐詩》一四○作王昌齡詩，第二句「人」《圖書集成》作「入」，第五句「昔」作「常」，末三字「望清輝」作「無清機」。","）。"]', '["空（《古今圖书集成·神異典·僧部》。","又《山川典·廬山部》作句融诗）殷璠《河嶽共同願望尽快集》卷上收此爲（劉眘虛诗。","）（《全唐诗》一四○作王昌齡诗，第二句「人」《圖书集成》作「入」，第五句「昔」作「常」，末三字「望清輝」作「無清機」。","）。"]', '诗', 'shi', '', NULL, '送東林廉上人還廬（山） 徐浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a502a51-a28d-4566-8ea3-47fbb969fd5a', '感春（句）', '感春（句）', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["梧桐三寸葉，楊柳一尋枝。","（《歲華紀麗》一《春》）。"]', '["梧桐三寸葉，楊柳一尋枝。","（《歲华紀丽》一《春》）。"]', '诗', 'shi', '', NULL, '感春（句） 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b598667e-5676-4369-a4fb-dcfd5441c5fe', '句（書《奉使帖》後）', '句（书《奉使帖》後）', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["人心無路見，時事只天知。","（黃本驥編訂《顏魯公文集》十二）。"]', '["人心無路见，时事只天知。","（黄本驥編訂《顏魯公文集》十二）。"]', '诗', 'shi', '', NULL, '句（書《奉使帖》後） 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a067d553-fa9f-4468-bc16-21939d9c0c85', '龍虎山', '龙虎山', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["道土身披魚鬣衣，白日忽上青天飛。","龍虎山頭好明月，玉殿珠樓空翠微。","（《古今圖書集成·山川典》一四七《龍虎山部》。","又《職方典》八六六《廣信府部》）。"]', '["道土身披鱼鬣衣，白日忽上青天飞。","龙虎山头好明月，玉殿珠楼空翠微。","（《古今圖书集成·山川典》一四七《龙虎山部》。","又《職方典》八六六《廣信府部》）。"]', '诗', 'shi', '', NULL, '龍虎山 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39569c37-60e8-4c3c-b85a-240145c47934', '竹枝詞', '竹枝词', '246a6bf8-2556-4935-a46c-8046c1378a57', '唐', '["（二首○《蜀中名勝記》二三《夔州府·萬縣》引《碑目》云：「大雲寺碑有唐僧圓澤傳。","」又《忠義傳》載李源道人再生事詩云云。","）。"]', '["（二首○《蜀中名勝記》二三《夔州府·万縣》引《碑目》云：「大云寺碑有唐僧圓澤傳。","」又《忠義傳》載李源道人再生事诗云云。","）。"]', '诗', 'shi', '', NULL, '竹枝詞 圓觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9ae8023-64e1-460e-b6ec-0cbeee895ffb', '竹枝詞 一', '竹枝词 一', '246a6bf8-2556-4935-a46c-8046c1378a57', '唐', '["三生石上舊精魂，賞月吟風不要論。","慚愧情人遠相訪，此身雖異性長存。"]', '["三生石上旧精魂，賞月吟风不要論。","慚愧情人远相訪，此身雖異性长存。"]', '诗', 'shi', '', NULL, '竹枝詞 一 圓觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('340c17d9-fc8f-41e4-8e75-46526cace0ff', '竹枝詞 二', '竹枝词 二', '246a6bf8-2556-4935-a46c-8046c1378a57', '唐', '["身前身後事茫茫，欲話因緣恐斷腸。","吳越溪山尋已遍，卻迴煙棹上瞿塘。","（《歲時廣紀》三三《中秋》引《甘澤謠》）（見《太平廣記》卷三八七引《甘澤謠》。","《宋高僧傳》卷二十有《唐洛京慧林寺圓觀傳》）。"]', '["身前身後事茫茫，欲話因緣恐斷腸。","吳越溪山尋已遍，卻迴煙棹上瞿塘。","（《歲时廣紀》三三《中秋》引《甘澤謠》）（见《太平廣記》卷三八七引《甘澤謠》。","《宋高僧傳》卷二十有《唐洛京慧林寺圓观傳》）。"]', '诗', 'shi', '', NULL, '竹枝詞 二 圓觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec5358e-b4f0-47ee-957b-374b127fe096', '爲哥舒翰歌', '爲哥舒翰歌', '2fd1adae-e222-4919-b6c1-e3fd5c9adcfd', '唐', '["（天寶中，哥舒翰爲安西節度使，控地數千里，甚著威令。","故西鄙人歌曰：）北斗七星高，哥舒夜帶刀。","吐蕃總殺盡，更築[麗]（西）重壕。","（《全唐詩》後二句作「至今窺牧馬，不敢過臨洮」。","《南部新書》庚）（據《太平廣記》卷四九五引《乾𦠆子》及《知不足齋叢書》本《南部新書》校改。","「哥舒」，《太平廣記》作「歌舒翰」，衍一字。","）。"]', '["（天寶中，哥舒翰爲安西節度使，控地數千里，甚著威令。","故西鄙人歌曰：）北斗七星高，哥舒夜带刀。","吐蕃總殺尽，更築[丽]（西）重壕。","（《全唐诗》後二句作「至今窺牧马，不敢過臨洮」。","《南部新书》庚）（據《太平廣記》卷四九五引《乾𦠆子》及《知不足斋叢书》本《南部新书》校改。","「哥舒」，《太平廣記》作「歌舒翰」，衍一字。","）。"]', '诗', 'shi', '', NULL, '爲哥舒翰歌 西鄙人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c409f7-1df7-4a32-8bd8-cc185c9ab1f8', '寒女吟', '寒女吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔君布衣時，與妾同辛苦。","一拜五官郎，便索邯鄲女。","妾欲辭君去，君心便相許。","妾讀蘼蕪書，悲歌淚如雨。","憶昔嫁君時，曾無一夜樂。","不是妾無堪，君家婦難作。","起來強歌舞，縱好君嫌惡。","下堂辭君去，去後悔遮莫。","（《才調集》六）。"]', '["昔君布衣时，與妾同辛苦。","一拜五官郎，便索邯鄲女。","妾欲辞君去，君心便相許。","妾读蘼蕪书，悲歌泪如雨。","憶昔嫁君时，曾無一夜乐。","不是妾無堪，君家婦难作。","起来強歌舞，縱好君嫌惡。","下堂辞君去，去後悔遮莫。","（《才調集》六）。"]', '诗', 'shi', '', NULL, '寒女吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3579b2dd-56be-4596-99be-d8e6e4c5f803', '日出東南隅行', '日出东南隅行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["（《文苑英華》一九三載李白此詩，注云：「集無此詩。","」郭茂倩《樂府詩集》以爲殷謀詩。","）秦樓出佳麗，正值朝日光。","陌頭能駐馬，花處復添香。","（《樂府詩集》卷二八署陳殷謀，《先秦漢魏晉南北朝詩·陳詩》卷九據以收入。","）。"]', '["（《文苑英华》一九三載李白此诗，注云：「集無此诗。","」郭茂倩《乐府诗集》以爲殷謀诗。","）秦楼出佳丽，正值朝日光。","陌头能駐马，花处复添香。","（《乐府诗集》卷二八署陳殷謀，《先秦漢魏晉南北朝诗·陳诗》卷九據以收入。","）。"]', '诗', 'shi', '', NULL, '日出東南隅行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68068990-33c1-4298-955e-0328ae78b131', '代佳人寄翁參樞先輩', '代佳人寄翁參樞先輩', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["（《文苑英華》二六二注云：「此詩總目及《李集》皆不載，惟《英華》諸本有之。","」）等閑經夏復經寒，夢裏驚嗟豈暫安。","南家風光當世少，西陵江浪過江難。","周旋小字桃燈讀，重疊遙山隔霧看。","真是爲君飡不得，書來莫說更加飡。","（《文苑英華》）（嚴羽《滄浪詩話·考證》謂本詩「乃晚唐之下者」。","詹鍈《李詩辨僞》云：「按《文苑英華》編次體例，各類之中，一以時代先後爲序。","此詩置於張祜、李洞、方干與李羣玉、陳陶之間，與太白時代相去懸遠，定是晚唐之作。","」吳企明云：「先輩爲應試舉子對已及第者的稱呼，或是進士出身的人互相推敬的稱呼，李白從未應試，不應用此稱呼，集中亦無此稱。","」又推測翁參樞或爲《登科記考》卷二二所載咸通元年盈第的翁彥樞，「參」、「彥」形近易訛，時代亦與李洞、方干相近。","）。"]', '["（《文苑英华》二六二注云：「此诗總目及《李集》皆不載，惟《英华》諸本有之。","」）等闲經夏复經寒，梦裏驚嗟豈暫安。","南家风光當世少，西陵江浪過江难。","周旋小字桃灯读，重叠遙山隔霧看。","真是爲君飡不得，书来莫说更加飡。","（《文苑英华》）（嚴羽《滄浪诗話·考證》謂本诗「乃晚唐之下者」。","詹鍈《李诗辨僞》云：「按《文苑英华》編次體例，各類之中，一以时代先後爲序。","此诗置於張祜、李洞、方干與李羣玉、陳陶之间，與太白时代相去懸远，定是晚唐之作。","」吳企明云：「先輩爲應試舉子对已及第者的稱呼，或是進士出身的人互相推敬的稱呼，李白從未應試，不應用此稱呼，集中亦無此稱。","」又推測翁參樞或爲《登科記考》卷二二所載咸通元年盈第的翁彥樞，「參」、「彥」形近易訛，时代亦與李洞、方干相近。","）。"]', '诗', 'shi', '', NULL, '代佳人寄翁參樞先輩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540f82fd-3684-4b8d-aabc-36cbe88aee2a', '陽春曲', '陽春曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["芣苡生前徑，含桃落小園。","春心自搖蕩，百舌更多言。"]', '["芣苡生前徑，含桃落小园。","春心自搖蕩，百舌更多言。"]', '诗', 'shi', '', NULL, '陽春曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e0f5a23-8b71-4dcc-977b-5f1940842520', '摩多樓子', '摩多楼子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["從戎向邊北，遠行辭密親。","借問陰山侯，還知塞上人。","（以上《萬首唐人絕句》。","又《樂府詩集》作無名氏）（按影宋本《樂府詩集》卷五一收《陽春曲》，卷七八收《摩多樓子》，皆不署作者名，但緊接李白詩後，於例並非李白詩。","汲古閣刊本目錄於《陽春曲》下署「無名氏」，可證。","今人校點本於《摩多樓子》下據王琦《李太白集》補「李白」二字，尤誤，王琦已云《樂府詩集》作無名氏。","）。"]', '["從戎向邊北，远行辞密親。","借问陰山侯，還知塞上人。","（以上《万首唐人絕句》。","又《乐府诗集》作無名氏）（按影宋本《乐府诗集》卷五一收《陽春曲》，卷七八收《摩多楼子》，皆不署作者名，但緊接李白诗後，於例並非李白诗。","汲古閣刊本目錄於《陽春曲》下署「無名氏」，可證。","今人校点本於《摩多楼子》下據王琦《李太白集》補「李白」二字，尤誤，王琦已云《乐府诗集》作無名氏。","）。"]', '诗', 'shi', '', NULL, '摩多樓子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('313d6622-0384-4f62-80bc-b17d2db0e179', '釣灘（一作「臺」）', '釣灘（一作「台」）', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["磨盡石嶺墨，潯陽釣赤魚。","靄峯尖似筆，堪畫不堪書。","（《輿地紀勝》二十《徽州》有此詩，注稱在黟縣南十八里，相傳太白遊新安，嘗釣於此，作詩云云。","《九域志》、《錦繡萬花谷》、《一統志》皆引「靄峯尖似筆」之句，以爲太白詩。","康熙《徽州府志》二《山川》引此詩，「石嶺墨」作「石墨嶺」，「筆」作「削」。","〖王琦《李太白詩集注》卷三十疑此詩或爲南唐另翰林學士李白作。","〗）。"]', '["磨尽石嶺墨，潯陽釣赤鱼。","靄峯尖似笔，堪畫不堪书。","（《輿地紀勝》二十《徽州》有此诗，注稱在黟縣南十八里，相傳太白游新安，嘗釣於此，作诗云云。","《九域志》、《錦繡万花谷》、《一統志》皆引「靄峯尖似笔」之句，以爲太白诗。","康熙《徽州府志》二《山川》引此诗，「石嶺墨」作「石墨嶺」，「笔」作「削」。","〖王琦《李太白诗集注》卷三十疑此诗或爲南唐另翰林学士李白作。","〗）。"]', '诗', 'shi', '', NULL, '釣灘（一作「臺」） 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea81abe4-ff70-42be-a714-0412207f557e', '小桃源', '小桃源', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黟縣小桃源，烟霞百里間。","地多靈草木，人尚古衣冠。","市向晡前散，山經夜後寒。","（《輿地紀勝》二十《徯州》載此詩六句，注云見《龍城志》。","《錦繡節花谷》亦載此詩，以爲太白作。","王琦按：「此詩乃南唐許堅詩，其後小有二韻。","」今按：已從《輿地紀勝》補其一韻。","又按：《全唐詩》七五七及八六一兩見許堅，皆未收此詩。","〖本書卷十五又笖此詩於許堅名下，凡八句。","今仍兩存之。","〗）。"]', '["黟縣小桃源，烟霞百里间。","地多靈草木，人尚古衣冠。","市向晡前散，山經夜後寒。","（《輿地紀勝》二十《徯州》載此诗六句，注云见《龙城志》。","《錦繡節花谷》亦載此诗，以爲太白作。","王琦按：「此诗乃南唐許堅诗，其後小有二韻。","」今按：已從《輿地紀勝》補其一韻。","又按：《全唐诗》七五七及八六一兩见許堅，皆未收此诗。","〖本书卷十五又笖此诗於許堅名下，凡八句。","今仍兩存之。","〗）。"]', '诗', 'shi', '', NULL, '小桃源 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e80a600-5389-4222-8bcc-77b455920e70', '烏牙寺', '烏牙寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["夜宿烏牙寺，舉手捫星辰。","不取高聲語，恐驚天上人。","（《輿地紀勝》四七《蘄州》引王得臣《塵史》云：「蘄之黃梅有烏牙山，僧舍小詩，曰李太白也，李集中無之。","」又《侯鯖錄》、《西清詩話》、《苕溪漁隱叢話》、《竹坡詩話》等又作《題峯頂寺》。","〖詩見《塵史》卷中。","王琦《李太白詩集注》卷三十收錄有關此詩之資料甚衆，其中引《侯鯖錄》，或云此爲王元之〖即王禹偁〗少登樓詩，《竹坡詩話》則云爲楊大年〖楊億〗幼年時作，《西清詩話》則以爲非極億作。","王琦亦未能定之。","諸書引文差異甚大，不具錄。","〗）。"]', '["夜宿烏牙寺，舉手捫星辰。","不取高声語，恐驚天上人。","（《輿地紀勝》四七《蘄州》引王得臣《塵史》云：「蘄之黄梅有烏牙山，僧舍小诗，曰李太白也，李集中無之。","」又《侯鯖錄》、《西清诗話》、《苕溪漁隐叢話》、《竹坡诗話》等又作《題峯頂寺》。","〖诗见《塵史》卷中。","王琦《李太白诗集注》卷三十收錄有关此诗之資料甚衆，其中引《侯鯖錄》，或云此爲王元之〖即王禹偁〗少登楼诗，《竹坡诗話》則云爲楊大年〖楊億〗幼年时作，《西清诗話》則以爲非極億作。","王琦亦未能定之。","諸书引文差異甚大，不具錄。","〗）。"]', '诗', 'shi', '', NULL, '烏牙寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('913c1611-695d-40e9-90b1-a5d5cb6e23f1', '桃源（二首） 一', '桃源（二首） 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔日狂秦事可嗟，直驅雞犬入桃花。","至今不出煙溪（一作「巒」）口，萬古潺湲二（一作「一」）水斜。","。"]', '["昔日狂秦事可嗟，直驱雞犬入桃花。","至今不出煙溪（一作「巒」）口，万古潺湲二（一作「一」）水斜。","。"]', '诗', 'shi', '', NULL, '桃源（二首） 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5776c6e-6641-4733-9f4d-4015dc7745a6', '桃源（二首） 二', '桃源（二首） 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["露暗煙濃草色新，一翻流水滿溪春。","可憐漁歌父重來訪，只見桃花不見人。","（《輿地紀勝》六八《常德府》引《綿州志》云「李白逸篇」）。"]', '["露暗煙濃草色新，一翻流水满溪春。","可怜漁歌父重来訪，只见桃花不见人。","（《輿地紀勝》六八《常德府》引《綿州志》云「李白逸篇」）。"]', '诗', 'shi', '', NULL, '桃源（二首） 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2134590c-79c3-4a94-b4ce-0cbb26714ad6', '普照寺', '普照寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天台國清寺，天下爲四絕。","今到普照遊，到來復何別。","柟（一作「枿」）木白雲飛，高僧頂殘雪。","門外（一作「前」）一條溪（一作「水」），幾回流歲月。","（《咸淳臨安志》八四。","○蘇東坡曰：「予舊在富陽，見國清院太白詩，絕凡近，即此篇也。","」《漁隱叢話》：「新安水西寺，寺依山背，下瞰長溪。","太白題詩斷句云：『檻外一條溪。","幾回流碎月。","』今集中無之。","」王琦按：「《漁隱》所引，即此篇末二句也，蓋未睹全篇，故訛以爲《是否水西寺》斷句也。","」。）"]', '["天台国清寺，天下爲四絕。","今到普照游，到来复何別。","柟（一作「枿」）木白云飞，高僧頂殘雪。","门外（一作「前」）一條溪（一作「水」），幾回流歲月。","（《咸淳臨安志》八四。","○蘇东坡曰：「予旧在富陽，见国清院太白诗，絕凡近，即此篇也。","」《漁隐叢話》：「新安水西寺，寺依山背，下瞰长溪。","太白題诗斷句云：『檻外一條溪。","幾回流碎月。","』今集中無之。","」王琦按：「《漁隐》所引，即此篇末二句也，蓋未睹全篇，故訛以爲《是否水西寺》斷句也。","」。）"]', '诗', 'shi', '', NULL, '普照寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5bd656f-ec24-4806-ab9a-b3f4cf4dc14e', '興唐寺', '兴唐寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["（在歙縣郡城練水西，唐至德二年建。","宋太平舉國中勅改太平舉國寺。","）天台國清寺，天下稱四絕。","我來舉唐遊，於中更無別。","枿木劃斷雲，高峯頂積雪。","檻外一條溪，幾回流碎月。","（康熙《徽州府志》十八《寺觀》。","○今按：此詩與前篇，異地異題，輾轉漢傳，各有可取之處。","《苕溪漁隱》所引，應即此一篇之末二句。","王琦未見此篇，不得稱《漁隱》以爲《題水西寺》斷句爲訛。","〖宋朱弁《曲洧舊聞》卷八謂此詩石刻在歙溪西太平寺。","〗）。"]', '["（在歙縣郡城練水西，唐至德二年建。","宋太平舉国中勅改太平舉国寺。","）天台国清寺，天下稱四絕。","我来舉唐游，於中更無別。","枿木劃斷云，高峯頂積雪。","檻外一條溪，幾回流碎月。","（康熙《徽州府志》十八《寺观》。","○今按：此诗與前篇，異地異題，輾轉漢傳，各有可取之处。","《苕溪漁隐》所引，應即此一篇之末二句。","王琦未见此篇，不得稱《漁隐》以爲《題水西寺》斷句爲訛。","〖宋朱弁《曲洧旧闻》卷八謂此诗石刻在歙溪西太平寺。","〗）。"]', '诗', 'shi', '', NULL, '興唐寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a401105-2f4f-4467-9b8c-ee4d39cb3a7e', '殷十一贈栗岡硯', '殷十一贈栗岡硯', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["殷侯三玄士，贈我栗岡硯。","灑染中山毫，光映吳門練。","天寒水不凍，日用心不倦。","攜此臨墨池，還如對君面。","（高似孫《硯箋》四）（見宋初吳淑《事類賦》卷十五，「光映」作「光輝」。","）。"]', '["殷侯三玄士，贈我栗岡硯。","灑染中山毫，光映吳门練。","天寒水不凍，日用心不倦。","携此臨墨池，還如对君面。","（高似孫《硯箋》四）（见宋初吳淑《事類賦》卷十五，「光映」作「光輝」。","）。"]', '诗', 'shi', '', NULL, '殷十一贈栗岡硯 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b225361e-84a7-4e32-b4b8-0f73af0c8cef', '贈江油尉', '贈江油尉', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嵐光深院裏，傍砌水泠泠。","野燕巢官舍。","溪雲入[古]廳。","日斜孤吏過，簾捲亂峯青。","五色神仙尉，焚香讀道經。","（楊慎《全蜀藝文志》）（見《蜀中名勝記》卷十，云此詩「爲米芾書，刻在縣衛」。","「古」字據此書補。","吳企明謂此詩中「五色神仙尉」一句，用《北夢瑣言》卷十二所載張裼之子聞說壁魚入道經函，因蠹食神仙字身有五色，吞之可成仙的典故，因疑此詩爲晚唐人或宋人所假託。","）。"]', '["嵐光深院裏，傍砌水泠泠。","野燕巢官舍。","溪云入[古]廳。","日斜孤吏過，簾捲亂峯青。","五色神仙尉，焚香读道經。","（楊慎《全蜀藝文志》）（见《蜀中名勝記》卷十，云此诗「爲米芾书，刻在縣衛」。","「古」字據此书補。","吳企明謂此诗中「五色神仙尉」一句，用《北梦瑣言》卷十二所載張裼之子闻说壁鱼入道經函，因蠹食神仙字身有五色，吞之可成仙的典故，因疑此诗爲晚唐人或宋人所假託。","）。"]', '诗', 'shi', '', NULL, '贈江油尉 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29a8c83b-ca99-4598-8413-b6963ce4296e', '南陵五松山別荀七', '南陵五松山別荀七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["六即潁水荀，何慚許郡賓。","相逢太史奏，應是聚賢人。","玉隱且在石，蘭枯還見春。","俄成萬里別，立德貴清真。","（見影宋蜀刻本《李太白文集》卷十三，「立德」作「立得」。","）。"]', '["六即潁水荀，何慚許郡賓。","相逢太史奏，應是聚賢人。","玉隐且在石，蘭枯還见春。","俄成万里別，立德貴清真。","（见影宋蜀刻本《李太白文集》卷十三，「立德」作「立得」。","）。"]', '诗', 'shi', '', NULL, '南陵五松山別荀七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb6d00ef-3e92-4b27-a745-80de47fc2fa4', '暖酒', '暖酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["熱暖將來賓鐵文，暫時不動聚白雲。","撥卻白雲見青天，掇頭裏許便乘仙。","（見影宋蜀刻本《李太白文集》卷二十三。","）（以上繆氏本《太白集》）。"]', '["熱暖將来賓鐵文，暫时不动聚白云。","撥卻白云见青天，掇头裏許便乘仙。","（见影宋蜀刻本《李太白文集》卷二十三。","）（以上繆氏本《太白集》）。"]', '诗', 'shi', '', NULL, '暖酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e5436d-55d9-4dbe-af65-6480f7eab7fd', '棲賢寺', '棲賢寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["知見一何高，拭眼避天位。","同觀洗耳人，千古應無愧。","（以上《正德南康府志》十《詩類》）。"]', '["知见一何高，拭眼避天位。","同观洗耳人，千古應無愧。","（以上《正德南康府志》十《诗類》）。"]', '诗', 'shi', '', NULL, '棲賢寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f5d3ef-8c37-46c2-9798-275ffcdb939e', '題樓山石笋', '題楼山石笋', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["石笋如卓筆，縣之山之巔。","誰爲不平者，與之書青天。","（《遵義府志》四五《藝文詩》）（按此詩太白文集不載，即他拾遺本亦無之。","孫志有此，不知何本，仍錄俟考。","）。"]', '["石笋如卓笔，縣之山之巔。","誰爲不平者，與之书青天。","（《遵義府志》四五《藝文诗》）（按此诗太白文集不載，即他拾遺本亦無之。","孫志有此，不知何本，仍錄俟考。","）。"]', '诗', 'shi', '', NULL, '題樓山石笋 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d78816d-e627-48dd-9f7d-758042fd0d0f', '闕題', '闕題', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝披夢澤雲，笠釣青茫茫。","暮跨紫鱗去，海氣侵肌涼。","（《苕溪漁隱叢話前集》五引東坡。","又《詩話總龜》七《評論門》引《百斛明珠》。","云：「予都下見有人携一紙文書，字則顏魯公也，墨跡如未乾，紙亦新健，其首兩句云云。","此語非太白不能道。","」〖此即傳爲李白所作之《上清寶鼎詩》中的四句，全詩及考證見《全唐詩續拾遺》卷十四。","〗）。"]', '["朝披梦澤云，笠釣青茫茫。","暮跨紫鱗去，海氣侵肌涼。","（《苕溪漁隐叢話前集》五引东坡。","又《诗話總龟》七《評論门》引《百斛明珠》。","云：「予都下见有人携一紙文书，字則顏魯公也，墨跡如未乾，紙亦新健，其首兩句云云。","此語非太白不能道。","」〖此即傳爲李白所作之《上清寶鼎诗》中的四句，全诗及考證见《全唐诗續拾遺》卷十四。","〗）。"]', '诗', 'shi', '', NULL, '闕題 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1784005-83c8-4ebc-9d28-700374a0eb84', '闕題', '闕題', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["庭中繁樹乍含芳，紅錦重重翦作囊。","還合炎蒸留爍景，題來渭得好篇章。","（王琦輯注《太白集》附錄）（詳後「句」末附按。","）。"]', '["庭中繁樹乍含芳，紅錦重重翦作囊。","還合炎蒸留爍景，題来渭得好篇章。","（王琦輯注《太白集》附錄）（詳後「句」末附按。","）。"]', '诗', 'shi', '', NULL, '闕題 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52fb39aa-c15f-4383-8b26-eff34d8c8142', '題寶圌山（圌音纏）（句）', '題寶圌山（圌音纏）（句）', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["樵夫與耕者，出入畫屏中。","（《方輿勝覽》五四）。"]', '["樵夫與耕者，出入畫屏中。","（《方輿勝覽》五四）。"]', '诗', 'shi', '', NULL, '題寶圌山（圌音纏）（句） 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08300ba0-8213-47ec-bf26-a3c0978290bd', '句', '句', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '句 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79147662-e6d9-4aef-a4f3-e6716e579770', '句 一', '句 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["野禽啼杜宇，山蝶舞莊周。","（《苕溪漁隱叢話後集》四引《法藏碎金》）（見《法藏碎金》卷六。","）。"]', '["野禽啼杜宇，山蝶舞莊周。","（《苕溪漁隐叢話後集》四引《法藏碎金》）（见《法藏碎金》卷六。","）。"]', '诗', 'shi', '', NULL, '句 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e3b86d0-3b7a-4797-999a-42319b2cc418', '句 二', '句 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["霜結梅梢玉，陰凝竹幹銀。"]', '["霜結梅梢玉，陰凝竹幹銀。"]', '诗', 'shi', '', NULL, '句 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a68ae5-93b7-41ca-8d09-d80141e70ef1', '句 三', '句 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["竹粉千腰白，桃皮半頰紅。"]', '["竹粉千腰白，桃皮半頰紅。"]', '诗', 'shi', '', NULL, '句 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4838cf8-69ed-4e01-a869-d312988554d1', '句 四', '句 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["心爲殺人劍，淚是報恩珠。"]', '["心爲殺人劍，泪是報恩珠。"]', '诗', 'shi', '', NULL, '句 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8708a06-ceb1-4526-a90d-892046415f28', '句 五', '句 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["佳人微醉玉顏酡，笑伾粧樓澹小蛾。"]', '["佳人微醉玉顏酡，笑伾粧楼澹小蛾。"]', '诗', 'shi', '', NULL, '句 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b2e8f59-9a2e-43f3-bf22-a68c22dd7f59', '句 六', '句 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["借問單樓與同穴，可能銀漢勝重泉。","（以上王琦輯注《太白集》附錄）（以上諸句及「庭中繁樹乍含芳」一首，王琦云見於《海錄碎事》、《錦繡萬花谷》二書，「未詳爲誰氏之作，其句法皆與太白不相似，亦皆以爲太白詩矣。","」又推測或爲南唐時另一翰林學士李白撰。","）。"]', '["借问單楼與同穴，可能銀漢勝重泉。","（以上王琦輯注《太白集》附錄）（以上諸句及「庭中繁樹乍含芳」一首，王琦云见於《海錄碎事》、《錦繡万花谷》二书，「未詳爲誰氏之作，其句法皆與太白不相似，亦皆以爲太白诗矣。","」又推測或爲南唐时另一翰林学士李白撰。","）。"]', '诗', 'shi', '', NULL, '句 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6ff19b1-1052-42ab-a2d1-3e74126fe184', '菩薩蠻', '菩薩蠻', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["舉頭忽見衡陽雁，千聲萬字情何限。","叵耐薄情夫，一行書也無。","泣歸香閣恨，和淚淹紅粉。","待雁却回時，也無書寄伊。","（《尊前集》）（《全宋詞》第四冊第二五一月頁云《歷代詩餘》卷九載此爲陳以莊詞，楊金本《草堂詩餘》卷下作陳達叟詞。","）。"]', '["舉头忽见衡陽雁，千声万字情何限。","叵耐薄情夫，一行书也無。","泣归香閣恨，和泪淹紅粉。","待雁却回时，也無书寄伊。","（《尊前集》）（《全宋词》第四冊第二五一月頁云《歷代诗餘》卷九載此爲陳以莊词，楊金本《草堂诗餘》卷下作陳達叟词。","）。"]', '诗', 'shi', '', NULL, '菩薩蠻 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12966c79-9a9f-4b61-840d-5d6600fb8059', '畫像題詩', '畫像題诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["迎旦東風騎蹇驢，旋呵凍手暖髯鬚。","洛陽無限丹青手，還有功夫畫我無？","（《苕溪漁隱叢話後集》八云：「世有碑本子美畫像，上有詩云云。","子美決不肯自作，兼集中亦無之，必好事者爲之也。","」又《詩人玉屑》十一《考證》云：「『迎旦東風騎蹇驢』，決非唐人氣象，只似白樂天言語。","今者世俗圖畫，以爲少陵詩，漁隱亦辨其非矣。","黃伯思編入《杜集》，非也。","」〖《詩人玉屑》所引，見《滄浪詩話·考證》。","〗）。"]', '["迎旦东风騎蹇驢，旋呵凍手暖髯鬚。","洛陽無限丹青手，還有功夫畫我無？","（《苕溪漁隐叢話後集》八云：「世有碑本子美畫像，上有诗云云。","子美決不肯自作，兼集中亦無之，必好事者爲之也。","」又《诗人玉屑》十一《考證》云：「『迎旦东风騎蹇驢』，決非唐人氣象，只似白乐天言語。","今者世俗圖畫，以爲少陵诗，漁隐亦辨其非矣。","黄伯思編入《杜集》，非也。","」〖《诗人玉屑》所引，见《滄浪诗話·考證》。","〗）。"]', '诗', 'shi', '', NULL, '畫像題詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20bf5b64-fdd1-4359-808b-9473f4b74e71', '句', '句', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君看牆頭桃樹花，盡是行人眼中血。","（《螢雪叢說》下卷）（宋曾季貍《艇齋詩話》引唐人詩云：「時人有酒送張八，惟我無酒送張八。","君有陌上梅花紅，盡是離人眼中血。","」末二句與此僅數字不同。","《唐詩紀事》卷三一收李約《贈韋況》有「明月照張八」之句，疑此詩亦李約作。","《四庫提要》謂《螢雪叢書》錯誤甚多，作杜詩恐不足爲據。","）。"]', '["君看牆头桃樹花，尽是行人眼中血。","（《螢雪叢说》下卷）（宋曾季貍《艇斋诗話》引唐人诗云：「时人有酒送張八，惟我無酒送張八。","君有陌上梅花紅，尽是離人眼中血。","」末二句與此僅數字不同。","《唐诗紀事》卷三一收李約《贈韋況》有「明月照張八」之句，疑此诗亦李約作。","《四庫提要》謂《螢雪叢书》錯誤甚多，作杜诗恐不足爲據。","）。"]', '诗', 'shi', '', NULL, '句 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e13840b-6c3b-4960-8e86-d911c6cd327b', '', '', '86e438ca-a0c9-41cc-aede-ec51c7df3871', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 劉秩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca001389-8d5a-480d-8eda-1c1cdbf9d6ae', '過蕪湖', '過蕪湖', '86e438ca-a0c9-41cc-aede-ec51c7df3871', '唐', '["百里蕪湖縣，封侯自漢朝。","荻林秋帶雨，沙浦晚生潮。","近海魚鹽富，瀕淮粟麥饒。","相逢白頭叟，擊壤頌唐堯。","（《嘉慶蕪湖縣志》二三《藝文志》）。"]', '["百里蕪湖縣，封侯自漢朝。","荻林秋带雨，沙浦晚生潮。","近海鱼鹽富，瀕淮粟麦饒。","相逢白头叟，擊壤頌唐堯。","（《嘉慶蕪湖縣志》二三《藝文志》）。"]', '诗', 'shi', '', NULL, '過蕪湖 劉秩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658657fd-144b-4290-bc25-d3a1a6cc8f2d', '題龍日寺西龕石壁', '題龙日寺西龕石壁', '052e3e11-c95b-4bb3-83e9-87e49d61b457', '唐', '["聖澤久潤物，皇明常獨幽。","恩從祥風翱，德與和氣遊。","報國建香剎，開蠻臨僻州。","天長面綠水，地迥起朱樓。","尋異遍衆壑，坐禪逢一丘。","永懷根本妙，誓以身心修。","奇色艷草滿，珍名嘉樹稠。","遠江崩濤喧，復澗微雨休。","嘹唳猿響谷，參差峯入流。","碧煙曳篁徑，白日懸沙洲。","泛海謝安石，吟詩王子猷。","揚雄愛清靜，山簡多優游。","性分固有適，蓍龜何足求？","神閒孤臺月，目送千里舟。","攜手逸羣品，浩歌邈悠悠。","山情慕禽尚，詩格驚曹劉。","旌能舉滯時，選異拔奇儔。","鼎食當自致，巖棲難久留。","嗟余參符守，漢主遠分憂。","往往行春到，聞鐘散客愁。","（《蜀中名勝記》二五《保寧府·巴州》）。"]', '["聖澤久潤物，皇明常独幽。","恩從祥风翱，德與和氣游。","報国建香剎，开蠻臨僻州。","天长面綠水，地迥起朱楼。","尋異遍衆壑，坐禪逢一丘。","永懷根本妙，誓以身心修。","奇色艷草满，珍名嘉樹稠。","远江崩濤喧，复澗微雨休。","嘹唳猿响谷，參差峯入流。","碧煙曳篁徑，白日懸沙洲。","泛海謝安石，吟诗王子猷。","揚雄愛清静，山簡多優游。","性分固有適，蓍龟何足求？","神閒孤台月，目送千里舟。","携手逸羣品，浩歌邈悠悠。","山情慕禽尚，诗格驚曹劉。","旌能舉滯时，選異拔奇儔。","鼎食當自致，巖棲难久留。","嗟余參符守，漢主远分憂。","往往行春到，闻鐘散客愁。","（《蜀中名勝記》二五《保寧府·巴州》）。"]', '诗', 'shi', '', NULL, '題龍日寺西龕石壁 嚴武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfbb8bf-7211-4847-8b0a-08771971eefb', '寧國院（在新城縣）', '寧国院（在新城縣）', 'f113a05d-12af-47c9-8906-ce0497f01b9a', '唐', '["步步穿蘿入徑幽，柏高松老幾人游。","花開花落非僧事，自有清流對碧流。","（《嘉慶浙江通志》二二七《寺觀》）（南宋潛說友《咸淳臨安志》卷八五收此詩，幷云此院唐時名碧流，吳越時因避諱更名碧沼，宋大中祥符元年始改名寧國。","據此，詩題似應作《碧流院》）。"]', '["步步穿蘿入徑幽，柏高松老幾人游。","花开花落非僧事，自有清流对碧流。","（《嘉慶浙江通志》二二七《寺观》）（南宋潛说友《咸淳臨安志》卷八五收此诗，幷云此院唐时名碧流，吳越时因避諱更名碧沼，宋大中祥符元年始改名寧国。","據此，诗題似應作《碧流院》）。"]', '诗', 'shi', '', NULL, '寧國院（在新城縣） 牛仙客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ba4c40-e83b-4dc5-8109-d5416cca19db', '句', '句', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["經來白馬寺，僧到赤烏年。","（《詩話總龜後集》四四《釋氏門》引《雪波齋日記》）（見《劉賓客文集》卷十九《澈上人文集紀》，詩題爲《芙蓉園新寺》。","）。"]', '["經来白马寺，僧到赤烏年。","（《诗話總龟後集》四四《釋氏门》引《雪波斋日記》）（见《劉賓客文集》卷十九《澈上人文集紀》，诗題爲《芙蓉园新寺》。","）。"]', '诗', 'shi', '', NULL, '句 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd9df7d-009c-4506-98a5-b345a6540d97', '贈兄崇凱', '贈兄崇凱', 'd138ce4f-710e-4972-a701-7bca28fd7c54', '唐', '["空（〖1〗《全唐詩》二九五作何兆詩，題爲《贈兄》。","首句「兄」《全蜀藝文志》作「君」○《全蜀藝文志》二○）（「崇凱，內江人，奏《花萼樓賦》爲第一。","其弟元凱，亦自負其才，故贈兄」云云。","○今按：本詩前有李白《送友人內江范崇凱》五律一首，查各本《李白集》題下均無內江范崇凱五字，王琦亦未加注，不知楊慎有何依據。","特記於此。","）。"]', '["空（〖1〗《全唐诗》二九五作何兆诗，題爲《贈兄》。","首句「兄」《全蜀藝文志》作「君」○《全蜀藝文志》二○）（「崇凱，內江人，奏《花萼楼賦》爲第一。","其弟元凱，亦自負其才，故贈兄」云云。","○今按：本诗前有李白《送友人內江范崇凱》五律一首，查各本《李白集》題下均無內江范崇凱五字，王琦亦未加注，不知楊慎有何依據。","特記於此。","）。"]', '诗', 'shi', '', NULL, '贈兄崇凱 范元凱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b3e154-2b8c-4bc6-8485-2b3afd05d149', '題阮客舊居（《全唐詩》二六二作李陽冰，第三句「到」《詩話總龜》作「得」）', '題阮客旧居（《全唐诗》二六二作李陽冰，第三句「到」《诗話總龟》作「得」）', 'dc1cc545-6817-42f9-b2e2-fed3a75830c6', '唐', '["空（趙明誠《金石錄》云：《題阮客舊居詩》，小篆書，《集古錄》以爲陽冰作。","驗其姓名，乃縉雲今李{茊/山}，非陽冰也。","其字畫亦不工。","蓋陽冰肅宗上元中嘗令縉運，其篆字石刻，尚多有存者，故歐陽公亦誤以此詩爲陽冰作爾。","○《詩話總龜》二九《正訛門》〖趙明誠語見《金石錄》卷三十，「李{茊/山}」作「李𬜪」。","〗）。"]', '["空（趙明誠《金石錄》云：《題阮客旧居诗》，小篆书，《集古錄》以爲陽冰作。","驗其姓名，乃縉云今李{茊/山}，非陽冰也。","其字畫亦不工。","蓋陽冰肅宗上元中嘗令縉運，其篆字石刻，尚多有存者，故歐陽公亦誤以此诗爲陽冰作爾。","○《诗話總龟》二九《正訛门》〖趙明誠語见《金石錄》卷三十，「李{茊/山}」作「李𬜪」。","〗）。"]', '诗', 'shi', '', NULL, '題阮客舊居（《全唐詩》二六二作李陽冰，第三句「到」《詩話總龜》作「得」） 李𬜪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('792d644a-969f-498b-8cc3-2c913cc048bc', '鐵山（一名鳳凰山）', '鐵山（一名鳳凰山）', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["雁陣起秋雲，雞聲滿林屋。","客思不可禁，鐵峯駐雕轂。","（《蜀中名勝記》三○《潼川府·安岳縣》）。"]', '["雁陣起秋云，雞声满林屋。","客思不可禁，鐵峯駐雕轂。","（《蜀中名勝記》三○《潼川府·安岳縣》）。"]', '诗', 'shi', '', NULL, '鐵山（一名鳳凰山） 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac137a8-d1a0-41de-b992-04735dd41885', '經蘭亭故池聯句', '經蘭亭故池聯句', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["（原注：鮑防、嚴維、劉全白、宋迪，共三十五人，具姓名。","大歷中唱和五十七人，元本不注姓名於聯句下。","）曝水邀歡處，遺芳尚宛然。","名從右軍出，山在古人前。","蕪沒成塵跡，規模得大賢。","湖心舟已並，村步騎仍連。","賞是文辭會，歡同癸丑年。","茂林無舊徑，修竹起新煙。","宛是崇山下，仍依古道邊。","院開新地勝，門占舊畬田。","荒阪披蘭築，枯池帶墨穿。","敍成應唱道，杯作每推先。","空見雲生岫，時聞鶴唳天。","滑苔封石磴，密篠礙飛泉。","事感人寰變，歸慚府服牽。","寓時仍覩葉，歎逝更臨川。","野興攀藤坐，幽情枕石眠。","玩奇聊倚策，尋異稍移船。","草露猶霑服，松風尚入弦。","山遊稱絕調，今古有多篇。","（桑世昌《蘭亭考》十二）（此詩爲衆人聯句之作。","最早應見於《大曆年浙東聯唱集》，此書今不傳。","北宋孔延之《會稽掇英總集》卷十四收入時，每兩句後空兩格，題注：「元本不注名姓於聯句下。","」「元本即指《大曆年浙東聯唱集》。","《蘭亭考》連抄不空格，本書收嚴維名下而未作說明，皆欠妥。","」）。"]', '["（原注：鲍防、嚴維、劉全白、宋迪，共三十五人，具姓名。","大歷中唱和五十七人，元本不注姓名於聯句下。","）曝水邀歡处，遺芳尚宛然。","名從右軍出，山在古人前。","蕪沒成塵跡，規模得大賢。","湖心舟已並，村步騎仍連。","賞是文辞會，歡同癸丑年。","茂林無旧徑，修竹起新煙。","宛是崇山下，仍依古道邊。","院开新地勝，门占旧畬田。","荒阪披蘭築，枯池带墨穿。","敍成應唱道，杯作每推先。","空见云生岫，时闻鹤唳天。","滑苔封石磴，密篠礙飞泉。","事感人寰变，归慚府服牽。","寓时仍覩葉，歎逝更臨川。","野兴攀藤坐，幽情枕石眠。","玩奇聊倚策，尋異稍移船。","草露猶霑服，松风尚入弦。","山游稱絕調，今古有多篇。","（桑世昌《蘭亭考》十二）（此诗爲衆人聯句之作。","最早應见於《大曆年浙东聯唱集》，此书今不傳。","北宋孔延之《會稽掇英總集》卷十四收入时，每兩句後空兩格，題注：「元本不注名姓於聯句下。","」「元本即指《大曆年浙东聯唱集》。","《蘭亭考》連抄不空格，本书收嚴維名下而未作说明，皆欠妥。","」）。"]', '诗', 'shi', '', NULL, '經蘭亭故池聯句 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d36c62-2c18-45e2-9d7e-42083622a84a', '泛太湖', '泛太湖', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["萬頃波涵一碧秋，飄飄隨處任輕舟。","踏歌聽立忘機鷺，擊楫驚飛熟夢鷗。","烟水淡圖山點翠，雲霞麗景日拋毬。","帆收不盡湖天景，何必蒹葭古渡頭。","（《古今圖書集成·山川典》二八二《太湖部》）。"]', '["万頃波涵一碧秋，飄飄隨处任轻舟。","踏歌听立忘機鷺，擊楫驚飞熟梦鷗。","烟水淡圖山点翠，云霞丽景日拋毬。","帆收不尽湖天景，何必蒹葭古渡头。","（《古今圖书集成·山川典》二八二《太湖部》）。"]', '诗', 'shi', '', NULL, '泛太湖 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deabcfa8-b5aa-40a8-8b24-708d5793f742', '題竹', '題竹', '21cb05c2-b06b-4352-9494-f23d9d7eeb1c', '唐', '["（玄覽，大曆末住荆州陟岵寺，道高有風韻，人不可得而親。","張璪嘗畫古松於齋壁，符載讚之，衛象詩之，亦一時三絕，覽悉加堊焉。","問其故，曰：「無事疥吾壁也。","」僧那即其甥，爲寺之患，發瓦探鷇，壞牆薰鼠，覽未嘗責。","有弟子義詮，布衣一食，覽亦不稱。","或怪之，乃題詩於竹曰：）大海從魚躍，長空任鳥飛。","欲知吾道廓，不與物情違。","（《酉陽雜俎前集》十二《語資》。","又《詩話總龜》三十《道僧門》引《古今詩話》。","又《萬首唐人絕句》補本十，詩中前二句與後二句倒置。","。）"]', '["（玄覽，大曆末住荆州陟岵寺，道高有风韻，人不可得而親。","張璪嘗畫古松於斋壁，符載讚之，衛象诗之，亦一时三絕，覽悉加堊焉。","问其故，曰：「無事疥吾壁也。","」僧那即其甥，爲寺之患，發瓦探鷇，壞牆薰鼠，覽未嘗責。","有弟子義詮，布衣一食，覽亦不稱。","或怪之，乃題诗於竹曰：）大海從鱼躍，长空任鸟飞。","欲知吾道廓，不與物情違。","（《酉陽杂俎前集》十二《語資》。","又《诗話總龟》三十《道僧门》引《古今诗話》。","又《万首唐人絕句》補本十，诗中前二句與後二句倒置。","。）"]', '诗', 'shi', '', NULL, '題竹 玄覽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb51edd6-2fb2-4973-8d74-8125cdfb1109', '貞元六年春三月庚子百寮宴於曲江亭上賦詩以賜之', '貞元六年春三月庚子百寮宴於曲江亭上賦诗以賜之', 'fe374631-429c-4026-89f6-6aa64b179b22', '唐', '["歲閏節華晚，衆芳繁暮春。","霽日天地晴，元巳風景新。","禊飲傳舊俗，古今歡此辰。","至樂在同和，絲竹奚所陳。","薰琴是賞心，姑射可凝神。","何必尚躭緬，浮觴曲水濱？","（《太平御覽》五九二《文部·御製》引《唐書》。","）（今按：兩《唐書》本紀均不載，《全唐詩》另有一首不同。","）。"]', '["歲閏節华晚，衆芳繁暮春。","霽日天地晴，元巳风景新。","禊饮傳旧俗，古今歡此辰。","至乐在同和，絲竹奚所陳。","薰琴是賞心，姑射可凝神。","何必尚躭緬，浮觴曲水濱？","（《太平御覽》五九二《文部·御製》引《唐书》。","）（今按：兩《唐书》本紀均不載，《全唐诗》另有一首不同。","）。"]', '诗', 'shi', '', NULL, '貞元六年春三月庚子百寮宴於曲江亭上賦詩以賜之 李适 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa72d96-9a31-4634-b05a-721700be9740', '三月三日寒食從劉八丈使君登遷仁樓眺望', '三月三日寒食從劉八丈使君登遷仁楼眺望', '09380d71-c8bd-4acb-bfce-64606e2d66ea', '唐', '["從公無小大，在伴樂人賢。","楚國逢荒歲，隨人若有年。","空波交水埒，重岫夾畬田。","桑柘溫風軟，雲霞返照鮮。","因高寺剎迥，臨遠郡樓偏。","花柳清明節，親賓上巳筵。","故鄉徒有路，春雁獨歸邊。","幸望山陰客，爲文內史前。","（《劉長卿集》五）。"]', '["從公無小大，在伴乐人賢。","楚国逢荒歲，隨人若有年。","空波交水埒，重岫夾畬田。","桑柘溫风軟，云霞返照鲜。","因高寺剎迥，臨远郡楼偏。","花柳清明節，親賓上巳筵。","故乡徒有路，春雁独归邊。","幸望山陰客，爲文內史前。","（《劉长卿集》五）。"]', '诗', 'shi', '', NULL, '三月三日寒食從劉八丈使君登遷仁樓眺望 李穆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b34d73c8-d4df-4289-8f22-9dac80455351', '留辭', '留辞', '09380d71-c8bd-4acb-bfce-64606e2d66ea', '唐', '["（今按：劉長卿另有《送李穆歸淮南詩》，《全唐詩》一五一誤以此詩爲長卿詩○同前八。","）。"]', '["（今按：劉长卿另有《送李穆归淮南诗》，《全唐诗》一五一誤以此诗爲长卿诗○同前八。","）。"]', '诗', 'shi', '', NULL, '留辭 李穆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a13722f-8284-43ee-a787-1517d637d7f0', '送韋判官赴閩中', '送韋判官赴閩中', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["空（《全唐詩》二一○作皇甫詩。","第四句「傷」《文苑英華》作「驚」《文苑英華》二七二《送行》）。"]', '["空（《全唐诗》二一○作皇甫诗。","第四句「傷」《文苑英华》作「驚」《文苑英华》二七二《送行》）。"]', '诗', 'shi', '', NULL, '送韋判官赴閩中 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3239d1f-b2d7-4c4c-ba6d-b7cf1912c983', '寄（一作「贈」）章司直', '寄（一作「贈」）章司直', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["空（原注：「《百家詩選》作郎士元詩。","」《全唐詩》二四八作郎士元《贈韋司直》同上二五四《寄贈》）。"]', '["空（原注：「《百家诗選》作郎士元诗。","」《全唐诗》二四八作郎士元《贈韋司直》同上二五四《寄贈》）。"]', '诗', 'shi', '', NULL, '寄（一作「贈」）章司直 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad1252aa-58d8-482e-9429-b97d85df647c', '三月三日後亭泛舟', '三月三日後亭泛舟', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["越中山水高且深，興來無處不登臨。","永和九年刺海郡，暮春三月醉山陰。","（桑世昌《蘭亭考》十二）。"]', '["越中山水高且深，兴来無处不登臨。","永和九年刺海郡，暮春三月醉山陰。","（桑世昌《蘭亭考》十二）。"]', '诗', 'shi', '', NULL, '三月三日後亭泛舟 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9be8b56-8f0b-477c-9f5e-99d517da5ce4', '太姥山', '太姥山', '928d386f-e6b7-4736-a303-978a5fe7b998', '唐', '["揚舲窮海島，選勝訪神仙。","鬼斧巧開鑿，仙蹤常往還。","東甌冥漠外，南越渺茫間。","爲問容成子，刀圭乞駐顏。","（《古今圖書集成·職方典》一一○八《福寧州部》）。"]', '["揚舲窮海島，選勝訪神仙。","鬼斧巧开鑿，仙蹤常往還。","东甌冥漠外，南越渺茫间。","爲问容成子，刀圭乞駐顏。","（《古今圖书集成·職方典》一一○八《福寧州部》）。"]', '诗', 'shi', '', NULL, '太姥山 薛令之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832f5525-5dfe-486a-b781-ac067583d98e', '送元使君', '送元使君', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["郢門將咫尺，龍節莫夷猶。","送客與雲散，行人看月愁。","遙聞江漢水，日與政聲流。","（《輿地紀勝》八四《郢州》）。"]', '["郢门將咫尺，龙節莫夷猶。","送客與云散，行人看月愁。","遙闻江漢水，日與政声流。","（《輿地紀勝》八四《郢州》）。"]', '诗', 'shi', '', NULL, '送元使君 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51ae71a4-d49a-4bda-beea-c20b1b689f6a', '歷山', '歷山', '92a54357-bc0c-4dcc-beeb-df9b758973c5', '唐', '["（齊州城東有孤石，平地聳出，俗謂之歷山。","以北有泉，號舜井。","東隔小街，又有石井，汲之不絕，云是舜東家之井。","乾元中有魏炎者，於此題詩曰：）齊州城東舜子郡，邑人雖移井不改。","時聞洶洶動綠波，猶謂華井中在。"]', '["（齊州城东有孤石，平地聳出，俗謂之歷山。","以北有泉，號舜井。","东隔小街，又有石井，汲之不絕，云是舜东家之井。","乾元中有魏炎者，於此題诗曰：）齊州城东舜子郡，邑人雖移井不改。","时闻洶洶动綠波，猶謂华井中在。"]', '诗', 'shi', '', NULL, '歷山 魏炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce48467d-1b82-4aec-91e5-d8213627f1e4', '又曰', '又曰', '92a54357-bc0c-4dcc-beeb-df9b758973c5', '唐', '["西家今爲定戒寺，東家今爲練戒寺。","一邊井中投一瓶，兩井相搖響泙濞。"]', '["西家今爲定戒寺，东家今爲練戒寺。","一邊井中投一瓶，兩井相搖响泙濞。"]', '诗', 'shi', '', NULL, '又曰 魏炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2796398b-d3d8-44b8-a942-9e7f31e93f30', '又曰', '又曰', '92a54357-bc0c-4dcc-beeb-df9b758973c5', '唐', '["濟南郡裏多沮洳，娥皇女英汲井處。","竊向池中潛甽來，澆茆畦上平流去。","（《封氏聞見記》八《歷山》）。"]', '["濟南郡裏多沮洳，娥皇女英汲井处。","竊向池中潛甽来，澆茆畦上平流去。","（《封氏闻见記》八《歷山》）。"]', '诗', 'shi', '', NULL, '又曰 魏炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3f93372-0398-48b5-9d4a-e729495291c0', '', '', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0acb14e-6223-4453-b9a1-a863b56e320a', '詩', '诗', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["寒食涔陽諸小兒，齊歌齊舞帶花枝。","郡從兵亂年荒後，人似開元天寶時。","（《輿地紀勝》引此四句後，注「云云」二字，復引「行春」二句。","知原詩爲七律，引時刪去第三聯，今僅六句。","此處分列，未允。","）。"]', '["寒食涔陽諸小兒，齊歌齊舞带花枝。","郡從兵亂年荒後，人似开元天寶时。","（《輿地紀勝》引此四句後，注「云云」二字，复引「行春」二句。","知原诗爲七律，引时刪去第三聯，今僅六句。","此处分列，未允。","）。"]', '诗', 'shi', '', NULL, '詩 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3700468-1cbc-49fb-8305-0b61996e392a', '句 一', '句 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["行春更欲遊何處，東郭門前竹馬期。"]', '["行春更欲游何处，东郭门前竹马期。"]', '诗', 'shi', '', NULL, '句 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b43c1faf-8a76-4da9-a0ee-1289c8d30cda', '句 二', '句 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["不須挂嶺居天末，但見涔陽在眼前。","〖1〗（以上《輿地紀勝》七十《灃州》）（〖1〗《輿地紀勝》卷一○三《靜江府》引「不知桂嶺居天末」句，題作《寄薛評事》，注云：「見《曹州圖經》。","」）。"]', '["不須挂嶺居天末，但见涔陽在眼前。","〖1〗（以上《輿地紀勝》七十《灃州》）（〖1〗《輿地紀勝》卷一○三《静江府》引「不知桂嶺居天末」句，題作《寄薛評事》，注云：「见《曹州圖經》。","」）。"]', '诗', 'shi', '', NULL, '句 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e5c9f1f-d009-4a10-ae40-cd7e2805fca5', '藥（一見《宋之問集》）', '藥（一见《宋之问集》）', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["有嘉（宋作「卉」）秘神仙，君臣有禮焉。","忻當苦口喻，不畏入腸偏。","扁鵲功成日，神農定器然（宋作「品年」）。","丹成如可待，鷄犬自聞天。","（《文苑英華》三二七《花木》。","此詩在宋之問《春泉洗藥》後，缺姓名，據目錄作陳潤。","）。"]', '["有嘉（宋作「卉」）秘神仙，君臣有禮焉。","忻當苦口喻，不畏入腸偏。","扁鵲功成日，神農定器然（宋作「品年」）。","丹成如可待，鷄犬自闻天。","（《文苑英华》三二七《花木》。","此诗在宋之问《春泉洗藥》後，缺姓名，據目錄作陳潤。","）。"]', '诗', 'shi', '', NULL, '藥（一見《宋之問集》） 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4afee65-f035-4956-87a1-47994ccd5021', '酬張二十員外（《全唐詩》二四二張繼《江上送客遊廬山》詩後）', '酬張二十員外（《全唐诗》二四二張繼《江上送客游廬山》诗後）', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["空（此詩原缺出處，應出《文苑英華》卷二四三，題作《酬張二十員外前成長子博士叔向》，署「張繼」，《全唐詩》據以收於張繼名下，岑仲勉《唐人行第錄》考證此應爲竇叔向詩，張二十即張繼。","此詩題應作《酬張二十員外》，「前國子博士叔向」爲附收入張作時之署名。","後人不明唐集附收之例，因誤作張詩。","）。"]', '["空（此诗原缺出处，應出《文苑英华》卷二四三，題作《酬張二十員外前成长子博士叔向》，署「張繼」，《全唐诗》據以收於張繼名下，岑仲勉《唐人行第錄》考證此應爲竇叔向诗，張二十即張繼。","此诗題應作《酬張二十員外》，「前国子博士叔向」爲附收入張作时之署名。","後人不明唐集附收之例，因誤作張诗。","）。"]', '诗', 'shi', '', NULL, '酬張二十員外（《全唐詩》二四二張繼《江上送客遊廬山》詩後） 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51e6574-b34a-4ce6-b469-2cb9f5ab360f', '題普門上人房（《文苑英華》二三五《寺院》〖1〗）', '題普门上人房（《文苑英华》二三五《寺院》〖1〗）', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["空（〖1〗《全唐詩》卷二四九作皇甫冉，卷一四八又作劉長卿詩，另日末流藏唐鈔本《唐詩卷》則作郎士元詩。","）。"]', '["空（〖1〗《全唐诗》卷二四九作皇甫冉，卷一四八又作劉长卿诗，另日末流藏唐鈔本《唐诗卷》則作郎士元诗。","）。"]', '诗', 'shi', '', NULL, '題普門上人房（《文苑英華》二三五《寺院》〖1〗） 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd27c72-d591-45f6-9d65-c74df8c71d2d', '送韓司直（《全唐詩》二四八作郎士元詩，第三句「春草」，《文苑英華》作「芳草」○同上二七二《送行》〖1〗）', '送韓司直（《全唐诗》二四八作郎士元诗，第三句「春草」，《文苑英华》作「芳草」○同上二七二《送行》〖1〗）', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["空（〖1〗《全唐詩》卷一四八又作劉長卿詩。","《極玄集》卷下又作皇甫冉詩。","〗）。"]', '["空（〖1〗《全唐诗》卷一四八又作劉长卿诗。","《極玄集》卷下又作皇甫冉诗。","〗）。"]', '诗', 'shi', '', NULL, '送韓司直（《全唐詩》二四八作郎士元詩，第三句「春草」，《文苑英華》作「芳草」○同上二七二《送行》〖1〗） 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde5b36a-0894-4d3c-9f4b-f9178d4ccef1', '句', '句', '08a93454-0a28-49f1-b0fa-85f014582942', '唐', '["（贄爲渭南尉有詩云云。","蓋縣內多流泉。","）姜泉流渺渺，夾砌樹陰陰。","（宋敏求《長安志》十七《渭南縣》。","）（今按：《全唐詩》引《唐語林》，謂任江淮尉題廰詩句。","第一句不同，第二句「夾」誤「來」。","〖此引《長安志》當爲《經訓堂叢書》本，《四庫全書》本前句作「遶堦流虢㶁」，《唐語林》卷四作「遶階流助𣵪」，「助𣵪」當作「渺渺」。","《記纂淵海》卷二四題作《題姜泉》，前句作「遶街流渺渺」。","〗）。"]', '["（贄爲渭南尉有诗云云。","蓋縣內多流泉。","）姜泉流渺渺，夾砌樹陰陰。","（宋敏求《长安志》十七《渭南縣》。","）（今按：《全唐诗》引《唐語林》，謂任江淮尉題廰诗句。","第一句不同，第二句「夾」誤「来」。","〖此引《长安志》當爲《經訓堂叢书》本，《四庫全书》本前句作「遶堦流虢㶁」，《唐語林》卷四作「遶階流助𣵪」，「助𣵪」當作「渺渺」。","《記纂淵海》卷二四題作《題姜泉》，前句作「遶街流渺渺」。","〗）。"]', '诗', 'shi', '', NULL, '句 陸贄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43e3f24-d8e4-4f73-b656-528d2ce3677e', '語錄詩', '語錄诗', '57774cd3-6ad5-485e-9109-f050455d08e4', '唐', '["慧眼近空心，非關髑髏孔。","對面說不識，饒你母姓董。","（敦煌寫本《歷代法實記》所附（《歷代法寶記》云此爲無住引王梵志詩。","此作無住，似誤。","）。"]', '["慧眼近空心，非关髑髏孔。","对面说不識，饒你母姓董。","（敦煌寫本《歷代法實記》所附（《歷代法寶記》云此爲無住引王梵志诗。","此作無住，似誤。","）。"]', '诗', 'shi', '', NULL, '語錄詩 無住 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f78e62ce-db93-4c29-83b5-25a5fec4f559', '詠走馬燈詩', '詠走马灯诗', '27683bbe-7a24-48fd-a0e6-b10174b72716', '唐', '["團團遊了又來遊，無箇明人指路頭。","除卻心中三昧火，鎗刀馬一齊休。","（《悅心集》一）（曹汛謂走馬燈始見於宋，唐時未有，詩疑出依託。","）。"]', '["團團游了又来游，無箇明人指路头。","除卻心中三昧火，鎗刀马一齊休。","（《悅心集》一）（曹汛謂走马灯始见於宋，唐时未有，诗疑出依託。","）。"]', '诗', 'shi', '', NULL, '詠走馬燈詩 無際 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a982470e-d834-4abc-966c-502d713d75a3', '榮祿（句）', '榮祿（句）', 'dc833e8e-5b61-4f72-b8af-4048e081017e', '唐', '["牛羊衛草窺環珮，鳥雀離花聽管絃。","（《輿地紀勝》一五五《遂寧府》）。"]', '["牛羊衛草窺环珮，鸟雀離花听管絃。","（《輿地紀勝》一五五《遂寧府》）。"]', '诗', 'shi', '', NULL, '榮祿（句） 張九宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('920cb46a-d278-43ec-bc70-7fd7a5452ed1', '白雲向空盡（原注：《類詩》作焦郁。《全唐詩》五○五作焦郁詩〖1〗）', '白云向空尽（原注：《類诗》作焦郁。《全唐诗》五○五作焦郁诗〖1〗）', 'd31bd057-0ca2-43ec-b600-6a74788fb022', '唐', '["白雲生（一作「昇」）遠岫，搖曳入晴空。","乘化隨舒卷，無心任始終。","欲銷仍白（一作「帶」）日，將斷或（一作「更」）因風。","勢薄飛難定，天高色易窮。","影收元氣表，光滅太虛中。","況（一作「儻」）若從龍去（一作「出」），還施潤（一作「濟」）物功。","（《文苑英華》一八二《省試》）（明刻本《文苑英華》注引《類詩》，指宋人所編之《唐宋類詩》，其於省試諸詩的歸屬，與《文苑英華》有異。","就今所可考知之各例看，多以《文苑英華》所署者爲長。","而《全唐詩》多從《類詩》，似未允。","）。"]', '["白云生（一作「昇」）远岫，搖曳入晴空。","乘化隨舒卷，無心任始終。","欲銷仍白（一作「带」）日，將斷或（一作「更」）因风。","勢薄飞难定，天高色易窮。","影收元氣表，光滅太虛中。","況（一作「儻」）若從龙去（一作「出」），還施潤（一作「濟」）物功。","（《文苑英华》一八二《省試》）（明刻本《文苑英华》注引《類诗》，指宋人所編之《唐宋類诗》，其於省試諸诗的归屬，與《文苑英华》有異。","就今所可考知之各例看，多以《文苑英华》所署者爲长。","而《全唐诗》多從《類诗》，似未允。","）。"]', '诗', 'shi', '', NULL, '白雲向空盡（原注：《類詩》作焦郁。《全唐詩》五○五作焦郁詩〖1〗） 周存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f991aaa-fdc0-4ea2-90f7-471d1dffd3a2', '竹〖1〗', '竹〖1〗', '8a782d18-dc36-482e-b0d2-094cebe8381b', '唐', '["竹價長東南，別種殊草木。","成林處處雲，抽筍年年玉。","天風起成韻，池水涵更綠。","閒臨庾信園，數竿心自足。","（《古今圖書集成·草木典》一九二《竹部》）（〖1〗《文苑英華》卷三二五、《全唐詩》卷二九六收張南史《竹》詩，爲一字至七字詩。","此作五言詩，而詩句與一字至七字詩大致相同，可斷定爲後人據原詩改寫而成。","《佩文斎詠物詩選》卷三三五所收亦同此。","）。"]', '["竹價长东南，別種殊草木。","成林处处云，抽筍年年玉。","天风起成韻，池水涵更綠。","閒臨庾信园，數竿心自足。","（《古今圖书集成·草木典》一九二《竹部》）（〖1〗《文苑英华》卷三二五、《全唐诗》卷二九六收張南史《竹》诗，爲一字至七字诗。","此作五言诗，而诗句與一字至七字诗大致相同，可斷定爲後人據原诗改寫而成。","《佩文斎詠物诗選》卷三三五所收亦同此。","）。"]', '诗', 'shi', '', NULL, '竹〖1〗 張南史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e01abff6-50a0-4a83-8cdd-0b80a6e629fb', '晚次渭上', '晚次渭上', '9f0732d5-e1de-441d-8bf7-a6de05ead378', '唐', '["晚來清渭上，一似楚江邊。","魚網依沙岸，人家旁水田。","不逢京口信，空認渡頭船。","逆旅無消息，歸心誰爲傳？","（《又玄集》上）。"]', '["晚来清渭上，一似楚江邊。","鱼網依沙岸，人家旁水田。","不逢京口信，空認渡头船。","逆旅無消息，归心誰爲傳？","（《又玄集》上）。"]', '诗', 'shi', '', NULL, '晚次渭上 冷朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbf5206-a54a-4be4-8d6e-ef9a069dccb9', '過繡林（句）', '過繡林（句）', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["繡林直照劉郎浦，鋪磧女臯。","（《輿地紀勝》六五《江陵府》）。"]', '["繡林直照劉郎浦，鋪磧女臯。","（《輿地紀勝》六五《江陵府》）。"]', '诗', 'shi', '', NULL, '過繡林（句） 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff1456b-997f-4f2a-9d5d-7e74c5550846', '登瀛洲閣〖1〗', '登瀛洲閣〖1〗', '99564124-c046-4116-be43-d12dffe3b5d2', '唐', '["翠閣傍瀛洲，洲中勝事幽。","沙明眠雪鷺，波漲宿霜鷗。","濺雨荷盤膩，縈風柳帶柔。","公餘自多暇，尊酒奉仙遊。","（曹汛謂康熙《蓬萊縣志》卷二、乾隆《登州府志》卷；用均云《登蓬萊閣》爲宋李愿撰。","並疑其人約歐陽修同時。","姑仍存之，俟考詳。","）。"]', '["翠閣傍瀛洲，洲中勝事幽。","沙明眠雪鷺，波漲宿霜鷗。","濺雨荷盤膩，縈风柳带柔。","公餘自多暇，尊酒奉仙游。","（曹汛謂康熙《蓬萊縣志》卷二、乾隆《登州府志》卷；用均云《登蓬萊閣》爲宋李愿撰。","並疑其人約歐陽修同时。","姑仍存之，俟考詳。","）。"]', '诗', 'shi', '', NULL, '登瀛洲閣〖1〗 李愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c729b8-9922-4aec-a28c-d053b5f7b8aa', '望仙門', '望仙门', '99564124-c046-4116-be43-d12dffe3b5d2', '唐', '["樓影空門裏，門開望衆仙。","綠鬟雲漠漠，翠黛月涓涓。","煙駕知何處，星槎記昔年。","夕陽孤鳥畔，渺渺海浮天。","（《古今圖集當成·職方典》二八○《登州府部》）。"]', '["楼影空门裏，门开望衆仙。","綠鬟云漠漠，翠黛月涓涓。","煙駕知何处，星槎記昔年。","夕陽孤鸟畔，渺渺海浮天。","（《古今圖集當成·職方典》二八○《登州府部》）。"]', '诗', 'shi', '', NULL, '望仙門 李愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ed7622-9b8b-47da-b29f-1279aa58320c', '梅花吟', '梅花吟', '2d988867-ce13-4dc3-b4c5-729d232ce4db', '唐', '["平淮策騎過東來，適遇梅花灼爍開。","相耐歲寒存苦節，故於冷境發枯荄。","（《弘治黃州府志》七《藝文·黃梅縣》）。"]', '["平淮策騎過东来，適遇梅花灼爍开。","相耐歲寒存苦節，故於冷境發枯荄。","（《弘治黄州府志》七《藝文·黄梅縣》）。"]', '诗', 'shi', '', NULL, '梅花吟 李愬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01d2ff56-9c8e-4c2a-bb47-a5fa460604a6', '漳州（句）', '漳州（句）', 'e575ec45-b79b-4db5-b3da-adf2e86e46a6', '唐', '["南宮才調久淹留，符節初臨海上州。","（《輿地紀勝》一三一《漳州》）。"]', '["南宮才調久淹留，符節初臨海上州。","（《輿地紀勝》一三一《漳州》）。"]', '诗', 'shi', '', NULL, '漳州（句） 徐放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af27d77b-4437-4002-ba58-e50b5584fcbf', '留別劉員外', '留別劉員外', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["寥落窮秋九月天，風吹白雪起江邊。","豈意與君於此別，相看挃淚水潺湲。","（《四部叢刊》影印明正德本《劉隨州詩集》八）。"]', '["寥落窮秋九月天，风吹白雪起江邊。","豈意與君於此別，相看挃泪水潺湲。","（《四部叢刊》影印明正德本《劉隨州诗集》八）。"]', '诗', 'shi', '', NULL, '留別劉員外 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6f9439-7c07-4c42-84d8-28caf5fd2dab', '膏澤多豐年', '膏澤多豐年', 'e03e529f-d309-47c2-8af3-6a1333cbfa66', '唐', '["空（原缺姓名，據目錄補。","《全唐詩》四六六作薛存誠，第四句「庾」《文苑英華》作「慶」，又七八七列入無名氏。","）。"]', '["空（原缺姓名，據目錄補。","《全唐诗》四六六作薛存誠，第四句「庾」《文苑英华》作「慶」，又七八七列入無名氏。","）。"]', '诗', 'shi', '', NULL, '膏澤多豐年 張聿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d018613d-82c5-40c1-b4e3-31492bc7f52c', '望禁苑祥光', '望禁苑祥光', 'e03e529f-d309-47c2-8af3-6a1333cbfa66', '唐', '["空（原缺姓名，據目錄補。","《全唐詩》七八七列入無名氏，第七句「鼎氣」《文苑英華》作「暴氣」○以上《文苑英華》一八○《省試》。","）。"]', '["空（原缺姓名，據目錄補。","《全唐诗》七八七列入無名氏，第七句「鼎氣」《文苑英华》作「暴氣」○以上《文苑英华》一八○《省試》。","）。"]', '诗', 'shi', '', NULL, '望禁苑祥光 張聿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d090eea9-5041-41eb-84d8-14f4c7c8f9b9', '題皎然影堂', '題皎然影堂', '7522f6a6-f353-4dcd-a334-1334ef84b6df', '唐', '["（皎然名晝，以貞元元年終山寺。","有集十卷，于頔序集。","貞元八年正月，勅寫其文集入於秘閣，天下榮之。","又著《儒釋交遊傳》及《內典類聚》共四十卷，《號呶子》十卷，時貴流布。","元和四年，太守范傳正、會稽釋靈澈同過舊院，就影堂傷悼彌久，遺題曰：）道安已返無何鄉，慧遠來過舊草堂。","余亦當時及門者，共吟佳句一焚香。","（《古今圖書集成·神異典》一六九《僧部列傳》引《高僧傳》）（見《宋高僧傳》卷二十九《唐湖州杼山皎然傳》。","「以貞元元年終山寺」，《宋高僧傳》作「以貞元年終山寺」。","據趙昌平考證，皎然約卒於貞元末。","）。"]', '["（皎然名晝，以貞元元年終山寺。","有集十卷，于頔序集。","貞元八年正月，勅寫其文集入於秘閣，天下榮之。","又著《儒釋交游傳》及《內典類聚》共四十卷，《號呶子》十卷，时貴流布。","元和四年，太守范傳正、會稽釋靈澈同過旧院，就影堂傷悼彌久，遺題曰：）道安已返無何乡，慧远来過旧草堂。","余亦當时及门者，共吟佳句一焚香。","（《古今圖书集成·神異典》一六九《僧部列傳》引《高僧傳》）（见《宋高僧傳》卷二十九《唐湖州杼山皎然傳》。","「以貞元元年終山寺」，《宋高僧傳》作「以貞元年終山寺」。","據趙昌平考證，皎然約卒於貞元末。","）。"]', '诗', 'shi', '', NULL, '題皎然影堂 范傳正 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e35e787-92aa-453d-81ee-357d775f5fd0', '秋疾初愈月夜詠左思招隱詩因而成詠', '秋疾初愈月夜詠左思招隐诗因而成詠', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["閑吟理輕步，不厭凉夜詠。","斷續風際聲，清羸月中影。","螢光拂花露，泉脈連桐井。","心暢百慮銷，境條萬籟靜。","前賢有遺韻，顧我三日省。","朗懷方自怡，星河漸耿耿。"]', '["闲吟理轻步，不厭凉夜詠。","斷續风際声，清羸月中影。","螢光拂花露，泉脈連桐井。","心暢百慮銷，境條万籟静。","前賢有遺韻，顧我三日省。","朗懷方自怡，星河漸耿耿。"]', '诗', 'shi', '', NULL, '秋疾初愈月夜詠左思招隱詩因而成詠 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d756e2b0-4fb8-436f-ba12-1778b6e16f1b', '臥病初愈崔侍御相訪', '臥病初愈崔侍御相訪', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["移疾門常掩，今朝枉繡衣。","笑言之乍愜，拜伏力猶微。","晚歲貞筠少，貧家上客稀。","如何忽見訪，里巷有清輝。"]', '["移疾门常掩，今朝枉繡衣。","笑言之乍愜，拜伏力猶微。","晚歲貞筠少，貧家上客稀。","如何忽见訪，里巷有清輝。"]', '诗', 'shi', '', NULL, '臥病初愈崔侍御相訪 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013f7e88-6d59-48e5-9931-3ac310b902da', '夏雨率成呈邑中諸', '夏雨率成呈邑中諸', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["片雲飛暮雨，瀟灑小亭閑。","細響疎蕪裏，目涼坐臥間。","已深池際水，更綠枕前山。","未敢勞車馬，柴扉且閉關。"]', '["片云飞暮雨，瀟灑小亭闲。","細响疎蕪裏，目涼坐臥间。","已深池際水，更綠枕前山。","未敢勞车马，柴扉且閉关。"]', '诗', 'shi', '', NULL, '夏雨率成呈邑中諸 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d953c0-6b63-4a6d-bbf8-eaddef7408f3', '自咎', '自咎', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["自咎咎何窮，飄然蓽戶中。","清時名未立，稔歲室猶空。","幽獨慚芳桂，飛鳴羨早鴻。","出門何所見，歏息向秋風。","（以上《四部叢刊》影印大興氏刊本《權載之文集》一）。"]', '["自咎咎何窮，飄然蓽戶中。","清时名未立，稔歲室猶空。","幽独慚芳桂，飞鳴羨早鴻。","出门何所见，歏息向秋风。","（以上《四部叢刊》影印大兴氏刊本《權載之文集》一）。"]', '诗', 'shi', '', NULL, '自咎 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4063b2-a9e4-4dcb-bcaf-aca4f55a17dd', '題隱者所居', '題隐者所居', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["一逕茅茨下，千峯麋鹿羣。","鴻妻同懶逸，漁父每知聞。","旦暮鳥擇木，天陰山出雲。","此心終不動，鼓腹向堯君。","（同前七）。"]', '["一逕茅茨下，千峯麋鹿羣。","鴻妻同懶逸，漁父每知闻。","旦暮鸟擇木，天陰山出云。","此心終不动，鼓腹向堯君。","（同前七）。"]', '诗', 'shi', '', NULL, '題隱者所居 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2ea9bc-83ef-4cc3-982e-d7fbc770c5fd', '天竺寺', '天竺寺', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["香剎西天寺，昔遊夢中。","煙蘿迷俗駕，猿狖應山童。","蕭颯松靜，欹危石棧通。","雲霞棲半壁，丹紺照晴空。","世累悲何已，心期惜未同。","相看整歸騎，花雨夕洪濛濛。","（同前七）。"]', '["香剎西天寺，昔游梦中。","煙蘿迷俗駕，猿狖應山童。","蕭颯松静，欹危石棧通。","云霞棲半壁，丹紺照晴空。","世累悲何已，心期惜未同。","相看整归騎，花雨夕洪濛濛。","（同前七）。"]', '诗', 'shi', '', NULL, '天竺寺 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5bb0cb2-5835-4643-a969-68013ea49382', '貞元七年蒙恩除太常博士自江東來朝時與郡君同行西岳廟停東祝謁元和八年拜東都留守途次祠下追計前事已二十三年于茲矣時郡君以疾恙續發因代書却寄', '貞元七年蒙恩除太常博士自江东来朝时與郡君同行西岳廟停东祝謁元和八年拜东都留守途次祠下追計前事已二十三年于茲矣时郡君以疾恙續發因代书却寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["憶昔辛未歲，詔書下江酒濡。","盡室赴禮官，脂車雜輜軿。","行役過梁苑，淹留經圃田。","（郡君表姊壻元俯爲宣武從事，權理宋州，郡君從壻李融，時爲鄭州，各淹留累日。","）秦關信百二，征駕逾三千。","仙掌眺蓮峯，靈祠謁八天。","騶馭儼已駐，女巫爭來前。","動容既紛若，展敬方肅然。","（時爲女竺所導，過於恭敬，不能具舉。","）蹇步入國門，華簪拱祥烟。","諫曹迨居守，倐已十六遷。","及茲東乘轅，二十餘三年。","盛明受恩澤，清近皆聯翩。","忽當禮寺重，俄忝相印懸。","陳力才不任，乞骸詞頗堅。","解龜罷八鼎，賜劍猶要麼泉。","鄙夫何所能，實賴中饋賢。","談笑皆體遠，箴規諒才全。","拜恩理晨裝，詔使來駢闐。","風生鞍馬疾，日出旌旗鮮。","信宿歷道途，曩遊記周旋。","暫別亦不易，沉痾今未痊。","醫文驗桐君，道術依竺乾。","庶憑神明佑，得使疾恙蠲。","（醫工輔氏，深於藥術診切，大比丘尼優曇持念精至，並約同來，累路將護。","）永懷心如惔，引望脰已㾓。","離披夏雲盡，皎鏡秋月圓。","開緘諷色絲，撰日馳平肩。","延企勞夢寐，涕洟暗潺湲。","想君路經茲，還復申祝延。","攝拜奠清酤，相期保華顛。","遠慚周君較，聊擬顧彥先。","慇懃俟來報，淚墨書此篇。","（同前十）。"]', '["憶昔辛未歲，詔书下江酒濡。","尽室赴禮官，脂车杂輜軿。","行役過梁苑，淹留經圃田。","（郡君表姊壻元俯爲宣武從事，權理宋州，郡君從壻李融，时爲鄭州，各淹留累日。","）秦关信百二，征駕逾三千。","仙掌眺蓮峯，靈祠謁八天。","騶馭儼已駐，女巫爭来前。","动容既紛若，展敬方肅然。","（时爲女竺所導，過於恭敬，不能具舉。","）蹇步入国门，华簪拱祥烟。","諫曹迨居守，倐已十六遷。","及茲东乘轅，二十餘三年。","盛明受恩澤，清近皆聯翩。","忽當禮寺重，俄忝相印懸。","陳力才不任，乞骸词頗堅。","解龟罷八鼎，賜劍猶要麼泉。","鄙夫何所能，實賴中饋賢。","談笑皆體远，箴規諒才全。","拜恩理晨裝，詔使来駢闐。","风生鞍马疾，日出旌旗鲜。","信宿歷道途，曩游記周旋。","暫別亦不易，沉痾今未痊。","醫文驗桐君，道術依竺乾。","庶憑神明佑，得使疾恙蠲。","（醫工輔氏，深於藥術診切，大比丘尼優曇持念精至，並約同来，累路將護。","）永懷心如惔，引望脰已㾓。","離披夏云尽，皎镜秋月圓。","开緘諷色絲，撰日驰平肩。","延企勞梦寐，涕洟暗潺湲。","想君路經茲，還复申祝延。","攝拜奠清酤，相期保华顛。","远慚周君較，聊擬顧彥先。","慇懃俟来報，泪墨书此篇。","（同前十）。"]', '诗', 'shi', '', NULL, '貞元七年蒙恩除太常博士自江東來朝時與郡君同行西岳廟停東祝謁元和八年拜東都留守途次祠下追計前事已二十三年于茲矣時郡君以疾恙續發因代書却寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f922380-6012-4394-985b-801e256f6d2c', '漳州', '漳州', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["漳州悲遠道，龕留大業僧。","七年馳便路，三躡石梯層。","（《永樂大典》九七六四「歲」字韻引《恩平志》。","）。"]', '["漳州悲远道，龕留大業僧。","七年驰便路，三躡石梯層。","（《永乐大典》九七六四「歲」字韻引《恩平志》。","）。"]', '诗', 'shi', '', NULL, '漳州 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c02370b-c491-4056-94a9-c9fbd1376565', '秋夜館中醉後作', '秋夜館中醉後作', '4755852b-b3e1-4fbc-9cc8-497eb251d246', '唐', '["一葉驚風風已涼，華燈照夜夜何長。","閬山截雲不過雁，漲海浸日誰爲梁。","北向多虞劍戛戛，南中獨望天茫茫。","客亭遲還還復醉，醉裏狂歌歌更狂。","（同上一一三一三「館」字韻引《張燈集》）。"]', '["一葉驚风风已涼，华灯照夜夜何长。","閬山截云不過雁，漲海浸日誰爲梁。","北向多虞劍戛戛，南中独望天茫茫。","客亭遲還還复醉，醉裏狂歌歌更狂。","（同上一一三一三「館」字韻引《張灯集》）。"]', '诗', 'shi', '', NULL, '秋夜館中醉後作 張登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('686852eb-5daf-407c-a2bf-eb81fef09cfd', '賞牡丹（句）', '賞牡丹（句）', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["（唐文皇好詩，大和中賞牡丹，上謂程脩己曰：「今京邑人傳牡丹詩，誰爲首出？","」對曰：「中書舍人李正封詩天番云云。","」時楊妃侍，上曰：「妝臺前宜飲以一紫金盞酒，則正封之詩見矣。","」）天香夜染衣，國色朝酣酒。","（《唐詩紀事》四十）（見《松窗雜錄》。","）。"]', '["（唐文皇好诗，大和中賞牡丹，上謂程脩己曰：「今京邑人傳牡丹诗，誰爲首出？","」对曰：「中书舍人李正封诗天番云云。","」时楊妃侍，上曰：「妝台前宜饮以一紫金盞酒，則正封之诗见矣。","」）天香夜染衣，国色朝酣酒。","（《唐诗紀事》四十）（见《松窗杂錄》。","）。"]', '诗', 'shi', '', NULL, '賞牡丹（句） 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf18b84f-88a7-4d04-a7c0-6599cd14eb99', '峴山（句）', '峴山（句）', '73e7ca05-f35a-4db2-b9bb-a79ed4cdc7bd', '唐', '["峴山移柱石，流水輟恩波。","（《輿地紀勝》八二《襄陽府》）。"]', '["峴山移柱石，流水輟恩波。","（《輿地紀勝》八二《襄陽府》）。"]', '诗', 'shi', '', NULL, '峴山（句） 李正封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c48d4a-5264-438e-8198-861fdcd806e4', '九鯉湖', '九鯉湖', '2717562e-af42-40c5-bf30-c9df09585c30', '唐', '["道是燒丹地，依然雲水居。","山空人去後，夢醒客去初。","溪雨飛沙霽，巖門隱霧虛。","高歌對明月，松影落扶疎。","（《古今圖書集成·山川典》三○二《九鯉湖部》。"]', '["道是燒丹地，依然云水居。","山空人去後，梦醒客去初。","溪雨飞沙霽，巖门隐霧虛。","高歌对明月，松影落扶疎。","（《古今圖书集成·山川典》三○二《九鯉湖部》。"]', '诗', 'shi', '', NULL, '九鯉湖 許稷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bef5eb7-dfc3-4dc9-aa2e-eed2af51fae5', '', '', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0456205-941d-489e-8092-b51a6dc9ed21', '題杜工部墳', '題杜工部墳', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["何人鑿開混沌殼，二氣由來有清濁。","孕其清者爲聖賢，鍾其濁者成愚樸。","英豪雖沒名猶嘉，不肖虛死蓬麻。","榮華一旦世俗眼，忠孝萬古賢人芽。","有唐文物盛復全，名書史冊俱才賢。","中間詩筆誰清新？屈指都無四五人。","獨有工部稱全美，當日詩人無擬倫。","筆追清風洗俗耳，心奪造化回陽春。","天光晴射洞庭秋，寒玉萬頃清光流。","我常愛慕如饑渴，不見其面生閑愁。","今春偶客耒陽路，悽慘去尋江上墓。","召朋特地踏煙霧，路入溪村數百步。","招手借問騎牛兒，牧兒指我祠堂路。","入門古屋三四間，草茅緣砌生無數。","寒竹珊珊搖晚風，野蔓層層纏庭戶。","升堂再拜心惻然，心欲虔啓不成語。","一堆空土煙蕪裏，虛使詩人歎悲起。","怨聲千古寄西風，寒骨一夜沉秋水。","歸時處處多白酒，生肉如今家家有。","飲酒食肉今如此，何故常人無飽死？","子美歸日稱才賢，聶侯見待誠非喜。","洎乎聖意再搜求，姦臣以此欺天子。","捉月走入千丈波，忠諫便沉汩羅底。","固知天意有所存，三賢所歸同一水。","過客留詩千百人，佳詞繡句虛相美。","墳空飫死已傳聞，千古醜聲竟誰洗？","明時好古疾惡人，應以我意知終始。","（蔡夢弼《集注草堂杜工部詩外集酬唱附錄》引）（〖1〗蔡夢弼跋云：「此退之《題杜工部墳》，惟見於劉斧《摭遺小說》，韓昌黎正集無之，似非退之所作。","然大曆、元和，時之相去猶未爲遠，不歸與本集抵牾若是。","乃後之好事俗休儒託而爲之，以厚誣退之，決非退之所作也睄矣。","夢弼今謾錄於此，以備後人觀覽也。","」）。"]', '["何人鑿开混沌殼，二氣由来有清濁。","孕其清者爲聖賢，鍾其濁者成愚樸。","英豪雖沒名猶嘉，不肖虛死蓬麻。","榮华一旦世俗眼，忠孝万古賢人芽。","有唐文物盛复全，名书史冊俱才賢。","中间诗笔誰清新？屈指都無四五人。","独有工部稱全美，當日诗人無擬倫。","笔追清风洗俗耳，心奪造化回陽春。","天光晴射洞庭秋，寒玉万頃清光流。","我常愛慕如饑渴，不见其面生闲愁。","今春偶客耒陽路，悽慘去尋江上墓。","召朋特地踏煙霧，路入溪村數百步。","招手借问騎牛兒，牧兒指我祠堂路。","入门古屋三四间，草茅緣砌生無數。","寒竹珊珊搖晚风，野蔓層層纏庭戶。","升堂再拜心惻然，心欲虔啓不成語。","一堆空土煙蕪裏，虛使诗人歎悲起。","怨声千古寄西风，寒骨一夜沉秋水。","归时处处多白酒，生肉如今家家有。","饮酒食肉今如此，何故常人無飽死？","子美归日稱才賢，聶侯见待誠非喜。","洎乎聖意再搜求，姦臣以此欺天子。","捉月走入千丈波，忠諫便沉汩羅底。","固知天意有所存，三賢所归同一水。","過客留诗千百人，佳词繡句虛相美。","墳空飫死已傳闻，千古醜声竟誰洗？","明时好古疾惡人，應以我意知終始。","（蔡梦弼《集注草堂杜工部诗外集酬唱附錄》引）（〖1〗蔡梦弼跋云：「此退之《題杜工部墳》，惟见於劉斧《摭遺小说》，韓昌黎正集無之，似非退之所作。","然大曆、元和，时之相去猶未爲远，不归與本集抵牾若是。","乃後之好事俗休儒託而爲之，以厚誣退之，決非退之所作也睄矣。","梦弼今謾錄於此，以備後人观覽也。","」）。"]', '诗', 'shi', '', NULL, '題杜工部墳 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a0558a4-9f00-4e88-8bbd-77fa0143d246', '三傷頌', '三傷頌', '385232c9-2cec-40fd-8472-27b73b6cd01d', '唐', '["（斯五五五八卷錄此詩，題作「龍興寺香嚴和尚《嗟世三傷吟》」。","香嚴和尚法名智閑，青州人，住持鄧州香嚴山，梁乾化中卒。","《宜堂集》卷十九、《宋高僧傳》卷十三有傳。","該卷存前二首，其一爲「傷嗟啜刀鳥」，其三爲「傷嗟壘巢燕」，異文較多，校如次。","校文中均以「一作某」代指該卷。","）。"]', '["（斯五五五八卷錄此诗，題作「龙兴寺香嚴和尚《嗟世三傷吟》」。","香嚴和尚法名智闲，青州人，住持鄧州香嚴山，梁乾化中卒。","《宜堂集》卷十九、《宋高僧傳》卷十三有傳。","該卷存前二首，其一爲「傷嗟啜刀鸟」，其三爲「傷嗟壘巢燕」，異文較多，校如次。","校文中均以「一作某」代指該卷。","）。"]', '诗', 'shi', '', NULL, '三傷頌 伏牛上人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda65a40-8f31-4969-8866-59bb7b28a4ef', '三傷頌 其一', '三傷頌 其一', '385232c9-2cec-40fd-8472-27b73b6cd01d', '唐', '["傷嗟壘巢燕，雖巧無深見。","修營一箇窠，往復幾千轉。","雙飛碧水頭，對主動權虹梁畔。","身緣覓食疲，口爲銜泥爛。","驅馳九夏初，方產巢中卵。","（「產巢」，一作「有窠」。","）停騰怕饑渴，撫養知寒煖。","憐惜過於人，銜蟲餧皆徧。","（「餧」，一作「餵」）父爲理毛衣，母來將食饘（一作「眩」）。","一旦翅翼成，（「一旦」句，一作「一旦翅開便」。","）分飛不相管。","世有少智人，懇力憂家眷。","男女未成長，顏色已（一作「亦」）衰變。","（「顏色」，一作「容顏」。","）燕子燕子聽吾語，隨時且過休辛苦。","縱使窠中千箇兒，秋風纔動終須去。","（「秋風」句，一作「秋穴纔起皆飛去」。","）世人世人不要貪，（「貪」，一作「忙」。","）此言是藥思量取。","（「思量取」，一作「容思量」。","）饒你平生男女多，誰能伴歸泉路。","（「饒你」二句，一作「饒渠平生男女多，三塗惡業自須當」。","）。"]', '["傷嗟壘巢燕，雖巧無深见。","修營一箇窠，往复幾千轉。","雙飞碧水头，对主动權虹梁畔。","身緣覓食疲，口爲銜泥爛。","驱驰九夏初，方產巢中卵。","（「產巢」，一作「有窠」。","）停腾怕饑渴，撫養知寒煖。","怜惜過於人，銜蟲餧皆徧。","（「餧」，一作「餵」）父爲理毛衣，母来將食饘（一作「眩」）。","一旦翅翼成，（「一旦」句，一作「一旦翅开便」。","）分飞不相管。","世有少智人，懇力憂家眷。","男女未成长，顏色已（一作「亦」）衰变。","（「顏色」，一作「容顏」。","）燕子燕子听吾語，隨时且過休辛苦。","縱使窠中千箇兒，秋风纔动終須去。","（「秋风」句，一作「秋穴纔起皆飞去」。","）世人世人不要貪，（「貪」，一作「忙」。","）此言是藥思量取。","（「思量取」，一作「容思量」。","）饒你平生男女多，誰能伴归泉路。","（「饒你」二句，一作「饒渠平生男女多，三塗惡業自須當」。","）。"]', '诗', 'shi', '', NULL, '三傷頌 其一 伏牛上人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df253614-9565-4ade-91cc-b08e5e45c08e', '三傷頌 其二', '三傷頌 其二', '385232c9-2cec-40fd-8472-27b73b6cd01d', '唐', '["傷嗟鵽刀鳥，夜夜啼天曉。","墜翼柳攀枝，（「柳」，一作「脚」。","）身隨露葉低，影逐風枝裊。","一種情相生，爾獨何枯槁。","（「一種」二句，一作「一種情想生，尔何獨枯栲」。","）驅驅飲啄稀，役役飛騰少。","不是官所差，都緣業所造。","（「都緣」句，一作「有緣業力造」。","）亦似世間人，貪生不覺老。","喫著能幾多，强自縈煩惱。","咄絡無眼人，（「無眼人」，一作「無眠人」。","）織絡何時了。","只爲一六迷，遂成十二到。","（「到」，一作「倒」。","）{歠欠=鳥}刀{歠欠=鳥}刀林裏叫，（「叫」，一作「啼」。","）山僧山僧床上笑。","有人會意解推尋，不假三祇便成道。","（「有人」二句，一作「有人會意解推尋，不歷僧祗便成道」。","）。"]', '["傷嗟鵽刀鸟，夜夜啼天晓。","墜翼柳攀枝，（「柳」，一作「脚」。","）身隨露葉低，影逐风枝裊。","一種情相生，爾独何枯槁。","（「一種」二句，一作「一種情想生，尔何独枯栲」。","）驱驱饮啄稀，役役飞腾少。","不是官所差，都緣業所造。","（「都緣」句，一作「有緣業力造」。","）亦似世间人，貪生不覺老。","喫著能幾多，强自縈煩惱。","咄絡無眼人，（「無眼人」，一作「無眠人」。","）织絡何时了。","只爲一六迷，遂成十二到。","（「到」，一作「倒」。","）{歠欠=鸟}刀{歠欠=鸟}刀林裏叫，（「叫」，一作「啼」。","）山僧山僧床上笑。","有人會意解推尋，不假三祇便成道。","（「有人」二句，一作「有人會意解推尋，不歷僧祗便成道」。","）。"]', '诗', 'shi', '', NULL, '三傷頌 其二 伏牛上人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c085bc47-1a2f-43d9-93f5-6c8d6ce5f67a', '三傷頌 其三', '三傷頌 其三', '385232c9-2cec-40fd-8472-27b73b6cd01d', '唐', '["傷嗟造蜜蜂，忙忙採花蘂。","接翼入芳業，分頭傍煙水。","抱蘂唼香滋，尋花戀春餌。","驅馳如有縈，盤旋若遭魅。","蹭蹬遇絲羅，飄零餵螻蟻。","才能翅翼成，方始窠巢備。","惡人把火燒，哀鳴樹中死。","蜜是他人將，美是他人美。","虛忙百草頭，於身有何利。","世有少智人，與此恰相似。","只緣貪愛牽，幾度虛沈墜。","夏日歲處浮生，十年作童稚。","一半悲與愁，一半病與悴。","除折算將來，能得幾多子。","更將有漏身，自翳無生理。","永不見如來，都緣開眼睡。","蜜蜂蜜蜂休役役，空哉終是他人喫。","世人世人不要貪，留富他人有何益。"]', '["傷嗟造蜜蜂，忙忙採花蘂。","接翼入芳業，分头傍煙水。","抱蘂唼香滋，尋花戀春餌。","驱驰如有縈，盤旋若遭魅。","蹭蹬遇絲羅，飄零餵螻蟻。","才能翅翼成，方始窠巢備。","惡人把火燒，哀鳴樹中死。","蜜是他人將，美是他人美。","虛忙百草头，於身有何利。","世有少智人，與此恰相似。","只緣貪愛牽，幾度虛沈墜。","夏日歲处浮生，十年作童稚。","一半悲與愁，一半病與悴。","除折算將来，能得幾多子。","更將有漏身，自翳無生理。","永不见如来，都緣开眼睡。","蜜蜂蜜蜂休役役，空哉終是他人喫。","世人世人不要貪，留富他人有何益。"]', '诗', 'shi', '', NULL, '三傷頌 其三 伏牛上人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2c4bfae-f03c-4af0-8371-d642058a6599', '一鉢歌', '一鉢歌', '21d7a943-6ffa-4589-9201-235b323c6361', '唐', '["阿剌剌，鬧聒聒，總是悠悠造末撻。","（「阿」，《大正藏》本《景德傳燈錄》〖以下簡稱「一作」〗卷三十作「遏」。","「末撻」，一作「抹㒓」）如饑喫監加得渴，枉却一生頭戛戛。","（「戛戛」，一作「枿枿」。","）究竟不能知本末，（「本末」，一作「始末」。","）拋却死屍何處脫。","閑事到頭須結撮，火落身上當頭撥。","（「頭」，一作「須」。","）莫待臨時叫菩薩，大丈夫兒須豁豁。","（「大丈夫兒」，一作「丈夫語話」。","）莫學癡人受摩捋，也繫裏，也擺撥，（「也繫裏」二句，一作「趁時結裏學擺撥」。","）也學柔和也粗糲，亦解剃頭亦披褐，（「亦解」句，一作「也剃頭，也披褐」。","）也學凡夫作生活。","直言向君君未達，（「直言」，一作「直語」。","）更作長歌歌一鉢。","多中少，少中多，（「多中少」二句，一作「一鉢歌，多中一，一中多」。","）莫笑野人一鉢歌，緣持此鉢度婆娑。","（「一鉢歌」，一作「歌一鉢」。","「緣持此鉢」，一作「曾將一鉢」。","）青天寥寥月初上，此時境空含萬象。","（「境空」，一作「影空」。","）幾處浮生自是非，一源清潔無來往。","（「清潔」，一作「清淨」。","）莫謾將心學水泡，百毛流火無事交。","（「莫謾」二句，一作「更莫將心造水泡，百毛流血是誰教」。","）不如靜坐真如地，頭上從他鵲作巢。","（「頭」，一作「頂」。","）萬代金輪聖王子，只這真如靈覺是。","菩提樹下度衆生，度盡生不生死。","真丈夫，（「真丈夫」，一作「不生不死真丈夫」。","）無形無相大毘盧。","塵勞滅盡真如在，一顆圓明無價珠。","眼不見，耳不聞，無見無聞無不聞。","（「無見」句，一作「不見不聞真見聞」。","）從來一鉢無言說，（「一鉢」，一作「一句」。","）今日千言强爲分。","强爲分，須諦聽，人人總有真如性。","（「總」，一作「盡」。","）恰似黃金在鑛中，鍊去金砂金體淨。","（「金砂」，一作「鍊來」。","）真是妄，妄是真，爲求真妄更無人。","（「爲求」，一作「若除」。","）將心不用生煩惱，（「將心不用」，一作「真心莫謾」。","）衣食隨時養色身。","好也著，惡也著，一切不貪無染著。","（「惡」，一作「弱」。","「不貪」，一作「無心」。","）亦無惡，亦無好，一際坦然平等道。","（「一」，一作「二」。","）粗亦飡，莫學凡夫相上看。","（「看」，一作「觀」。","）亦無粗，亦無細，（「亦」，一作「也」。","）上方香積無根蒂。","坐亦行，行亦坐，坐死樹是菩提果。","（坐」，一作「生」。","一本此下多「亦無坐，亦無行，無生何用覓無生。","生亦得，死亦得，處處當來見彌勒」六句。","）亦無生，亦無死，三世如來總如此。","離即著，著即離，實相門中無實義。","（「即」，一作「則」。","「實相」，一作「幻化」。","）不可離，不可著，何處更求治病藥。","（「不」，一作「無」。","「治」，一作「無」。","）語時默，默時語，語默尋蹤無定所。","（「尋蹤」，一作「縱橫」。","「定」，一作「處」。","）亦無語，亦無默，莫喚東西作南北。","嗔時喜，喜時嗔，（「時」，一作「即」。","）我自降魔轉法輪。","亦無嗔，亦無喜，水不離波波是水。","（「是」，一作「即」。","）慳時捨，捨時慳，不離內外與中間。","（「與」，一作「及」。","）亦無慳，亦無捨，寂寂寥寥無可把。","苦時樂，樂時苦，只箇修行斷門戶。","（「箇」，一作「遮」。","）亦無苦，亦無樂，本來自性無纏縛。","（「本來自在無繩索」。","）垢即淨，淨即垢，兩邊惡境無關於後。","（「惡境」，一作「畢竟」。","）亦無垢，亦無淨，大千同一真如性。","藥是病，病是藥，到頭兩事渾捻（一作「忘」）却。","（「渾」，一作「須」。","）亦無藥，亦無病。","正是真如靈覺性。","魔是佛。","佛是魔，如影隨形水上波。","（「是」，一作「作」。","「如影隨形」，一作「鏡裏尋形」。","）亦無魔，亦無佛，三界比來無一物。","（「三界比來」，一作「三世本來」。","）凡即聖，聖即凡，色裏膠清水裏鹹。","亦無凡，亦無聖，萬行掃除無一行。","（「掃除」，一作「總持」。","）真中假，假中真，自是凡起惡塵。","（「惡」，一作「妄」。","）亦無真，亦無假，若不呼時誰應者。","（「若不」句，一作「若不喚時何應諾」。","）本無姓，本無名，（「本無姓」，一作「本來無姓」。","）只麼騰騰信脚行。","有時市鄽（一作「井」）幷屠肆，一葉蓮花火上生。","（「一葉蓮花」，一作「一朶紅蓮」。","）也曾策杖遊京洛，身似浮雲無住著。","（「住」，一作「定」。","）究竟從來是寄居，他方處處無纏縛。","（「究竟」二句，一作「幻化由來似寄居，他家觸處更清虛」。","）若覓戒，三毒藥病何時瘥；（「藥病何」，一作「瘡痍幾」。","）若覓禪，我自縱橫大可憐。","不是狂，不是顛，在世間中出世間。","（「我自」四句，一作「我自縱橫汩碖眠。","大可憐，不是顛，世間出世天中天」。","）時人不會此中意，打著南邊與北邊。","（「與」，一作「動」。","）若覓法，雞足山頭問迦葉。","見說傳衣在彼中，無心不用求某甲。","（「見說」二句，一作「大士持衣在此中，本來不用求專甲。","若覓經，法性真源無可聽。","若覓律，窮子不須教走出」，凡六匔。","）若覓修，八萬浮圖何處求。","只知黃葉上啼哭，（「上」，一作「止」。","）不覺黑雲遮日頭。","莫怪狂言無次第，篩羅漸入粗中細。","只這粗中細。","只這粗中細也無，即是圓明真實諦。","亦無真，但有名聞即是塵。","（「亦無真」，一作「真實諦，本非真」。","「有」，一作「是」。","）若向塵中解真實，便是當來出世人。","（「當來」，一作「堂堂」。","）無造作，獨行獨坐空索索。","（「無造作」，一作「出世人，莫造作」。","「坐」，一作「步」。","）無湼槃，（「無湼槃」，一作「無生無死無湼槃」。","）本來生死不相干。","直須省，（「直須省」，一作「無是非，無動靜」。","）莫謾將身入空井。","無去也無來，明鏡掛高臺。","（「無去」二句，一作「無善惡，無去來，亦無明鏡掛高臺」。","）儂家見解只如此，不用將心算劫灰。","（「儂家」，一作「山僧」。","「不用」句，一作「不信從他造劫灰」。","）（以上《鑑誡錄》十《高僧諭》）。"]', '["阿剌剌，鬧聒聒，總是悠悠造末撻。","（「阿」，《大正藏》本《景德傳灯錄》〖以下簡稱「一作」〗卷三十作「遏」。","「末撻」，一作「抹㒓」）如饑喫監加得渴，枉却一生头戛戛。","（「戛戛」，一作「枿枿」。","）究竟不能知本末，（「本末」，一作「始末」。","）拋却死屍何处脫。","闲事到头須結撮，火落身上當头撥。","（「头」，一作「須」。","）莫待臨时叫菩薩，大丈夫兒須豁豁。","（「大丈夫兒」，一作「丈夫語話」。","）莫学癡人受摩捋，也繫裏，也擺撥，（「也繫裏」二句，一作「趁时結裏学擺撥」。","）也学柔和也粗糲，亦解剃头亦披褐，（「亦解」句，一作「也剃头，也披褐」。","）也学凡夫作生活。","直言向君君未達，（「直言」，一作「直語」。","）更作长歌歌一鉢。","多中少，少中多，（「多中少」二句，一作「一鉢歌，多中一，一中多」。","）莫笑野人一鉢歌，緣持此鉢度婆娑。","（「一鉢歌」，一作「歌一鉢」。","「緣持此鉢」，一作「曾將一鉢」。","）青天寥寥月初上，此时境空含万象。","（「境空」，一作「影空」。","）幾处浮生自是非，一源清潔無来往。","（「清潔」，一作「清淨」。","）莫謾將心学水泡，百毛流火無事交。","（「莫謾」二句，一作「更莫將心造水泡，百毛流血是誰教」。","）不如静坐真如地，头上從他鵲作巢。","（「头」，一作「頂」。","）万代金輪聖王子，只這真如靈覺是。","菩提樹下度衆生，度尽生不生死。","真丈夫，（「真丈夫」，一作「不生不死真丈夫」。","）無形無相大毘盧。","塵勞滅尽真如在，一顆圓明無價珠。","眼不见，耳不闻，無见無闻無不闻。","（「無见」句，一作「不见不闻真见闻」。","）從来一鉢無言说，（「一鉢」，一作「一句」。","）今日千言强爲分。","强爲分，須諦听，人人總有真如性。","（「總」，一作「尽」。","）恰似黄金在鑛中，鍊去金砂金體淨。","（「金砂」，一作「鍊来」。","）真是妄，妄是真，爲求真妄更無人。","（「爲求」，一作「若除」。","）將心不用生煩惱，（「將心不用」，一作「真心莫謾」。","）衣食隨时養色身。","好也著，惡也著，一切不貪無染著。","（「惡」，一作「弱」。","「不貪」，一作「無心」。","）亦無惡，亦無好，一際坦然平等道。","（「一」，一作「二」。","）粗亦飡，莫学凡夫相上看。","（「看」，一作「观」。","）亦無粗，亦無細，（「亦」，一作「也」。","）上方香積無根蒂。","坐亦行，行亦坐，坐死樹是菩提果。","（坐」，一作「生」。","一本此下多「亦無坐，亦無行，無生何用覓無生。","生亦得，死亦得，处处當来见彌勒」六句。","）亦無生，亦無死，三世如来總如此。","離即著，著即離，實相门中無實義。","（「即」，一作「則」。","「實相」，一作「幻化」。","）不可離，不可著，何处更求治病藥。","（「不」，一作「無」。","「治」，一作「無」。","）語时默，默时語，語默尋蹤無定所。","（「尋蹤」，一作「縱橫」。","「定」，一作「处」。","）亦無語，亦無默，莫喚东西作南北。","嗔时喜，喜时嗔，（「时」，一作「即」。","）我自降魔轉法輪。","亦無嗔，亦無喜，水不離波波是水。","（「是」，一作「即」。","）慳时捨，捨时慳，不離內外與中间。","（「與」，一作「及」。","）亦無慳，亦無捨，寂寂寥寥無可把。","苦时乐，乐时苦，只箇修行斷门戶。","（「箇」，一作「遮」。","）亦無苦，亦無乐，本来自性無纏縛。","（「本来自在無繩索」。","）垢即淨，淨即垢，兩邊惡境無关於後。","（「惡境」，一作「畢竟」。","）亦無垢，亦無淨，大千同一真如性。","藥是病，病是藥，到头兩事渾捻（一作「忘」）却。","（「渾」，一作「須」。","）亦無藥，亦無病。","正是真如靈覺性。","魔是佛。","佛是魔，如影隨形水上波。","（「是」，一作「作」。","「如影隨形」，一作「镜裏尋形」。","）亦無魔，亦無佛，三界比来無一物。","（「三界比来」，一作「三世本来」。","）凡即聖，聖即凡，色裏膠清水裏鹹。","亦無凡，亦無聖，万行掃除無一行。","（「掃除」，一作「總持」。","）真中假，假中真，自是凡起惡塵。","（「惡」，一作「妄」。","）亦無真，亦無假，若不呼时誰應者。","（「若不」句，一作「若不喚时何應諾」。","）本無姓，本無名，（「本無姓」，一作「本来無姓」。","）只麼腾腾信脚行。","有时市鄽（一作「井」）幷屠肆，一葉蓮花火上生。","（「一葉蓮花」，一作「一朶紅蓮」。","）也曾策杖游京洛，身似浮云無住著。","（「住」，一作「定」。","）究竟從来是寄居，他方处处無纏縛。","（「究竟」二句，一作「幻化由来似寄居，他家觸处更清虛」。","）若覓戒，三毒藥病何时瘥；（「藥病何」，一作「瘡痍幾」。","）若覓禪，我自縱橫大可怜。","不是狂，不是顛，在世间中出世间。","（「我自」四句，一作「我自縱橫汩碖眠。","大可怜，不是顛，世间出世天中天」。","）时人不會此中意，打著南邊與北邊。","（「與」，一作「动」。","）若覓法，雞足山头问迦葉。","见说傳衣在彼中，無心不用求某甲。","（「见说」二句，一作「大士持衣在此中，本来不用求專甲。","若覓經，法性真源無可听。","若覓律，窮子不須教走出」，凡六匔。","）若覓修，八万浮圖何处求。","只知黄葉上啼哭，（「上」，一作「止」。","）不覺黑云遮日头。","莫怪狂言無次第，篩羅漸入粗中細。","只這粗中細。","只這粗中細也無，即是圓明真實諦。","亦無真，但有名闻即是塵。","（「亦無真」，一作「真實諦，本非真」。","「有」，一作「是」。","）若向塵中解真實，便是當来出世人。","（「當来」，一作「堂堂」。","）無造作，独行独坐空索索。","（「無造作」，一作「出世人，莫造作」。","「坐」，一作「步」。","）無湼槃，（「無湼槃」，一作「無生無死無湼槃」。","）本来生死不相干。","直須省，（「直須省」，一作「無是非，無动静」。","）莫謾將身入空井。","無去也無来，明镜掛高台。","（「無去」二句，一作「無善惡，無去来，亦無明镜掛高台」。","）儂家见解只如此，不用將心算劫灰。","（「儂家」，一作「山僧」。","「不用」句，一作「不信從他造劫灰」。","）（以上《鑑誡錄》十《高僧諭》）。"]', '诗', 'shi', '', NULL, '一鉢歌 一鉢和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03e23082-8019-4cb3-b414-3c8d2a389bfc', '靈岩洞', '靈岩洞', '06ccb9a6-28c7-4727-a61a-7d729109d8e7', '唐', '["一灣溪水出岩泉，前洞沉沉後洞連。","可惜秦人不曾到，空留名蹟在桃川。","（《古今圖書集成·職方典》一二六二《常德府部》）。"]', '["一灣溪水出岩泉，前洞沉沉後洞連。","可惜秦人不曾到，空留名蹟在桃川。","（《古今圖书集成·職方典》一二六二《常德府部》）。"]', '诗', 'shi', '', NULL, '靈岩洞 蔣防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('494b0906-60eb-4540-a689-4b1fa24aaaf8', '瀑布泉', '瀑布泉', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["時出西郊霽色開，尋真欲去重徘徊。","風泉净洗高人耳，松柏化爲君子材。","翠巘絶高尖插漢，碧潭無底攪轟雷。","上盤下際非凡境，箇裏何曾俗客來。","（《正德南康府志》十《詩類》）。"]', '["时出西郊霽色开，尋真欲去重徘徊。","风泉净洗高人耳，松柏化爲君子材。","翠巘絶高尖插漢，碧潭無底攪轟雷。","上盤下際非凡境，箇裏何曾俗客来。","（《正德南康府志》十《诗類》）。"]', '诗', 'shi', '', NULL, '瀑布泉 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f3c1e4a-1ced-416c-9a14-fac27e879354', '虎丘西寺', '虎丘西寺', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["吳王冠劍作塵埃，葬地翻爲七寶臺。","石砌百□光似鏡，井輪千轉響成雷。","昔年棣萼聯枝發，今日蓮宮並蒂開。","更有女郎墳在此，時時雲雨試僧來。","（康熙顧《虎丘志》三《寺字》）。"]', '["吳王冠劍作塵埃，葬地翻爲七寶台。","石砌百□光似镜，井輪千轉响成雷。","昔年棣萼聯枝發，今日蓮宮並蒂开。","更有女郎墳在此，时时云雨試僧来。","（康熙顧《虎丘志》三《寺字》）。"]', '诗', 'shi', '', NULL, '虎丘西寺 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3d9a52b-3056-44a5-a14a-defe59effd40', '恩賜耆老布帛（《文苑英華》一八○《省試》）', '恩賜耆老布帛（《文苑英华》一八○《省試》）', '147859af-f651-42c1-be56-4838c23e962c', '唐', '["空（《全唐詩》三一九作崔樞詩。","第二句「賑黎元」《文苑英華》作「軫玄元」，第三句「生涯作」作「生成在」，第七句「泰」作「太」，第八句「沾」作「澹」。","）。"]', '["空（《全唐诗》三一九作崔樞诗。","第二句「賑黎元」《文苑英华》作「軫玄元」，第三句「生涯作」作「生成在」，第七句「泰」作「太」，第八句「沾」作「澹」。","）。"]', '诗', 'shi', '', NULL, '恩賜耆老布帛（《文苑英華》一八○《省試》） 張復元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d004fd4-ad1c-4655-b2be-a2a5ee2609ce', '過華山（句）（《全唐詩》四八四作楊虞卿句）', '過华山（句）（《全唐诗》四八四作楊虞卿句）', '37e1c79a-da9e-41d6-ab62-8b253a64dfd9', '唐', '["（《雲谿友議》卷中《中山誨》云：「楊危〖應作茂〗卿配校書《過華山》詩曰〖見下〗。","此句實爲佳對。","又《唐語林》二《文學》，劉禹錫茂卿云。","〖見下〗此詩題云《過華山下作》。","而用蓮蓬之菡萏。","極的當而暗靜矣。","」）河勢崑崙遠，山形菡萏秋。","（《唐詩紀事》三九）。"]', '["（《云谿友議》卷中《中山誨》云：「楊危〖應作茂〗卿配校书《過华山》诗曰〖见下〗。","此句實爲佳对。","又《唐語林》二《文学》，劉禹錫茂卿云。","〖见下〗此诗題云《過华山下作》。","而用蓮蓬之菡萏。","極的當而暗静矣。","」）河勢崑崙远，山形菡萏秋。","（《唐诗紀事》三九）。"]', '诗', 'shi', '', NULL, '過華山（句）（《全唐詩》四八四作楊虞卿句） 楊茂卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('236becaf-9ae6-4afc-8297-280df8d8e870', '觀音巖', '观音巖', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["巖洞分明是普陀，和風甘雨向來多。","空山寂寞香燈少，蓮坐春雲長薜蘿。","（《古今圖書集·職方典》七八五《安慶府部》）。"]', '["巖洞分明是普陀，和风甘雨向来多。","空山寂寞香灯少，蓮坐春云长薜蘿。","（《古今圖书集·職方典》七八五《安慶府部》）。"]', '诗', 'shi', '', NULL, '觀音巖 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab411d4-398d-4046-ae47-b78e647a69df', '虎丘寺', '虎丘寺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["望月登樓海氣昏，劍池無底浸雲根。","老僧只怕山移去，日暮先教鎖寺門。","（康熙顧湄《虎丘志》三《寺字》）。"]', '["望月登楼海氣昏，劍池無底浸云根。","老僧只怕山移去，日暮先教鎖寺门。","（康熙顧湄《虎丘志》三《寺字》）。"]', '诗', 'shi', '', NULL, '虎丘寺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705043d3-fbbb-43a1-93ec-e4a96fc5f474', '白門前', '白门前', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["白門前，大樓喜，懸虹雲，撻龍尾。","劍破匣，舞蛟龍，蚩尤死，鼓龍蓬。","天墮地，無驚飛，海千里。","（《四部業刊》影印所以刊本《李賀歌詩編》）（此詩爲《全唐詩》卷三九三李賀《上之回》一詩之別本，前八句僅數字不同，末四句，《上之回》爲七言二句。","）。"]', '["白门前，大楼喜，懸虹云，撻龙尾。","劍破匣，舞蛟龙，蚩尤死，鼓龙蓬。","天墮地，無驚飞，海千里。","（《四部業刊》影印所以刊本《李賀歌诗編》）（此诗爲《全唐诗》卷三九三李賀《上之回》一诗之別本，前八句僅數字不同，末四句，《上之回》爲七言二句。","）。"]', '诗', 'shi', '', NULL, '白門前 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e2edea-796a-42d3-b54a-63a90a0bcd79', '落葉', '落葉', '0a6d7131-b48b-4828-9416-6f9511d024f8', '唐', '["返蟻難尋穴，歸禽易見窠。","滿廊僧不厭，一片俗嫌多。","（《詩話總亀後集》三八《詼諧門》（此詩出《苕溪漁歌隱業話前集》卷五五《宋朝雜記下》，作者作劉義。","《詩人玉屑》卷三引《冷斎夜話》、《詩林廣記》卷二引《古今詩話》均以爲鄭谷詩，未詳孰是。","「劉乂」，輯者意當指劉叉、乂、義相淆者較多，但此詩是否劉叉作，恐尚難確定。","）。"]', '["返蟻难尋穴，归禽易见窠。","满廊僧不厭，一片俗嫌多。","（《诗話總亀後集》三八《詼諧门》（此诗出《苕溪漁歌隐業話前集》卷五五《宋朝杂記下》，作者作劉義。","《诗人玉屑》卷三引《冷斎夜話》、《诗林廣記》卷二引《古今诗話》均以爲鄭谷诗，未詳孰是。","「劉乂」，輯者意當指劉叉、乂、義相淆者較多，但此诗是否劉叉作，恐尚难確定。","）。"]', '诗', 'shi', '', NULL, '落葉 劉乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8817723-0ce0-4458-a949-8559a7ec0a4c', '黃鶴樓', '黄鹤楼', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["高檻危簷勢若飛，孤雲野水共依依。","青山萬古長如舊，黃鶴何年去不歸。","岸映西山（一作「州」）城半山，烟生南浦樹將微。","定知羽客無因見，空使含情對落暉。","（《古今圖書集成·職方典》一一二五《武昌府部》（民國《湖北通志》卷一○一《金石》九錄《鄂州雜詩碑》，分五層，錄謝朓及唐人詩三十九首，其中即賈島此詩及本書後錄之盧郢詩。","碑署「熙寧二年六月□日額立」，不著書人姓名，清代尚存於黃鶴樓後斗姥閣西壁。","）。"]', '["高檻危簷勢若飞，孤云野水共依依。","青山万古长如旧，黄鹤何年去不归。","岸映西山（一作「州」）城半山，烟生南浦樹將微。","定知羽客無因见，空使含情对落暉。","（《古今圖书集成·職方典》一一二五《武昌府部》（民国《湖北通志》卷一○一《金石》九錄《鄂州杂诗碑》，分五層，錄謝朓及唐人诗三十九首，其中即賈島此诗及本书後錄之盧郢诗。","碑署「熙寧二年六月□日額立」，不著书人姓名，清代尚存於黄鹤楼後斗姥閣西壁。","）。"]', '诗', 'shi', '', NULL, '黃鶴樓 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76034a1b-1950-4595-bfb1-a98a1952f883', '留題南趙古廟', '留題南趙古廟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["鱗鵕老樹鐵生斑，神宇荒涼野壑閒。","地僻無人秋寂寂，一川紅影夕陽間。","（同上三○五《太原府部》）。"]', '["鱗鵕老樹鐵生斑，神宇荒涼野壑閒。","地僻無人秋寂寂，一川紅影夕陽间。","（同上三○五《太原府部》）。"]', '诗', 'shi', '', NULL, '留題南趙古廟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c9833b-733b-4cda-a981-67a556a190c6', '虎丘千人坐（又名千人石）', '虎丘千人坐（又名千人石）', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["上陟千人從，低窺百尺松。","碧池藏寶劍，寒澗宿潛龍。","（康熙顧湄《虎邱志》二《泉石》）。"]', '["上陟千人從，低窺百尺松。","碧池藏寶劍，寒澗宿潛龙。","（康熙顧湄《虎邱志》二《泉石》）。"]', '诗', 'shi', '', NULL, '虎丘千人坐（又名千人石） 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743489e7-44a6-4688-8aef-a89d92d36b95', '題安業縣', '題安業縣', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一山未了一山迎，百里都無半里平。","宜是老禪遙指處，只堪圖畫不堪行。","（《關中勝蹟圖志》二五《商州地理》）。"]', '["一山未了一山迎，百里都無半里平。","宜是老禪遙指处，只堪圖畫不堪行。","（《关中勝蹟圖志》二五《商州地理》）。"]', '诗', 'shi', '', NULL, '題安業縣 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531622e6-d628-4286-bf64-a87952c34f3f', '貢茶唱和（句）', '貢茶唱和（句）', '200c552c-1130-45ab-ba7b-42ac8cdd5299', '唐', '["（金沙池泉，在常州宜興縣罨畫溪之東，有寺，寺有碑，載當時杭、湖、常三州貢茶唱和，樂天云：「十隻畫船何處宿？","洞庭山脚太湖心。","」常州太守，忘其姓名，和云。","○今按：白居易二句見《全唐詩》四四七卷《宿湖中》一詩。","同卷有《赴蘇州至常州答賈舍人》。","及《自到郡齋僅旬日方專公務未及宴遊偷閒走筆題二十四韻兼寄常州賈舍人湖州崔郎中仍呈吳中諸客》各詩，知常州太守即賈餗。","）殷勤爲報春風道，不貢新茶只貢心。","（《詩話總龜》三四《紀夢門》）。"]', '["（金沙池泉，在常州宜兴縣罨畫溪之东，有寺，寺有碑，載當时杭、湖、常三州貢茶唱和，乐天云：「十隻畫船何处宿？","洞庭山脚太湖心。","」常州太守，忘其姓名，和云。","○今按：白居易二句见《全唐诗》四四七卷《宿湖中》一诗。","同卷有《赴蘇州至常州答賈舍人》。","及《自到郡斋僅旬日方專公務未及宴游偷閒走笔題二十四韻兼寄常州賈舍人湖州崔郎中仍呈吳中諸客》各诗，知常州太守即賈餗。","）殷勤爲報春风道，不貢新茶只貢心。","（《诗話總龟》三四《紀梦门》）。"]', '诗', 'shi', '', NULL, '貢茶唱和（句） 賈餗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e938cb80-61ae-4b92-bc06-c3fea0fd6776', '李娃行（句）', '李娃行（句）', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["平常不是堆珠玉，難得門前暫徘徊。","（任淵《後山詩註》二《徐氏閑軒》注引）玉顏婷婷階（原誤作「街」）下立。","（同上《黃梅五首》之三注引）。"]', '["平常不是堆珠玉，难得门前暫徘徊。","（任淵《後山诗註》二《徐氏闲軒》注引）玉顏婷婷階（原誤作「街」）下立。","（同上《黄梅五首》之三注引）。"]', '诗', 'shi', '', NULL, '李娃行（句） 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('662e7685-5c70-4190-841c-810f66d99ea4', '送沈倉曹赴江西', '送沈倉曹赴江西', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["落日驅單騎，涼風換袷衣。","遠魚傳信至，秋雁趁行飛。","洛下閑居住，城東醉伴稀。","莫辭船舫重，多覓酒錢歸。","（《白氏長慶集》五九《三教論衡》）。"]', '["落日驱單騎，涼风換袷衣。","远鱼傳信至，秋雁趁行飞。","洛下闲居住，城东醉伴稀。","莫辞船舫重，多覓酒錢归。","（《白氏长慶集》五九《三教論衡》）。"]', '诗', 'shi', '', NULL, '送沈倉曹赴江西 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30b4055e-b978-472c-8623-0b4248091b60', '東山寺（在黃梅縣）', '东山寺（在黄梅縣）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["直上青霄望八都，白雲影裏月輪孤。","茫茫宇宙人無數，幾箇男兒是丈夫。","（《弘治黃州府志》七《藝文》）（曹汛謂《全唐詩》卷八五八呂巖《絶句》三十二首之十四，後二句與此全同，前句稍異，作白詩疑誤。","）。"]', '["直上青霄望八都，白云影裏月輪孤。","茫茫宇宙人無數，幾箇男兒是丈夫。","（《弘治黄州府志》七《藝文》）（曹汛謂《全唐诗》卷八五八呂巖《絶句》三十二首之十四，後二句與此全同，前句稍異，作白诗疑誤。","）。"]', '诗', 'shi', '', NULL, '東山寺（在黃梅縣） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9aa7f4-583a-4c17-a2b9-aa63e1625faf', '句（《全唐詩》七八四作織錦人「如今」句。「士」《白香山詩集·補遺》作「事」○汪立名輯《白香山詩集·補遺》）', '句（《全唐诗》七八四作织錦人「如今」句。「士」《白香山诗集·補遺》作「事」○汪立名輯《白香山诗集·補遺》）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空（〖1〗《盧氏雜話》云：盧氏子合下第，步出都門，投逆旅。","有一人續至。","吟詩云云。","盧愕然，憶是白居易詩，問之，曰：）（「某世織綾錦，以薄藝投本行，皆云如今花樣與前不同，且東歸去。","」〖2〗此段出《太平廣記》卷二五七引《盧氏雜說》，汪氏所引爲節文。","）。"]', '["空（〖1〗《盧氏杂話》云：盧氏子合下第，步出都门，投逆旅。","有一人續至。","吟诗云云。","盧愕然，憶是白居易诗，问之，曰：）（「某世织綾錦，以薄藝投本行，皆云如今花樣與前不同，且东归去。","」〖2〗此段出《太平廣記》卷二五七引《盧氏杂说》，汪氏所引爲節文。","）。"]', '诗', 'shi', '', NULL, '句（《全唐詩》七八四作織錦人「如今」句。「士」《白香山詩集·補遺》作「事」○汪立名輯《白香山詩集·補遺》） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3cd31ec-1767-4086-b419-55b64aee3f49', '漢文帝母薄太后廟賦詩', '漢文帝母薄太后廟賦诗', 'de627c39-c31e-4b7c-802f-80e543334355', '唐', '["香風引上大羅天，月地花宮拜洞仙。","具道人間惆悵事，不知今夕是何年。","（《唐詩紀事》二九引《周秦行紀》（《周秦行紀》，一般認爲是李黨託牛僧孺之作，《賈氏談錄》謂韋瓘作。","詩繫牛僧孺名下，恐未允。","）。"]', '["香风引上大羅天，月地花宮拜洞仙。","具道人间惆悵事，不知今夕是何年。","（《唐诗紀事》二九引《周秦行紀》（《周秦行紀》，一般認爲是李黨託牛僧孺之作，《賈氏談錄》謂韋瓘作。","诗繫牛僧孺名下，恐未允。","）。"]', '诗', 'shi', '', NULL, '漢文帝母薄太后廟賦詩 牛僧孺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35fbe497-6800-4add-a563-f84d7c28003e', '答張郎中分寄翰林貢餘筆歌', '答張郎中分寄翰林貢餘笔歌', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["圓金五寸輕錯刀，天人摘落霜兔毛。","我之宗兄掌文檄，翰林分與神仙毫。","東風吹柳作金線，狂湧辭波力生健。","此時捧得江文通，五色光從掌中見。","江龍角嫩無精彩，盡日揮空射煙靄。","誰能邀得懷素來，晴明書破琉璃海。","揚雄得之《甘泉賦》，胸中白鳯無因飛。","他年擬把補造化，穿江入海剜天涯。","昨宵夢見歐率更，先來醉我黃金觥。","手擎瑟瑟三十斗，博歸天上書《黃庭》。","夢中擺手不相許，悵望空乘碧雲去。","（《文房四譜》二《筆譜》）。"]', '["圓金五寸轻錯刀，天人摘落霜兔毛。","我之宗兄掌文檄，翰林分與神仙毫。","东风吹柳作金線，狂湧辞波力生健。","此时捧得江文通，五色光從掌中见。","江龙角嫩無精彩，尽日揮空射煙靄。","誰能邀得懷素来，晴明书破琉璃海。","揚雄得之《甘泉賦》，胸中白鳯無因飞。","他年擬把補造化，穿江入海剜天涯。","昨宵梦见歐率更，先来醉我黄金觥。","手擎瑟瑟三十斗，博归天上书《黄庭》。","梦中擺手不相許，悵望空乘碧云去。","（《文房四譜》二《笔譜》）。"]', '诗', 'shi', '', NULL, '答張郎中分寄翰林貢餘筆歌 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0598b28-f586-487c-948b-5805d6b540df', '遊安禪寺', '游安禪寺', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["欲到安禪遊聖概，先觀湧塔出香城。","樓臺有日連雲漢，壑谷無年斷水聲。","倚竹並肩青玉立，上橋如踏白虹行。","傷嗟置寺碑交碎，不見梁朝施主名。","（《嚴陵集》一）。"]', '["欲到安禪游聖概，先观湧塔出香城。","楼台有日連云漢，壑谷無年斷水声。","倚竹並肩青玉立，上橋如踏白虹行。","傷嗟置寺碑交碎，不见梁朝施主名。","（《嚴陵集》一）。"]', '诗', 'shi', '', NULL, '遊安禪寺 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd904a40-322e-42a7-ba67-679caf9a79a7', '蘇小小墓', '蘇小小墓', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["古木寒鴉噪夕陽，六朝遺恨草茫茫。","水如香篆船如葉，咫尺西陵不見郎。","（《輿地紀勝三《嘉興府·古迹》（熊飛云《宋詩紀事》卷二十二據《嘉興府志補》收此詩爲沈括作。","今按徐凝有《嘉興寒食》詩詠及蘇小小墓，此詩疑因脫冒而誤歸其名下。","沈括《長興集》存本詩皆缺失，尚難定讞，姑仍存。","）。"]', '["古木寒鴉噪夕陽，六朝遺恨草茫茫。","水如香篆船如葉，咫尺西陵不见郎。","（《輿地紀勝三《嘉兴府·古迹》（熊飞云《宋诗紀事》卷二十二據《嘉兴府志補》收此诗爲沈括作。","今按徐凝有《嘉兴寒食》诗詠及蘇小小墓，此诗疑因脫冒而誤归其名下。","沈括《长兴集》存本诗皆缺失，尚难定讞，姑仍存。","）。"]', '诗', 'shi', '', NULL, '蘇小小墓 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa4611fe-5bcc-441f-9574-916afb401c71', '砥柱', '砥柱', 'a6e68cf2-6750-4873-8b09-d948dcef70ae', '唐', '["禹鑿鋒鈚後，巍峨直至今。","孤峰浮水面，一柱釘波心。","頂壓三門險，根隨九曲深。","拄天形突兀，逐浪勢浮沉。","岸嚮秋濤射，祠斑夜漲侵。","噴香龍上下，刷羽鳥登臨。","祇有尖迎日，曾無柱影陰。","舊碑文字在，遺事可追尋。","（《古今圖書集成·山川典》三九《底柱山部》（《記纂淵海》卷二十四收此詩「頂壓三門險」以下四句，題作《題砥柱山》。","「拄天」作「撑天」。","）。"]', '["禹鑿鋒鈚後，巍峨直至今。","孤峰浮水面，一柱釘波心。","頂壓三门險，根隨九曲深。","拄天形突兀，逐浪勢浮沉。","岸嚮秋濤射，祠斑夜漲侵。","噴香龙上下，刷羽鸟登臨。","祇有尖迎日，曾無柱影陰。","旧碑文字在，遺事可追尋。","（《古今圖书集成·山川典》三九《底柱山部》（《記纂淵海》卷二十四收此诗「頂壓三门險」以下四句，題作《題砥柱山》。","「拄天」作「撑天」。","）。"]', '诗', 'shi', '', NULL, '砥柱 柳公權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0869e2f-7c16-4cb9-a941-9d7af7b7c58c', '謝廬山僧寄谷簾水', '謝廬山僧寄谷簾水', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["消渴陵客，甘涼廬阜泉。","瀉從千仞石，寄逐陰江船。","竹櫃新茶出，銅鐺活火煎。","育花浮晚菊，沸沫響秋蟬。","啜憶吳僧共，傾宜越椀圓。","氣清寧怕睡，骨健欲成仙。","吏役尋無暇，詩情得有緣。","深疑嘗沆瀣，猶欠聽潺湲。","迢遞康王谷，塵埃陸羽篇。","何當結茅屋，長在水簾前。","（《正德南康府志》十）。"]', '["消渴陵客，甘涼廬阜泉。","瀉從千仞石，寄逐陰江船。","竹櫃新茶出，銅鐺活火煎。","育花浮晚菊，沸沫响秋蟬。","啜憶吳僧共，傾宜越椀圓。","氣清寧怕睡，骨健欲成仙。","吏役尋無暇，诗情得有緣。","深疑嘗沆瀣，猶欠听潺湲。","迢遞康王谷，塵埃陸羽篇。","何當結茅屋，长在水簾前。","（《正德南康府志》十）。"]', '诗', 'shi', '', NULL, '謝廬山僧寄谷簾水 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7531332b-05e4-4083-af1c-1fc91959003b', '題常雲峯（常雲峯，去樂清縣東八十里，在雁蕩山西谷。以其「常」有雲霧，登者心志則爲澄霽。又名靈府山。）', '題常云峯（常云峯，去乐清縣东八十里，在雁蕩山西谷。以其「常」有云霧，登者心志則爲澄霽。又名靈府山。）', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["仙府雲壇莫謾登，綵雲香霧晝常烝。","君能到此消塵慮，隱豹垂天亦爲澄。","（《永樂溫州府樂清縣志》二《山川》。","又《廣雁蕩山誌》三《山水》）。"]', '["仙府云壇莫謾登，綵云香霧晝常烝。","君能到此消塵慮，隐豹垂天亦爲澄。","（《永乐溫州府乐清縣志》二《山川》。","又《廣雁蕩山誌》三《山水》）。"]', '诗', 'shi', '', NULL, '題常雲峯（常雲峯，去樂清縣東八十里，在雁蕩山西谷。以其「常」有雲霧，登者心志則爲澄霽。又名靈府山。） 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1308f73-427f-4c78-ad2f-d33797288d15', '太玉洞（句）', '太玉洞（句）', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["一國洞天三十六，東嘉幸得一仙居。","（《永樂大典》一三○七五「洞」字韻引《元一統志》）。"]', '["一国洞天三十六，东嘉幸得一仙居。","（《永乐大典》一三○七五「洞」字韻引《元一統志》）。"]', '诗', 'shi', '', NULL, '太玉洞（句） 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b6096b-4190-4e10-937d-c461534b1b41', '龍虎山', '龙虎山', '22deb826-1dec-4e61-9e39-84c33144d597', '唐', '["龍虎山中紫翠烟，青精顏色四時妍。","桃枝慣見花成實，瀛島宜聞海變田。","五斗米仙真有道，一神樓藥豈無緣。","秋風吹綠茂陵草，的的黃金飛上天。","（《古今圖書集成·山川典》一四七《龍虎山部》）。"]', '["龙虎山中紫翠烟，青精顏色四时妍。","桃枝慣见花成實，瀛島宜闻海变田。","五斗米仙真有道，一神楼藥豈無緣。","秋风吹綠茂陵草，的的黄金飞上天。","（《古今圖书集成·山川典》一四七《龙虎山部》）。"]', '诗', 'shi', '', NULL, '龍虎山 吳武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f7198d-5a70-4527-85af-8fbfa2acf615', '傳奇小說（詩句）', '傳奇小说（诗句）', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["命笑無人笑，含嬌何處嬌。","徘徊花上月，空（一作「虛」）度可憐宵。","（《藝林伐山》十七。","又《詩人玉屑》十二《品藻》引後二句（《太平廣記》卷三二六《沈警》條引《異聞錄》載此爲沈警詩。","《詩人玉屑》以爲沈亞之作，未詳所據。","程毅中《〈異聞集〉考》因疑《沈警》篇爲沈亞之作。","惜尚乏他證佐定之。","）。"]', '["命笑無人笑，含嬌何处嬌。","徘徊花上月，空（一作「虛」）度可怜宵。","（《藝林伐山》十七。","又《诗人玉屑》十二《品藻》引後二句（《太平廣記》卷三二六《沈警》條引《異闻錄》載此爲沈警诗。","《诗人玉屑》以爲沈亞之作，未詳所據。","程毅中《〈異闻集〉考》因疑《沈警》篇爲沈亞之作。","惜尚乏他證佐定之。","）。"]', '诗', 'shi', '', NULL, '傳奇小說（詩句） 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1749816-3621-4579-b0ed-a1a665866a5d', '長揖詩（貞元中，劉忠州任大夫科選，多濫進。有無名子自云山東野客，移書於劉，附長揖詩曰：）', '长揖诗（貞元中，劉忠州任大夫科選，多濫進。有無名子自云山东野客，移书於劉，附长揖诗曰：）', 'b4a25c89-a35d-4267-afaf-bfc13c25876d', '唐', '["三銓選客不須嗔，五箇登科各有因。","無識伯和憐吉獠，弄權虞候爲王申。","載華甲第歸丞相，裴子門徒入舍人。","莫怪邵南書判好，他家自有景監親。","（《唐摭言》十三《無名子謗議》）。"]', '["三銓選客不須嗔，五箇登科各有因。","無識伯和怜吉獠，弄權虞候爲王申。","載华甲第归丞相，裴子门徒入舍人。","莫怪邵南书判好，他家自有景監親。","（《唐摭言》十三《無名子謗議》）。"]', '诗', 'shi', '', NULL, '長揖詩（貞元中，劉忠州任大夫科選，多濫進。有無名子自云山東野客，移書於劉，附長揖詩曰：） 山東野客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bebe1d2-248c-4f65-9e96-07414057b14e', '桂花曲', '桂花曲', '7e8188ea-8881-40dd-84ea-38b9c94bda04', '唐', '["仙女侍，董雙成，桂殿夜涼（一作「寒」）吹玉笙。","曲終却從仙宮去，萬戶千門空月明。","河漢女，玉練顏，雲軿往往到人間。","九霄有路去無際（一作「迹」），裊裊大風吹珮環。","《苕溪漁隱業話後集》十二：「戰鬥曲《許彦周詩話》謂是李衛公作，《桐江詩話》謂是均州武當山石壁上刻之，云神仙所作，未知孰是。","」（《全唐詩補逸》卷五以前五句作李栖筠詩，未妥，今刪彼存此。","詳參書末之修訂說明。","《全唐詩》卷八九○收作李白《桂殿秋》詞，恐誤。","）。"]', '["仙女侍，董雙成，桂殿夜涼（一作「寒」）吹玉笙。","曲終却從仙宮去，万戶千门空月明。","河漢女，玉練顏，云軿往往到人间。","九霄有路去無際（一作「迹」），裊裊大风吹珮环。","《苕溪漁隐業話後集》十二：「戰鬥曲《許彦周诗話》謂是李衛公作，《桐江诗話》謂是均州武當山石壁上刻之，云神仙所作，未知孰是。","」（《全唐诗補逸》卷五以前五句作李栖筠诗，未妥，今刪彼存此。","詳參书末之修訂说明。","《全唐诗》卷八九○收作李白《桂殿秋》词，恐誤。","）。"]', '诗', 'shi', '', NULL, '桂花曲 李德谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6f4b1aa-b63a-43a9-b488-7d01caf50c8b', '寄家書', '寄家书', '7e8188ea-8881-40dd-84ea-38b9c94bda04', '唐', '["琼與中原隔，自然音信疎。","天涯無去雁，船上有回書。","一別五年外，相思萬里餘。","開緘更多感，老泪濕霜鬚。","（《光緒崖州志》二一《藝文》（周建國云：李德裕大中元年貶崖州，三年冬卒。","「別五年外」之「五「當作「三」。","）。"]', '["琼與中原隔，自然音信疎。","天涯無去雁，船上有回书。","一別五年外，相思万里餘。","开緘更多感，老泪濕霜鬚。","（《光緒崖州志》二一《藝文》（周建国云：李德裕大中元年貶崖州，三年冬卒。","「別五年外」之「五「當作「三」。","）。"]', '诗', 'shi', '', NULL, '寄家書 李德谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee21f98-eb0d-4032-988f-c2ca51f6ef3e', '謫崖州過北流鬼門關作（《輿地紀勝》一○四《容州·景物》。又《永樂大典》二三三八及二三四○「梧」字韻兩見）', '謫崖州過北流鬼门关作（《輿地紀勝》一○四《容州·景物》。又《永乐大典》二三三八及二三四○「梧」字韻兩见）', '7e8188ea-8881-40dd-84ea-38b9c94bda04', '唐', '["空（《全唐詩》一二一作楊炎詩，《唐詩紀事》三二同。","第三句「何處在」《輿地紀勝》作「在何處」。","〖周建國云此當爲李德裕作，宋初樂史《太平寰宇記·嶺南道·容州》已收爲李作，比《唐詩紀事》可靠。","〗）。"]', '["空（《全唐诗》一二一作楊炎诗，《唐诗紀事》三二同。","第三句「何处在」《輿地紀勝》作「在何处」。","〖周建国云此當爲李德裕作，宋初乐史《太平寰宇記·嶺南道·容州》已收爲李作，比《唐诗紀事》可靠。","〗）。"]', '诗', 'shi', '', NULL, '謫崖州過北流鬼門關作（《輿地紀勝》一○四《容州·景物》。又《永樂大典》二三三八及二三四○「梧」字韻兩見） 李德谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe6b909-4e6c-4192-ad09-91788204e067', '詠吐綬雞（句）', '詠吐綬雞（句）', '7e8188ea-8881-40dd-84ea-38b9c94bda04', '唐', '["葳蕤散綬輕風裏，若銜（御）若垂何可擬。","（《詩話總龜後集》二七《詠物門》引《蔡寬夫詩話》。","○今按：《全唐詩》四七五引《事文類聚》，上句缺「散綬」二字，又無序，故重錄之。","）（〖1〗《蔡寬夫詩話》今佚，《總龜》所引，系據《苕溪漁隱業話前集》卷二十轉錄。","二書所引，皆未以此段文字爲序。","按其文意，僅「出剡溪」三字爲李德裕所云，餘皆蔡寬夫之語。","此處誤讀。","《說郛》卷二十二引《山家清供》錄二句，後句作「若衍若垂何可據」。","周建國告《劉賓客文集》卷三七《吐綬鳥詞》序提及此首，題應作《吐綬鳥詞》。","）。"]', '["葳蕤散綬轻风裏，若銜（御）若垂何可擬。","（《诗話總龟後集》二七《詠物门》引《蔡寬夫诗話》。","○今按：《全唐诗》四七五引《事文類聚》，上句缺「散綬」二字，又無序，故重錄之。","）（〖1〗《蔡寬夫诗話》今佚，《總龟》所引，系據《苕溪漁隐業話前集》卷二十轉錄。","二书所引，皆未以此段文字爲序。","按其文意，僅「出剡溪」三字爲李德裕所云，餘皆蔡寬夫之語。","此处誤读。","《说郛》卷二十二引《山家清供》錄二句，後句作「若衍若垂何可據」。","周建国告《劉賓客文集》卷三七《吐綬鸟词》序提及此首，題應作《吐綬鸟词》。","）。"]', '诗', 'shi', '', NULL, '詠吐綬雞（句） 李德谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b81957f5-7868-4cad-9322-2eea021e8ab0', '南竄途中感憤（句）', '南竄途中感憤（句）', '7e8188ea-8881-40dd-84ea-38b9c94bda04', '唐', '["（李衛公歷三朝大權，出門下者多矣。","及南竄，怨嫌併集，途中感憤，有句云：）十五餘年車馬客，無人相送到崖州。","（《唐語林》七《補遺》）。"]', '["（李衛公歷三朝大權，出门下者多矣。","及南竄，怨嫌併集，途中感憤，有句云：）十五餘年车马客，無人相送到崖州。","（《唐語林》七《補遺》）。"]', '诗', 'shi', '', NULL, '南竄途中感憤（句） 李德谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ed12645-8064-44ec-80ba-b683169b219b', '詩', '诗', '0ad09381-2da7-4170-a50b-9385ea3c0db6', '唐', '["（《唐語林》七《補遺》云：「李衛公頗升寒素。","舊府解有等第，衛公既貶，崔少保龜從在省，子殷夢爲府解元。","廣今諸生爲詩云云。","盧渥司徒以府元爲第五人，自此廢等第。","」又《唐摭言》七云：「李太尉德裕頗爲寒畯〖《紀事》爲素〗開路，及謫官南去，或有詩曰：「八百孤寒齊下淚，一時南望李崖州。","」〖又《雲谿友議》云：「後之文場困辱者，若周人之思鄉焉。","皆曰：『八百孤寒齊下淚，一時回首望崖州』。","」《唐新的紀事》及《全唐詩》無名氏詩句同，亦均只存後二句。","）省司府局正綢繆，殷夢元知作解頭。","三百孤寒齊下淚，一時南望李崖州。","（《唐語林》七《補遺》）。"]', '["（《唐語林》七《補遺》云：「李衛公頗升寒素。","旧府解有等第，衛公既貶，崔少保龟從在省，子殷梦爲府解元。","廣今諸生爲诗云云。","盧渥司徒以府元爲第五人，自此廢等第。","」又《唐摭言》七云：「李太尉德裕頗爲寒畯〖《紀事》爲素〗开路，及謫官南去，或有诗曰：「八百孤寒齊下泪，一时南望李崖州。","」〖又《云谿友議》云：「後之文場困辱者，若周人之思乡焉。","皆曰：『八百孤寒齊下泪，一时回首望崖州』。","」《唐新的紀事》及《全唐诗》無名氏诗句同，亦均只存後二句。","）省司府局正綢繆，殷梦元知作解头。","三百孤寒齊下泪，一时南望李崖州。","（《唐語林》七《補遺》）。"]', '诗', 'shi', '', NULL, '詩 廣文諸生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408c76e2-ec43-468b-a92b-7b69068a6967', '金庭洞', '金庭洞', '6e45ae2a-da9e-4516-8abc-a9763e46f5f7', '唐', '["寂寂金庭洞，清香發桂枝。","魚吞左慈釣，鵝踏右軍池。","（《永樂大典》一三○七四「洞」字韻（此詩未全，全篇見《全唐詩續拾》卷二六。","）。"]', '["寂寂金庭洞，清香發桂枝。","鱼吞左慈釣，鵝踏右軍池。","（《永乐大典》一三○七四「洞」字韻（此诗未全，全篇见《全唐诗續拾》卷二六。","）。"]', '诗', 'shi', '', NULL, '金庭洞 裴通 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f75321-11fd-4ecc-8e8e-342cbbd4a057', '白雲亭（《全唐詩》八六○作許宣平《見李白詩又吟》，出入較多，故重錄。）', '白云亭（《全唐诗》八六○作許宣平《见李白诗又吟》，出入較多，故重錄。）', '3daccdee-534f-4fcc-a66d-1f7e5fda0b59', '唐', '["一池荷葉衣無盡，數樹松花食有餘。","剛被世人知住處，不如依舊再移居。","（《嚴陵集》二）（原列入無世次作者。","按《雲笈七籤》卷一一三錄沈汾《續仙傳》云：「羅萬象，不知何所人。","有文學，明天文，洞深於）（《易》，節操奇特。","惟布衣遊天下，居王屋山。","久之，遊羅浮山，遂結庵以居。","」《輿地紀勝》卷八引晏殊《類要》云：「唐羅萬象者分水縣人也。","隱於紫邏山。","節度使李德裕使人召之，聞之，更移入深山，依白雲而居，終身不出。","」今移此。","曹汛謂《五燈會元》卷三收大梅法常偈，與此多同。","）。"]', '["一池荷葉衣無尽，數樹松花食有餘。","剛被世人知住处，不如依旧再移居。","（《嚴陵集》二）（原列入無世次作者。","按《云笈七籤》卷一一三錄沈汾《續仙傳》云：「羅万象，不知何所人。","有文学，明天文，洞深於）（《易》，節操奇特。","惟布衣游天下，居王屋山。","久之，游羅浮山，遂結庵以居。","」《輿地紀勝》卷八引晏殊《類要》云：「唐羅万象者分水縣人也。","隐於紫邏山。","節度使李德裕使人召之，闻之，更移入深山，依白云而居，終身不出。","」今移此。","曹汛謂《五灯會元》卷三收大梅法常偈，與此多同。","）。"]', '诗', 'shi', '', NULL, '白雲亭（《全唐詩》八六○作許宣平《見李白詩又吟》，出入較多，故重錄。） 羅萬象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed150864-bd14-455a-8327-e261f7d6a8ad', '泰伯井', '泰伯井', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["至德今何在，平墟井有泉。","梁鴻重濬後，又歷幾千年。","（《梅里志》三《詩》）。"]', '["至德今何在，平墟井有泉。","梁鴻重濬後，又歷幾千年。","（《梅里志》三《诗》）。"]', '诗', 'shi', '', NULL, '泰伯井 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98207084-c2f1-4c75-a2fc-650c5766586f', '鶯鶯歌（逸句〖1〗）', '鶯鶯歌（逸句〖1〗）', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["（董解元《西廂記諸宮調》徵引公垂《鶯鶯歌》凡四處。","卷一有「伯勞飛遲燕飛疾」八句，已見《全唐詩》。","）。"]', '["（董解元《西廂記諸宮調》徵引公垂《鶯鶯歌》凡四处。","卷一有「伯勞飞遲燕飞疾」八句，已见《全唐诗》。","）。"]', '诗', 'shi', '', NULL, '鶯鶯歌（逸句〖1〗） 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5780913-088b-40b7-bf02-4ee72cd45700', '鶯鶯歌（逸句〖1〗） 一', '鶯鶯歌（逸句〖1〗） 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["河橋上將亡官軍，虎騎長「戟」（戰）交壘門。","鳳凰詔書猶未到，滿城戈甲如「雲」（雪）屯。","家家玉帛棄泥土，少女嬌妻愁被虜。","出門走馬皆健兒，紅粉潛藏欲何處？","鳴鳴阿母啼向天，窗中抱女投金鈿。","鉛華不顧欲藏艷，玉颜轉瑩如神仙（《董解元西廂記》卷二〖2〗）。"]', '["河橋上將亡官軍，虎騎长「戟」（戰）交壘门。","鳳凰詔书猶未到，满城戈甲如「云」（雪）屯。","家家玉帛棄泥土，少女嬌妻愁被虜。","出门走马皆健兒，紅粉潛藏欲何处？","鳴鳴阿母啼向天，窗中抱女投金鈿。","鉛华不顧欲藏艷，玉颜轉瑩如神仙（《董解元西廂記》卷二〖2〗）。"]', '诗', 'shi', '', NULL, '鶯鶯歌（逸句〖1〗） 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33205615-7370-4ceb-bc7e-2217caf89d98', '鶯鶯歌（逸句〖1〗） 二', '鶯鶯歌（逸句〖1〗） 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["此時潘郎未相識，偶住蓮館對南北。","潛歎悽惶阿母心，爲求白馬將軍力。","明明飛詔五雲下，將選金門兵悉罷。","阿母深居雞犬安，八珍玉食邀郎餐。","千言萬語對生意，小女初笄爲姊妹。","（同上〖卷三〗）。"]', '["此时潘郎未相識，偶住蓮館对南北。","潛歎悽惶阿母心，爲求白马將軍力。","明明飞詔五云下，將選金门兵悉罷。","阿母深居雞犬安，八珍玉食邀郎餐。","千言万語对生意，小女初笄爲姊妹。","（同上〖卷三〗）。"]', '诗', 'shi', '', NULL, '鶯鶯歌（逸句〖1〗） 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fc6c38a-8b2a-4e1f-84f6-b702f53223ff', '鶯鶯歌（逸句〖1〗） 三', '鶯鶯歌（逸句〖1〗） 三', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["丹誠寸之難自比，寫在紅箋方寸紙。","寄與春風伴落花，彷彿隨風綠楊裏。","窗中暗讀人不知，剪破紅綃裁作詩。","還怕香風易飄蕩，自令青鳥口啣之。","詩中報郎含隱語，郎知暗到花深處。","三五月明當戶時，與郎相見花間路。","（同上〖卷四〗）。"]', '["丹誠寸之难自比，寫在紅箋方寸紙。","寄與春风伴落花，彷彿隨风綠楊裏。","窗中暗读人不知，剪破紅綃裁作诗。","還怕香风易飄蕩，自令青鸟口啣之。","诗中報郎含隐語，郎知暗到花深处。","三五月明當戶时，與郎相见花间路。","（同上〖卷四〗）。"]', '诗', 'shi', '', NULL, '鶯鶯歌（逸句〖1〗） 三 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a5bca5-b8e8-4338-815d-70950adac4ef', '鶯鶯歌（逸句〖1〗） 四', '鶯鶯歌（逸句〖1〗） 四', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["恍然夢作瑤臺客。","（《施注蘇詩》十五《見月詩》注引）（〖1〗《董解元西厢記》卷一、卷二、卷三所引，皆作《鶯鶯本傳歌》，卷四作《本傳歌》。","〖2〗兩處校改，均據人民文學出版社出版淩景埏校注本。","）。"]', '["恍然梦作瑤台客。","（《施注蘇诗》十五《见月诗》注引）（〖1〗《董解元西厢記》卷一、卷二、卷三所引，皆作《鶯鶯本傳歌》，卷四作《本傳歌》。","〖2〗兩处校改，均據人民文学出版社出版淩景埏校注本。","）。"]', '诗', 'shi', '', NULL, '鶯鶯歌（逸句〖1〗） 四 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9df0489d-3b63-4015-a489-649d53d40e4f', '石佛谷', '石佛谷', '00fa3bf2-ac76-4fc2-9171-a1d4d0319966', '唐', '["空（〖1〗《全唐詩》三六九作皇甫湜詩，第十五句「鳥跡」《圖書集成》作「鳥趾」，十七句「間」作「闊」。","〖2〗《古今圖書集成·職方典》三六四《澤州部》〖《金石錄》卷十著錄：「唐皇甫曙《題石佛谷詩》，李道夷正書，開成元年十一月。","」《寶刻業編》卷二十亦著錄。","皇甫曙於大和九年至開成二年間任澤州刺史，詳郁賢皓《唐刺史考》卷八。","詩即曙刺澤州時作。","《全唐詩》誤歸皇甫湜，應移正。","〗）。"]', '["空（〖1〗《全唐诗》三六九作皇甫湜诗，第十五句「鸟跡」《圖书集成》作「鸟趾」，十七句「间」作「闊」。","〖2〗《古今圖书集成·職方典》三六四《澤州部》〖《金石錄》卷十著錄：「唐皇甫曙《題石佛谷诗》，李道夷正书，开成元年十一月。","」《寶刻業編》卷二十亦著錄。","皇甫曙於大和九年至开成二年间任澤州刺史，詳郁賢皓《唐刺史考》卷八。","诗即曙刺澤州时作。","《全唐诗》誤归皇甫湜，應移正。","〗）。"]', '诗', 'shi', '', NULL, '石佛谷 皇甫曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe08a04-7245-419a-a36a-b007a00cf3b2', '九華山謝雨詩', '九华山謝雨诗', '866b99f8-63c3-4396-a112-6e52e0147fb6', '唐', '["青嶂廟前纔滴酒，白龍湫上氣如蒸。","一聲霹靂驚風雨，萬頃秋田水溢堘。","（《嘉靖池州府志》五）。"]', '["青嶂廟前纔滴酒，白龙湫上氣如蒸。","一声霹靂驚风雨，万頃秋田水溢堘。","（《嘉靖池州府志》五）。"]', '诗', 'shi', '', NULL, '九華山謝雨詩 費冠卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a929552e-dccb-42aa-a4ec-d07229b8045a', '過桐廬場鄭判官', '過桐廬場鄭判官', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["榮陽鄭君游說餘，偶因榷茗來桐廬。","幽奇山水引高步，暐煜風光隨使車。","算緍百萬日不虛，吏人業裏唯簿書。","眼前橫製斷犀劍，心中暗轉靈蛇珠。","有時退公兼退食，一尊長在朱軒側。","胡商大鼻左右趍，趙妾細眉前後直。","醉來引客上紅樓，面前一道桐溪流。","登臨山色在掌內，指點霞光隨杖頭。","東郭野人慵櫛沐，使將破履升華屋。","數杯酩酊不得歸，樓中便蓋江雲宿。","卻被江郎濕我衣，賴君借我貂襜歸。"]', '["榮陽鄭君游说餘，偶因榷茗来桐廬。","幽奇山水引高步，暐煜风光隨使车。","算緍百万日不虛，吏人業裏唯簿书。","眼前橫製斷犀劍，心中暗轉靈蛇珠。","有时退公兼退食，一尊长在朱軒側。","胡商大鼻左右趍，趙妾細眉前後直。","醉来引客上紅楼，面前一道桐溪流。","登臨山色在掌內，指点霞光隨杖头。","东郭野人慵櫛沐，使將破履升华屋。","數杯酩酊不得归，楼中便蓋江云宿。","卻被江郎濕我衣，賴君借我貂襜归。"]', '诗', 'shi', '', NULL, '過桐廬場鄭判官 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4138ffa-537b-4677-a3e2-2b2cd66291b8', '西山即事奉寄故園徐處士', '西山即事奉寄故园徐处士', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["僕作江西少施氏，君爲城北老徐翁。","詩篇憶昔歡相接，颜貎如今恨不同。","世界盡憂蔬上露，時人皆怕燭前風。","唯余獨慕神仙道，芥子雖窮壽不窮。"]', '["僕作江西少施氏，君爲城北老徐翁。","诗篇憶昔歡相接，颜貎如今恨不同。","世界尽憂蔬上露，时人皆怕燭前风。","唯余独慕神仙道，芥子雖窮壽不窮。"]', '诗', 'shi', '', NULL, '西山即事奉寄故園徐處士 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b849a1ed-cbc3-4e1e-ad11-a77f70421200', '夏日過從叔幽居', '夏日過從叔幽居', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["且將一葉繫垂陽，角對清溪夏日長。","林下喜逢青竹卷，局邊輸卻紫羅囊。","碧蹄駿馬銜芻細，紅粉佳人挈榼香。","伯仲歷官年盡少，那知不笑漢馮唐。"]', '["且將一葉繫垂陽，角对清溪夏日长。","林下喜逢青竹卷，局邊輸卻紫羅囊。","碧蹄駿马銜芻細，紅粉佳人挈榼香。","伯仲歷官年尽少，那知不笑漢馮唐。"]', '诗', 'shi', '', NULL, '夏日過從叔幽居 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69904a0-a985-4af2-9a3d-edf344c1be08', '贈族叔處士', '贈族叔处士', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["我家名士已無求，若見翔鴻便舉頭。","紫有巖邊吟繡段，青苔紙上落銀鉤。","高人酒席稱無醉，細字經書讀未休。","定是仙山足靈藥，年過八十轉風流。","。"]', '["我家名士已無求，若见翔鴻便舉头。","紫有巖邊吟繡段，青苔紙上落銀鉤。","高人酒席稱無醉，細字經书读未休。","定是仙山足靈藥，年過八十轉风流。","。"]', '诗', 'shi', '', NULL, '贈族叔處士 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48f9021-fa6b-454d-ad6d-776bab94d3e6', '桐廬廳覩論事叟', '桐廬廳覩論事叟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["擾擾廳前走羸瘵，中有老人扶杖拜。","天公霹靂耳不聞，猶爲子孫争地界。"]', '["擾擾廳前走羸瘵，中有老人扶杖拜。","天公霹靂耳不闻，猶爲子孫争地界。"]', '诗', 'shi', '', NULL, '桐廬廳覩論事叟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf8a06d-523b-4973-8111-cc6ca25da293', '秋日桐江送裴秀才歸淮南（〖1〗《全唐詩》四九四題爲《送裴秀才歸淮南》，第二句「楓葉」《嚴陵集》作「桐樹」，「夕」作「葉」。）', '秋日桐江送裴秀才归淮南（〖1〗《全唐诗》四九四題爲《送裴秀才归淮南》，第二句「楓葉」《嚴陵集》作「桐樹」，「夕」作「葉」。）', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '秋日桐江送裴秀才歸淮南（〖1〗《全唐詩》四九四題爲《送裴秀才歸淮南》，第二句「楓葉」《嚴陵集》作「桐樹」，「夕」作「葉」。） 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4537d402-311c-434d-ae2b-86bb379214c2', '題釣臺蘭若', '題釣台蘭若', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["山僧不釣臺下魚，幾年空寄臺邊坐。","有時手把乾松枝，沿江乞得沙上火。"]', '["山僧不釣台下鱼，幾年空寄台邊坐。","有时手把乾松枝，沿江乞得沙上火。"]', '诗', 'shi', '', NULL, '題釣臺蘭若 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2886292-97c1-4ad5-8dc5-12acc58d2ee7', '歸分水留贈王少府', '归分水留贈王少府', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["仙吏飲冰多玉聲，新詩麗句遺狂生。","不愁日暮歸山去，故把隋珠入夜行。","（以上《嚴陵集》一）。"]', '["仙吏饮冰多玉声，新诗丽句遺狂生。","不愁日暮归山去，故把隋珠入夜行。","（以上《嚴陵集》一）。"]', '诗', 'shi', '', NULL, '歸分水留贈王少府 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('383c49d5-14ed-4ee8-aa47-223e13de5eaa', '寺居清晨（〖1〗《全唐詩》三○五作劉復詩，第四句「虛光」《文苑英華》作「靈光」。○《文苑英華》二三六《寺院》。）', '寺居清晨（〖1〗《全唐诗》三○五作劉复诗，第四句「虛光」《文苑英华》作「靈光」。○《文苑英华》二三六《寺院》。）', '8052fe5d-97c4-4a9d-a01d-643ad3e02840', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '寺居清晨（〖1〗《全唐詩》三○五作劉復詩，第四句「虛光」《文苑英華》作「靈光」。○《文苑英華》二三六《寺院》。） 劉三復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b73a0c7-8b5c-4471-a04b-5bb64dc3d187', '憂旱吟', '憂旱吟', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["炎熇肆蒸溽，南薫日飄颺。","田疇苦焦烈，龜坼無潤壤。","嘉禾穟爲實，灌注期穰穰。","午火雲熾，虐焰彌穹蒼。","桔槹置無用，何計盈倉箱。","老農力耕耨，捫心熱衷腸。","公租與私稅，焉得俱無傷？","今年已憔悴，斗米百錢償。","富豪索高價，閉廩幾絕糧。","引領望甘雨，傾城禱林桑。","匹夫動天地，奚俟暴巫尫。","浹旬竟弗驗，神明果茫茫。","彼蒼豈降割，以重吾民殃。","（《古今圖書集成·庶徵典》五九《旱災部》）。"]', '["炎熇肆蒸溽，南薫日飄颺。","田疇苦焦烈，龟坼無潤壤。","嘉禾穟爲實，灌注期穰穰。","午火云熾，虐焰彌穹蒼。","桔槹置無用，何計盈倉箱。","老農力耕耨，捫心熱衷腸。","公租與私稅，焉得俱無傷？","今年已憔悴，斗米百錢償。","富豪索高價，閉廩幾絕糧。","引領望甘雨，傾城禱林桑。","匹夫动天地，奚俟暴巫尫。","浹旬竟弗驗，神明果茫茫。","彼蒼豈降割，以重吾民殃。","（《古今圖书集成·庶徵典》五九《旱災部》）。"]', '诗', 'shi', '', NULL, '憂旱吟 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48cdfb0e-e92b-4da7-801b-d84fab5e3ddc', '平望驛寄吳興徐使君玄之〖1〗', '平望驛寄吳兴徐使君玄之〖1〗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["故人爲作郡，百里到吳興。","藻思江湖滿，公平道路稱。","包山方峻直，霅水況澄清。","佇聽司空第，遙知下詔徵。","（《百城烟水》四《吴江》）（〖1〗《嘉泰吳興志》卷十四《郡守題名》云：「徐玄之，開元七年自諫議大夫授，改邠王府長史。","《統紀》云：開元十五年。","」郁賢皓《唐刺史考》從《統紀》之說。","張祜約生於貞元間，卒於大中中，於徐玄之不同時，詩顯非其作。","確作者不詳，姑仍存此。","）。"]', '["故人爲作郡，百里到吳兴。","藻思江湖满，公平道路稱。","包山方峻直，霅水況澄清。","佇听司空第，遙知下詔徵。","（《百城烟水》四《吴江》）（〖1〗《嘉泰吳兴志》卷十四《郡守題名》云：「徐玄之，开元七年自諫議大夫授，改邠王府长史。","《統紀》云：开元十五年。","」郁賢皓《唐刺史考》從《統紀》之说。","張祜約生於貞元间，卒於大中中，於徐玄之不同时，诗显非其作。","確作者不詳，姑仍存此。","）。"]', '诗', 'shi', '', NULL, '平望驛寄吳興徐使君玄之〖1〗 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16df6328-f394-4442-b62a-94fb0698f8a6', '伊山', '伊山', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["晉代衣冠夢一場，精藍往是讀書堂。","桓伊曾弄柯亭笛，吹落梅花萬點香。","（《古今圖書集成·職方典》一二五三《衡州府部》）。"]', '["晉代衣冠梦一場，精藍往是读书堂。","桓伊曾弄柯亭笛，吹落梅花万点香。","（《古今圖书集成·職方典》一二五三《衡州府部》）。"]', '诗', 'shi', '', NULL, '伊山 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63a53316-12e4-4263-bb44-4662b45e0295', '即席爲詩獻徐州節度王智興（時於使院會飲賦詩）', '即席爲诗獻徐州節度王智兴（时於使院會饮賦诗）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古來英傑動寰區，武德文經未有餘。","王氏柱天動業外，李陵章句右軍書。","（《唐詩紀事》五十四王智興名下引此詩，前三句作「十年受命鎮方隅，孝節忠規兩有餘。","誰信將壇嘉政外（第四句同）。","」又《全唐詩》三百十四王智興《徐州使院賦》，第一句「三十年前老健兒」，《劇談錄》作「平生弓劍自相隨」，第四句「獨」作「自」。","附注於此。","○《劇談錄》上。","。"]', '["古来英傑动寰區，武德文經未有餘。","王氏柱天动業外，李陵章句右軍书。","（《唐诗紀事》五十四王智兴名下引此诗，前三句作「十年受命鎮方隅，孝節忠規兩有餘。","誰信將壇嘉政外（第四句同）。","」又《全唐诗》三百十四王智兴《徐州使院賦》，第一句「三十年前老健兒」，《劇談錄》作「平生弓劍自相隨」，第四句「独」作「自」。","附注於此。","○《劇談錄》上。","。"]', '诗', 'shi', '', NULL, '即席爲詩獻徐州節度王智興（時於使院會飲賦詩） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a0e084-a815-4004-a44b-893872df8388', '文學泉（〖1〗《全唐詩》一二九裴迪《西塔寺陸羽茶泉》，共八句，最後二句爲此詩所無。題下注《統籤》云：「此詩楊慎以爲見之石刻，然羽自在大曆後，則非迪詩矣。」〖楊慎語見《升庵詩話》卷十二。按裴迪爲玄、肅間人，代宗時似已不存，陸羽約生於開元末，卒於貞元末，與裴迪時代相接。然詩中云：「景陵西塔寺，……曾經陸羽居。草堂荒產蛤，茶井冷生魚。」似應爲陸羽身後作。裴夷直長慶、大和間在世，與詩意正合。《統籤》疑僞是，當從《輿紀勝》歸夷直。〗〖2〗《輿地紀勝》七六《復州》）', '文学泉（〖1〗《全唐诗》一二九裴迪《西塔寺陸羽茶泉》，共八句，最後二句爲此诗所無。題下注《統籤》云：「此诗楊慎以爲见之石刻，然羽自在大曆後，則非迪诗矣。」〖楊慎語见《升庵诗話》卷十二。按裴迪爲玄、肅间人，代宗时似已不存，陸羽約生於开元末，卒於貞元末，與裴迪时代相接。然诗中云：「景陵西塔寺，……曾經陸羽居。草堂荒產蛤，茶井冷生鱼。」似應爲陸羽身後作。裴夷直长慶、大和间在世，與诗意正合。《統籤》疑僞是，當從《輿紀勝》归夷直。〗〖2〗《輿地紀勝》七六《复州》）', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '文學泉（〖1〗《全唐詩》一二九裴迪《西塔寺陸羽茶泉》，共八句，最後二句爲此詩所無。題下注《統籤》云：「此詩楊慎以爲見之石刻，然羽自在大曆後，則非迪詩矣。」〖楊慎語見《升庵詩話》卷十二。按裴迪爲玄、肅間人，代宗時似已不存，陸羽約生於開元末，卒於貞元末，與裴迪時代相接。然詩中云：「景陵西塔寺，……曾經陸羽居。草堂荒產蛤，茶井冷生魚。」似應爲陸羽身後作。裴夷直長慶、大和間在世，與詩意正合。《統籤》疑僞是，當從《輿紀勝》歸夷直。〗〖2〗《輿地紀勝》七六《復州》） 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa03e403-6e20-45b9-b909-7d93befd6197', '和李衛公漳浦驛留題', '和李衛公漳浦驛留題', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["南盡封郵見好山，蒼蒼桂嶺類商颜，誰憐後夜思鄉處，白草黃茅舊漢關。","（《輿地紀勝》一三一《漳州》。","又《康熙漳浦縣志》十九《雜志·古蹟》）。"]', '["南尽封郵见好山，蒼蒼桂嶺類商颜，誰怜後夜思乡处，白草黄茅旧漢关。","（《輿地紀勝》一三一《漳州》。","又《康熙漳浦縣志》十九《杂志·古蹟》）。"]', '诗', 'shi', '', NULL, '和李衛公漳浦驛留題 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('961eb5cb-078c-4647-81ff-0c14f9358f24', '', '', 'b3e87c42-9b98-44d0-b05e-9884a15681cf', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63c5246-f463-4a25-9a86-51218bf79f25', '賀州思九疑作', '賀州思九疑作', 'b3e87c42-9b98-44d0-b05e-9884a15681cf', '唐', '["我世家九疑，山在宅之陽。","林業倚虛壁，峭拔絕坤方。","卓植斗杓南，序列儼成行。","煙嵐緲相接，午影常中堂。","去留如有期，勝覽誇新妝。","少懷不羈思，那能繫空桑？","對此疑山高，目懸幾成尩。","飄風微我蕩，此興頎然長。","幸隨長者車，身便神亦爽。","詎仍手中扶，扶搖上翱翔。","雲開躋巒頂，萬丈誠孤亢。","俯瞷總羣植，纖纖若毫芒。","上與舉汗漫期，倒景徹罔浪。","璇璣盤胸次，燦爛皆文章。","清風時掀髯，世慮渾相忘。","伸手叩元關，閶闔鳴金琅。","九垓若可極，縱身托穹蒼。","四眺憑空忽，興盡思弓藏。","翩然下其肩，稽首來帝旁。","有嚴淑多士，登戶皆賢良。","探懷攄忠藎，吾亦傾吾囊。","鋒鋩避英銳，鉛槧費揮張。","臚傳動天閽，颜厚何可當。","騰章控多遜，遺珠映奎光。","蔽賢吾焉敢，亦將勵名芳。","維皇怒斯赫，投檄幷炎荒。","悵望九峯雲，母遠在蓮塘。","夜分緝餘緒，旦期裨袞裳。","美人弗可見，此心中忙忙。","朝哦甑巓松，夕把流霞觴。","何上層解羈紲，量移慰悽愴。","媸作盧敖遊，願爲曼倩狂。","長揖別臨賀，策馬指延唐。","時攜二三子，葺彼山阿房。","莧莧迹其故，餘復奚所望。"]', '["我世家九疑，山在宅之陽。","林業倚虛壁，峭拔絕坤方。","卓植斗杓南，序列儼成行。","煙嵐緲相接，午影常中堂。","去留如有期，勝覽誇新妝。","少懷不羈思，那能繫空桑？","对此疑山高，目懸幾成尩。","飄风微我蕩，此兴頎然长。","幸隨长者车，身便神亦爽。","詎仍手中扶，扶搖上翱翔。","云开躋巒頂，万丈誠孤亢。","俯瞷總羣植，纖纖若毫芒。","上與舉汗漫期，倒景徹罔浪。","璇璣盤胸次，燦爛皆文章。","清风时掀髯，世慮渾相忘。","伸手叩元关，閶闔鳴金琅。","九垓若可極，縱身托穹蒼。","四眺憑空忽，兴尽思弓藏。","翩然下其肩，稽首来帝旁。","有嚴淑多士，登戶皆賢良。","探懷攄忠藎，吾亦傾吾囊。","鋒鋩避英銳，鉛槧費揮張。","臚傳动天閽，颜厚何可當。","腾章控多遜，遺珠映奎光。","蔽賢吾焉敢，亦將勵名芳。","維皇怒斯赫，投檄幷炎荒。","悵望九峯云，母远在蓮塘。","夜分緝餘緒，旦期裨袞裳。","美人弗可见，此心中忙忙。","朝哦甑巓松，夕把流霞觴。","何上層解羈紲，量移慰悽愴。","媸作盧敖游，願爲曼倩狂。","长揖別臨賀，策马指延唐。","时携二三子，葺彼山阿房。","莧莧迹其故，餘复奚所望。"]', '诗', 'shi', '', NULL, '賀州思九疑作 李郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1517038e-c9bb-465d-a36f-c0f400fa3a6a', '過九疑山有懷', '過九疑山有懷', 'b3e87c42-9b98-44d0-b05e-9884a15681cf', '唐', '["晚度疑山道，依然想重華。","雲飄上苑葉，雪映御溝花。","行歎戍麾遠，坐令衣帶賒。","交何通絕徼，弱水浸流沙。","旅思徒漂梗，歸期未及瓜。","兩階干羽絕，夜夜泣胡笳。"]', '["晚度疑山道，依然想重华。","云飄上苑葉，雪映御溝花。","行歎戍麾远，坐令衣带賒。","交何通絕徼，弱水浸流沙。","旅思徒漂梗，归期未及瓜。","兩階干羽絕，夜夜泣胡笳。"]', '诗', 'shi', '', NULL, '過九疑山有懷 李郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7c859b-969c-4c92-bdee-a0c9b3823172', '詠舜廟古杉', '詠舜廟古杉', 'b3e87c42-9b98-44d0-b05e-9884a15681cf', '唐', '["總負億年質，高臨千仞峯。","貞心欺晚桂，勁節掩寒松。","任彼風飙折，挺然霜雪衝。","莖凌霄漢表，根蟠龍窟中。","仙客頻棲舞，良工何渺逢。","枝頭連理翠，擁護聖神宮。"]', '["總負億年質，高臨千仞峯。","貞心欺晚桂，勁節掩寒松。","任彼风飙折，挺然霜雪衝。","莖凌霄漢表，根蟠龙窟中。","仙客頻棲舞，良工何渺逢。","枝头連理翠，擁護聖神宮。"]', '诗', 'shi', '', NULL, '詠舜廟古杉 李郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9d8e27-f651-435a-a257-e06dc0221206', '遊九疑黃庭觀（《全唐詩》七八作駱賓王《遊靈公觀》，詩中字句多有異同）', '游九疑黄庭观（《全唐诗》七八作駱賓王《游靈公观》，诗中字句多有異同）', 'b3e87c42-9b98-44d0-b05e-9884a15681cf', '唐', '["靈峯標舜境，神府枕疑川。","玉殿斜臨漢，金堂逈架烟。","斷風疎晚竹，流水切寒絃。","別有月帔上，寄懷騎鶴仙。","（《文苑英華》卷二二六、江標影宋本《駱賓王集》卷中、《唐人三家集》本《駱賓王文集》〖據影宋蜀刻本翻雕〗卷四均收此詩爲駱作，作李詩恐非是。","）（以上《古今圖書集成·山川典》一七○《九疑山部》）。"]', '["靈峯標舜境，神府枕疑川。","玉殿斜臨漢，金堂逈架烟。","斷风疎晚竹，流水切寒絃。","別有月帔上，寄懷騎鹤仙。","（《文苑英华》卷二二六、江標影宋本《駱賓王集》卷中、《唐人三家集》本《駱賓王文集》〖據影宋蜀刻本翻雕〗卷四均收此诗爲駱作，作李诗恐非是。","）（以上《古今圖书集成·山川典》一七○《九疑山部》）。"]', '诗', 'shi', '', NULL, '遊九疑黃庭觀（《全唐詩》七八作駱賓王《遊靈公觀》，詩中字句多有異同） 李郃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44017ef7-213b-461f-8e15-2c6dfb2699e4', '還故居', '還故居', 'f794e2a8-f24c-4413-89fe-edac82afbda0', '唐', '["路入豐溪上，超然絕世氛。","懶尋書作伴，長與鶴爲羣。","千慮凈如水，一身閒似雲。","梅花領幽賞，疎雪隔簾分。","（嘉慶《旌德縣志》七《選舉》及十九《藝文》）。"]', '["路入豐溪上，超然絕世氛。","懶尋书作伴，长與鹤爲羣。","千慮凈如水，一身閒似云。","梅花領幽賞，疎雪隔簾分。","（嘉慶《旌德縣志》七《選舉》及十九《藝文》）。"]', '诗', 'shi', '', NULL, '還故居 江全銘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3523a3bc-0f83-432c-9eac-e63e72b7f3b8', '九華山', '九华山', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["昔年幽賞快疎慵，每喜佳山在邑封。","江上重來六七載，雲間略見兩三峯。","凌空瘦骨寒如削，照水清光翠且重。","却憶謫仙才格俊，解吟秀出九芙蓉。","（《輿地紀勝》二二《池州》（吳在慶謂此詩又見於嘉靖《池州府志》卷八，僅錄後四句。","又云杜牧僅在會昌四年九月至六年九月在池州任刺史，此外別無到池州之迹，亦無游九華山之作。","相據此詩前四句，顯爲詩人重游九華山之作，所謂「昔年」乃距重游時六七年，而這一情況，顯然與杜牧生平不合。","因疑此詩非杜牧作。","）。"]', '["昔年幽賞快疎慵，每喜佳山在邑封。","江上重来六七載，云间略见兩三峯。","凌空瘦骨寒如削，照水清光翠且重。","却憶謫仙才格俊，解吟秀出九芙蓉。","（《輿地紀勝》二二《池州》（吳在慶謂此诗又见於嘉靖《池州府志》卷八，僅錄後四句。","又云杜牧僅在會昌四年九月至六年九月在池州任刺史，此外別無到池州之迹，亦無游九华山之作。","相據此诗前四句，显爲诗人重游九华山之作，所謂「昔年」乃距重游时六七年，而這一情況，显然與杜牧生平不合。","因疑此诗非杜牧作。","）。"]', '诗', 'shi', '', NULL, '九華山 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafcc947-f881-41f3-ba0d-751109add461', '句', '句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["江聲秋入寺（一作「峽」），雨氣（一作「色」）夜侵樓。"]', '["江声秋入寺（一作「峽」），雨氣（一作「色」）夜侵楼。"]', '诗', 'shi', '', NULL, '句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af82cb3c-898a-45c3-a81e-59fc82ad46b9', '句', '句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["閉門客到常疑（一作「如」）病，滿院花開不似（一作「未是」）貧。","（以上《雲谿友議》上《馮生佞》。","又《唐詩紀事》五六、《詩話總龜》三《知遇門》、《詩人玉屑》十《知音》、《唐才子傳》七）。"]', '["閉门客到常疑（一作「如」）病，满院花开不似（一作「未是」）貧。","（以上《云谿友議》上《馮生佞》。","又《唐诗紀事》五六、《诗話總龟》三《知遇门》、《诗人玉屑》十《知音》、《唐才子傳》七）。"]', '诗', 'shi', '', NULL, '句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca3b0f7-351b-476c-8296-2db63a84186a', '題陰陽井', '題陰陽井', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["仙人修煉地，玉井著神功。","日月雙輪見，陰陽兩竅通。","可堪清徹底，那更施無窮。","尚冀丹砂力，當澆俗慮空。","（《弘治句容縣志》八《題詠類》）。"]', '["仙人修煉地，玉井著神功。","日月雙輪见，陰陽兩竅通。","可堪清徹底，那更施無窮。","尚冀丹砂力，當澆俗慮空。","（《弘治句容縣志》八《題詠類》）。"]', '诗', 'shi', '', NULL, '題陰陽井 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ad055c-b008-46b5-8643-5792b5b05c27', '白雲潭禪院（在寧國白雲山）', '白云潭禪院（在寧国白云山）', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一片白雲千丈峯，殿略樓閣架虛空。","山僧不語捲簾坐，遙看世間如夢中。","（嘉靖《寧國府志》卷四、卷五兩見）。"]', '["一片白云千丈峯，殿略楼閣架虛空。","山僧不語捲簾坐，遙看世间如梦中。","（嘉靖《寧国府志》卷四、卷五兩见）。"]', '诗', 'shi', '', NULL, '白雲潭禪院（在寧國白雲山） 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff68291-86c7-4f89-80bc-7c0083bf5382', '晉元帝廟', '晉元帝廟', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["青山遺廟與僧鄰，斷鏃殘碑鎖暗塵。","紫蓋適符江左運，翠華空憶洛中春。","夜臺無月照珠戶，秋殿有風開玉宸。","弓劍神靈定何處？年年春綠上麒麟。","（《浩然齋雅談》（見《四庫全書》本《浩然齋雅談》卷中，四庫館臣注：「案此詩李商隱集不載，未詳所據何本，疑姓名有誤。","」）。"]', '["青山遺廟與僧鄰，斷鏃殘碑鎖暗塵。","紫蓋適符江左運，翠华空憶洛中春。","夜台無月照珠戶，秋殿有风开玉宸。","弓劍神靈定何处？年年春綠上麒麟。","（《浩然斋雅談》（见《四庫全书》本《浩然斋雅談》卷中，四庫館臣注：「案此诗李商隐集不載，未詳所據何本，疑姓名有誤。","」）。"]', '诗', 'shi', '', NULL, '晉元帝廟 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652818ca-a487-480d-849a-c124e57d2969', '缺題', '缺題', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["重午雲陰日正長，佳辰早至浴蘭湯。","涼風入座無消扇，彩索靈符映羽觴。","（《錦繡花谷別集》）。"]', '["重午云陰日正长，佳辰早至浴蘭湯。","涼风入座無消扇，彩索靈符映羽觴。","（《錦繡花谷別集》）。"]', '诗', 'shi', '', NULL, '缺題 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c12a997-dc34-4b67-bc69-49ec7e23637a', '詠雪（句）', '詠雪（句）', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["郊野鵝毛滿，江湖雁影空。","（《合璧事類》）。"]', '["郊野鵝毛满，江湖雁影空。","（《合璧事類》）。"]', '诗', 'shi', '', NULL, '詠雪（句） 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c47b2d09-015a-48cd-8098-85d81cd32c55', '詠桃（句）', '詠桃（句）', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["酥胸酣暖日，玉臉笑春風。","（《錦繡萬花谷》）。"]', '["酥胸酣暖日，玉臉笑春风。","（《錦繡万花谷》）。"]', '诗', 'shi', '', NULL, '詠桃（句） 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aace3aa4-f8df-4982-b914-cb1fc3cb1379', '桐柏觀', '桐柏观', '76eb2f1a-1acc-4ffd-a0a1-5d194f5be1c5', '唐', '["深山桐柏觀，殘雪路猶分。","數里踏紅葉，全家穿但是雲。","月寒巖障曉，風遠蕙蘭芬。","明日出雲去，吹笙不可聞。","（《古今圖書集成·山川典》一二六《桐柏山部》（見《嘉定赤城志》卷三十。","《天台前集》卷中題作《冬暮挈家宿桐拍觀》。","）。"]', '["深山桐柏观，殘雪路猶分。","數里踏紅葉，全家穿但是云。","月寒巖障晓，风远蕙蘭芬。","明日出云去，吹笙不可闻。","（《古今圖书集成·山川典》一二六《桐柏山部》（见《嘉定赤城志》卷三十。","《天台前集》卷中題作《冬暮挈家宿桐拍观》。","）。"]', '诗', 'shi', '', NULL, '桐柏觀 鄭薰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('017c2cea-1cfe-4e10-ac25-53bec19ffe82', '松江', '松江', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["松江菰葉正芳繁，張翰逢秋憶故園。","千里帆遮館娃寺，一川風暖采香村。","潮聲漸遇仙人宅，鶴市曾迷子夜魂。","我有五湖烟艇在，不堪殘日動征鞍。","（《百城烟水》四《吳江》）。"]', '["松江菰葉正芳繁，張翰逢秋憶故园。","千里帆遮館娃寺，一川风暖采香村。","潮声漸遇仙人宅，鹤市曾迷子夜魂。","我有五湖烟艇在，不堪殘日动征鞍。","（《百城烟水》四《吳江》）。"]', '诗', 'shi', '', NULL, '松江 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b45f713-78f5-4a52-93b1-5a6ce9a524d9', '題開元寺水閣（在宣州）', '題开元寺水閣（在宣州）', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["年來獨向此遊頻，謝氏青山與寺鄰。","朱檻夜飛溪路雪，碧林晴隔馬蹄塵。","波穿十里橋連寺，絮壓千家柳送春。","（《輿地紀勝》一九《寧國府》）。"]', '["年来独向此游頻，謝氏青山與寺鄰。","朱檻夜飞溪路雪，碧林晴隔马蹄塵。","波穿十里橋連寺，絮壓千家柳送春。","（《輿地紀勝》一九《寧国府》）。"]', '诗', 'shi', '', NULL, '題開元寺水閣（在宣州） 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2780bf81-6fb3-4926-9948-78aae7bb036a', '廣陵', '廣陵', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["廣陵城中饒花光，賺得英雄盡白頭。","（《國史補》曰：「進士科得之艱難，其有老死於文場者，亦無所恨。","故詩云云。","」《畫墁錄》以爲趙嘏作。","（李肇《國史補》無此則。","《唐摭言》卷一錄此二句，不云作者，《全唐詩》卷七九六收作無名氏句。","《畫墁錄》謂趙嘏作，未言所據。","）。"]', '["廣陵城中饒花光，賺得英雄尽白头。","（《国史補》曰：「進士科得之艱难，其有老死於文場者，亦無所恨。","故诗云云。","」《畫墁錄》以爲趙嘏作。","（李肇《国史補》無此則。","《唐摭言》卷一錄此二句，不云作者，《全唐诗》卷七九六收作無名氏句。","《畫墁錄》謂趙嘏作，未言所據。","）。"]', '诗', 'shi', '', NULL, '廣陵 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e11d072-0217-4f2d-9711-f76e567d3d32', '謁天柱山真君祠', '謁天柱山真君祠', '2d2359ae-7001-413d-a0dc-64dff7df0233', '唐', '["天柱吐白雲，仙宮隔青靄。","新亭皇黃家，舊封傳漢代。","猶持蘋藻奠，永荷閻閭泰。","彷彿見羣仙，凌風振青珮，仰攀丹鳳翼，俯躍蒼龍背。","暫息三峯前，還逐九霄外。","灊嶽高似掌，皖水遙疑帶。","半壁風雨來，空林鬼神會。","今我何爲者，赤紱仍皂蓋。","遠愧黃與龔，流芳及千載。","（《古今圖書集成·山川典》八六《灊山部》）（〖1〗韋曾，原列入「無世次」作者。","今考《元和姓纂》卷二韋氏西眷房有韋曾，爲萬年令光朝之子，任舒州刺史、職方）（員外郎。","《寶刻業編》卷十八載韋曾貞元二十年撰《巴郡太守嚴颜廟碑》。","《郎官石柱題名》司動員外郎有韋曾，勞格《郎官考》卷八錄山東益都元和十四年石刻《寶鞏等題名》有「裏行韋曾」字樣。","天柱山在舒州懷寧，此詩當即韋曾任舒州刺史時作。","）。"]', '["天柱吐白云，仙宮隔青靄。","新亭皇黄家，旧封傳漢代。","猶持蘋藻奠，永荷閻閭泰。","彷彿见羣仙，凌风振青珮，仰攀丹鳳翼，俯躍蒼龙背。","暫息三峯前，還逐九霄外。","灊嶽高似掌，皖水遙疑带。","半壁风雨来，空林鬼神會。","今我何爲者，赤紱仍皂蓋。","远愧黄與龔，流芳及千載。","（《古今圖书集成·山川典》八六《灊山部》）（〖1〗韋曾，原列入「無世次」作者。","今考《元和姓纂》卷二韋氏西眷房有韋曾，爲万年令光朝之子，任舒州刺史、職方）（員外郎。","《寶刻業編》卷十八載韋曾貞元二十年撰《巴郡太守嚴颜廟碑》。","《郎官石柱題名》司动員外郎有韋曾，勞格《郎官考》卷八錄山东益都元和十四年石刻《寶鞏等題名》有「裏行韋曾」字樣。","天柱山在舒州懷寧，此诗當即韋曾任舒州刺史时作。","）。"]', '诗', 'shi', '', NULL, '謁天柱山真君祠 韋曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612c4670-eb52-4bb9-811f-d5feef9203d6', '丫髻岩', '丫髻岩', '549bbfcb-c99e-429e-b419-017a33597c17', '唐', '["丫髻山頭殘月，臘岩洞口斜陽。","啼鳥喚人歸去，此身猶在他鄉。","（同上《職方典》一○二六《溫州府部》）（〖1〗韋膺，原列入「無世次」作者。","今考《新唐書》卷七四《宰相世系表》韋氏逍遙公房有韋膺，爲衢州刺史光輔之子。","《元和姓纂》卷二載光輔爲京兆杜陵人，任大理少卿。","《唐會要》卷六六載光輔大曆十年任太府少卿，《寶刻業編》卷十三載其貞元三年任衢州刺史。","可知韋膺應爲貞元以後人。","嘉靖《瑞安縣志》卷九有刺史韋庸，喜慶《浙江通志》卷一一二載韋鏞，宣宗時任溫州刺史，同書卷一五六引《明一統志》云會昌中溫州刺史韋庸興水利而爲民所頌，何誤。","其任溫州刺史的時間，當從《唐刺史考》作會昌中爲是。","〖參張忱石考證〗）。"]', '["丫髻山头殘月，臘岩洞口斜陽。","啼鸟喚人归去，此身猶在他乡。","（同上《職方典》一○二六《溫州府部》）（〖1〗韋膺，原列入「無世次」作者。","今考《新唐书》卷七四《宰相世系表》韋氏逍遙公房有韋膺，爲衢州刺史光輔之子。","《元和姓纂》卷二載光輔爲京兆杜陵人，任大理少卿。","《唐會要》卷六六載光輔大曆十年任太府少卿，《寶刻業編》卷十三載其貞元三年任衢州刺史。","可知韋膺應爲貞元以後人。","嘉靖《瑞安縣志》卷九有刺史韋庸，喜慶《浙江通志》卷一一二載韋鏞，宣宗时任溫州刺史，同书卷一五六引《明一統志》云會昌中溫州刺史韋庸兴水利而爲民所頌，何誤。","其任溫州刺史的时间，當從《唐刺史考》作會昌中爲是。","〖參張忱石考證〗）。"]', '诗', 'shi', '', NULL, '丫髻岩 韋膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('874f7878-7fc1-4542-a394-d66f758c594e', '行桐柏山', '行桐柏山', 'ea818f0d-74e7-4dc8-8099-17cb16c53e37', '唐', '["際海禮冰碧，穿雲來玉清。","千山盤鳥道，十里入猿聲。","草木飄香異，雲霞引步輕。","誰言鼇頂上，此處是蓬瀛。","（《古今圖書集成·山川典》一二六《桐拍山部》）。"]', '["際海禮冰碧，穿云来玉清。","千山盤鸟道，十里入猿声。","草木飄香異，云霞引步轻。","誰言鼇頂上，此处是蓬瀛。","（《古今圖书集成·山川典》一二六《桐拍山部》）。"]', '诗', 'shi', '', NULL, '行桐柏山 姚鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('053a7435-5b88-4c45-ab8d-d9f822dca24c', '過灊嶽', '過灊嶽', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["塞上徵兵久，淮南賦歛多。","抱琴方此去，爲縣欲如何。","灊嶽積蒼翠，皖溪生素波。","真君松廟近，公退爲誰過？","（《古今圖書集成·山川典》八六《灊山部）。"]', '["塞上徵兵久，淮南賦歛多。","抱琴方此去，爲縣欲如何。","灊嶽積蒼翠，皖溪生素波。","真君松廟近，公退爲誰過？","（《古今圖书集成·山川典》八六《灊山部）。"]', '诗', 'shi', '', NULL, '過灊嶽 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8dc72a8-038e-41be-b4d0-c52f6f3cb32c', '方城懷古（句）', '方城懷古（句）', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["申胥枉向秦庭哭，靳尚終貽楚國羞。","（《唐語林》二《文學》〖1〗○今按：《全唐詩》五五六缺題，又無出處。","）（〖1〗此則出《金華子雜編》，見原本《說郛》卷十一，《四庫全書》輯本《金華子雜編》失收。","）。"]', '["申胥枉向秦庭哭，靳尚終貽楚国羞。","（《唐語林》二《文学》〖1〗○今按：《全唐诗》五五六缺題，又無出处。","）（〖1〗此則出《金华子杂編》，见原本《说郛》卷十一，《四庫全书》輯本《金华子杂編》失收。","）。"]', '诗', 'shi', '', NULL, '方城懷古（句） 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9193a4-42fc-4846-88a1-5478386b95b1', '題銅官山廟（靈祐王祠在銅官山）', '題銅官山廟（靈祐王祠在銅官山）', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["潯陽賢太守，遺廟古溪邊。","樹影入流水，石門當洞天。","幡花凝寶座，香案儼爐煙。","若到千年後，重修事宛然。","（《嘉靖銅陵縣志》八、又《嘉靖池州府志》五）。"]', '["潯陽賢太守，遺廟古溪邊。","樹影入流水，石门當洞天。","幡花凝寶座，香案儼爐煙。","若到千年後，重修事宛然。","（《嘉靖銅陵縣志》八、又《嘉靖池州府志》五）。"]', '诗', 'shi', '', NULL, '題銅官山廟（靈祐王祠在銅官山） 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25cf8191-9e7c-4de0-b104-a7ea01d1accd', '白鹿寺釋迦瑞相詩', '白鹿寺釋迦瑞相诗', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["無相無虧有相圓，多生檀越種因緣。","三千境見閻浮土，丈六身留兜率天。","紺目輝騰滄海月，玉毫光射寶爐煙。","道人參到非非處，不是丹霞破佛禪。","（《同治湖南通志》二三八《方外志·寺觀·益陽縣》）。"]', '["無相無虧有相圓，多生檀越種因緣。","三千境见閻浮土，丈六身留兜率天。","紺目輝腾滄海月，玉毫光射寶爐煙。","道人參到非非处，不是丹霞破佛禪。","（《同治湖南通志》二三八《方外志·寺观·益陽縣》）。"]', '诗', 'shi', '', NULL, '白鹿寺釋迦瑞相詩 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a47d24-68fa-4a56-83bb-e0f5825f979a', '東林寺', '东林寺', '17772329-329e-466a-a146-cf74d2b01835', '唐', '["駐斾息東林，清泉洗病心。","爐峯霄漢近，煙樹荔蘿陰。","溪浚龍蛇隱，喦高雨露侵。","猿聲雲壑斷，罄韻竹房深。","欲問吾師法，衰年力不任。","（《永樂大典》六六九九江字韻引《江州志》）（〖1〗張毅夫，原列「無世次」作者。","今檢《舊唐書》卷一六二《張正甫傳》附其事迹，節引如次：毅夫，南陽人。","正甫之子。","登進士第，位至戶部侍郎、弘文館學士判院事。","《唐僕尚丞郎表》卷三謂其任戶部侍郎約在咸通間。","《舊唐書·宣宗紀》載其大中十一年四月自江西觀察使爲京兆尹，十二年正月出爲鄂岳觀察使。","）。"]', '["駐斾息东林，清泉洗病心。","爐峯霄漢近，煙樹荔蘿陰。","溪浚龙蛇隐，喦高雨露侵。","猿声云壑斷，罄韻竹房深。","欲问吾師法，衰年力不任。","（《永乐大典》六六九九江字韻引《江州志》）（〖1〗張毅夫，原列「無世次」作者。","今檢《旧唐书》卷一六二《張正甫傳》附其事迹，節引如次：毅夫，南陽人。","正甫之子。","登進士第，位至戶部侍郎、弘文館学士判院事。","《唐僕尚丞郎表》卷三謂其任戶部侍郎約在咸通间。","《旧唐书·宣宗紀》載其大中十一年四月自江西观察使爲京兆尹，十二年正月出爲鄂岳观察使。","）。"]', '诗', 'shi', '', NULL, '東林寺 張毅夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('839b5456-9e6c-4e02-aad1-f480b4162a4b', '句', '句', 'c9649f8f-23ba-49b9-aa91-5be696f16a68', '唐', '["春遊雞鹿塞，家在鷓鴣天。","（《藝需要伐山》十八）。"]', '["春游雞鹿塞，家在鷓鴣天。","（《藝需要伐山》十八）。"]', '诗', 'shi', '', NULL, '句 鄭嵎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fd1ad68-cc34-4b3d-bd17-30cd99231e1c', '寄鄭碏疊石硯歌', '寄鄭碏叠石硯歌', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["媧皇補天殘錦片，飛落人間爲石硯。","孤峯削疊一尺雲，虎幹熊跪勢皆徧。","半掬走泉澄淺清，洞天徹底寒泓泓。","筆頭搶起松烟輕，龍蛇怒閗秋雲生。","我今得此以代耕，如探禹穴披峥嶸。","披峥嶸，心骨驚，坐中髣髴到蓬瀛。","（《文房四譜》三《硯譜》）。"]', '["媧皇補天殘錦片，飞落人间爲石硯。","孤峯削叠一尺云，虎幹熊跪勢皆徧。","半掬走泉澄淺清，洞天徹底寒泓泓。","笔头搶起松烟轻，龙蛇怒閗秋云生。","我今得此以代耕，如探禹穴披峥嶸。","披峥嶸，心骨驚，坐中髣髴到蓬瀛。","（《文房四譜》三《硯譜》）。"]', '诗', 'shi', '', NULL, '寄鄭碏疊石硯歌 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a40d6c1-b9af-4031-a9ed-34641dc6a37b', '明月湖醉後薔薇花歌（《文苑英華》三三七《歌行》。《全唐詩》七八五無名氏第一首）（〖1〗《文苑英華》錄詩皆署作者姓名，不署字，此說恐未允。）', '明月湖醉後薔薇花歌（《文苑英华》三三七《歌行》。《全唐诗》七八五無名氏第一首）（〖1〗《文苑英华》錄诗皆署作者姓名，不署字，此说恐未允。）', 'fdefaf65-1191-45df-82c0-e1c4851c969e', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '明月湖醉後薔薇花歌（《文苑英華》三三七《歌行》。《全唐詩》七八五無名氏第一首）（〖1〗《文苑英華》錄詩皆署作者姓名，不署字，此說恐未允。） 英才 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df6c5884-5f1f-4690-83a6-a13724a8c171', '石榴歌', '石榴歌', 'c12f6abd-96a3-4480-87a9-4cf1ce2a2a68', '唐', '["玳瑁殻皴枝婀娜，馬牙硝骨綿敷裏。","霜風擊破錦香囊，鸚鵡啄殘紅豆顆。","美人擎在金盤腹，錯認海螺斑碌碌。","滿口含嘗瓊液甘，一堂齒冷敲寒玉。","（《古今圖書集成·草木典》二八二《石榴部》〖1〗）（〖1〗此詩見宋祝穆《事文類聚後集》卷二六、陳景沂《全芳備祖後集》卷六。","）。"]', '["玳瑁殻皴枝婀娜，马牙硝骨綿敷裏。","霜风擊破錦香囊，鸚鵡啄殘紅豆顆。","美人擎在金盤腹，錯認海螺斑碌碌。","满口含嘗瓊液甘，一堂齒冷敲寒玉。","（《古今圖书集成·草木典》二八二《石榴部》〖1〗）（〖1〗此诗见宋祝穆《事文類聚後集》卷二六、陳景沂《全芳備祖後集》卷六。","）。"]', '诗', 'shi', '', NULL, '石榴歌 莊布 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('566860d2-1939-443a-8f2f-a7ab925d329e', '四面寺瀑布', '四面寺瀑布', '8ad429a5-89c5-42c6-a515-c5ed62cfdf5c', '唐', '["穿山度石不辭勞，到底還他地步高。","溪澗豈能留得住，終層大海作波濤。","（《古今圖書集·職方典》七八五《安慶府部》。","又《全唐詩》以前二句爲黃蘗禪師聯句，且文字多不同。","）。"]', '["穿山度石不辞勞，到底還他地步高。","溪澗豈能留得住，終層大海作波濤。","（《古今圖书集·職方典》七八五《安慶府部》。","又《全唐诗》以前二句爲黄蘗禪師聯句，且文字多不同。","）。"]', '诗', 'shi', '', NULL, '四面寺瀑布 李忱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3edbc59-8bd3-4114-88b1-ec12721de573', '贈隱者', '贈隐者', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楚客隱名姓，圍碁當薜蘿。","亂溪藏釣石，一鶴在庭柯。","敗堰水聲急，破窗山色多。","南軒新竹逕，應許子猷過。","（《又玄集》中）。"]', '["楚客隐名姓，圍碁當薜蘿。","亂溪藏釣石，一鹤在庭柯。","敗堰水声急，破窗山色多。","南軒新竹逕，應許子猷過。","（《又玄集》中）。"]', '诗', 'shi', '', NULL, '贈隱者 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5356e7c-2423-427b-af40-05a9c3fe89db', '蜂蝶（句）', '蜂蝶（句）', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蜜官金翼使，花賊玉腰奴。","（《清異錄》三）。"]', '["蜜官金翼使，花賊玉腰奴。","（《清異錄》三）。"]', '诗', 'shi', '', NULL, '蜂蝶（句） 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a2410a-da7a-4c9b-9cde-1b93da40faf6', '與溫庭筠雲藍紙絕句（幷序。詩見《全唐詩》五八四。現補序）', '與溫庭筠云藍紙絕句（幷序。诗见《全唐诗》五八四。現補序）', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["一日辱飛卿九寸小紙，兩行親書，云要采箋十番，錄少詩「稿」（爲）。","予有雜箋數角，多抽揀與人，既玩之輕明，復用殊麻滑。","尚愧大庾所得，猶至四百枚，豈及右軍不節，盡付九萬幅。","因知碧雲棋上，重翻懊惱之辭，紅葉溝中，更擬相思之曲。","固應桑根作本，藤角爲封，古拙不重蔡侯，新樣偏饒桓氏。","何啻奔墨馳騁，有貴長簾，下筆縱橫，偏求側理。","所恨無色如鴨卵，狀如馬肝，稱寫《璇璣》，且題裂帛者。","予在九江，出意造雲藍紙。","既乏左伯之法，全無張永之功。","輙分五十枚，並絕句一首，或得閑中暫當藥餌也。","（原注：今《飛卿集》中有《播掿詞》○蘇易簡《文房四譜》四《紙譜》。","〖1〗）（〖1〗據《知不足齋業書》本《文房四譜》校改。","另「碧雲棋上」，作「碧聯棋上」；「裂帛」，作「裂錦」；「全無張永之功」之「全」字作「今」字。","）。"]', '["一日辱飞卿九寸小紙，兩行親书，云要采箋十番，錄少诗「稿」（爲）。","予有杂箋數角，多抽揀與人，既玩之轻明，复用殊麻滑。","尚愧大庾所得，猶至四百枚，豈及右軍不節，尽付九万幅。","因知碧云棋上，重翻懊惱之辞，紅葉溝中，更擬相思之曲。","固應桑根作本，藤角爲封，古拙不重蔡侯，新樣偏饒桓氏。","何啻奔墨驰騁，有貴长簾，下笔縱橫，偏求側理。","所恨無色如鴨卵，狀如马肝，稱寫《璇璣》，且題裂帛者。","予在九江，出意造云藍紙。","既乏左伯之法，全無張永之功。","輙分五十枚，並絕句一首，或得闲中暫當藥餌也。","（原注：今《飞卿集》中有《播掿词》○蘇易簡《文房四譜》四《紙譜》。","〖1〗）（〖1〗據《知不足斋業书》本《文房四譜》校改。","另「碧云棋上」，作「碧聯棋上」；「裂帛」，作「裂錦」；「全無張永之功」之「全」字作「今」字。","）。"]', '诗', 'shi', '', NULL, '與溫庭筠雲藍紙絕句（幷序。詩見《全唐詩》五八四。現補序） 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9057d892-a95b-4806-a8d3-268d4ec40a84', '老僧續得貴妃襪（李羣玉同作）', '老僧續得貴妃襪（李羣玉同作）', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["墜仙遺襪老僧收，一鎖金函八十秋。","霞色尚鮮宮錦靿，彩光依舊夾羅頭。","輕香爲著紅酥踐，微絢曾經玉指搆。","三十六宮歌舞地，唯君獨步占風流。","（《青瑣高議前集》六）。"]', '["墜仙遺襪老僧收，一鎖金函八十秋。","霞色尚鲜宮錦靿，彩光依旧夾羅头。","轻香爲著紅酥踐，微絢曾經玉指搆。","三十六宮歌舞地，唯君独步占风流。","（《青瑣高議前集》六）。"]', '诗', 'shi', '', NULL, '老僧續得貴妃襪（李羣玉同作） 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e476ed3-ecb1-40b3-a769-a4e63aeaa3d6', '李遠獲貴妃襪（各賦詩一首）', '李远獲貴妃襪（各賦诗一首）', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["故物存事渺茫，把來忍見舊時香。","抝連綺錦分奇樣，終合飛蟬飲瑞光。","常束凝酥迷聖主，應隨玉步浴溫湯。","如今落在吾兄手，無限幽情付本子郎。","（《青瑣高議前集》六）。"]', '["故物存事渺茫，把来忍见旧时香。","抝連綺錦分奇樣，終合飞蟬饮瑞光。","常束凝酥迷聖主，應隨玉步浴溫湯。","如今落在吾兄手，無限幽情付本子郎。","（《青瑣高議前集》六）。"]', '诗', 'shi', '', NULL, '李遠獲貴妃襪（各賦詩一首） 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ed4663-a493-4bc6-8b91-7f11d916eb71', '滄洲〖1〗', '滄洲〖1〗', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["童兒待郭伋，竹馬空遲留。","路指雲漢津，誰能吟《四愁》。","銀壺傲海雪，青管羅名謳。","賤子跡未安，謀身拙如鳩。","分隨煙霞老，豈有風雲求。","不逐萬物化，但貽知己羞。","方窮力命說，戰勝心悠悠。","不然蹲會稽，鈎下二五牛。","所期波濤助，燀赫呈吞舟。","（四部業刊影宋本《李羣玉詩便攜集》卷上）（〖1〗《全唐詩》卷五六八收作《洞庭驛樓雪讌集奉贈前湘州張員外》之後半篇，似誤。","王安石《唐百家詩選》卷十七亦以此詩自爲一首。","）。"]', '["童兒待郭伋，竹马空遲留。","路指云漢津，誰能吟《四愁》。","銀壺傲海雪，青管羅名謳。","賤子跡未安，謀身拙如鳩。","分隨煙霞老，豈有风云求。","不逐万物化，但貽知己羞。","方窮力命说，戰勝心悠悠。","不然蹲會稽，鈎下二五牛。","所期波濤助，燀赫呈吞舟。","（四部業刊影宋本《李羣玉诗便携集》卷上）（〖1〗《全唐诗》卷五六八收作《洞庭驛楼雪讌集奉贈前湘州張員外》之後半篇，似誤。","王安石《唐百家诗選》卷十七亦以此诗自爲一首。","）。"]', '诗', 'shi', '', NULL, '滄洲〖1〗 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23fcb656-68f0-482c-af27-dced092fc664', '送羣玉歸別業（句）', '送羣玉归別業（句）', '1cc57c5b-3b0a-457c-b619-f97e8e2a1c76', '唐', '["秦樹有殘蟬，灃浦將歸客。","（《輿地紀勝》七十《灃州》）（〖1〗作者原作「李朝士、李壽朋」。","檢《輿地紀勝》原文作「唐季朝士李壽朋」知李壽朋爲唐末朝士，非另有「李朝士」其人。","茲刪去「李朝士」三字。","）。"]', '["秦樹有殘蟬，灃浦將归客。","（《輿地紀勝》七十《灃州》）（〖1〗作者原作「李朝士、李壽朋」。","檢《輿地紀勝》原文作「唐季朝士李壽朋」知李壽朋爲唐末朝士，非另有「李朝士」其人。","茲刪去「李朝士」三字。","）。"]', '诗', 'shi', '', NULL, '送羣玉歸別業（句） 李壽朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fed5f9f-2ec9-47ef-ba10-a02d9e66a990', '送羣玉（句）', '送羣玉（句）', '07c1e1a9-7d0d-4770-b9f8-92ee63f92d52', '唐', '["濡毫亂灑湘江月，整棹輕飛灃浦船。","（同上）。"]', '["濡毫亂灑湘江月，整棹轻飞灃浦船。","（同上）。"]', '诗', 'shi', '', NULL, '送羣玉（句） 韓續 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('726cea4b-aabe-446c-9339-3c942dc7163c', '望南郡城（《全唐詩》引《方輿勝覽》缺題）', '望南郡城（《全唐诗》引《方輿勝覽》缺題）', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["楚地八千里，槃槃此都會。","巍峨數里城，遠水霜映帶。","（《輿地紀勝》六五《江陵府》）。"]', '["楚地八千里，槃槃此都會。","巍峨數里城，远水霜映带。","（《輿地紀勝》六五《江陵府》）。"]', '诗', 'shi', '', NULL, '望南郡城（《全唐詩》引《方輿勝覽》缺題） 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e057302-5276-40c4-b104-3b7066b44398', '寄舊友西乾耕隱童先輩', '寄旧友西乾耕隐童先輩', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["種竹參差長，栽松次第成。","戎衣遍江漢，未厭子真耕。","（《四部業刊三編》影明抄本《梨嶽詩集·輯補》（原注：「右見徐璈刊本。","」）。"]', '["種竹參差长，栽松次第成。","戎衣遍江漢，未厭子真耕。","（《四部業刊三編》影明抄本《梨嶽诗集·輯補》（原注：「右见徐璈刊本。","」）。"]', '诗', 'shi', '', NULL, '寄舊友西乾耕隱童先輩 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a93d3b1-6c03-4196-94e0-df08d2f2af9d', '送春', '送春', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["無語共春別，細腰枝上紅。","來年又相見，還恐是愁中。","（江標影刻宋本《唐五十家小集》）。"]', '["無語共春別，細腰枝上紅。","来年又相见，還恐是愁中。","（江標影刻宋本《唐五十家小集》）。"]', '诗', 'shi', '', NULL, '送春 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f2489cf-0e1c-4110-bbf6-2cb24216c5b3', '九華樓', '九华楼', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["東門帶溪路，上有三丈樓。","層基接重阜，一覽山水周。","天邊九芙蓉，出沒不可求。","鴻驚曉霜凈，花明雨初收。","巉然倚圭璧，爽氣凌尊籌。","主人金閨彦高興思窮幽。","時來據繩床，山色供遠眸。","危峯曳遊雲，嶺月懸曲鈞。","吟嘨意不淺，浩然追軻丘。","明年雞省夢，肯忘江上州。"]', '["东门带溪路，上有三丈楼。","層基接重阜，一覽山水周。","天邊九芙蓉，出沒不可求。","鴻驚晓霜凈，花明雨初收。","巉然倚圭璧，爽氣凌尊籌。","主人金閨彦高兴思窮幽。","时来據繩床，山色供远眸。","危峯曳游云，嶺月懸曲鈞。","吟嘨意不淺，浩然追軻丘。","明年雞省梦，肯忘江上州。"]', '诗', 'shi', '', NULL, '九華樓 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c03145-5fcb-421a-a48f-81c79304d121', '樓望', '楼望', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["樓高九華近，極目望峯頂。","雲破松風寒，路濃山色迥。","古剎軒層簷，白水浮小艇。","願結一間茅，歸來就丹鼎。","（以上《嘉靖池州府志》八）。"]', '["楼高九华近，極目望峯頂。","云破松风寒，路濃山色迥。","古剎軒層簷，白水浮小艇。","願結一间茅，归来就丹鼎。","（以上《嘉靖池州府志》八）。"]', '诗', 'shi', '', NULL, '樓望 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55355aa-8bbe-4a83-8d5f-294863f5b8ca', '贈妓（相牧廬州，有朝客留意飲妓，祖送短亭，妓車後至，相贈之曰：）', '贈妓（相牧廬州，有朝客留意饮妓，祖送短亭，妓车後至，相贈之曰：）', '4743646b-0a05-45bc-8d96-2b27f21aeadb', '唐', '["望斷蘇娘小小坡，竹埿金雁展輕莎。","客卿幸有凝情意，何必臨尊始轉波？","（《詩話總龜》二三《寓情門》引《唐賢抒情》）（〖1〗敬相，當作敬湘。","《新唐書·宰相世系表五上》敬氏有「湘，廬州刺史」，爲敬括曾孫。","《郎官石柱題名考》卷十六金部員外郎有敬湘，約咸通末年任。","原列「無世次」作者，今移此。","）。"]', '["望斷蘇娘小小坡，竹埿金雁展轻莎。","客卿幸有凝情意，何必臨尊始轉波？","（《诗話總龟》二三《寓情门》引《唐賢抒情》）（〖1〗敬相，當作敬湘。","《新唐书·宰相世系表五上》敬氏有「湘，廬州刺史」，爲敬括曾孫。","《郎官石柱題名考》卷十六金部員外郎有敬湘，約咸通末年任。","原列「無世次」作者，今移此。","）。"]', '诗', 'shi', '', NULL, '贈妓（相牧廬州，有朝客留意飲妓，祖送短亭，妓車後至，相贈之曰：） 敬相 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92952b4f-e235-4f95-aeed-f45b3cc15360', '泛石岐海', '泛石岐海', '56355a6f-287b-4a28-ae04-3ab685c5d112', '唐', '["此日攜琴劍，飄然事遠遊。","臺山初罷霧，岐海正分流。","漁浦颺來笛，鴻逵翼去舟。","鬂愁蒲柳早，衣怯芰荷秋。","未卜虞翻宅，休登王粲樓，愴然懷伴侶，徒爾賦離憂。","（《嘉慶廣東通志》一○一《山川略·香山縣》）（〖1〗《全唐詩》卷五九七收「臺山」以下四句，題爲《幼作》。","）。"]', '["此日携琴劍，飄然事远游。","台山初罷霧，岐海正分流。","漁浦颺来笛，鴻逵翼去舟。","鬂愁蒲柳早，衣怯芰荷秋。","未卜虞翻宅，休登王粲楼，愴然懷伴侶，徒爾賦離憂。","（《嘉慶廣东通志》一○一《山川略·香山縣》）（〖1〗《全唐诗》卷五九七收「台山」以下四句，題爲《幼作》。","）。"]', '诗', 'shi', '', NULL, '泛石岐海 鄭愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('764c17b8-fa53-489e-bba0-805797ea424b', '春日遊南山（句）', '春日游南山（句）', 'b5ef68c5-c241-41aa-a1d1-b37afac70df3', '唐', '["屏開十里畫，江渡兩歧風。","（《輿地紀勝》一五四《潼川府》）。"]', '["屏开十里畫，江渡兩歧风。","（《輿地紀勝》一五四《潼川府》）。"]', '诗', 'shi', '', NULL, '春日遊南山（句） 劉蛻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f0dc253-16a7-4170-83f7-8a894db55b37', '武侯墓', '武侯墓', '77c5d63b-d6d7-402e-bf09-0c768c2780de', '唐', '["動業伊周亞，經綸楚漢前。","有才真命世，無地與中天。","大統《春秋》意，謄章《說命篇》。","吾家子房後，千載英賢。","（《關中勝蹟圖志》二十二《漢中府·古蹟·郊邑》）。"]', '["动業伊周亞，經綸楚漢前。","有才真命世，無地與中天。","大統《春秋》意，謄章《说命篇》。","吾家子房後，千載英賢。","（《关中勝蹟圖志》二十二《漢中府·古蹟·郊邑》）。"]', '诗', 'shi', '', NULL, '武侯墓 張演 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71732ac5-a5c5-4f7e-b163-8c88f7f5b4cd', '贈劉郎中', '贈劉郎中', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["東南秀氣動文星，天子應教掃內庭。","湘渚雪晴弧鶴唳，錦江雲盡一峰青。","仁含楚樹花先發，爽照賓「筵」□□□。","□□定宜端劍珮，上仙風骨紫蘭馨。"]', '["东南秀氣动文星，天子應教掃內庭。","湘渚雪晴弧鹤唳，錦江云尽一峰青。","仁含楚樹花先發，爽照賓「筵」□□□。","□□定宜端劍珮，上仙风骨紫蘭馨。"]', '诗', 'shi', '', NULL, '贈劉郎中 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432d2498-b100-4b19-9df5-dc5f147d124a', '題水精釵', '題水精釵', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["脉脉兩條秋水色，農夫賤賣古城旁。","何年偶墮青絲髮，問價應齊白玉璫。","插去定難分鏡彩，看時長似滴珠光。","人間更有不足貴，金雀徒誇十二行。"]', '["脉脉兩條秋水色，農夫賤賣古城旁。","何年偶墮青絲髮，问價應齊白玉璫。","插去定难分镜彩，看时长似滴珠光。","人间更有不足貴，金雀徒誇十二行。"]', '诗', 'shi', '', NULL, '題水精釵 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fbabd35-53d0-4865-a2c7-70eeccc2f3e7', '放鷓鴣', '放鷓鴣', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["玉樓珠戶養經時，放出雕籠久不飛。","秦地遊僧一彈指，楚城遷客重思歸。","崗田戲下晴風暖，茅壠驚啼返照微。","山畔家家有羅網，莫教傷損好毛衣。"]', '["玉楼珠戶養經时，放出雕籠久不飞。","秦地游僧一彈指，楚城遷客重思归。","崗田戲下晴风暖，茅壠驚啼返照微。","山畔家家有羅網，莫教傷損好毛衣。"]', '诗', 'shi', '', NULL, '放鷓鴣 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd835b3-9f8c-4adb-bb36-34da1132a2a4', '渡淮後却泗州秦處士', '渡淮後却泗州秦处士', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["淮上風吹別酒醒，淮南潮落見沙汀。","正愁客路逢山雨，更憶雲外臥草亭。","野鷺獨飛仙嶂綠，農田□植晚苗青。","何人得及秦居士，藥化丹砂劍有靈。","。"]', '["淮上风吹別酒醒，淮南潮落见沙汀。","正愁客路逢山雨，更憶云外臥草亭。","野鷺独飞仙嶂綠，農田□植晚苗青。","何人得及秦居士，藥化丹砂劍有靈。","。"]', '诗', 'shi', '', NULL, '渡淮後却泗州秦處士 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091be757-bc63-4180-b62a-fc65c7a2851c', '山中', '山中', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["清濁山中一氣分，洞中仙籟靜時聞。","竹花生□□□□，桑葉抱風蠒蛾紛紛。","夜月泛琴絃似磬，秋潭洗硯墨成雲。","海邊兄弟無音息，斜日愁看綠嶠曛。"]', '["清濁山中一氣分，洞中仙籟静时闻。","竹花生□□□□，桑葉抱风蠒蛾紛紛。","夜月泛琴絃似磬，秋潭洗硯墨成云。","海邊兄弟無音息，斜日愁看綠嶠曛。"]', '诗', 'shi', '', NULL, '山中 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2fe0e3b-75a8-46bb-a589-28402391040f', '送友生下第出關', '送友生下第出关', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["天牓無名玉未焚，幾飄凝淚泣青雲。","挈將孤劍家何在，叫斷重閽帝不聞。","花笑旅人惟賴酒，鏡欺雙鬢莫言文。","糟床滴瀝餘聲盡，典重裘又送君。"]', '["天牓無名玉未焚，幾飄凝泪泣青云。","挈將孤劍家何在，叫斷重閽帝不闻。","花笑旅人惟賴酒，镜欺雙鬢莫言文。","糟床滴瀝餘声尽，典重裘又送君。"]', '诗', 'shi', '', NULL, '送友生下第出關 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b784150e-f7de-40dc-9f9f-7361e088105a', '早春送友人歸江南', '早春送友人归江南', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["洞庭歸客莫相催，予憶滄江久未迥。","歸渡遇霜楊柳盡，寒郊欲雪鶺鴒來。","舟依青路帆初挂，鳥出紅塵眼漸開。","千里同來不同去，莫驚愁淚濺離杯。"]', '["洞庭归客莫相催，予憶滄江久未迥。","归渡遇霜楊柳尽，寒郊欲雪鶺鴒来。","舟依青路帆初挂，鸟出紅塵眼漸开。","千里同来不同去，莫驚愁泪濺離杯。"]', '诗', 'shi', '', NULL, '早春送友人歸江南 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('773a6774-bd36-4cb4-ae05-1adb4e1d3f53', '讀《漢武內傳》', '读《漢武內傳》', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["雲錦囊開得畫圖，岳神森聳耀靈軀。","青真小童捧訣籙，紫府道士攜瓊蘇。","金鼎未成悲濁世，玉緘時捧望青都。","一辭姥長昏醉，方朔留言盡記無。"]', '["云錦囊开得畫圖，岳神森聳耀靈軀。","青真小童捧訣籙，紫府道士携瓊蘇。","金鼎未成悲濁世，玉緘时捧望青都。","一辞姥长昏醉，方朔留言尽記無。"]', '诗', 'shi', '', NULL, '讀《漢武內傳》 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b08685-f43f-4628-b048-3e3e9cd91849', '不睡', '不睡', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["沃洲山裏苦心人，十五年來少睡身。","詩句每多閒夜得，鬢毛終爲半愁新。","紛紛落燼看將久，歷歷寒更聽轉頻。","家寄江南斷音信，一憑歸夢去無因。","。"]', '["沃洲山裏苦心人，十五年来少睡身。","诗句每多閒夜得，鬢毛終爲半愁新。","紛紛落燼看將久，歷歷寒更听轉頻。","家寄江南斷音信，一憑归梦去無因。","。"]', '诗', 'shi', '', NULL, '不睡 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e502cd8-2f7e-4295-b7e4-7f2b8f096fcb', '春晚思江上舊遊寄城中知己', '春晚思江上旧游寄城中知己', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["一春江上好韶光，劉阮相隨醉幾場。","令節輕雲著羅綺，曉天晴色在壺觴。","紫雲樓畔金絲發，紅杏園中玉輦香。"]', '["一春江上好韶光，劉阮相隨醉幾場。","令節轻云著羅綺，晓天晴色在壺觴。","紫云楼畔金絲發，紅杏园中玉輦香。"]', '诗', 'shi', '', NULL, '春晚思江上舊遊寄城中知己 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743a7a15-e568-4874-86c3-4d19741d0d54', '寄友人乞菊栽（〖1〗《全唐詩》八八四有缺字。第五句「及」《石渠寶笈》作「近」，第七句《全唐詩》缺首字「孺」，末句「鳩」《石渠寶笈》作「鴛」。）', '寄友人乞菊栽（〖1〗《全唐诗》八八四有缺字。第五句「及」《石渠寶笈》作「近」，第七句《全唐诗》缺首字「孺」，末句「鳩」《石渠寶笈》作「鴛」。）', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '寄友人乞菊栽（〖1〗《全唐詩》八八四有缺字。第五句「及」《石渠寶笈》作「近」，第七句《全唐詩》缺首字「孺」，末句「鳩」《石渠寶笈》作「鴛」。） 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61ffad51-10f8-40de-a5ec-876977771e2d', '送澗水陜東二十里自江南來作', '送澗水陜东二十里自江南来作', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["泠泠孤澗陜城東，我有飛泉此路通。","行客莫驚黃葉盡，家山祇在白雲中。","秋聲可亂鳥魚意，遠色偏依蒲稗業。","過去多應不相待，殷勤重掬洒西風。"]', '["泠泠孤澗陜城东，我有飞泉此路通。","行客莫驚黄葉尽，家山祇在白云中。","秋声可亂鸟鱼意，远色偏依蒲稗業。","過去多應不相待，殷勤重掬洒西风。"]', '诗', 'shi', '', NULL, '送澗水陜東二十里自江南來作 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d260bae-68fc-47ae-9820-9f79af1d3a6f', '五湖冬日', '五湖冬日', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["楚人家住五湖東，斜掩柴門水石中。","獵獵夜山明遠燒，騷騷寒葦動疎風。","園林向臘停霜果，葭菼和烟宿暝鴻。","范蠡扁舟不知處，一將前事話漁翁。"]', '["楚人家住五湖东，斜掩柴门水石中。","獵獵夜山明远燒，騷騷寒葦动疎风。","园林向臘停霜果，葭菼和烟宿暝鴻。","范蠡扁舟不知处，一將前事話漁翁。"]', '诗', 'shi', '', NULL, '五湖冬日 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a462602-8b46-42a9-a64a-753dd1d2a7e9', '江南冬日喜遇故人', '江南冬日喜遇故人', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["江南木落塞鴻飛，江漢離人久未歸。","客舍無成重相見，雪天留宿可相違。","篇章只使容颜改，名利空教翰墨稀。","終擬全家漾舟去，五湖高掩白雲扉。"]', '["江南木落塞鴻飞，江漢離人久未归。","客舍無成重相见，雪天留宿可相違。","篇章只使容颜改，名利空教翰墨稀。","終擬全家漾舟去，五湖高掩白云扉。"]', '诗', 'shi', '', NULL, '江南冬日喜遇故人 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aedaa700-4818-4eb7-b024-35d518fe63a2', '春夜', '春夜', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["街鼓初殘百八聲，小園芳樹宿孤鶯。","人迴野寺昏醉，月照閑房悄悄明。","杏酪香濃寒食近，梨花影散夜風輕。","誰家靜捻參差管，一曲《霓裳》學鳳清。"]', '["街鼓初殘百八声，小园芳樹宿孤鶯。","人迴野寺昏醉，月照闲房悄悄明。","杏酪香濃寒食近，梨花影散夜风轻。","誰家静捻參差管，一曲《霓裳》学鳳清。"]', '诗', 'shi', '', NULL, '春夜 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af63259-523e-4187-af03-ba18c8ba04d8', '雨夜', '雨夜', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["蛩聲雨思夜迢迢，空館何人問寂寥。","寒燭細烟搖寢幌，濕螢微影綴芭蕉。","正當孤枕鴻初過，況復窮居葉盡凋。","閒憶秋江釣船裏，洒篷沾浪聽蕭蕭。"]', '["蛩声雨思夜迢迢，空館何人问寂寥。","寒燭細烟搖寢幌，濕螢微影綴芭蕉。","正當孤枕鴻初過，況复窮居葉尽凋。","閒憶秋江釣船裏，洒篷沾浪听蕭蕭。"]', '诗', 'shi', '', NULL, '雨夜 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657547af-0b83-4035-b775-9b9f615f5eba', '送僧遊天台（〖1〗《全唐詩》五九○題作《送圓鑑上人遊天台》。末句《石渠寶笈續編》作「幽澗泠泠竹室開」）', '送僧游天台（〖1〗《全唐诗》五九○題作《送圓鑑上人游天台》。末句《石渠寶笈續編》作「幽澗泠泠竹室开」）', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '送僧遊天台（〖1〗《全唐詩》五九○題作《送圓鑑上人遊天台》。末句《石渠寶笈續編》作「幽澗泠泠竹室開」） 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef0a5374-48c9-4b85-b55d-dde6d4a16e33', '試日上主司侍郎 一', '試日上主司侍郎 一', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["十年多病到京遲，到日風霜逼試期。","線不因針何處入，水難投石古來知。","青烟羃寒更恨，白髮星星曉鏡悲。","可惜龍門好風水，何人一爲整鱗鬐。"]', '["十年多病到京遲，到日风霜逼試期。","線不因針何处入，水难投石古来知。","青烟羃寒更恨，白髮星星晓镜悲。","可惜龙门好风水，何人一爲整鱗鬐。"]', '诗', 'shi', '', NULL, '試日上主司侍郎 一 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402720ac-2441-4e3e-aec1-1d8376b229c9', '試日上主司侍郎 二', '試日上主司侍郎 二', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["石帆山下有靈源，修竹茅堂寄此村。","閉戶偶多鄉老譽，讀書精得聖人言。","來時已作青雲意，試夜憂生白髮根。","十五年餘詩弟子，名成豈合在他門。"]', '["石帆山下有靈源，修竹茅堂寄此村。","閉戶偶多乡老譽，读书精得聖人言。","来时已作青云意，試夜憂生白髮根。","十五年餘诗弟子，名成豈合在他门。"]', '诗', 'shi', '', NULL, '試日上主司侍郎 二 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8fd0d7e-56b8-4dce-90b2-7b457b088345', '送李商隱侍御奉使入關', '送李商隐侍御奉使入关', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["梁園相遇管絃中，君踏仙梯我轉蓬。","《白雪》詠歌人似玉，青雲頭角馬生風。","相逢幾日虛懷待，賓幕連期醉蝶同。","如有扁舟棹歌思，題詩時寄五湖東。"]', '["梁园相遇管絃中，君踏仙梯我轉蓬。","《白雪》詠歌人似玉，青云头角马生风。","相逢幾日虛懷待，賓幕連期醉蝶同。","如有扁舟棹歌思，題诗时寄五湖东。"]', '诗', 'shi', '', NULL, '送李商隱侍御奉使入關 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29b7e6e0-68b8-4294-9cce-1ff2909e6d03', '板橋重送', '板橋重送', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["梁苑城西蘸水頭，玉鞭公子醉風流。","幾多紅粉低鬟恨，一部清商駐拍留。","王事有程須仃仃，客身如夢正悠悠。","洛陽浸畔逢神女，莫墜金樓醉石榴。"]', '["梁苑城西蘸水头，玉鞭公子醉风流。","幾多紅粉低鬟恨，一部清商駐拍留。","王事有程須仃仃，客身如梦正悠悠。","洛陽浸畔逢神女，莫墜金楼醉石榴。"]', '诗', 'shi', '', NULL, '板橋重送 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f088612-28d7-4007-a1e8-1c0e9fd93e38', '紫極宮上元齋日呈諸道流（〖1〗《全唐詩》「日」作「次」。又詩中第五句「風拂亂燈山磬曙」，《全唐詩》缺「曙」字。）', '紫極宮上元斋日呈諸道流（〖1〗《全唐诗》「日」作「次」。又诗中第五句「风拂亂灯山磬曙」，《全唐诗》缺「曙」字。）', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '紫極宮上元齋日呈諸道流（〖1〗《全唐詩》「日」作「次」。又詩中第五句「風拂亂燈山磬曙」，《全唐詩》缺「曙」字。） 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b17146-fff8-46ed-a309-90e801eea931', '贈羅道士', '贈羅道士', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["子訓成仙色似花，每人思見禮烟霞。","氣呵雲液變白髮，爪入水精嘗綠瓜。","五岳真官隨起坐，百年風燭笑榮華。"]', '["子訓成仙色似花，每人思见禮烟霞。","氣呵云液变白髮，爪入水精嘗綠瓜。","五岳真官隨起坐，百年风燭笑榮华。"]', '诗', 'shi', '', NULL, '贈羅道士 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7df0bab-67c7-4fe7-b162-f892c2723b4b', '終南山', '終南山', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["終南雨後絶纖埃，太乙先生石室開。","漢史烟霞通楚塞，秦風章句有條梅。","歸逢四皓收靈朮，幾見千官祝壽杯。","會得功成畢婚嫁，幅巾藜杖獨歸來。"]', '["終南雨後絶纖埃，太乙先生石室开。","漢史烟霞通楚塞，秦风章句有條梅。","归逢四皓收靈朮，幾见千官祝壽杯。","會得功成畢婚嫁，幅巾藜杖独归来。"]', '诗', 'shi', '', NULL, '終南山 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8639e4e4-fc45-4b5d-9706-40669b8b7228', '春山夜雨', '春山夜雨', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["詩成數盞兀忘思，瞑目昏昏倒接䍦。","無魚無愁且須醉，好風好月更何爲。","長留酒在花堆雪，不厭身閒鬢聚絲。","一夕春山到明坐，杜鵑啼歇麑啼時。"]', '["诗成數盞兀忘思，瞑目昏昏倒接䍦。","無鱼無愁且須醉，好风好月更何爲。","长留酒在花堆雪，不厭身閒鬢聚絲。","一夕春山到明坐，杜鵑啼歇麑啼时。"]', '诗', 'shi', '', NULL, '春山夜雨 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531f8ac2-ad6e-4558-868d-b88ff04ec0a5', '驪山懷古（五首） 一', '驪山懷古（五首） 一', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["武帝尋仙駕海遊，禁門高閉水空流。","深宮帶日年年靜，翠柏凝烟夜夜愁。","鸞鳳影沉歸萬古，歌鐘聲斷夢千秋。","晚來惆悵無人會，雲水猶飛傍玉樓。"]', '["武帝尋仙駕海游，禁门高閉水空流。","深宮带日年年静，翠柏凝烟夜夜愁。","鸾鳳影沉归万古，歌鐘声斷梦千秋。","晚来惆悵無人會，云水猶飞傍玉楼。"]', '诗', 'shi', '', NULL, '驪山懷古（五首） 一 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9bd191b-a3e4-4df5-a9b1-f2df33b7eab0', '驪山懷古（五首） 二', '驪山懷古（五首） 二', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["烟深樹老蔽蒼蒼，樓殿參差隱夕陽。","白玉砌寒苔自碧，真珠簾斷月無光。","驪山南去侵天盡，渭水東流入海長。","唯有春風舊情在，不將花艷出宮牆。"]', '["烟深樹老蔽蒼蒼，楼殿參差隐夕陽。","白玉砌寒苔自碧，真珠簾斷月無光。","驪山南去侵天尽，渭水东流入海长。","唯有春风旧情在，不將花艷出宮牆。"]', '诗', 'shi', '', NULL, '驪山懷古（五首） 二 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aacbd527-e0ee-4bfd-acfe-11fc6a6eef0f', '驪山懷古（五首） 三', '驪山懷古（五首） 三', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["紫府靈壇降玉真，華清臺殿影長新。","雪翻曉豔御階秀，風送夜香宮樹春。","杉桂靜同無夢客，烟花深似有愁人。","自從霜落芙蓉死，空使秦山鬼哭頻。"]', '["紫府靈壇降玉真，华清台殿影长新。","雪翻晓豔御階秀，风送夜香宮樹春。","杉桂静同無梦客，烟花深似有愁人。","自從霜落芙蓉死，空使秦山鬼哭頻。"]', '诗', 'shi', '', NULL, '驪山懷古（五首） 三 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c9e668-cece-4d83-95f7-79d0fdc65ff1', '驪山懷古（五首） 四', '驪山懷古（五首） 四', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["碧瓦雕牆擁翠微，泉聲一去杳難期。","一聞緱嶺仙成日，空想鈞天夢盡時。","青嶂淺深當雨靜，古松疎密向風悲。"]', '["碧瓦雕牆擁翠微，泉声一去杳难期。","一闻緱嶺仙成日，空想鈞天梦尽时。","青嶂淺深當雨静，古松疎密向风悲。"]', '诗', 'shi', '', NULL, '驪山懷古（五首） 四 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24226b96-86b2-496b-a55e-5f55baee5a3d', '驪山懷古（五首） 五', '驪山懷古（五首） 五', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["當時事事笑秦皇，今日追思倍可傷。","珠玉影搖千樹冷，綺羅風動滿川香。","雖名金殿長生字，誤說茅山不死方。","獨向逝波無問處，古槐花落路茫茫。"]', '["當时事事笑秦皇，今日追思倍可傷。","珠玉影搖千樹冷，綺羅风动满川香。","雖名金殿长生字，誤说茅山不死方。","独向逝波無问处，古槐花落路茫茫。"]', '诗', 'shi', '', NULL, '驪山懷古（五首） 五 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c6cc7ba-136f-4a8a-b91e-8a254a0b39ed', '夜思', '夜思', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["軒墀寂寞夜如何，沙渚頻驚候雁過。","一點秋燈人夢覺，萬重寒葉雨聲多。","酒衝肺腑愁生病，詩役心神漸有魔。"]', '["軒墀寂寞夜如何，沙渚頻驚候雁過。","一点秋灯人梦覺，万重寒葉雨声多。","酒衝肺腑愁生病，诗役心神漸有魔。"]', '诗', 'shi', '', NULL, '夜思 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56bc1361-b543-4018-b976-a3f6f612f48f', '贈李商隱贈佳人', '贈李商隐贈佳人', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["金珠約臂近笄年，秋月嫦娥漢浦仙。","雲髮膩垂香挅妥，黛眉愁入翠連娟。","花庭避客鳴環珮，鳳閣持杯泥管絃。","聞道彩鶯三十六，一雙雙映碧池蓮。"]', '["金珠約臂近笄年，秋月嫦娥漢浦仙。","云髮膩垂香挅妥，黛眉愁入翠連娟。","花庭避客鳴环珮，鳳閣持杯泥管絃。","闻道彩鶯三十六，一雙雙映碧池蓮。"]', '诗', 'shi', '', NULL, '贈李商隱贈佳人 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a956ce-9e57-4412-ad16-e962f42705f5', '傷賈島無可（《全唐詩》五九○收此詩，文字異同較多，故重錄）', '傷賈島無可（《全唐诗》五九○收此诗，文字異同較多，故重錄）', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["却到城中（《全唐詩》作「京師」）事事傷。","惠休歸去（寂）賈生亡。","誰人收得章句（文章）篋。","獨我重（來）經苔蘚房。","一命未沾爲逐客。","萬緣初盡別空王。","蕭蕭竹塢殘（斜）陽在。","葉拂（覆）閒堦雪擁墻。","。"]', '["却到城中（《全唐诗》作「京師」）事事傷。","惠休归去（寂）賈生亡。","誰人收得章句（文章）篋。","独我重（来）經苔蘚房。","一命未沾爲逐客。","万緣初尽別空王。","蕭蕭竹塢殘（斜）陽在。","葉拂（覆）閒堦雪擁墻。","。"]', '诗', 'shi', '', NULL, '傷賈島無可（《全唐詩》五九○收此詩，文字異同較多，故重錄） 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd58259d-eb57-4e17-9dbf-e27abe637303', '闕題', '闕題', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["一道春江枕驛樓，聞君此處泊行舟。","花當粉檻人閒立，燕拂青蘋水漫流。","芳草引歸南國夢，和風吹起故園愁。","余今自是迷津者，爲勸王孫莫遠遊。"]', '["一道春江枕驛楼，闻君此处泊行舟。","花當粉檻人閒立，燕拂青蘋水漫流。","芳草引归南国梦，和风吹起故园愁。","余今自是迷津者，爲勸王孫莫远游。"]', '诗', 'shi', '', NULL, '闕題 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c0525e9-389c-4f03-8c0f-71950ff1c74a', '闕下獻楊侍郎', '闕下獻楊侍郎', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["滄洲垂釣本無名，十月風霜偶到京。","羸馬未曾諳道路，片文誰爲達公卿？","聽殘曉漏愁終在，畫盡寒灰計不成。","心苦篇章頭早白，十年江漢憶先生。"]', '["滄洲垂釣本無名，十月风霜偶到京。","羸马未曾諳道路，片文誰爲達公卿？","听殘晓漏愁終在，畫尽寒灰計不成。","心苦篇章头早白，十年江漢憶先生。"]', '诗', 'shi', '', NULL, '闕下獻楊侍郎 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f39643d-bc59-4700-a03e-6c0744526674', '江州城樓', '江州城楼', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["灘頭獨鳥立枯楂，灘上行人踏淺沙。","秋色池塘無限草，夕陽門外幾千家。","寺連山谷松聲遠，川繞閻閭水勢斜。","常恐郡城砧杵動，秋風吹盡古槐花。"]', '["灘头独鸟立枯楂，灘上行人踏淺沙。","秋色池塘無限草，夕陽门外幾千家。","寺連山谷松声远，川繞閻閭水勢斜。","常恐郡城砧杵动，秋风吹尽古槐花。"]', '诗', 'shi', '', NULL, '江州城樓 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a99cac6-6b24-4786-8fc8-28dd0d6debcb', '春日題園林', '春日題园林', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["東園落盡綠絲長，風觸誰家酒瓮香。","紅粉人閑教鸚鵡，碧波池暖漾鴛鴦。","新蒲長疾看齊岸，晚蝶飛高欲過墻。","記取因逢賣樵客，囑教春暮採松篁。"]', '["东园落尽綠絲长，风觸誰家酒瓮香。","紅粉人闲教鸚鵡，碧波池暖漾鴛鴦。","新蒲长疾看齊岸，晚蝶飞高欲過墻。","記取因逢賣樵客，囑教春暮採松篁。"]', '诗', 'shi', '', NULL, '春日題園林 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e6b712-48a5-496c-bdd2-182c518b57bc', '贈（據《壯陶閣帖》卷二補。）', '贈（據《壯陶閣帖》卷二補。）', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["建陽門外柳千條，斜插鸞篦小錯刀。","紫袖握蟬聲欲絕，紅巾撲蝶勢潛高。","愁眉對照烟江柳，嫩臉初開露井桃。","閑把金釵惱鸚鵡，亂聲啞嘎落輕毛。","（以上《秘殿珠林石渠寶笈續編》。","）（《秘殿珠林石渠寶笈續編》收李郢詩卷，原藏於淳化軒。","卷末有樂全居士、柯九思、陳繹曾、周仁榮、張翥五人附跋。","茲錄前三人跋如次。","）（〖1〗其一：李公嘗出守房陵商州，有善政，以能詩聞諸公間，有文集行於世。","此詩翰墨豪健，自成一家。","宣和六年季夏一日，樂全居士書。","〖原注：張密學諱確，字子固。","〗〖2〗其二：右唐李郢字楚望書七言詩真跡，後有張樂全跋，曾入紹興內府，合縫小璽具存。","詩法清麗，筆意飄撇，自有一種風氣。","僕僅見宣和所收許渾詩稿，精緻亦如之，足以見唐人所尚，流風餘韻，令人興起。","至治初，以佳本定武《蘭亭》易得之，愛玩不能去手。","丹丘柯九思識。","〖3〗其三：唐李楚望端公大中十年七言詩一卷。","楚望以是歲登進士第，其上主司詩云：「閉戶偶多鄉老譽，讀書精得聖人言。","」視「一日看盡長安花」，殆有間矣。","宜其疏於馳競，以藩鎮從事終也。","此紙鳥絲欄絕精緻，字畫有歐柳意。","楚望居餘杭，豈出於故家遺俗之所傳者歟？","泰定元年十月十三日，吳興陳繹曾書。","）。"]', '["建陽门外柳千條，斜插鸾篦小錯刀。","紫袖握蟬声欲絕，紅巾撲蝶勢潛高。","愁眉对照烟江柳，嫩臉初开露井桃。","闲把金釵惱鸚鵡，亂声啞嘎落轻毛。","（以上《秘殿珠林石渠寶笈續編》。","）（《秘殿珠林石渠寶笈續編》收李郢诗卷，原藏於淳化軒。","卷末有乐全居士、柯九思、陳繹曾、周仁榮、張翥五人附跋。","茲錄前三人跋如次。","）（〖1〗其一：李公嘗出守房陵商州，有善政，以能诗闻諸公间，有文集行於世。","此诗翰墨豪健，自成一家。","宣和六年季夏一日，乐全居士书。","〖原注：張密学諱確，字子固。","〗〖2〗其二：右唐李郢字楚望书七言诗真跡，後有張乐全跋，曾入紹兴內府，合縫小璽具存。","诗法清丽，笔意飄撇，自有一種风氣。","僕僅见宣和所收許渾诗稿，精緻亦如之，足以见唐人所尚，流风餘韻，令人兴起。","至治初，以佳本定武《蘭亭》易得之，愛玩不能去手。","丹丘柯九思識。","〖3〗其三：唐李楚望端公大中十年七言诗一卷。","楚望以是歲登進士第，其上主司诗云：「閉戶偶多乡老譽，读书精得聖人言。","」視「一日看尽长安花」，殆有间矣。","宜其疏於驰競，以藩鎮從事終也。","此紙鸟絲欄絕精緻，字畫有歐柳意。","楚望居餘杭，豈出於故家遺俗之所傳者歟？","泰定元年十月十三日，吳兴陳繹曾书。","）。"]', '诗', 'shi', '', NULL, '贈（據《壯陶閣帖》卷二補。） 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32848f7a-35db-439d-b840-a6806fe481c9', '平望驛感先輩李從實處士周鉷二故人', '平望驛感先輩李從實处士周鉷二故人', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["蘆葦風多驛堠長，昔年携手上河梁。","青雲才子鴛鴻季，白石山人芝木香。","華驥欲陪先道路，大川斯濟戢舟航，少微星沒桂枝重，正掛孤帆過水鄉（《百城烟水》四《吳江》）。"]', '["蘆葦风多驛堠长，昔年携手上河梁。","青云才子鴛鴻季，白石山人芝木香。","华驥欲陪先道路，大川斯濟戢舟航，少微星沒桂枝重，正掛孤帆過水乡（《百城烟水》四《吳江》）。"]', '诗', 'shi', '', NULL, '平望驛感先輩李從實處士周鉷二故人 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9fc9cee-c08e-449e-a088-48add41f4996', '賞花短歌', '賞花短歌', '9ae1f9d3-6738-4447-80d2-979a74ecdd38', '唐', '["長生白，久視黃，共拜金剛不壞王（謂菊花也。","《清異錄》二）。"]', '["长生白，久視黄，共拜金剛不壞王（謂菊花也。","《清異錄》二）。"]', '诗', 'shi', '', NULL, '賞花短歌 李漼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbdf53d1-3a88-4d48-83e2-9423de1f1dd8', '題惠山泉（二首） 一', '題惠山泉（二首） 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["丞相長思煮泉時，郡侯催發只憂遲。","吳關去國三千里，莫笑楊妃愛荔枝。"]', '["丞相长思煮泉时，郡侯催發只憂遲。","吳关去国三千里，莫笑楊妃愛荔枝。"]', '诗', 'shi', '', NULL, '題惠山泉（二首） 一 皮日休 shi');
